const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => Array.from(document.querySelectorAll(selector));

async function bootMeidsApp() {
  applyStoredTheme();
  bindLanding();
  bindNavigation();
  bindChat();
  bindTwinSwitch();
  bindTwins();
  bindIngest();
  bindVoice();
  bindQuality();
  bindSkills();
  bindGraph();
  document.addEventListener("click", handleGraphInteractionCapture, true);
  bindDrawer();
  bindThemeToggle();
  bindKnowledgeFabricQueueActions();
  exposeLocalAgentRuntimeUatHook();
  $("#backToMainBtn").addEventListener("click", showLanding);
  $("#refreshBtn").addEventListener("click", refreshWorkspace);
  $("#refreshActivityBtn").addEventListener("click", safeRefreshActivity);
  $("#conceptSearch").addEventListener("input", renderConcepts);
  bindViewFilters();
  await loadAgentRuntimeConfig();
  state.knowledgeFabricIngestQueue = readKnowledgeFabricIngestQueue();
  await refreshAll();
  applyInitialRoute();
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", bootMeidsApp);
} else {
  bootMeidsApp();
}

function bindViewFilters() {
  $$("[data-concept-review]").forEach((button) => {
    button.addEventListener("click", () => {
      state.conceptReviewFilter = button.dataset.conceptReview || "all";
      updateFilterChips("[data-concept-review]", state.conceptReviewFilter, "conceptReview");
      renderConcepts();
    });
  });
  $("#conceptTypeFilter")?.addEventListener("change", (event) => {
    state.conceptTypeFilter = event.target.value || "all";
    renderConcepts();
  });
  $("#conceptSourceFilter")?.addEventListener("change", (event) => {
    state.conceptSourceFilter = event.target.value || "all";
    renderConcepts();
  });
  $("#conceptProfileFacets")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-concept-profile]");
    if (!button) return;
    state.conceptProfileFilter = button.dataset.conceptProfile || "all";
    renderConcepts();
  });
  $("#conceptHealthClusters")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-knowledge-cluster]");
    if (!button) return;
    const cluster = button.dataset.knowledgeCluster || "all";
    state.conceptClusterFilter = state.conceptClusterFilter === cluster ? "all" : cluster;
    renderConcepts();
  });
  $("#knowledgeSourceReadiness")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-concept-source-filter]");
    if (!button) return;
    state.conceptSourceFilter = button.dataset.conceptSourceFilter || "all";
    const select = $("#conceptSourceFilter");
    if (select) select.value = state.conceptSourceFilter;
    renderConcepts();
  });
  $("#knowledgeRetrievalPresetBar")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-knowledge-retrieval-preset]");
    if (!button) return;
    applyKnowledgeRetrievalPreset(button.dataset.knowledgeRetrievalPreset || "all");
  });
  $("#conceptDensityBtn")?.addEventListener("click", () => {
    state.conceptDensity = state.conceptDensity === "compact" ? "comfortable" : "compact";
    renderConcepts();
  });
  $("#skillStatusFilter")?.addEventListener("change", (event) => {
    state.skillStatusFilter = event.target.value || "all";
    renderSkillCatalog();
  });
  $$("[data-activity-filter]").forEach((button) => {
    button.addEventListener("click", () => {
      state.activityFilter = button.dataset.activityFilter || "all";
      updateFilterChips("[data-activity-filter]", state.activityFilter, "activityFilter");
      applyActivityFilter();
    });
  });
  $("#traceCockpitSummary")?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-activity-filter-jump]");
    if (!button) return;
    state.activityFilter = button.dataset.activityFilterJump || "all";
    updateFilterChips("[data-activity-filter]", state.activityFilter, "activityFilter");
    applyActivityFilter();
    $(".activity-timeline-grid")?.scrollIntoView({ block: "start", behavior: "smooth" });
  });
  $("#activityDensityBtn")?.addEventListener("click", () => {
    state.activityDensity = state.activityDensity === "compact" ? "comfortable" : "compact";
    applyActivityFilter();
  });
}

function updateFilterChips(selector, activeValue, datasetKey) {
  $$(selector).forEach((button) => {
    button.classList.toggle("active", button.dataset[datasetKey] === activeValue);
  });
}

function applyStoredTheme() {
  const theme = storedValue(storageKeys.theme) || "light";
  document.body.classList.toggle("theme-dark", theme === "dark");
  updateThemeToggle(theme);
}

function bindThemeToggle() {
  $("#themeToggleBtn")?.addEventListener("click", () => {
    const nextTheme = document.body.classList.contains("theme-dark") ? "light" : "dark";
    window.localStorage.setItem(storageKeys.theme, nextTheme);
    document.body.classList.toggle("theme-dark", nextTheme === "dark");
    updateThemeToggle(nextTheme);
  });
  updateThemeToggle(document.body.classList.contains("theme-dark") ? "dark" : "light");
}

function updateThemeToggle(theme) {
  const button = $("#themeToggleBtn");
  if (!button) return;
  const isDark = theme === "dark";
  button.textContent = isDark ? "Light" : "Dark";
  button.setAttribute("aria-pressed", String(isDark));
}

function bindLanding() {
  const landing = $("#landing");
  const dismiss = () => {
    landing.classList.add("dismissed");
    window.localStorage.setItem(storageKeys.landingDismissed, "true");
  };
  if (storedValue(storageKeys.landingDismissed) === "true") {
    landing.classList.add("dismissed");
  }
  $("#enterWorkspaceBtn").addEventListener("click", dismiss);
  $("#landingCreateTwinBtn").addEventListener("click", () => {
    dismiss();
    showView("twins");
    $("#twinDisplayName").focus();
  });
  $$("[data-landing-route]").forEach((button) => {
    button.addEventListener("click", () => {
      dismiss();
      showView(button.dataset.landingRoute || "chat");
    });
  });
}

function showLanding() {
  $("#landing").classList.remove("dismissed");
  window.localStorage.removeItem(storageKeys.landingDismissed);
}

function bindNavigation() {
  $$(".nav-item").forEach((button) => {
    button.addEventListener("click", () => {
      showView(button.dataset.view);
    });
  });
  const activeButton = $(".nav-item.active");
  if (activeButton) activeButton.setAttribute("aria-current", "page");
  $$(".dashboard-filter").forEach((button) => {
    button.addEventListener("click", () => {
      state.dashboardFilter = button.dataset.dashboardFilter || "all";
      renderDashboardFilter();
    });
  });
  document.addEventListener("click", (event) => {
    const action = event.target.closest("[data-cockpit-action]");
    if (!action) return;
    handleCockpitAction(action.dataset.cockpitAction);
  });
  document.addEventListener("click", async (event) => {
    const action = event.target.closest("[data-agent-probe-evidence-action]");
    if (!action) return;
    if (action.dataset.agentProbeEvidenceAction === "copy") await copyAgentProbeEvidencePacket();
    if (action.dataset.agentProbeEvidenceAction === "export") exportAgentProbeEvidencePacket();
  });
}

function applyInitialRoute() {
  const params = new URLSearchParams(window.location.search);
  const view = params.get("view");
  if (!view) return;
  const validView = document.querySelector(`.nav-item[data-view="${CSS.escape(view)}"]`);
  if (!validView) return;
  $("#landing")?.classList.add("dismissed");
  showView(view);
  const qualityGroup = params.get("quality");
  if (view === "quality" && qualityGroup) {
    setQualityGroup(qualityGroup);
  }
  const dashboardFilter = params.get("dashboard");
  if (view === "dashboard" && dashboardFilter) {
    state.dashboardFilter = dashboardFilter;
    renderDashboardFilter();
  }
}

function showView(viewId) {
  const button = document.querySelector(`.nav-item[data-view="${CSS.escape(viewId)}"]`);
  const view = $(`#${CSS.escape(viewId)}`);
  if (!button || !view) return;
  $$(".nav-item").forEach((item) => {
    item.classList.remove("active");
    item.removeAttribute("aria-current");
  });
  $$(".view").forEach((item) => item.classList.remove("active"));
  button.classList.add("active");
  button.setAttribute("aria-current", "page");
  view.classList.add("active");
  $("#pageTitle").textContent = button.textContent;
  renderWorkspaceMode(viewId);
  if (viewId === "chat") {
    renderChatSkillMode();
    void ensureN8nChat();
  }
}

function renderWorkspaceMode(viewId) {
  const modeByView = {
    twins: "Design Cockpit",
    skills: "Skill Cockpit",
    dashboard: "Review Cockpit",
    graph: "Review Cockpit",
    activity: "Review Cockpit",
    quality: "Production Cockpit",
  };
  const isCockpit = Boolean(modeByView[viewId]);
  document.body.classList.toggle("cockpit-mode", isCockpit);
  document.body.classList.toggle("workspace-mode", !isCockpit);
  document.body.dataset.activeView = viewId;
  document.body.dataset.activeZone = isCockpit ? "cockpit" : "workspace";
  const mode = $("#workspaceMode");
  if (mode) {
    mode.textContent = modeByView[viewId] || "Workspace";
    mode.classList.toggle("cockpit", isCockpit);
  }
  renderProductionProgressHeader();
  renderProductionKnowledgeRepoReadiness();
}

function handleCockpitAction(action) {
  const routes = {
    reviewConcepts: () => {
      state.dashboardFilter = "concepts";
      showView("dashboard");
      renderDashboardFilter();
      $("#dashPendingConcepts")?.scrollIntoView({ block: "center", behavior: "smooth" });
    },
    openSkills: () => showView("skills"),
    openTwins: () => showView("twins"),
    openQuality: () => showView("quality"),
    openProductionCockpit: () => {
      showView("quality");
      setQualityGroup("production");
      $(".mcp-cockpit")?.scrollIntoView({ block: "center", behavior: "smooth" });
    },
    openHostedConfig: () => {
      showView("quality");
      setQualityGroup("production");
      $(".production-cockpit")?.scrollIntoView({ block: "start", behavior: "smooth" });
      $(".production-stage.hosted")?.setAttribute("open", "");
      $("#productionConfigureNext")?.scrollIntoView({ block: "center", behavior: "smooth" });
    },
    openMcpQueue: () => {
      state.dashboardFilter = "mcp";
      showView("dashboard");
      renderDashboardFilter();
      $("#dashMcpQueue")?.scrollIntoView({ block: "center", behavior: "smooth" });
    },
    openTraceReview: () => {
      state.dashboardFilter = "traces";
      showView("dashboard");
      renderDashboardFilter();
      $("#dashLatestTraces")?.scrollIntoView({ block: "center", behavior: "smooth" });
    },
    openRefinementReview: () => {
      state.dashboardFilter = "refinements";
      showView("dashboard");
      renderDashboardFilter();
      $("#dashRefinementQueue")?.scrollIntoView({ block: "center", behavior: "smooth" });
    },
    focusSkillShape: () => {
      showView("skills");
      $(".workflow-shape")?.scrollIntoView({ block: "center", behavior: "smooth" });
    },
    focusSkillApproval: () => {
      showView("skills");
      $(".workflow-approve")?.scrollIntoView({ block: "center", behavior: "smooth" });
    },
    focusSkillRun: () => {
      showView("skills");
      $(".workflow-run")?.setAttribute("open", "");
      $(".workflow-run")?.scrollIntoView({ block: "center", behavior: "smooth" });
    },
    focusSkillImprove: () => {
      showView("skills");
      $(".workflow-improve")?.setAttribute("open", "");
      $(".workflow-improve")?.scrollIntoView({ block: "center", behavior: "smooth" });
    },
    openActivity: () => showView("activity"),
    openDashboard: () => showView("dashboard"),
    openChat: () => showView("chat"),
    openKnowledge: () => showView("concepts"),
    openGraph: () => showView("graph"),
    exportGraphPromotionHistory: exportGraphPromotionHistory,
    exportOkfGraphPackage: exportOkfGraphPromotionPackage,
    copyOkfGraphRepoSync: copyOkfGraphPromotionRepoSyncPackage,
    openVoice: () => showView("voice"),
  };
  routes[action]?.();
}

function renderDashboardFilter() {
  $$(".dashboard-filter").forEach((button) => {
    button.classList.toggle("active", (button.dataset.dashboardFilter || "all") === state.dashboardFilter);
  });
  $$(".dashboard-section").forEach((section) => {
    const visible = state.dashboardFilter === "all" || section.dataset.dashboardSection === state.dashboardFilter;
    section.hidden = !visible;
  });
}

