function handleGraphInteractionCapture(event) {
  if (!event.target.closest?.("#graph")) return;
  const edgeClassFilter = event.target.closest("[data-graph-edge-class-filter]");
  if (edgeClassFilter) {
    event.preventDefault();
    event.stopPropagation();
    state.graphReasoningPreset = "custom";
    state.graphEdgeClassFilter = edgeClassFilter.dataset.graphEdgeClassFilter || "all";
    renderGraphCockpit();
    return;
  }
  const edgeAction = event.target.closest("[data-graph-edge-action]");
  if (edgeAction) {
    event.preventDefault();
    event.stopPropagation();
    reviewGraphEdge(edgeAction.dataset.graphEdgeKey, edgeAction.dataset.graphEdgeAction);
  }
}

function handleGraphEdgeLabelDocumentClick(event) {
  if (!$("#graph")?.classList.contains("active")) return;
  const direct = event.target?.closest?.(".graph-svg-edge-label[data-graph-edge]");
  const hit = document.elementFromPoint(event.clientX, event.clientY)?.closest?.(".graph-svg-edge-label[data-graph-edge]");
  const label = direct || hit || findGraphEdgeLabelAtPoint(event.clientX, event.clientY);
  if (!label || !$("#graphCanvas")?.contains(label)) return;
  event.preventDefault();
  event.stopPropagation();
  selectGraphEdgeForReview(label.dataset.graphEdge || "", "label");
}

function findGraphEdgeLabelAtPoint(x, y) {
  if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
  const tolerance = 36;
  return [...document.querySelectorAll("#graphCanvas .graph-svg-edge-label[data-graph-edge]")]
    .map((label) => {
      const rect = label.getBoundingClientRect();
      const within = x >= rect.left - tolerance
        && x <= rect.right + tolerance
        && y >= rect.top - tolerance
        && y <= rect.bottom + tolerance;
      const centerX = rect.left + rect.width / 2;
      const centerY = rect.top + rect.height / 2;
      return {
        label,
        within,
        distance: Math.hypot(centerX - x, centerY - y),
      };
    })
    .filter((item) => item.within)
    .sort((a, b) => a.distance - b.distance)[0]?.label || null;
}

async function safeRefreshGraph() {
  const status = $("#graphStatus");
  if (status) status.textContent = "Loading graph...";
  try {
    const [graph, taskResult, reviewResult, postgresRead] = await Promise.all([
      getJson(`/api/okf/graph?twin=${encodeURIComponent(state.activeTwin)}&include_drafts=${state.graphIncludeDrafts}`),
      getJson(`/api/okf/graph/recommendation-tasks?twin=${encodeURIComponent(state.activeTwin)}&limit=20`).catch(() => ({ tasks: [] })),
      getJson(`/api/okf/graph/edge-reviews?twin=${encodeURIComponent(state.activeTwin)}&limit=300`).catch(() => ({ reviews: [] })),
      getJson(`/api/okf/graph/postgres-read?twin=${encodeURIComponent(state.activeTwin)}&tenant_id=local`).catch((error) => ({ status: "unavailable", blockers: [compactError(error.message)] })),
    ]);
    state.okfGraph = graph;
    state.graphRecommendationTasks = taskResult.tasks || [];
    state.graphEdgeReviews = reviewResult.reviews || [];
    state.graphPostgresRead = postgresRead;
    state.graphEdgeReviewsLoadedFor = state.activeTwin;
    state.okfGraphLoadedAt = new Date().toISOString();
    state.okfGraphNodeDetail = null;
    state.selectedGraphNodeKey = "";
    state.selectedGraphEdgeKey = "";
    renderGraphFilters();
    syncGraphControlValues();
    renderDashboardGraphDecisionQueue();
    renderGraphCockpit();
    if (status) {
      const summary = graph.summary || {};
      status.textContent = `${summary.node_count || summary.nodes || 0} nodes, ${summary.edge_count || summary.edges || 0} edges. ${state.graphIncludeDrafts ? "Drafts visible." : "Approved only."}`;
    }
  } catch (error) {
    if (status) status.textContent = `Graph unavailable: ${compactError(error.message)}`;
    $("#graphCanvas").innerHTML = renderEmptyState("Knowledge graph unavailable.");
  }
}

function downloadGraphSvg() {
  const status = $("#graphStatus");
  const exportPayload = buildGraphSvgExport();
  if (!exportPayload) {
    if (status) status.textContent = "Graph visual export unavailable: no SVG rendered.";
    showToast("Graph visual export unavailable", "Load the knowledge graph first.", "error");
    return;
  }
  const { payload, filenameBase } = exportPayload;
  const blob = new Blob([payload], { type: "image/svg+xml;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const filename = `${filenameBase}.svg`;
  triggerDownload(url, filename);
  URL.revokeObjectURL(url);
  if (status) status.textContent = `Graph visual exported: ${filename}`;
  showToast("Graph visual exported", filename, "success");
}

async function downloadGraphPng() {
  const status = $("#graphStatus");
  const exportPayload = buildGraphSvgExport();
  if (!exportPayload) {
    if (status) status.textContent = "Graph PNG export unavailable: no SVG rendered.";
    showToast("Graph PNG export unavailable", "Load the knowledge graph first.", "error");
    return;
  }
  const { payload, filenameBase, width, height } = exportPayload;
  const blob = new Blob([payload], { type: "image/svg+xml;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  try {
    const image = await loadGraphImage(url);
    const scale = Math.min(2, Math.max(1, window.devicePixelRatio || 1));
    const canvas = document.createElement("canvas");
    canvas.width = Math.round(width * scale);
    canvas.height = Math.round(height * scale);
    const context = canvas.getContext("2d");
    context.fillStyle = document.body.classList.contains("theme-dark") ? "#151a16" : "#f6f5f1";
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    const pngBlob = await new Promise((resolve) => canvas.toBlob(resolve, "image/png"));
    if (!pngBlob) throw new Error("Canvas PNG export failed");
    const pngUrl = URL.createObjectURL(pngBlob);
    const filename = `${filenameBase}.png`;
    triggerDownload(pngUrl, filename);
    URL.revokeObjectURL(pngUrl);
    if (status) status.textContent = `Graph PNG exported: ${filename}`;
    showToast("Graph PNG exported", filename, "success");
  } catch (error) {
    if (status) status.textContent = `Graph PNG export failed: ${compactError(error.message)}`;
    showToast("Graph PNG export failed", compactError(error.message), "error");
  } finally {
    URL.revokeObjectURL(url);
  }
}

function buildGraphSvgExport() {
  const svg = $("#graphCanvas .graph-topology-svg");
  if (!svg) return null;
  const clone = svg.cloneNode(true);
  clone.removeAttribute("style");
  clone.classList.add(`export-layout-${safeGraphClass(state.graphLayoutMode)}`);
  clone.setAttribute("xmlns", "http://www.w3.org/2000/svg");
  clone.setAttribute("data-exported-from", "MeIDs Knowledge Graph");
  const [viewX, viewY, viewWidth, viewHeight] = (clone.getAttribute("viewBox") || "0 0 1120 720")
    .split(/\s+/)
    .map((value) => Number(value) || 0);
  clone.setAttribute("width", String(viewWidth || 1120));
  clone.setAttribute("height", String(viewHeight || 720));
  const title = document.createElementNS("http://www.w3.org/2000/svg", "title");
  title.textContent = `MeIDs knowledge graph · ${labelizeGraph(state.graphLayoutMode)} layout · ${state.activeTwin}`;
  clone.insertBefore(title, clone.firstChild);
  const metadata = document.createElementNS("http://www.w3.org/2000/svg", "metadata");
  metadata.textContent = JSON.stringify({
    twin: state.activeTwin,
    layout: state.graphLayoutMode,
    density: state.graphDensityMode,
    includeDrafts: state.graphIncludeDrafts,
    nodeFilter: state.graphNodeTypeFilter,
    edgeFilter: state.graphEdgeTypeFilter,
    reviewFilter: state.graphReviewFilter,
    reasoningPreset: state.graphReasoningPreset,
    exportedAt: new Date().toISOString(),
  });
  clone.insertBefore(metadata, clone.children[1] || null);
  const style = document.createElementNS("http://www.w3.org/2000/svg", "style");
  style.textContent = graphExportCss(document.body.classList.contains("theme-dark"));
  clone.insertBefore(style, clone.children[2] || null);
  const background = document.createElementNS("http://www.w3.org/2000/svg", "rect");
  background.setAttribute("x", String(viewX || 0));
  background.setAttribute("y", String(viewY || 0));
  background.setAttribute("width", String(viewWidth || 1120));
  background.setAttribute("height", String(viewHeight || 720));
  background.setAttribute("fill", document.body.classList.contains("theme-dark") ? "#151a16" : "#f6f5f1");
  clone.insertBefore(background, clone.children[3] || null);
  const payload = `<?xml version="1.0" encoding="UTF-8"?>\n${new XMLSerializer().serializeToString(clone)}`;
  const stamp = new Date().toISOString().slice(0, 19).replace(/[-:T]/g, "");
  return {
    payload,
    filenameBase: `meids-knowledge-graph-${state.graphLayoutMode}-${stamp}`,
    width: viewWidth || 1120,
    height: viewHeight || 720,
    x: viewX,
    y: viewY,
  };
}

function graphExportCss(isDark) {
  const colors = isDark
    ? {
        ink: "#f5f2ea",
        muted: "#b9b3a8",
        nodeFill: "#1c211d",
        nodeStroke: "#5b6659",
        approvedFill: "#203c34",
        pendingFill: "#3a2f1f",
        reworkFill: "#402a20",
        rejectedFill: "#3b2422",
        explicit: "#8ce2ca",
        inferred: "#bdc7ff",
        candidate: "#f1d08c",
        rework: "#efb184",
        danger: "#f0a39a",
        accent: "#7be1c7",
      }
    : {
        ink: "#171916",
        muted: "#6f716a",
        nodeFill: "#fbfaf6",
        nodeStroke: "#d7d3c8",
        approvedFill: "#d8f1e9",
        pendingFill: "#fff7e8",
        reworkFill: "#fff0e8",
        rejectedFill: "#fdecea",
        explicit: "#2f8f79",
        inferred: "#5f6fb7",
        candidate: "#c8a35d",
        rework: "#c46a3a",
        danger: "#c84f3f",
        accent: "#2f8f79",
      };
  return `
    .graph-svg-edge-hit { display: none; }
    .graph-svg-zone rect {
      fill: ${isDark ? "rgba(241, 208, 140, 0.07)" : "#f4ead3"};
      opacity: 0.68;
      stroke: ${isDark ? "#f1d08c" : "#c8a35d"};
      stroke-dasharray: 8 8;
      stroke-width: 1.5;
    }
    .graph-svg-zone text {
      fill: ${colors.ink};
      font-family: Inter, Arial, sans-serif;
      font-size: 14px;
      font-weight: 900;
    }
    .graph-svg-zone .graph-svg-zone-count {
      fill: ${colors.muted};
      font-size: 11px;
      font-weight: 800;
    }
    .graph-svg-edge {
      cursor: pointer;
      fill: none;
      opacity: 0.78;
      stroke: ${colors.inferred};
      stroke-linecap: round;
      stroke-width: 1.8;
    }
    .graph-svg-edge.explicit { stroke: ${colors.explicit}; stroke-width: 2.2; }
    .graph-svg-edge.inferred { stroke: ${colors.inferred}; stroke-dasharray: 7 6; }
    .graph-svg-edge.candidate,
    .graph-svg-edge.duplicate-candidate,
    .graph-svg-edge.contradiction-candidate {
      stroke: ${colors.candidate};
      stroke-dasharray: 3 6;
      stroke-width: 2.2;
    }
    .graph-svg-edge.contradiction-candidate { stroke: ${colors.danger}; }
    .graph-svg-edge.accepted { opacity: 0.95; }
    .graph-svg-edge.rejected { opacity: 0.32; }
    .graph-svg-edge.selected { opacity: 1; stroke: ${colors.accent}; stroke-width: 4; }
    .graph-svg-edge.active-path { opacity: 1; stroke: ${colors.accent}; stroke-width: 4.4; }
    .graph-svg-edge-label rect {
      fill: ${isDark ? "#20271f" : "#fbfaf6"};
      stroke: ${isDark ? "#4a5648" : colors.nodeStroke};
      stroke-width: 1;
    }
    .graph-svg-edge-label text {
      fill: ${colors.ink};
      font-family: Inter, Arial, sans-serif;
      font-size: 10px;
      font-weight: 900;
      paint-order: stroke;
      stroke: ${isDark ? "#20271f" : "#fbfaf6"};
      stroke-linejoin: round;
      stroke-width: 3px;
      text-anchor: middle;
    }
    .graph-svg-edge-label.candidate rect,
    .graph-svg-edge-label.duplicate-candidate rect { fill: ${isDark ? "#3a2f1f" : "#fff7e8"}; stroke: ${colors.candidate}; }
    .graph-svg-edge-label.contradiction-candidate rect { fill: ${isDark ? "#3b2422" : "#fff0e8"}; stroke: ${colors.danger}; }
    .graph-svg-edge-label.active-path rect { fill: ${isDark ? "#203c34" : colors.approvedFill}; stroke: ${colors.accent}; stroke-width: 1.4; }
    .export-layout-cluster .graph-svg-edge { opacity: 0.42; }
    .export-layout-cluster .graph-svg-edge.explicit { opacity: 0.72; }
    .export-layout-cluster .graph-svg-edge.inferred { opacity: 0.24; }
    .export-layout-cluster .graph-svg-edge.candidate,
    .export-layout-cluster .graph-svg-edge.duplicate-candidate,
    .export-layout-cluster .graph-svg-edge.contradiction-candidate { opacity: 0.46; }
    .export-layout-cluster .graph-svg-edge.selected { opacity: 1; }
    .graph-svg-node circle {
      fill: ${colors.nodeFill};
      stroke: ${colors.nodeStroke};
      stroke-width: 2.5;
    }
    .graph-svg-node.approved circle { fill: ${colors.approvedFill}; stroke: ${colors.explicit}; }
    .graph-svg-node.pending-review circle { fill: ${colors.pendingFill}; stroke: ${colors.candidate}; }
    .graph-svg-node.needs-rework circle { fill: ${colors.reworkFill}; stroke: ${colors.rework}; }
    .graph-svg-node.rejected circle { fill: ${colors.rejectedFill}; stroke: ${colors.danger}; }
    .graph-svg-node.cluster circle { stroke-width: 4; }
    .graph-svg-node.selected circle { stroke: ${colors.accent}; stroke-width: 3.5; }
    .graph-svg-node text {
      fill: ${colors.ink};
      font-family: Inter, Arial, sans-serif;
      font-size: 13px;
      font-weight: 900;
      paint-order: stroke;
      pointer-events: none;
      stroke: ${isDark ? "#151a16" : colors.nodeFill};
      stroke-linejoin: round;
      stroke-width: 4px;
      text-anchor: middle;
    }
    .graph-svg-node .graph-svg-label {
      fill: ${colors.muted};
      font-size: 10px;
      font-weight: 800;
      stroke-width: 5px;
    }
    marker path { fill: ${colors.muted}; }
  `;
}

function loadGraphImage(url) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error("Could not load graph SVG for PNG export"));
    image.src = url;
  });
}

function triggerDownload(url, filename) {
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
}

function openGraphPresentation() {
  const overlay = $("#graphPresentationOverlay");
  const body = $("#graphPresentationBody");
  const source = $("#graphCanvas .graph-map") || $("#graphCanvas .graph-list-view");
  if (!overlay || !body || !source) {
    showToast("Presentation unavailable", "Load the knowledge graph first.", "error");
    return;
  }
  const clone = source.cloneNode(true);
  clone.classList.add("graph-presentation-clone");
  clone.querySelectorAll(".graph-viewport-actions, .graph-node-rail, input, select, textarea").forEach((node) => node.remove());
  clone.querySelectorAll("button").forEach((button) => {
    button.setAttribute("disabled", "true");
    button.setAttribute("tabindex", "-1");
  });
  clone.querySelectorAll("[tabindex]").forEach((node) => node.removeAttribute("tabindex"));
  const presentation = graphPresentationModel();
  body.innerHTML = renderGraphPresentationShell(presentation);
  $("#graphPresentationStage")?.appendChild(clone);
  const summary = state.okfGraph?.summary || {};
  const title = $("#graphPresentationTitle");
  const meta = $("#graphPresentationMeta");
  if (title) title.textContent = `${labelizeGraph(state.graphReasoningPreset)} knowledge graph`;
  if (meta) {
    meta.textContent = [
      state.activeTwin,
      `${summary.node_count || summary.nodes || 0} nodes`,
      `${summary.edge_count || summary.edges || 0} relations`,
      state.graphIncludeDrafts ? "drafts visible" : "approved only",
    ].join(" · ");
  }
  overlay.hidden = false;
  overlay.setAttribute("aria-hidden", "false");
  document.body.classList.add("graph-presenting");
  $("#graphPresentationCloseBtn")?.focus();
  showToast("Presentation mode", "Graph opened in a focused demo view.", "success");
}

function graphPresentationModel() {
  const graph = state.okfGraph || {};
  const baseNodes = filteredGraphNodes();
  const baseNodeKeys = new Set(baseNodes.map((node) => node.node_key));
  const baseEdges = (graph.edges || []).filter((edge) => baseNodeKeys.has(edge.source) && baseNodeKeys.has(edge.target));
  const projection = graphFocusProjection(baseNodes, baseEdges);
  const nodes = projection.nodes || [];
  const availableEdges = projection.edges || [];
  const edges = applyGraphEdgeFilters(availableEdges);
  const nodeMap = new Map((graph.nodes || []).map((node) => [node.node_key, node]));
  const selectedEdge = (graph.edges || []).find((edge) => edge.edge_key === state.selectedGraphEdgeKey) || null;
  const visibleRecommendations = filterGraphRecommendations(state.graphRecommendations || []);
  const nodeStates = countBy(nodes, (node) => node.review_state || "unknown");
  const edgeClasses = countBy(edges, (edge) => graphEdgeClass(edge));
  const relationTypes = countBy(edges, (edge) => edge.relation_type || edge.edge_type || "related");
  const topRelation = Object.entries(relationTypes).sort((a, b) => b[1] - a[1])[0];
  return {
    graph,
    nodes,
    edges,
    nodeMap,
    selectedEdge,
    visibleRecommendations,
    nodeStates,
    edgeClasses,
    topRelation,
    preset: graphPresetDefinition(state.graphReasoningPreset) || graphPresetDefinition("custom"),
  };
}

function renderGraphPresentationShell(model) {
  const approved = model.nodeStates.approved || 0;
  const pending = model.nodeStates["pending-review"] || model.nodeStates.pending_review || 0;
  const inferred = model.edgeClasses.inferred || 0;
  const candidate = (model.edgeClasses.candidate || 0)
    + (model.edgeClasses["duplicate-candidate"] || 0)
    + (model.edgeClasses["contradiction-candidate"] || 0);
  const selectedEdgePanel = model.selectedEdge
    ? renderGraphPresentationEdgePanel(model.selectedEdge, model.nodeMap)
    : renderGraphPresentationRecommendationPanel(model.visibleRecommendations);
  return `
    <section class="graph-presentation-hero">
      <div>
        <span class="badge">Executive graph view</span>
        <h3>${escapeHtml(model.preset?.label || "Knowledge graph")}</h3>
        <p>${escapeHtml(model.preset?.purpose || "Shows how governed knowledge becomes actor-ready context.")}</p>
      </div>
      <div class="graph-presentation-storyline" aria-label="Graph story">
        <span>Sources</span>
        <i></i>
        <span>Concepts</span>
        <i></i>
        <span>Inference</span>
        <i></i>
        <strong>Actor use</strong>
      </div>
    </section>
    <section class="graph-presentation-kpis" aria-label="Graph presentation metrics">
      <article><strong>${model.nodes.length}</strong><span>visible nodes</span></article>
      <article><strong>${model.edges.length}</strong><span>relations</span></article>
      <article><strong>${approved}</strong><span>approved concepts</span></article>
      <article><strong>${inferred}</strong><span>inferred bridges</span></article>
      <article><strong>${candidate}</strong><span>governance candidates</span></article>
      <article><strong>${model.visibleRecommendations.length}</strong><span>recommended actions</span></article>
    </section>
    <section class="graph-presentation-layout">
      <div class="graph-presentation-main">
        <div class="graph-presentation-stage-head">
          <div>
            <span class="eyebrow">Dynamic OKF projection</span>
            <h3>${escapeHtml(labelizeGraph(state.graphLayoutMode))} view</h3>
          </div>
          <span>${escapeHtml(model.topRelation ? `${labelizeGraph(model.topRelation[0])} · ${model.topRelation[1]}` : "all relation types")}</span>
        </div>
        <div id="graphPresentationStage" class="graph-presentation-stage"></div>
      </div>
      <aside class="graph-presentation-side">
        ${selectedEdgePanel}
        ${renderGraphPresentationNarrative(model, pending)}
      </aside>
    </section>
  `;
}

function renderGraphPresentationEdgePanel(edge, nodeMap) {
  const source = nodeMap.get(edge.source) || {};
  const target = nodeMap.get(edge.target) || {};
  const policy = graphEdgeUsagePolicy(edge);
  return `
    <article class="graph-presentation-panel">
      <span class="badge">${escapeHtml(graphProvenanceVerdict(edge))}</span>
      <h3>${escapeHtml(labelizeGraph(edge.relation_type || edge.edge_type || "relation"))}</h3>
      <p>${escapeHtml(graphRelationMeaning(edge, source, target))}</p>
      <dl>
        ${detailRow("Source", graphNodeTitle(source, edge.source))}
        ${detailRow("Target", graphNodeTitle(target, edge.target))}
        ${detailRow("Actor rule", policy.label)}
        ${detailRow("Confidence", edge.confidence == null ? "-" : `${Math.round(Number(edge.confidence) * 100)}%`)}
      </dl>
    </article>
  `;
}

function renderGraphPresentationRecommendationPanel(recommendations = []) {
  const top = recommendations.slice(0, 3);
  return `
    <article class="graph-presentation-panel">
      <span class="badge">Governance focus</span>
      <h3>Next graph actions</h3>
      ${top.length
        ? `<ol>${top.map((item) => `
            <li>
              <strong>${escapeHtml(item.title || "Graph recommendation")}</strong>
              <span>${escapeHtml(item.benefit || item.detail || "Improves graph quality.")}</span>
            </li>
          `).join("")}</ol>`
        : `<p>No open graph recommendations in the current projection.</p>`}
    </article>
  `;
}

function renderGraphPresentationNarrative(model, pendingCount) {
  return `
    <article class="graph-presentation-panel graph-presentation-narrative">
      <span class="badge">Twin interpretation</span>
      <h3>What this graph explains</h3>
      <ul>
        <li><strong>Knowledge surface</strong><span>${escapeHtml(model.preset?.actorUse || "Context for grounded twin answers.")}</span></li>
        <li><strong>Inference layer</strong><span>${escapeHtml(`${model.edgeClasses.inferred || 0} inferred bridge${(model.edgeClasses.inferred || 0) === 1 ? "" : "s"} expand recall beyond explicit source links.`)}</span></li>
        <li><strong>Governance state</strong><span>${escapeHtml(`${pendingCount} visible concept${pendingCount === 1 ? "" : "s"} still need approval before production reliance.`)}</span></li>
      </ul>
    </article>
  `;
}

function closeGraphPresentation() {
  const overlay = $("#graphPresentationOverlay");
  if (!overlay) return;
  overlay.hidden = true;
  overlay.setAttribute("aria-hidden", "true");
  $("#graphPresentationBody").innerHTML = "";
  document.body.classList.remove("graph-presenting");
}

function selectGraphEdgeForReview(edgeKey, source = "graph") {
  state.selectedGraphEdgeKey = edgeKey || "";
  state.graphEdgeSelectionSource = source;
  state.hoveredGraphEdgeKey = "";
  renderGraphCockpit();
  window.setTimeout(() => {
    const workbench = $("#graphPrimaryNodeAction .graph-edge-workbench") || $(".graph-edge-workbench");
    if (!workbench) return;
    const rect = workbench.getBoundingClientRect();
    window.scrollTo({ top: Math.max(0, window.scrollY + rect.top - 420), left: 0, behavior: "auto" });
  }, 30);
}

async function exportGraph() {
  const status = $("#graphStatus");
  if (status) status.textContent = "Exporting graph snapshot...";
  try {
    await refreshGraphEdgeReviews(true);
    const graph = await postJson(`/api/okf/graph/export?twin=${encodeURIComponent(state.activeTwin)}&include_drafts=${state.graphIncludeDrafts}`, {
      export_context: graphExportContext(),
    });
    state.okfGraph = graph;
    state.okfGraphArtifact = graph.artifact || null;
    state.okfGraphLoadedAt = new Date().toISOString();
    renderGraphCockpit();
    const artifactPath = graph.artifact?.path || "derived/knowledge-graph";
    if (status) status.textContent = `Graph exported: ${artifactPath}`;
    showToast("Graph exported", artifactPath, "success");
  } catch (error) {
    if (status) status.textContent = `Graph export failed: ${compactError(error.message)}`;
    showToast("Graph export failed", compactError(error.message), "error");
  }
}

function graphExportContext() {
  const graph = state.okfGraph || {};
  const nodes = filteredGraphNodes();
  const graphEdges = graph.edges || [];
  const visibleNodeKeys = new Set(nodes.map((node) => node.node_key));
  const visibleEdges = applyGraphEdgeFilters(graphEdges).filter((edge) => visibleNodeKeys.has(edge.source) && visibleNodeKeys.has(edge.target));
  const selectedEdge = graphEdges.find((edge) => edge.edge_key === state.selectedGraphEdgeKey);
  const selectedNode = (graph.nodes || []).find((node) => node.node_key === state.selectedGraphNodeKey);
  const visibleRecommendations = filterGraphRecommendations(state.graphRecommendations || []);
  const visibleTasks = filterGraphRecommendationTasks(state.graphRecommendationTasks || []);
  const packet = state.graphRecommendationActionPacket?.packet || {};
  const selectedNodeHistory = selectedNode ? graphNodeReviewHistory(selectedNode.node_key).slice(0, 12) : [];
  return {
    exported_from: "knowledge-graph-cockpit",
    exported_at_client: new Date().toISOString(),
    view: {
      reasoning_preset: state.graphReasoningPreset,
      layout_mode: state.graphLayoutMode,
      view_mode: state.graphViewMode,
      density_mode: state.graphDensityMode,
      node_type_filter: state.graphNodeTypeFilter,
      edge_type_filter: state.graphEdgeTypeFilter,
      edge_class_filter: state.graphEdgeClassFilter,
      review_filter: state.graphReviewFilter,
      search: state.graphSearch,
      include_drafts: String(state.graphIncludeDrafts),
      focus_mode: String(state.graphFocusMode),
    },
    selected: {
      node_key: state.selectedGraphNodeKey,
      edge_key: state.selectedGraphEdgeKey,
      edge_selection_source: state.graphEdgeSelectionSource,
    },
    visible_projection: {
      node_count: String(nodes.length),
      edge_count: String(visibleEdges.length),
      approved_nodes: String(nodes.filter((node) => node.review_state === "approved").length),
      candidate_edges: String(visibleEdges.filter((edge) => String(graphEdgeClass(edge)).includes("candidate")).length),
    },
    recommendation_filters: {
      priority: state.graphRecommendationPriorityFilter,
      type: state.graphRecommendationTypeFilter,
      task_status: state.graphRecommendationTaskStatusFilter,
    },
    visible_recommendations: visibleRecommendations.map((item) => ({
      key: item.key || "",
      recommendation_type: item.recommendationType || "",
      priority: item.priority || "",
      title: item.title || "",
      node_key: item.nodeKey || "",
      edge_key: item.edgeKey || "",
    })),
    recommendation_tasks: visibleTasks.map((task) => ({
      path: task.path || "",
      status: task.status || "",
      priority: task.priority || "",
      title: task.title || "",
      recommendation_type: task.recommendation_type || "",
    })),
    prepared_packet: {
      path: state.graphRecommendationActionPacket?.path || "",
      status: packet.status || state.graphRecommendationActionPacket?.status || "",
      title: packet.title || "",
      task_path: packet.task_path || "",
    },
    selected_node_provenance: selectedNode ? graphSelectedNodeExportProvenance(selectedNode) : {},
    selected_edge_provenance: selectedEdge ? graphSelectedEdgeExportProvenance(selectedEdge) : {},
    selected_node_review_history: selectedNodeHistory.map((review) => ({
      path: review.path || "",
      edge_key: review.edge_key || "",
      decision: review.decision || "",
      relation_type: review.relation_type || review.edge_type || "",
      confidence: String(graphEdgeConfidencePercent(review) || review.confidence || ""),
      source: review.source || "",
      target: review.target || "",
      actor: review.actor || "",
      reviewed_at: review.reviewed_at || "",
      note: review.note || "",
    })),
  };
}

function buildGraphSnapshotJson() {
  const graph = state.okfGraph || {};
  const visibleNodes = filteredGraphNodes();
  const visibleNodeKeys = new Set(visibleNodes.map((node) => node.node_key));
  const visibleEdges = applyGraphEdgeFilters(graph.edges || [])
    .filter((edge) => visibleNodeKeys.has(edge.source) && visibleNodeKeys.has(edge.target));
  const selectedNodePacket = selectedGraphContextPacket();
  const selectedEdge = (graph.edges || []).find((edge) => edge.edge_key === state.selectedGraphEdgeKey);
  const nodeMap = new Map((graph.nodes || []).map((node) => [node.node_key, node]));
  return {
    schema: "meids.okf.graph.snapshot.v1",
    exported_at: new Date().toISOString(),
    exported_from: "MeIDs Knowledge Graph cockpit",
    twin: state.activeTwin,
    graph_snapshot_hash: graph.snapshot_hash || "",
    okf_graph_version: graph.okf_graph_version || "",
    okf_version: graph.okf_version || "",
    summary: graph.summary || {},
    export_context: graphExportContext(),
    visible_projection: {
      nodes: visibleNodes.map((node) => ({
        node_key: node.node_key || "",
        title: node.title || "",
        node_type: node.node_type || "",
        review_state: node.review_state || "",
        cluster: node.cluster || node.metadata?.cluster || "",
        path: node.path || node.okf_path || "",
      })),
      edges: visibleEdges.map((edge) => ({
        edge_key: edge.edge_key || "",
        relation_type: edge.relation_type || edge.edge_type || "",
        review_state: edge.review_state || "unreviewed",
        confidence: edge.confidence,
        source: edge.source || "",
        source_title: nodeMap.get(edge.source)?.title || edge.source || "",
        target: edge.target || "",
        target_title: nodeMap.get(edge.target)?.title || edge.target || "",
        actor_use: graphEdgeUsagePolicy(edge).label,
      })),
    },
    selected_node_context: selectedNodePacket || {},
    selected_edge_context: selectedEdge ? graphSelectedEdgeExportProvenance(selectedEdge) : {},
    runtime_guidance: [
      "This is a frontend graph snapshot for review, AI context, and handoff.",
      "It does not approve concepts, mutate graph state, or execute tools.",
      "Use selected_node_context and selected_edge_context as bounded Actor Twin context.",
      "Candidate or unreviewed edges require human/curator review before autonomous reliance.",
    ],
  };
}

function formatGraphProjectionExplainPrompt(snapshot = buildGraphSnapshotJson()) {
  const visible = snapshot.visible_projection || {};
  const nodes = visible.nodes || [];
  const edges = visible.edges || [];
  const edgeClasses = countBy(edges, (edge) => graphEdgeClass(edge));
  const reviewStates = countBy(nodes, (node) => node.review_state || "unknown");
  const topNodes = [...nodes]
    .sort((a, b) => String(a.review_state || "").localeCompare(String(b.review_state || "")))
    .slice(0, 8);
  const topEdges = [...edges]
    .sort((a, b) => Number(b.confidence || 0) - Number(a.confidence || 0))
    .slice(0, 8);
  const lines = [
    "## OKF graph projection explanation request",
    `Twin: ${snapshot.twin || state.activeTwin}`,
    `Snapshot: ${snapshot.graph_snapshot_hash || "-"}`,
    `View: ${snapshot.export_context?.view?.reasoning_preset || state.graphReasoningPreset}; ${snapshot.export_context?.view?.layout_mode || state.graphLayoutMode}; drafts ${state.graphIncludeDrafts ? "included" : "excluded"}`,
    "",
    "### Projection summary",
    `- Visible nodes: ${nodes.length}`,
    `- Visible relations: ${edges.length}`,
    `- Approved nodes: ${reviewStates.approved || 0}`,
    `- Draft/pending/rework nodes: ${(reviewStates["pending-review"] || 0) + (reviewStates.draft || 0) + (reviewStates["needs-rework"] || 0)}`,
    `- Explicit relations: ${edgeClasses.explicit || 0}`,
    `- Inferred relations: ${edgeClasses.inferred || 0}`,
    `- Candidate relations: ${(edgeClasses.candidate || 0) + (edgeClasses["duplicate-candidate"] || 0) + (edgeClasses["contradiction-candidate"] || 0)}`,
    "",
    "### Important nodes",
  ];
  topNodes.forEach((node, index) => {
    lines.push(`${index + 1}. ${node.title || node.node_key} (${node.node_type || "node"}, ${node.review_state || "unknown"})`);
    if (node.path) lines.push(`   - Source: ${node.path}`);
  });
  lines.push("", "### Important relations");
  topEdges.forEach((edge, index) => {
    lines.push(`${index + 1}. ${edge.source_title || edge.source} -> ${edge.relation_type || "related"} -> ${edge.target_title || edge.target}`);
    lines.push(`   - Review: ${edge.review_state || "unreviewed"}; confidence: ${edge.confidence ?? "-"}; actor use: ${edge.actor_use || "-"}`);
  });
  lines.push("", "### Explain task");
  lines.push("- Explain what this projection tells the Actor Twin.");
  lines.push("- Distinguish approved knowledge, inferred bridges, and candidate/rework gates.");
  lines.push("- Recommend which paths are safe for answers, which need human review, and how this should influence skill activation.");
  return lines.join("\n");
}

async function explainGraphProjectionInChat() {
  if (!state.okfGraph?.nodes?.length) {
    showToast("Graph unavailable", "Refresh the knowledge graph before explaining a projection.", "error");
    return;
  }
  const snapshot = buildGraphSnapshotJson();
  const prompt = formatGraphProjectionExplainPrompt(snapshot);
  state.graphProjectionExplainPacket = {
    schema: "meids.okf.graph.projection_explain.v1",
    prepared_at: new Date().toISOString(),
    snapshot,
    prompt,
  };
  const context = $("#chatSkillKnowledge");
  if (!context) {
    showToast("Chat unavailable", "Open chat before applying the graph explanation request.", "error");
    return;
  }
  context.value = [context.value.trim(), prompt].filter(Boolean).join("\n\n");
  context.dispatchEvent(new Event("input", { bubbles: true }));
  setLegacyManualRequestValue("Explain this OKF knowledge graph projection and identify which paths the twin may use safely.");
  showView("chat");
  const details = $("#chatSkillContext");
  if (details) details.open = true;
  $("#n8nChatMount")?.scrollIntoView({ block: "center", behavior: "smooth" });
  try {
    const result = await postJson("/api/okf/graph/explain-trace", {
      twin: state.activeTwin,
      actor: "knowledge-graph-cockpit",
      prompt,
      snapshot,
    });
    state.graphProjectionExplainPacket.trace = result.trace || {};
    await safeRefreshActivity();
  } catch (error) {
    console.warn("Graph explain trace failed", error);
  }
  showToast("Projection explanation prepared", "Graph context is available to the embedded Actor Twin chat.", "success");
}

async function copyGraphSnapshotJson(button) {
  if (!state.okfGraph?.nodes?.length) {
    showToast("Graph snapshot unavailable", "Refresh the graph before copying JSON.", "error");
    return;
  }
  const copied = await copyTextToClipboard(JSON.stringify(buildGraphSnapshotJson(), null, 2));
  markButtonDone(button, copied ? "Copied" : "Copy failed");
  showToast(
    copied ? "Graph snapshot copied" : "Graph snapshot copy failed",
    copied ? "Current graph projection JSON is on the clipboard." : "Clipboard access failed.",
    copied ? "success" : "error",
  );
}

function downloadGraphSnapshotJson(button) {
  if (!state.okfGraph?.nodes?.length) {
    showToast("Graph snapshot unavailable", "Refresh the graph before downloading JSON.", "error");
    return;
  }
  const snapshot = buildGraphSnapshotJson();
  const filename = [
    "meids-graph-snapshot",
    safeGraphClass(state.activeTwin || "twin"),
    safeGraphClass(state.graphReasoningPreset || "graph"),
    new Date().toISOString().replace(/[:.]/g, "-"),
  ].join("-") + ".json";
  const blob = new Blob([JSON.stringify(snapshot, null, 2)], { type: "application/json;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  triggerDownload(url, filename);
  URL.revokeObjectURL(url);
  markButtonDone(button, "Downloaded");
  showToast("Graph snapshot JSON downloaded", filename, "success");
}

function graphSelectedNodeExportProvenance(node) {
  const graph = state.okfGraph || {};
  const graphEdges = graph.edges || [];
  const directEdges = graphEdges.filter((edge) => edge.source === node.node_key || edge.target === node.node_key);
  const evidenceEdges = directEdges.filter((edge) => {
    const relation = edge.relation_type || edge.edge_type || "";
    return relation === "derived_from" || edge.evidence_path || String(edge.source).startsWith("evidence:") || String(edge.target).startsWith("evidence:");
  });
  const governanceEdges = directEdges.filter((edge) => String(edge.relation_type || edge.edge_type || "").includes("candidate"));
  const readiness = graphNodeActorReadiness(node, evidenceEdges.length, governanceEdges, directEdges);
  return {
    node_key: node.node_key || "",
    title: node.title || "",
    node_type: node.node_type || "",
    review_state: node.review_state || "",
    path: node.path || node.okf_path || "",
    actor_readiness: `${readiness.label || ""} ${readiness.score ?? 0}%`.trim(),
    relation_count: String(directEdges.length),
    evidence_count: String(evidenceEdges.length),
    governance_gate_count: String(governanceEdges.length),
  };
}

function graphSelectedEdgeExportProvenance(edge) {
  const graph = state.okfGraph || {};
  const nodeMap = new Map((graph.nodes || []).map((node) => [node.node_key, node]));
  return {
    edge_key: edge.edge_key || "",
    relation_type: edge.relation_type || edge.edge_type || "",
    review_state: edge.review_state || "unreviewed",
    confidence: String(graphEdgeConfidencePercent(edge) || edge.confidence || ""),
    source: nodeMap.get(edge.source)?.title || edge.source || "",
    target: nodeMap.get(edge.target)?.title || edge.target || "",
    actor_use: graphEdgeUsagePolicy(edge).label || "",
  };
}

