function applyGraphReasoningPreset(preset) {
  const previousPreset = state.graphReasoningPreset || "custom";
  const settings = {
    explain: {
      includeDrafts: true,
      nodeType: "all",
      review: "all",
      edgeType: "all",
      density: "balanced",
      layout: "topology",
      focus: false,
      search: "",
    },
    decide: {
      includeDrafts: true,
      nodeType: "all",
      review: "all",
      edgeType: "contradiction_candidate",
      density: "spacious",
      layout: "decision",
      focus: false,
      search: "",
    },
    meeting: {
      includeDrafts: true,
      nodeType: "all",
      review: "all",
      edgeType: "derived_from",
      density: "balanced",
      layout: "evidence",
      focus: false,
      search: "meeting",
    },
    skill: {
      includeDrafts: true,
      nodeType: "all",
      review: "all",
      edgeType: "uses_context",
      density: "balanced",
      layout: "cluster",
      focus: false,
      search: "skill",
    },
    trusted: {
      includeDrafts: false,
      nodeType: "all",
      review: "approved",
      edgeType: "all",
      edgeClass: "explicit",
      density: "compact",
      layout: "evidence",
      focus: false,
      search: "",
    },
  }[preset];
  if (!settings) return;
  state.graphReasoningPreset = preset;
  state.graphPresetTransition = {
    from: previousPreset,
    to: preset,
    at: new Date().toISOString(),
  };
  state.graphIncludeDrafts = settings.includeDrafts;
  state.graphNodeTypeFilter = settings.nodeType;
  state.graphReviewFilter = settings.review;
  state.graphEdgeTypeFilter = settings.edgeType;
  state.graphEdgeClassFilter = settings.edgeClass || "all";
  state.graphDensityMode = settings.density;
  state.graphLayoutMode = settings.layout;
  state.graphFocusMode = settings.focus;
  state.graphZoom = 1;
  state.graphSearch = settings.search;
  state.selectedGraphNodeKey = "";
  state.selectedGraphEdgeKey = "";
  state.okfGraphNodeDetail = null;
  syncGraphControlValues();
  renderGraphCockpit();
  window.setTimeout(() => {
    if (state.graphPresetTransition?.to !== preset) return;
    state.graphPresetTransition = null;
    renderGraphCockpit();
  }, 3600);
}

