function applyGraphDemoStep(stepId) {
  const step = graphDemoSteps().find((item) => item.id === stepId) || graphDemoSteps()[0];
  state.graphDemoStep = step.id;
  applyGraphReasoningPreset(step.preset);
  window.setTimeout(() => {
    $("#graphCanvas")?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, 0);
}

function applyGraphTrustFilter(filter) {
  state.graphReasoningPreset = "custom";
  state.graphEdgeTypeFilter = "all";
  if (filter === "trusted") {
    state.graphReviewFilter = "all";
    state.graphEdgeClassFilter = "explicit";
  } else if (filter === "exploratory") {
    state.graphReviewFilter = "all";
    state.graphEdgeClassFilter = "inferred";
  } else if (filter === "candidate") {
    state.graphReviewFilter = "all";
    state.graphEdgeClassFilter = "candidate";
  } else if (filter === "blocked") {
    state.graphReviewFilter = "needs-rework";
    state.graphEdgeClassFilter = "all";
  } else {
    state.graphReviewFilter = "all";
    state.graphEdgeClassFilter = "all";
  }
  syncGraphControlValues();
  renderGraphCockpit();
}

function setGraphZoom(nextZoom) {
  state.graphZoom = Math.max(0.65, Math.min(1.45, Number(nextZoom) || 1));
  renderGraphCockpit();
}

function focusGraphOverviewNode(nodeKey) {
  if (!nodeKey) return;
  state.selectedGraphEdgeKey = "";
  state.graphFocusMode = true;
  state.graphReasoningPreset = "custom";
  syncGraphControlValues();
  openGraphNode(nodeKey);
}

function renderGraphCockpit() {
  const graph = state.okfGraph;
  $("#graph")?.classList.toggle("graph-story-active", state.graphLayoutMode === "story");
  $("#graph")?.classList.toggle("graph-decision-active", state.graphLayoutMode === "decision");
  $("#graph")?.classList.toggle("graph-list-active", state.graphViewMode === "list");
  renderGraphPresetControls();
  if (!graph) {
    $("#graphSummary").innerHTML = "";
    $("#graphTrustBoundary").innerHTML = "";
    $("#graphExportReadiness").innerHTML = "";
    $("#graphRetrievalContract").innerHTML = "";
    $("#graphPresetSignal").innerHTML = "";
    $("#graphInterpretationPanel").innerHTML = "";
    $("#graphTraceabilityPanel").innerHTML = "";
    $("#graphCanvas").innerHTML = renderEmptyState("Load the graph to inspect OKF relationships.");
    $("#graphQualityActions").innerHTML = "";
    $("#graphInsights").innerHTML = renderEmptyState("No graph insights loaded.");
    $("#graphRecommendationTasks").innerHTML = renderEmptyState("No graph recommendation tasks loaded.");
    $("#graphTools").innerHTML = renderEmptyState("No graph tools loaded.");
    return;
  }
  const baseNodes = filteredGraphNodes();
  const baseNodeKeys = new Set(baseNodes.map((node) => node.node_key));
  const baseEdges = (graph.edges || []).filter((edge) => baseNodeKeys.has(edge.source) && baseNodeKeys.has(edge.target));
  const projection = graphFocusProjection(baseNodes, baseEdges);
  const nodes = projection.nodes;
  const availableEdges = projection.edges;
  const edges = applyGraphEdgeFilters(availableEdges);
  renderGraphPrimaryNodeAction(nodes, availableEdges);
  renderGraphSummary(graph, nodes, edges);
  renderGraphTrustBoundary(graph, nodes, edges, availableEdges);
  renderGraphActorUseLanes(nodes, edges, availableEdges);
  renderGraphExportReadiness(graph, nodes, edges, availableEdges);
  renderGraphRetrievalContract(nodes, edges, availableEdges);
  renderGraphPresetTransitionPanel(nodes, edges);
  renderGraphInferenceVisual(graph, nodes, edges);
  renderGraphInterpretationPanel(graph, nodes, edges);
  renderGraphTraceabilityPanel(graph, nodes, edges);
  renderGraphCanvas(nodes, edges, availableEdges);
  renderGraphNodeDetail();
  renderGraphQualityActions(nodes, edges);
  renderGraphGovernanceQueue(graph, edges);
  renderGraphInsights(graph, nodes, edges);
  renderGraphRecommendationTasks();
  renderGraphTools(graph);
}

function renderGraphPrimaryNodeAction(nodes = [], edges = []) {
  const target = $("#graphPrimaryNodeAction");
  if (!target) return;
  const selected = nodes.find((node) => node.node_key === state.selectedGraphNodeKey);
  const topNode = selected || [...nodes]
    .sort((a, b) => graphNodeDegree(b, edges) - graphNodeDegree(a, edges))
    .find((node) => node.node_key);
  if (!topNode) {
    target.innerHTML = "";
    return;
  }
  target.innerHTML = `
    <button class="graph-primary-node-button ${safeGraphClass(topNode.review_state || "unknown")}" type="button" data-graph-node="${escapeHtml(topNode.node_key)}">
      <span>Inspect primary node</span>
      <strong>${escapeHtml(topNode.title || topNode.node_key)}</strong>
      <small>${escapeHtml(`${labelizeGraph(topNode.node_type || "node")} · ${topNode.review_state || "unknown"} · ${graphNodeDegree(topNode, edges)} visible relations`)}</small>
    </button>
    ${state.selectedGraphEdgeKey ? renderGraphEdgeWorkbench(nodes, edges) : ""}
    ${renderGraphNodeRelationLayerSummary(edges)}
  `;
  bindGraphRelationLayerControls(target);
  bindGraphEdgeReviewControls(target);
}

function renderGraphPresetTransitionPanel(nodes = [], edges = []) {
  const target = $("#graphPresetSignal");
  if (!target) return;
  const preset = graphPresetDefinition(state.graphReasoningPreset);
  const transition = state.graphPresetTransition;
  const relationTypes = countBy(edges, (edge) => edge.relation_type || edge.edge_type || "related");
  const topRelation = Object.entries(relationTypes).sort((a, b) => b[1] - a[1])[0];
  const modeLabel = preset?.label || labelizeGraph(state.graphReasoningPreset || "custom");
  const fromLabel = transition?.from ? labelizeGraph(transition.from) : "current";
  target.innerHTML = `
    <section class="graph-preset-signal ${transition ? "is-transitioning" : ""} ${safeGraphClass(state.graphReasoningPreset || "custom")}">
      <div>
        <span class="badge">${transition ? "Reasoning mode changed" : "Reasoning mode"}</span>
        <h3>${escapeHtml(modeLabel)}</h3>
        <p>${escapeHtml(preset?.purpose || "Custom projection based on current graph filters.")}</p>
      </div>
      <div class="graph-preset-route">
        <span>${escapeHtml(transition ? fromLabel : "OKF")}</span>
        <i></i>
        <strong>${escapeHtml(modeLabel)}</strong>
      </div>
      <dl>
        ${detailRow("Projection", `${escapeHtml(String(nodes.length))} nodes / ${escapeHtml(String(edges.length))} relations`)}
        ${detailRow("Focus", preset?.focus || (topRelation ? labelizeGraph(topRelation[0]) : "all relations"))}
        ${detailRow("Actor use", preset?.actorUse || "retrieve, explain, and cite governed knowledge")}
      </dl>
    </section>
    ${renderGraphReplaySignal(nodes, edges)}
  `;
}

function renderGraphReplaySignal(nodes = [], edges = []) {
  const replay = state.graphReplayContext;
  if (!replay?.packet) return "";
  const packetNodes = Array.isArray(replay.packet.nodes) ? replay.packet.nodes : [];
  const packetEdges = Array.isArray(replay.packet.edges) ? replay.packet.edges : [];
  const projection = replay.packet.projection || {};
  const matchedNodeCount = graphPacketNodeKeys(replay.packet).size ? nodes.length : 0;
  return `
    <section class="graph-replay-signal">
      <div>
        <span class="badge">Skill-run graph replay</span>
        <h3>${escapeHtml(replay.skillName || "Attached graph packet")}</h3>
        <p>${escapeHtml(replay.runId ? `Replaying graph context from ${replay.runId}.` : "Replaying a prepared graph packet.")}</p>
      </div>
      <dl>
        ${detailRow("Packet", `${packetNodes.length} nodes / ${packetEdges.length} relations`)}
        ${detailRow("Matched", `${matchedNodeCount} current graph nodes / ${edges.length} visible relations`)}
        ${detailRow("Projection", `${projection.preset || "skill"} / ${projection.layout || state.graphLayoutMode}`)}
      </dl>
      <button class="secondary small" type="button" data-graph-action="clear-replay">Clear replay</button>
    </section>
  `;
}

