function graphFocusProjection(nodes, edges) {
  if (!state.graphFocusMode || !state.selectedGraphNodeKey) return { nodes, edges };
  const nodeKeys = new Set(nodes.map((node) => node.node_key));
  if (!nodeKeys.has(state.selectedGraphNodeKey)) return { nodes, edges };
  const focusedKeys = new Set([state.selectedGraphNodeKey]);
  edges.forEach((edge) => {
    if (edge.source === state.selectedGraphNodeKey) focusedKeys.add(edge.target);
    if (edge.target === state.selectedGraphNodeKey) focusedKeys.add(edge.source);
  });
  const focusedNodes = nodes.filter((node) => focusedKeys.has(node.node_key));
  const focusedEdges = edges.filter((edge) => focusedKeys.has(edge.source) && focusedKeys.has(edge.target));
  return { nodes: focusedNodes, edges: focusedEdges };
}

function filteredGraphNodes() {
  const graph = state.okfGraph || {};
  const search = state.graphSearch.trim().toLowerCase();
  const replayKeys = graphPacketNodeKeys(state.graphReplayContext?.packet);
  const replayMatches = replayKeys.size
    ? (graph.nodes || []).filter((node) => replayKeys.has(node.node_key))
    : [];
  const sourceNodes = replayMatches.length ? replayMatches : (graph.nodes || []);
  return sourceNodes.filter((node) => {
    const typeOk = state.graphNodeTypeFilter === "all" || node.node_type === state.graphNodeTypeFilter;
    const reviewOk = state.graphReviewFilter === "all" || node.review_state === state.graphReviewFilter;
    const searchText = `${node.title || ""} ${node.summary || ""} ${node.cluster || ""} ${(node.tags || []).join(" ")}`.toLowerCase();
    return typeOk && reviewOk && (replayMatches.length || !search || searchText.includes(search));
  });
}

function graphPacketNodeKeys(packet) {
  const nodes = Array.isArray(packet?.nodes) ? packet.nodes : [];
  const edges = Array.isArray(packet?.edges) ? packet.edges : [];
  return new Set([
    ...nodes
      .map((node) => node.node_key || node.key || node.id || "")
      .filter(Boolean),
    ...edges.flatMap((edge) => [edge.source || "", edge.target || ""]).filter(Boolean),
  ]);
}

function graphPacketEdgeKeys(packet) {
  const edges = Array.isArray(packet?.edges) ? packet.edges : [];
  return new Set(
    edges
      .map((edge) => edge.edge_key || edge.key || edge.id || "")
      .filter(Boolean),
  );
}

function renderGraphSummary(graph, nodes, edges) {
  const summary = graph.summary || {};
  const states = countBy(nodes, (node) => node.review_state || "unknown");
  const edgeStates = countBy(edges, (edge) => edge.review_state || "unreviewed");
  const consumers = graphConsumerSummary(nodes, edges);
  $("#graphSummary").innerHTML = `
    <div><strong>${nodes.length}</strong><span>visible nodes</span></div>
    <div><strong>${edges.length}</strong><span>visible edges</span></div>
    <div><strong>${summary.approved_concepts || states.approved || 0}</strong><span>approved concepts</span></div>
    <div><strong>${edgeStates.unreviewed || 0}</strong><span>unreviewed edges</span></div>
    <div><strong>${escapeHtml(consumers.primary)}</strong><span>primary consumer</span></div>
    <div><strong>${state.okfGraphArtifact?.path ? "ready" : "local"}</strong><span>GitHub export</span></div>
  `;
}

function renderGraphTrustBoundary(graph, nodes = [], edges = [], availableEdges = edges) {
  const target = $("#graphTrustBoundary");
  if (!target) return;
  const nodeStates = countBy(nodes, (node) => node.review_state || "unknown");
  const edgeClasses = countBy(edges, (edge) => graphEdgeClass(edge));
  const trustLayers = graphTrustLayerSummary(edges);
  const availableTrustLayers = graphTrustLayerSummary(availableEdges);
  const approvedNodeRatio = nodes.length ? Math.round(((nodeStates.approved || 0) / nodes.length) * 100) : 0;
  const graphPath = graph?.artifact?.path || graph?.graph_artifact?.path || graph?.summary?.artifact_path || "";
  const tiles = [
    {
      key: "trusted",
      value: trustLayers.trusted,
      label: "trusted retrieval",
      detail: "approved or explicit evidence",
      className: "trusted",
    },
    {
      key: "exploratory",
      value: trustLayers.inferred,
      label: "inferred with caveat",
      detail: "attributed, not source fact",
      className: "inferred",
    },
    {
      key: "candidate",
      value: trustLayers.reviewable,
      label: "reviewable before use",
      detail: `${availableTrustLayers.reviewable} available in queue`,
      className: "candidate",
    },
    {
      key: "blocked",
      value: trustLayers.blocked + (nodeStates["needs-rework"] || 0) + (nodeStates.rejected || 0),
      label: "excluded until resolved",
      detail: "rejected, rework, or conflict",
      className: "blocked",
    },
  ];
  target.innerHTML = `
    <div class="graph-trust-boundary-main">
      <span class="badge">Trust boundary</span>
      <strong>${escapeHtml(`${approvedNodeRatio}% approved node basis`)}</strong>
      <small>${escapeHtml(`${nodes.length} visible nodes · ${edgeClasses.explicit || 0} explicit · ${edgeClasses.inferred || 0} inferred · ${graphPath ? "export ready" : "local snapshot"}`)}</small>
      <em>Only trusted retrieval is safe for direct Actor Twin answers. Inferred and reviewable layers need attribution or approval.</em>
    </div>
    <div class="graph-trust-boundary-grid">
      ${tiles.map((tile) => `
        <button class="${escapeHtml(tile.className)} ${graphTrustFilterActive(tile.key) ? "active" : ""}" type="button" data-graph-trust-filter="${escapeHtml(tile.key)}">
          <strong>${escapeHtml(String(tile.value))}</strong>
          <small>${escapeHtml(tile.label)}</small>
          <em>${escapeHtml(tile.detail)}</em>
        </button>
      `).join("")}
    </div>
  `;
}

function graphTrustLayerSummary(edges = []) {
  return edges.reduce((summary, edge) => {
    const trust = graphRelationTrust(edge).className;
    if (trust === "trusted") summary.trusted += 1;
    else if (trust === "exploratory") summary.inferred += 1;
    else if (trust === "blocked") summary.blocked += 1;
    else summary.reviewable += 1;
    return summary;
  }, {
    trusted: 0,
    inferred: 0,
    reviewable: 0,
    blocked: 0,
  });
}

function graphActorUseLaneSummary(nodes = [], edges = [], availableEdges = edges) {
  const nodeStates = countBy(nodes, (node) => node.review_state || "unknown");
  const edgeClasses = countBy(edges, (edge) => graphEdgeClass(edge));
  const availableClasses = countBy(availableEdges, (edge) => graphEdgeClass(edge));
  const approvedNodes = nodeStates.approved || 0;
  const draftNodes = Math.max(0, nodes.length - approvedNodes);
  const explicitEdges = edgeClasses.explicit || 0;
  const acceptedEdges = edges.filter((edge) => ["approved", "accepted"].includes(edge.review_state || "")).length;
  const inferredEdges = edgeClasses.inferred || 0;
  const candidateEdges = (edgeClasses.candidate || 0)
    + (edgeClasses["duplicate-candidate"] || 0)
    + (edgeClasses["contradiction-candidate"] || 0);
  const queuedCandidates = (availableClasses.candidate || 0)
    + (availableClasses["duplicate-candidate"] || 0)
    + (availableClasses["contradiction-candidate"] || 0);
  const blockedEdges = edges.filter((edge) => graphRelationTrust(edge).className === "blocked").length;
  const blockedNodes = (nodeStates["needs-rework"] || 0) + (nodeStates.rejected || 0);
  return [
    {
      className: "answer",
      label: "Answer",
      value: approvedNodes + explicitEdges + acceptedEdges,
      detail: `${approvedNodes} approved nodes · ${explicitEdges + acceptedEdges} trusted relations`,
      action: "Safe for direct Actor Twin grounding when cited.",
    },
    {
      className: "cite",
      label: "Cite",
      value: inferredEdges,
      detail: `${inferredEdges} inferred relation${inferredEdges === 1 ? "" : "s"}`,
      action: "Use as reasoning context with attribution and confidence.",
    },
    {
      className: "review",
      label: "Review",
      value: draftNodes + candidateEdges + queuedCandidates,
      detail: `${draftNodes} draft nodes · ${candidateEdges}/${queuedCandidates} candidate relations visible/queued`,
      action: "Promote, rework, or reject before trusted retrieval.",
    },
    {
      className: "block",
      label: "Block",
      value: blockedNodes + blockedEdges,
      detail: `${blockedNodes} blocked nodes · ${blockedEdges} blocked relations`,
      action: "Exclude from answers and skill context until resolved.",
    },
  ];
}

function renderGraphActorUseLanes(nodes = [], edges = [], availableEdges = edges) {
  const target = $("#graphActorUseLanes");
  if (!target) return;
  const lanes = graphActorUseLaneSummary(nodes, edges, availableEdges);
  const total = Math.max(1, lanes.reduce((sum, lane) => sum + Number(lane.value || 0), 0));
  target.innerHTML = `
    <div class="graph-actor-use-lanes-head">
      <span class="badge">Actor graph use</span>
      <strong>${escapeHtml(`${nodes.length} nodes · ${edges.length} active relations`)}</strong>
      <small>Operational policy for how the Actor Twin may use this graph projection.</small>
    </div>
    <div class="graph-actor-use-lanes-grid">
      ${lanes.map((lane) => {
        const percent = Math.round((Number(lane.value || 0) / total) * 100);
        return `
          <article class="graph-actor-use-lane ${escapeHtml(lane.className)}">
            <div>
              <strong>${escapeHtml(String(lane.value))}</strong>
              <span>${escapeHtml(lane.label)}</span>
            </div>
            <small>${escapeHtml(`${percent}% · ${lane.detail}`)}</small>
            <em>${escapeHtml(lane.action)}</em>
          </article>
        `;
      }).join("")}
    </div>
  `;
}

function renderGraphRetrievalContract(nodes = [], edges = [], availableEdges = edges) {
  const target = $("#graphRetrievalContract");
  if (!target) return;
  const nodeStates = countBy(nodes, (node) => node.review_state || "unknown");
  const visibleTrust = graphTrustLayerSummary(edges);
  const availableTrust = graphTrustLayerSummary(availableEdges);
  const approvedNodes = nodeStates.approved || 0;
  const draftNodes = Math.max(0, nodes.length - approvedNodes);
  const trustedContext = approvedNodes + visibleTrust.trusted;
  const citedContext = visibleTrust.inferred;
  const reviewQueue = visibleTrust.reviewable + availableTrust.reviewable;
  const blockedContext = visibleTrust.blocked + (nodeStates["needs-rework"] || 0) + (nodeStates.rejected || 0);
  const mode = trustedContext && !reviewQueue && !blockedContext
    ? "production"
    : trustedContext
      ? "governed"
      : "exploratory";
  const lanes = [
    {
      className: "answer",
      value: trustedContext,
      label: "answer",
      detail: "Approved concepts and explicit edges may ground direct Actor Twin answers.",
    },
    {
      className: "cite",
      value: citedContext,
      label: "cite",
      detail: "Inferred paths can be shown as reasoning context with attribution.",
    },
    {
      className: "review",
      value: reviewQueue,
      label: "review",
      detail: "Candidate relations remain Knowledge Fabric review work, not actor memory.",
    },
    {
      className: "exclude",
      value: blockedContext,
      label: "exclude",
      detail: "Rejected, rework, and conflict paths stay out of retrieval.",
    },
  ];
  target.innerHTML = `
    <section class="graph-retrieval-contract-panel ${safeGraphClass(mode)}">
      <div class="graph-retrieval-contract-head">
        <div>
          <span class="badge">Actor retrieval contract</span>
          <strong>${escapeHtml(mode === "production" ? "Trusted graph context can answer directly" : mode === "governed" ? "Graph can answer with governance gates" : "Graph is exploratory until review improves")}</strong>
          <p>${escapeHtml(`${approvedNodes}/${nodes.length} approved nodes · ${draftNodes} draft or pending nodes · ${edges.length}/${availableEdges.length} active relations`)}</p>
        </div>
        <span>${escapeHtml(labelizeGraph(mode))}</span>
      </div>
      ${renderCompactAgentBoundary(["actor_twin", "knowledge_fabric_agent"], {
        label: "Graph agent boundary",
        detail: "Actor Twin can use governed graph context; Knowledge Fabric Agent still owns relation promotion and source updates.",
      })}
      <div class="graph-retrieval-contract-flow">
        ${lanes.map((lane) => `
          <article class="${escapeHtml(lane.className)}">
            <strong>${escapeHtml(String(lane.value))}</strong>
            <span>${escapeHtml(lane.label)}</span>
            <small>${escapeHtml(lane.detail)}</small>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

