function renderGraphCanvas(nodes, edges, availableEdges = edges) {
  const target = $("#graphCanvas");
  if (!nodes.length) {
    target.innerHTML = renderEmptyState("No graph nodes match the current filters.");
    return;
  }
  if (state.graphViewMode === "list") {
    renderGraphListCanvas(target, nodes, edges, availableEdges);
    return;
  }
  if (state.graphLayoutMode === "story") {
    renderGraphStoryCanvas(target, nodes, edges, availableEdges);
    return;
  }
  if (state.graphLayoutMode === "decision") {
    renderGraphDecisionPathCanvas(target, nodes, edges, availableEdges);
    return;
  }
  const edgeCounts = countBy(availableEdges, (edge) => edge.relation_type || edge.edge_type || "related");
  const nodesByType = graphGroupBy(nodes, (node) => node.node_type || "node");
  const totalEdgeCount = availableEdges.length;
  const allChip = `
    <button
      class="graph-relation-chip ${state.graphEdgeTypeFilter === "all" ? "active" : ""}"
      type="button"
      data-graph-edge-filter="all"
      title="Show all visible relationship types"
    >All relations · ${totalEdgeCount}</button>
  `;
  const edgeMarkup = Object.entries(edgeCounts)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(
      ([type, count]) => `
        <button
          class="graph-relation-chip graph-edge-${safeGraphClass(type)} ${state.graphEdgeTypeFilter === type ? "active" : ""}"
          type="button"
          data-graph-edge-filter="${escapeHtml(type)}"
          title="Filter to ${escapeHtml(labelizeGraph(type))} relationships"
        >${escapeHtml(labelizeGraph(type))} · ${count}</button>
      `,
    )
    .join("");
  const activePath = graphActiveReasoningPath(nodes, edges, availableEdges);
  const displayEdges = graphTopologyDisplayEdges(nodes, edges, availableEdges, activePath);
  const topology = graphTopology(nodes, displayEdges, state.graphDensityMode, state.graphLayoutMode);
  const zoneSvg = (topology.zones || []).map((zone) => renderGraphSvgZone(zone)).join("");
  const edgeHitSvg = displayEdges
    .filter((edge) => topology.positions.has(edge.source) && topology.positions.has(edge.target))
    .map((edge) => renderGraphSvgEdge(edge, topology.positions, "hit"))
    .join("");
  const edgeSvg = displayEdges
    .filter((edge) => topology.positions.has(edge.source) && topology.positions.has(edge.target))
    .map((edge) => renderGraphSvgEdge(edge, topology.positions, "visible", activePath))
    .join("");
  const nodeSvg = nodes
    .filter((node) => topology.positions.has(node.node_key))
    .map((node) => renderGraphSvgNode(node, topology.positions.get(node.node_key), displayEdges, activePath, topology))
    .join("");
  const edgeLabelSvg = displayEdges
    .filter((edge) => topology.positions.has(edge.source) && topology.positions.has(edge.target))
    .map((edge) => renderGraphSvgEdgeLabel(edge, topology.positions, activePath))
    .join("");
  const laneMarkup = topology.lanes
    .map((lane) => `<span class="graph-lane-dot ${safeGraphClass(lane.type)}"><i></i>${escapeHtml(labelizeGraph(lane.type))} · ${lane.count}</span>`)
    .join("");
  const topConnected = [...nodes]
    .sort((a, b) => graphNodeDegree(b, displayEdges) - graphNodeDegree(a, displayEdges))
    .slice(0, 9)
    .map((node) => `
      <button class="graph-node-list-item ${safeGraphClass(node.review_state || "unknown")}" type="button" data-graph-node="${escapeHtml(node.node_key)}">
        <span>${escapeHtml(labelizeGraph(node.node_type || "node"))} · ${escapeHtml(String(graphNodeDegree(node, displayEdges)))} visible links</span>
        <strong>${escapeHtml(node.title || node.node_key)}</strong>
      </button>
    `)
    .join("");
  const hoverInspector = renderGraphHoverInspectorMarkup(nodes, displayEdges);
  const edgeWorkbench = renderGraphEdgeWorkbench(nodes, displayEdges);
  const semanticLegend = renderGraphSemanticLegend(nodes, displayEdges, activePath);
  const actorUseMap = renderGraphActorUseMap(nodes, displayEdges);
  const selectedNode = nodes.find((node) => node.node_key === state.selectedGraphNodeKey);
  const focusLabel = state.graphFocusMode
    ? selectedNode
      ? `Focused on ${selectedNode.title || selectedNode.node_key}`
      : "Focus mode waiting for a node"
    : `${labelizeGraph(state.graphLayoutMode)} layout`;
  const activeFilterCount = [
    state.graphNodeTypeFilter !== "all",
    state.graphEdgeTypeFilter !== "all",
    state.graphReviewFilter !== "all",
    Boolean(state.graphSearch),
    state.graphFocusMode,
    state.graphEdgeClassFilter !== "all",
    state.graphLayoutMode !== "topology",
  ].filter(Boolean).length;
  target.innerHTML = `
    <div class="graph-map graph-topology-map layout-${safeGraphClass(state.graphLayoutMode)}">
      <div class="graph-canvas-commandbar">
        <div>
          <span class="badge">Interactive topology</span>
          <strong>${escapeHtml(focusLabel)}</strong>
          <small>${nodes.length} nodes · ${displayEdges.length}/${edges.length} relation lines · ${activeFilterCount} filters</small>
        </div>
        <div class="graph-viewport-actions" aria-label="Graph viewport controls">
          <button class="secondary small" type="button" data-graph-action="zoom-out" title="Zoom out">−</button>
          <span>${Math.round(state.graphZoom * 100)}%</span>
          <button class="secondary small" type="button" data-graph-action="zoom-in" title="Zoom in">+</button>
          <button class="secondary small" type="button" data-graph-action="fit">Fit</button>
          <button class="secondary small" type="button" data-graph-action="copy-json">Copy JSON</button>
          <button class="secondary small" type="button" data-graph-action="download-json">JSON</button>
          <button class="secondary small" type="button" data-graph-action="present">Present</button>
          <button class="secondary small" type="button" data-graph-action="download-svg">SVG</button>
          <button class="secondary small" type="button" data-graph-action="download-png">PNG</button>
          <button class="secondary small" type="button" data-graph-action="reset">Reset view</button>
        </div>
      </div>
      ${edgeWorkbench}
      <div class="graph-relation-strip">${totalEdgeCount ? `${allChip}${edgeMarkup}` : "<span>No visible relations</span>"}</div>
      ${renderGraphNodeRelationLayerSummary(displayEdges)}
      ${renderGraphProjectionSummary(displayEdges, edges, activePath)}
      <div class="graph-lane-strip">${laneMarkup}</div>
      ${semanticLegend}
      ${actorUseMap}
      <div id="graphHoverInspector" class="graph-hover-inspector">${hoverInspector}</div>
      ${renderGraphActivePathCallout(activePath)}
      ${renderGraphOverviewPanel(topology, nodes, displayEdges, activePath, edges.length)}
      <div class="graph-topology-shell">
        <svg class="graph-topology-svg" style="--graph-zoom: ${state.graphZoom}; --graph-svg-width: ${topology.width}px;" viewBox="0 0 ${topology.width} ${topology.height}" role="img" aria-label="Interactive OKF knowledge graph topology">
          <defs>
            <marker id="graphArrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto">
              <path d="M0,0 L8,4 L0,8 Z"></path>
            </marker>
          </defs>
          <g class="graph-svg-zones">${zoneSvg}</g>
          <g class="graph-svg-edge-hits">${edgeHitSvg}</g>
          <g class="graph-svg-edges">${edgeSvg}</g>
          <g class="graph-svg-nodes">${nodeSvg}</g>
          <g class="graph-svg-edge-labels">${edgeLabelSvg}</g>
        </svg>
      </div>
      <div class="graph-node-rail">
        <strong>Most connected</strong>
        ${topConnected}
      </div>
    </div>
  `;
  bindGraphEdgeLabelClicks(target);
  bindGraphRelationLayerControls(target);
  bindGraphEdgeReviewControls(target);
}

function graphTopologyDisplayEdges(nodes = [], edges = [], availableEdges = edges, activePath = null) {
  if (state.graphLayoutMode !== "topology") return edges;
  const filterActive = state.graphEdgeTypeFilter !== "all"
    || state.graphEdgeClassFilter !== "all"
    || state.graphReviewFilter !== "all"
    || Boolean(state.graphSearch.trim())
    || Boolean(state.graphFocusMode)
    || Boolean(state.selectedGraphEdgeKey);
  const limit = { compact: 42, balanced: 58, spacious: 82 }[state.graphDensityMode] || 58;
  if (filterActive || edges.length <= limit) return edges;
  const nodeMap = new Map(nodes.map((node) => [node.node_key, node]));
  const activeEdgeKey = activePath?.edgeKey || activePath?.edge?.edge_key || "";
  const degreeMap = new Map();
  edges.forEach((edge) => {
    degreeMap.set(edge.source, (degreeMap.get(edge.source) || 0) + 1);
    degreeMap.set(edge.target, (degreeMap.get(edge.target) || 0) + 1);
  });
  const scoreEdge = (edge) => {
    const edgeClass = graphEdgeClass(edge);
    const review = String(edge.review_state || "unreviewed");
    const relation = String(edge.relation_type || edge.edge_type || "");
    const source = nodeMap.get(edge.source) || {};
    const target = nodeMap.get(edge.target) || {};
    let score = graphEdgeConfidencePercent(edge);
    if (edge.edge_key === activeEdgeKey) score += 10000;
    if (edge.edge_key === state.selectedGraphEdgeKey) score += 9500;
    if (edgeClass === "explicit") score += 140;
    if (edgeClass === "inferred") score += 52;
    if (edgeClass.includes("candidate")) score += 170;
    if (review === "needs-rework") score += 130;
    if (review === "accepted" || review === "approved") score += 70;
    if (source.review_state === "approved") score += 32;
    if (target.review_state === "approved") score += 32;
    if (source.node_type === "cluster" || target.node_type === "cluster") score += 45;
    if (relation === "member_of_cluster") score += 34;
    score += Math.min(80, ((degreeMap.get(edge.source) || 0) + (degreeMap.get(edge.target) || 0)) * 3);
    return score;
  };
  const selectedKeys = new Set([...edges]
    .sort((a, b) => scoreEdge(b) - scoreEdge(a))
    .slice(0, limit)
    .map((edge) => edge.edge_key));
  return edges.filter((edge) => selectedKeys.has(edge.edge_key));
}

function renderGraphProjectionSummary(displayEdges = [], allEdges = [], activePath = null) {
  const reduced = displayEdges.length < allEdges.length;
  const edgeClasses = countBy(displayEdges, (edge) => graphEdgeClass(edge));
  return `
    <section class="graph-projection-summary ${reduced ? "reduced" : "complete"}">
      <div>
        <span class="badge">${reduced ? "Curated projection" : "Complete projection"}</span>
        <strong>${escapeHtml(String(displayEdges.length))}/${escapeHtml(String(allEdges.length))} relation lines shown</strong>
        <small>${escapeHtml(reduced ? "Topology mode suppresses low-signal lines until you search, select, or filter." : "All currently active relation lines are visible.")}</small>
      </div>
      <div class="graph-projection-chips">
        <span>${escapeHtml(String(edgeClasses.explicit || 0))} explicit</span>
        <span>${escapeHtml(String(edgeClasses.inferred || 0))} inferred</span>
        <span>${escapeHtml(String((edgeClasses.candidate || 0) + (edgeClasses["duplicate-candidate"] || 0) + (edgeClasses["contradiction-candidate"] || 0)))} candidates</span>
        ${activePath ? `<span>1 active path</span>` : ""}
        <button class="secondary small" type="button" data-graph-action="explain-projection">Explain projection</button>
      </div>
    </section>
  `;
}

function renderGraphActorUseMap(nodes = [], edges = []) {
  const nodeStates = countBy(nodes, (node) => node.review_state || "unknown");
  const edgeClasses = countBy(edges, (edge) => graphEdgeClass(edge));
  const approved = nodeStates.approved || 0;
  const draft = nodes.length - approved;
  const explicit = edgeClasses.explicit || 0;
  const inferred = edgeClasses.inferred || 0;
  const candidates =
    (edgeClasses.candidate || 0)
    + (edgeClasses["duplicate-candidate"] || 0)
    + (edgeClasses["contradiction-candidate"] || 0);
  const readiness = graphActorUseReadiness(approved, draft, explicit, inferred, candidates);
  return `
    <section class="graph-actor-use-map ${safeGraphClass(readiness.level)}" aria-label="Actor use map">
      <div class="graph-actor-use-head">
        <span class="badge">Actor-use map</span>
        <strong>${escapeHtml(readiness.label)}</strong>
        <small>${escapeHtml(readiness.detail)}</small>
      </div>
      <div class="graph-actor-use-flow">
        <article class="approved-memory">
          <span>${escapeHtml(String(approved))}</span>
          <strong>Approved memory</strong>
          <small>Safe grounding layer</small>
        </article>
        <i></i>
        <article class="inference-bridge">
          <span>${escapeHtml(String(inferred))}</span>
          <strong>Inference bridge</strong>
          <small>Useful with citations</small>
        </article>
        <i></i>
        <article class="governance-risk">
          <span>${escapeHtml(String(candidates + draft))}</span>
          <strong>Review gates</strong>
          <small>Human approval before steering</small>
        </article>
      </div>
      <div class="graph-actor-use-proof">
        <span>${escapeHtml(String(explicit))} explicit edges</span>
        <span>${escapeHtml(String(inferred))} inferred edges</span>
        <span>${escapeHtml(String(candidates))} candidate edges</span>
      </div>
    </section>
  `;
}

function graphActorUseReadiness(approved = 0, draft = 0, explicit = 0, inferred = 0, candidates = 0) {
  if (candidates > 0) {
    return {
      level: "needs-review",
      label: "Use with governance",
      detail: "Candidate relations are visible. The twin should cite sources and avoid autonomous decisions on unresolved paths.",
    };
  }
  if (approved > 0 && explicit >= inferred) {
    return {
      level: "ready",
      label: "Grounded for actor use",
      detail: "Approved concepts and explicit relations dominate this view.",
    };
  }
  return {
    level: "caution",
    label: "Use as exploratory context",
    detail: "Draft or inferred context is useful for recall, but should be checked before decision steering.",
  };
}

function renderGraphListCanvas(target, nodes, edges, availableEdges = edges) {
  const edgeCounts = countBy(availableEdges, (edge) => edge.relation_type || edge.edge_type || "related");
  const activePath = graphActiveReasoningPath(nodes, edges, availableEdges);
  const activeFilterCount = [
    state.graphNodeTypeFilter !== "all",
    state.graphEdgeTypeFilter !== "all",
    state.graphReviewFilter !== "all",
    Boolean(state.graphSearch),
    state.graphFocusMode,
    state.graphEdgeClassFilter !== "all",
    state.graphLayoutMode !== "topology",
  ].filter(Boolean).length;
  const sortedNodes = [...nodes]
    .sort((a, b) => {
      const reviewWeight = graphReviewSortWeight(a.review_state) - graphReviewSortWeight(b.review_state);
      if (reviewWeight) return reviewWeight;
      return graphNodeDegree(b, edges) - graphNodeDegree(a, edges) || String(a.title || "").localeCompare(String(b.title || ""));
    })
    .slice(0, state.graphDensityMode === "compact" ? 18 : 28);
  const relationChips = Object.entries(edgeCounts)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, 8)
    .map(([type, count]) => `<span>${escapeHtml(labelizeGraph(type))} · ${count}</span>`)
    .join("");
  target.innerHTML = `
    <div class="graph-list-view">
      <div class="graph-canvas-commandbar">
        <div>
          <span class="badge">Compact graph</span>
          <strong>Evidence-first list</strong>
          <small>${nodes.length} nodes · ${edges.length} active edges · ${activeFilterCount} filters</small>
        </div>
        <div class="graph-viewport-actions" aria-label="Graph list controls">
          <button class="secondary small" type="button" data-graph-action="present">Present</button>
          <button class="secondary small" type="button" data-graph-action="download-json">JSON</button>
          <button class="secondary small" type="button" data-graph-action="download-svg">SVG</button>
          <button class="secondary small" type="button" data-graph-action="download-png">PNG</button>
          <button class="secondary small" type="button" data-graph-action="reset">Reset view</button>
        </div>
      </div>
      <div class="graph-list-summary">
        <div>
          <strong>${escapeHtml(String(sortedNodes.length))}</strong>
          <span>shown from ${escapeHtml(String(nodes.length))}</span>
        </div>
        <div>
          <strong>${escapeHtml(String(edges.length))}</strong>
          <span>active relations</span>
        </div>
        <div>
          <strong>${escapeHtml(activePath ? labelizeGraph(activePath.preset) : "none")}</strong>
          <span>reasoning path</span>
        </div>
      </div>
      ${relationChips ? `<div class="graph-list-relation-strip">${relationChips}</div>` : ""}
      <div class="graph-list-items">
        ${sortedNodes.map((node) => renderGraphListNode(node, edges)).join("")}
      </div>
    </div>
  `;
}

function graphReviewSortWeight(reviewState = "") {
  return {
    "needs-rework": 0,
    needs_rework: 0,
    "pending-review": 1,
    pending_review: 1,
    draft: 2,
    approved: 3,
  }[reviewState] ?? 4;
}

function renderGraphListNode(node, edges = []) {
  const degree = graphNodeDegree(node, edges);
  const outbound = edges.filter((edge) => edge.source === node.node_key).slice(0, 3);
  const inbound = edges.filter((edge) => edge.target === node.node_key).slice(0, 3);
  const relations = [...outbound, ...inbound]
    .slice(0, 4)
    .map((edge) => {
      const direction = edge.source === node.node_key ? "to" : "from";
      const otherKey = edge.source === node.node_key ? edge.target : edge.source;
      return `<button class="small secondary" type="button" data-graph-edge="${escapeHtml(edge.edge_key || "")}" title="${escapeHtml(otherKey)}">${escapeHtml(labelizeGraph(edge.relation_type || edge.edge_type || "related"))} ${escapeHtml(direction)}</button>`;
    })
    .join("");
  return `
    <article class="graph-list-node ${safeGraphClass(node.review_state || "unknown")} ${safeGraphClass(node.node_type || "node")}">
      <div class="graph-list-node-main">
        <span class="badge">${escapeHtml(labelizeGraph(node.node_type || "node"))}</span>
        <strong>${escapeHtml(node.title || node.node_key)}</strong>
        <p>${escapeHtml(node.summary || node.description || "No summary stored.")}</p>
        ${renderGraphConsumerBadges(node)}
      </div>
      <div class="graph-list-node-meta">
        <span>${escapeHtml(node.review_state || "unknown")}</span>
        <span>${degree} links</span>
        <span>${escapeHtml(node.cluster || node.metadata?.cluster || "unclustered")}</span>
      </div>
      <div class="graph-edge-review-actions">
        <button class="small secondary" type="button" data-graph-node="${escapeHtml(node.node_key)}">Inspect node</button>
        ${node.path ? `<button class="small secondary" type="button" data-concept-open="${escapeHtml(node.path)}">Open concept</button>` : ""}
        ${relations}
      </div>
    </article>
  `;
}

function bindGraphEdgeLabelClicks(root) {
  if (!root) return;
  root.querySelectorAll(".graph-svg-edge-label[data-graph-edge]").forEach((label) => {
    label.setAttribute("tabindex", "0");
    label.setAttribute("role", "button");
    label.setAttribute("aria-label", `Review graph relation ${label.textContent.trim()}`);
    const handler = (event) => {
      event.preventDefault();
      event.stopPropagation();
      selectGraphEdgeForReview(label.dataset.graphEdge || "", "label");
    };
    label.addEventListener("click", handler);
    label.addEventListener("pointerup", handler);
    label.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") handler(event);
    });
    label.querySelectorAll("rect, text").forEach((child) => child.addEventListener("click", handler));
  });
}

function bindGraphRelationLayerControls(root) {
  if (!root) return;
  root.querySelectorAll(".graph-relation-layer-summary [data-graph-edge-class-filter]").forEach((button) => {
    if (button.dataset.graphLayerBound === "true") return;
    button.dataset.graphLayerBound = "true";
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      state.graphReasoningPreset = "custom";
      state.graphEdgeClassFilter = button.dataset.graphEdgeClassFilter || "all";
      renderGraphCockpit();
    });
  });
}

function bindGraphEdgeReviewControls(root) {
  if (!root) return;
  root.querySelectorAll("[data-graph-edge-action]").forEach((button) => {
    if (button.dataset.graphEdgeReviewBound === "true") return;
    button.dataset.graphEdgeReviewBound = "true";
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      reviewGraphEdge(button.dataset.graphEdgeKey || "", button.dataset.graphEdgeAction || "");
    });
  });
}

function renderGraphSemanticLegend(nodes, edges, activePath = null) {
  const nodeStates = countBy(nodes, (node) => node.review_state || "unknown");
  const edgeClasses = countBy(edges, (edge) => graphEdgeClass(edge));
  const candidateCount = (edgeClasses.candidate || 0) + (edgeClasses["duplicate-candidate"] || 0) + (edgeClasses["contradiction-candidate"] || 0);
  const approved = nodeStates.approved || 0;
  const draft = (nodeStates["pending-review"] || nodeStates.pending_review || 0)
    + (nodeStates.draft || 0)
    + (nodeStates["needs-rework"] || nodeStates.needs_rework || 0);
  const confidenceBands = ["high", "medium", "low", "unscored"].map((key) => {
    const meta = graphConfidenceBandMeta(key);
    return { ...meta, count: edges.filter((edge) => graphEdgeConfidenceBand(edge).key === key).length };
  });
  const usePolicies = [
    {
      className: "ready",
      label: "Answer",
      detail: "approved + explicit",
      value: `${approved}/${nodes.length}`,
    },
    {
      className: "cite",
      label: "Explore",
      detail: "inferred with citation",
      value: String(edgeClasses.inferred || 0),
    },
    {
      className: "review",
      label: "Gate",
      detail: "drafts + candidates",
      value: String(candidateCount + draft),
    },
  ];
  const items = [
    {
      icon: '<i class="legend-node approved"></i>',
      label: "Approved",
      value: approved,
      detail: "usable as primary actor evidence",
      className: "approved",
    },
    {
      icon: '<i class="legend-node pending-review"></i>',
      label: "Draft",
      value: nodeStates["pending-review"] || nodeStates.pending_review || 0,
      detail: "visible but human review pending",
      className: "pending-review",
    },
    {
      icon: '<i class="legend-node needs-rework"></i>',
      label: "Rework",
      value: nodeStates["needs-rework"] || nodeStates.needs_rework || 0,
      detail: "do not rely on without correction",
      className: "needs-rework",
    },
    {
      icon: '<i class="legend-edge explicit"></i>',
      label: "Explicit",
      value: edgeClasses.explicit || 0,
      detail: "source-backed relation",
      className: "explicit",
      filter: "explicit",
    },
    {
      icon: '<i class="legend-edge inferred"></i>',
      label: "Inferred",
      value: edgeClasses.inferred || 0,
      detail: "AI-derived retrieval bridge",
      className: "inferred",
      filter: "inferred",
    },
    {
      icon: '<i class="legend-edge candidate"></i>',
      label: "Candidate",
      value: candidateCount,
      detail: "govern before actor reliance",
      className: "candidate",
      filter: "candidate",
    },
    {
      icon: '<i class="legend-edge duplicate-candidate"></i>',
      label: "Duplicate",
      value: edgeClasses["duplicate-candidate"] || 0,
      detail: "merge or keep separate",
      className: "duplicate-candidate",
      filter: "duplicate-candidate",
    },
    {
      icon: '<i class="legend-edge contradiction-candidate"></i>',
      label: "Contradiction",
      value: edgeClasses["contradiction-candidate"] || 0,
      detail: "resolve before decisions",
      className: "contradiction-candidate",
      filter: "contradiction-candidate",
    },
  ];
  if (activePath) {
    items.unshift({
      icon: '<i class="legend-edge active-path"></i>',
      label: "Active path",
      value: 1,
      detail: `${labelizeGraph(activePath.preset)} reasoning route`,
      className: "active-path",
    });
  }
  return `
    <section class="graph-legend semantic compact-control" aria-label="Knowledge graph layer controls">
      <div class="graph-legend-head">
        <div>
          <span class="badge">Graph layers</span>
          <strong>${escapeHtml(nodes.length)} nodes · ${escapeHtml(edges.length)} relations</strong>
        </div>
        <small>${escapeHtml(state.graphEdgeClassFilter === "all" ? "All relation layers" : `Filtered: ${labelizeGraph(state.graphEdgeClassFilter)}`)}</small>
      </div>
      <div class="graph-legend-items">
        ${items.map(renderGraphLegendItem).join("")}
      </div>
      <div class="graph-legend-bottom">
        <div class="graph-legend-trust-row" aria-label="Graph trust boundary">
          <span class="trusted"><strong>Trusted</strong><small>approved nodes + accepted or explicit source-backed edges</small></span>
          <span class="explainable"><strong>Explainable</strong><small>inferred bridges may support exploration with citation</small></span>
          <span class="review"><strong>Review first</strong><small>candidate, duplicate, contradiction, and rework edges stay gated</small></span>
        </div>
        <div class="graph-legend-actor-rule">
          <span class="badge">Actor rule</span>
          <strong>${escapeHtml(candidateCount || draft ? "Governance-aware use" : "Production-first use")}</strong>
          <small>${escapeHtml(candidateCount || draft
            ? "Approved concepts first; inferred and candidate layers stay explainable until reviewed."
            : "Current projection can ground actor answers with source-backed context.")}</small>
        </div>
        <div class="graph-legend-use-policy" aria-label="Actor Twin graph use policy">
          ${usePolicies.map((item) => `
            <span class="${safeGraphClass(item.className)}">
              <strong>${escapeHtml(item.value)}</strong>
              <small>${escapeHtml(item.label)}</small>
              <em>${escapeHtml(item.detail)}</em>
            </span>
          `).join("")}
        </div>
        <div class="graph-legend-confidence-strip" aria-label="Confidence bands">
          ${confidenceBands.map((band) => `
            <span class="${safeGraphClass(band.key)}" title="${escapeHtml(band.detail)}">
              <i></i><strong>${escapeHtml(String(band.count))}</strong><small>${escapeHtml(band.label.replace(" confidence", ""))}</small>
            </span>
          `).join("")}
        </div>
      </div>
    </section>
  `;
}

function renderGraphConfidenceLegend(edges = []) {
  const bands = ["high", "medium", "low", "unscored"].map((key) => {
    const bandEdges = edges.filter((edge) => graphEdgeConfidenceBand(edge).key === key);
    const meta = graphConfidenceBandMeta(key);
    return { ...meta, count: bandEdges.length };
  });
  return `
    <section class="graph-confidence-legend" aria-label="Relation confidence legend">
      <div>
        <span class="badge">Confidence bands</span>
        <strong>Edge weight indicates relation reliability</strong>
      </div>
      <div class="graph-confidence-band-list">
        ${bands.map((band) => `
          <span class="graph-confidence-band ${safeGraphClass(band.key)}">
            <i></i>
            <strong>${escapeHtml(band.label)} <em>${escapeHtml(String(band.count))}</em></strong>
            <small>${escapeHtml(band.detail)}</small>
          </span>
        `).join("")}
      </div>
    </section>
  `;
}

function renderGraphLegendItem(item = {}) {
  const active = item.filter && state.graphEdgeClassFilter === item.filter;
  const className = `graph-legend-item ${safeGraphClass(item.className)} ${active ? "active" : ""}`;
  const body = `
    ${item.icon}
    <strong>${escapeHtml(item.label)} <em>${escapeHtml(String(item.value))}</em></strong>
    <small>${escapeHtml(item.detail)}${item.filter ? " · click to filter" : ""}</small>
  `;
  if (!item.filter || item.value === 0) {
    return `<span class="${className}"${item.filter ? ' aria-disabled="true"' : ""}>${body}</span>`;
  }
  const nextFilter = active ? "all" : item.filter;
  return `
    <button
      class="${className}"
      type="button"
      data-graph-edge-class-filter="${escapeHtml(nextFilter)}"
      aria-pressed="${active ? "true" : "false"}"
      title="${active ? "Clear relation layer filter" : `Filter to ${item.label} relation layer`}"
    >${body}</button>
  `;
}

function renderGraphInferenceLegend(nodeStates = {}, edgeClasses = {}, candidateCount = 0) {
  const approved = nodeStates.approved || 0;
  const draft = (nodeStates["pending-review"] || nodeStates.pending_review || 0)
    + (nodeStates.draft || 0)
    + (nodeStates["needs-rework"] || nodeStates.needs_rework || 0);
  const lanes = [
    {
      className: "approved-use",
      title: "Production-ready memory",
      count: approved,
      detail: "Approved concepts and explicit relations can ground answers and skill context.",
    },
    {
      className: "inferred-use",
      title: "Inference bridge",
      count: edgeClasses.inferred || 0,
      detail: "AI-inferred links broaden recall, but answers should still cite source concepts.",
    },
    {
      className: "candidate-use",
      title: "Governance queue",
      count: candidateCount + draft,
      detail: "Drafts, duplicates, contradictions, and rework items require review before actor reliance.",
    },
  ];
  return `
    <section class="graph-inference-legend" aria-label="Inference and governance legend">
      <div>
        <span class="badge">Inference rules</span>
        <strong>How the twin may use the graph</strong>
      </div>
      <div class="graph-inference-legend-lanes">
        ${lanes.map((lane) => `
          <article class="${safeGraphClass(lane.className)}">
            <span>${escapeHtml(String(lane.count))}</span>
            <div>
              <strong>${escapeHtml(lane.title)}</strong>
              <small>${escapeHtml(lane.detail)}</small>
            </div>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function graphActiveReasoningPath(nodes, edges, availableEdges = edges) {
  const replayPath = graphReplayReasoningPath(nodes, edges);
  if (replayPath) return replayPath;
  if (!nodes.length || !edges.length || state.graphReasoningPreset === "custom") return null;
  const visibleNodeKeys = new Set(nodes.map((node) => node.node_key));
  const visibleEdges = edges.filter((edge) => visibleNodeKeys.has(edge.source) && visibleNodeKeys.has(edge.target));
  if (!visibleEdges.length) return null;
  const nodeMap = new Map(nodes.map((node) => [node.node_key, node]));
  const selected = state.selectedGraphEdgeKey
    ? visibleEdges.find((edge) => edge.edge_key === state.selectedGraphEdgeKey)
    : null;
  const scoreEdge = (edge) => {
    const relation = String(edge.relation_type || edge.edge_type || "related");
    const edgeClass = graphEdgeClass(edge);
    const confidence = Number(edge.confidence || 0);
    const review = String(edge.review_state || "unreviewed");
    const source = nodeMap.get(edge.source) || {};
    const target = nodeMap.get(edge.target) || {};
    let score = confidence;
    if (edgeClass === "explicit") score += 12;
    if (edgeClass === "inferred") score += 8;
    if (edgeClass.includes("candidate")) score += 6;
    if (review === "needs-rework" || review === "unreviewed") score += 5;
    if (state.graphReasoningPreset === "decide") {
      if (edgeClass.includes("candidate")) score += 38;
      if (review === "needs-rework") score += 26;
      if (relation.includes("contradiction")) score += 22;
    }
    if (state.graphReasoningPreset === "meeting") {
      if (relation.includes("derived") || relation.includes("supported") || relation.includes("source")) score += 28;
      if (source.node_type === "evidence" || target.node_type === "evidence") score += 16;
    }
    if (state.graphReasoningPreset === "skill") {
      if (relation.includes("uses") || relation.includes("context")) score += 28;
      if (source.node_type === "skill" || target.node_type === "skill") score += 18;
      if (source.node_type === "task" || target.node_type === "task") score += 12;
    }
    return score;
  };
  const edge = selected || [...visibleEdges].sort((a, b) => scoreEdge(b) - scoreEdge(a))[0];
  if (!edge) return null;
  const source = nodeMap.get(edge.source) || {};
  const target = nodeMap.get(edge.target) || {};
  const relation = edge.relation_type || edge.edge_type || "related";
  return {
    edge,
    source,
    target,
    edgeKey: edge.edge_key || "",
    nodeKeys: new Set([edge.source, edge.target]),
    relation,
    preset: state.graphReasoningPreset,
    label: `${labelizeGraph(state.graphReasoningPreset)} path`,
    summary: `${source.title || edge.source} → ${target.title || edge.target}`,
    detail: graphRelationMeaning(edge, source, target),
  };
}

function graphReplayReasoningPath(nodes, edges) {
  const replay = state.graphReplayContext;
  if (!replay?.packet || !nodes.length) return null;
  const nodeKeys = graphPacketNodeKeys(replay.packet);
  const visibleNodes = nodes.filter((node) => nodeKeys.has(node.node_key));
  if (!visibleNodes.length) return null;
  const edgeKeys = graphPacketEdgeKeys(replay.packet);
  const replayEdges = edges.filter((edge) => {
    if (edgeKeys.size && edgeKeys.has(edge.edge_key)) return true;
    return nodeKeys.has(edge.source) && nodeKeys.has(edge.target);
  });
  const edge = replayEdges[0] || {};
  const source = visibleNodes.find((node) => node.node_key === edge.source) || visibleNodes[0] || {};
  const target = visibleNodes.find((node) => node.node_key === edge.target) || visibleNodes[1] || source;
  return {
    edge,
    source,
    target,
    edgeKey: edge.edge_key || "",
    nodeKeys: new Set(visibleNodes.map((node) => node.node_key)),
    relation: edge.relation_type || edge.edge_type || "packet_context",
    preset: replay.kind === "question-path" ? "question-path" : "replayed-context",
    label: replay.kind === "question-path" ? "Question reasoning path" : "Replayed skill context",
    summary: replay.kind === "question-path"
      ? replay.query || replay.packet.query || "Graph-ranked question"
      : replay.runId ? `Skill run ${replay.runId}` : "Prepared graph packet",
    detail: replay.kind === "question-path"
      ? `${visibleNodes.length} context node${visibleNodes.length === 1 ? "" : "s"} and ${replayEdges.length} relation${replayEdges.length === 1 ? "" : "s"} are highlighted as the answer route.`
      : `${visibleNodes.length} packet node${visibleNodes.length === 1 ? "" : "s"} and ${replayEdges.length} relation${replayEdges.length === 1 ? "" : "s"} are highlighted from the stored skill-run context.`,
  };
}

function renderGraphActivePathCallout(activePath) {
  if (!activePath) return "";
  return `
    <section class="graph-active-path-callout ${safeGraphClass(activePath.preset)}">
      <div>
        <span class="badge">${escapeHtml(activePath.label)}</span>
        <strong>${escapeHtml(activePath.summary)}</strong>
        <p>${escapeHtml(activePath.detail)}</p>
      </div>
      <div class="graph-active-path-actions">
        <button class="secondary small" type="button" data-graph-node="${escapeHtml(activePath.source.node_key || activePath.edge.source || "")}">Inspect source</button>
        <button class="secondary small" type="button" data-graph-edge="${escapeHtml(activePath.edgeKey)}">Inspect relation</button>
        <button class="secondary small" type="button" data-graph-node="${escapeHtml(activePath.target.node_key || activePath.edge.target || "")}">Inspect target</button>
      </div>
    </section>
  `;
}

function renderGraphDecisionPathCanvas(target, nodes, edges, availableEdges = edges) {
  const model = graphDecisionPathModel(nodes, edges, availableEdges);
  const edge = model.edge || {};
  const relation = edge.relation_type || edge.edge_type || "selected_path";
  const source = model.source || {};
  const targetNode = model.target || {};
  const pathSteps = [
    {
      label: "Question",
      title: "What should the twin decide or explain?",
      detail: model.question,
      state: "neutral",
    },
    {
      label: "Ground",
      title: source.title || "Source context",
      detail: source.summary || source.description || source.okf_path || "Source node supplies the first part of the reasoning path.",
      state: source.review_state || "unknown",
      nodeKey: source.node_key,
    },
    {
      label: "Relate",
      title: labelizeGraph(relation),
      detail: graphRelationMeaning(edge, source, targetNode),
      state: graphEdgeClass(edge),
      edgeKey: edge.edge_key,
    },
    {
      label: "Apply",
      title: targetNode.title || "Target context",
      detail: targetNode.summary || targetNode.description || targetNode.okf_path || "Target node shows what the actor can use or must challenge.",
      state: targetNode.review_state || "unknown",
      nodeKey: targetNode.node_key,
    },
    {
      label: "Govern",
      title: graphEdgeUsagePolicy(edge).label,
      detail: graphQueueRecommendation(relation, edge.review_state || "unreviewed"),
      state: edge.review_state || "unreviewed",
      edgeKey: edge.edge_key,
    },
  ];
  const stepMarkup = pathSteps
    .map((step, index) => `
      <article class="graph-decision-step ${safeGraphClass(step.state)}">
        <span>${index + 1}</span>
        <small>${escapeHtml(step.label)}</small>
        <h4>${escapeHtml(step.title)}</h4>
        <p>${escapeHtml(step.detail || "No detail recorded.")}</p>
        ${step.nodeKey ? `<button class="secondary small" type="button" data-graph-node="${escapeHtml(step.nodeKey)}">Inspect node</button>` : ""}
        ${step.edgeKey ? `<button class="secondary small" type="button" data-graph-edge="${escapeHtml(step.edgeKey)}">Inspect relation</button>` : ""}
      </article>
    `)
    .join("");
  const relationCounts = countBy(availableEdges, (item) => item.relation_type || item.edge_type || "related");
  const relationMarkup = Object.entries(relationCounts)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, 5)
    .map(([key, count]) => `<span>${escapeHtml(labelizeGraph(key))} · ${count}</span>`)
    .join("");
  const candidateEdges = availableEdges.filter((item) => String(item.relation_type || item.edge_type || "").includes("candidate"));
  target.innerHTML = `
    <div class="graph-decision-path">
      <section class="graph-decision-hero">
        <div>
          <span class="badge">Decision path</span>
          <h3>${escapeHtml(model.headline)}</h3>
          <p>${escapeHtml(model.subline)}</p>
        </div>
        <div class="graph-decision-score">
          <strong>${model.readiness}%</strong>
          <span>decision readiness</span>
        </div>
      </section>
      <section class="graph-decision-steps">${stepMarkup}</section>
      <section class="graph-decision-footer">
        <div>
          <span class="badge">Visible relation shape</span>
          <div class="graph-decision-chipline">${relationMarkup || "<span>No relations in projection</span>"}</div>
        </div>
        <div>
          <span class="badge">Governance posture</span>
          <p>${candidateEdges.length ? `${candidateEdges.length} candidate relation${candidateEdges.length === 1 ? "" : "s"} still need human graph review before autonomous use.` : "No candidate relations are visible in this decision projection."}</p>
        </div>
      </section>
      ${edge.edge_key ? renderGraphSelectedEdgeActions(edge, source, targetNode) : ""}
    </div>
  `;
}

function graphDecisionPathModel(nodes, edges, availableEdges = edges) {
  const nodeMap = new Map(nodes.map((node) => [node.node_key, node]));
  const selectedEdge = availableEdges.find((edge) => edge.edge_key === state.selectedGraphEdgeKey);
  const candidate = [...availableEdges]
    .filter((edge) => String(edge.relation_type || edge.edge_type || "").includes("candidate"))
    .sort((a, b) => graphCandidateRiskScore(b) - graphCandidateRiskScore(a))[0];
  const representative = selectedEdge || candidate || [...availableEdges].sort((a, b) => Number(b.confidence || 0) - Number(a.confidence || 0))[0] || {};
  const source = nodeMap.get(representative.source) || nodes[0] || {};
  const targetNode = nodeMap.get(representative.target) || nodes.find((node) => node.node_key !== source.node_key) || {};
  const candidateCount = availableEdges.filter((edge) => String(edge.relation_type || edge.edge_type || "").includes("candidate")).length;
  const approvedCount = nodes.filter((node) => node.review_state === "approved").length;
  const readiness = graphDecisionReadiness(nodes, availableEdges);
  const relation = representative.relation_type || representative.edge_type || "path";
  const headline = candidate
    ? "Resolve the riskiest reasoning edge before actor use."
    : "Follow a compact OKF path from context to decision.";
  const subline = `${nodes.length} visible nodes, ${availableEdges.length} available relations, ${approvedCount} approved nodes, ${candidateCount} candidate gates.`;
  const question = state.graphSearch.trim()
    ? `Current question lens: "${state.graphSearch.trim()}".`
    : `Current preset: ${labelizeGraph(state.graphReasoningPreset)}. Relation focus: ${labelizeGraph(relation)}.`;
  return { edge: representative, source, target: targetNode, readiness, headline, subline, question };
}

function graphDecisionReadiness(nodes, edges) {
  if (!nodes.length) return 0;
  const approvedShare = nodes.filter((node) => node.review_state === "approved").length / nodes.length;
  const candidateShare = edges.length ? edges.filter((edge) => String(edge.relation_type || edge.edge_type || "").includes("candidate")).length / edges.length : 0;
  const explicitShare = edges.length ? edges.filter((edge) => graphEdgeClass(edge) === "explicit").length / edges.length : 0;
  return Math.max(0, Math.min(100, Math.round(approvedShare * 55 + explicitShare * 30 + (1 - candidateShare) * 15)));
}

function renderGraphStoryCanvas(target, nodes, edges, availableEdges = edges) {
  const approved = nodes.filter((node) => node.review_state === "approved");
  const drafts = nodes.filter((node) => node.review_state !== "approved");
  const explicitEdges = edges.filter((edge) => graphEdgeClass(edge) === "explicit");
  const inferredEdges = edges.filter((edge) => graphEdgeClass(edge) === "inferred");
  const candidateEdges = edges.filter((edge) => graphEdgeClass(edge) === "candidate");
  const topNodes = [...nodes]
    .sort((a, b) => graphNodeDegree(b, availableEdges) - graphNodeDegree(a, availableEdges))
    .slice(0, 5);
  const topRelations = Object.entries(countBy(availableEdges, (edge) => edge.relation_type || edge.edge_type || "related"))
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, 4);
  const readinessScore = graphStoryReadinessScore(nodes, edges);
  const candidateCopy = candidateEdges.length
    ? `${candidateEdges.length} candidate relation${candidateEdges.length === 1 ? "" : "s"} need human review before production steering.`
    : "No candidate relation blocks the current graph view.";
  const narrativeNodes = topNodes
    .map(
      (node, index) => `
        <article class="graph-story-node ${safeGraphClass(node.review_state || "unknown")}" data-graph-node="${escapeHtml(node.node_key)}">
          <span>${index + 1}</span>
          <div>
            <strong>${escapeHtml(node.title || node.node_key)}</strong>
            <small>${escapeHtml(labelizeGraph(node.node_type || "node"))} · ${escapeHtml(node.review_state || "unknown")} · ${graphNodeDegree(node, availableEdges)} links</small>
          </div>
        </article>
      `,
    )
    .join("");
  const relationMarkup = topRelations
    .map(
      ([relation, count]) => `
        <div class="graph-story-relation ${safeGraphClass(relation)}">
          <span>${escapeHtml(labelizeGraph(relation))}</span>
          <strong>${count}</strong>
        </div>
      `,
    )
    .join("");
  const firstCandidate = candidateEdges[0];
  const nodeMap = new Map(nodes.map((node) => [node.node_key, node]));
  const selectedEdge = edges.find((edge) => edge.edge_key === state.selectedGraphEdgeKey);
  const selectedEdgePanel = selectedEdge
    ? renderGraphStorySelectedEdge(selectedEdge, nodeMap.get(selectedEdge.source) || {}, nodeMap.get(selectedEdge.target) || {})
    : "";
  const candidateAction = firstCandidate
    ? `
      <button class="secondary small" type="button" data-graph-edge="${escapeHtml(firstCandidate.edge_key || "")}">
        Inspect top candidate
      </button>
    `
    : "";
  target.innerHTML = `
    <div class="graph-story-mode">
      <section class="graph-story-hero">
        <div>
          <span class="badge">Story mode</span>
          <h3>From markdown memory to governed AI context.</h3>
          <p>Use this view to explain how approved OKF concepts, typed relations, and inference governance become a safer reasoning substrate for the twin.</p>
        </div>
        <div class="graph-story-score" aria-label="Graph readiness score">
          <strong>${readinessScore}%</strong>
          <span>graph readiness</span>
        </div>
      </section>
      <section class="graph-story-board">
        <article class="graph-story-step">
          <span>1</span>
          <h4>Capture</h4>
          <p>${approved.length} approved concepts and ${drafts.length} draft concepts are visible in the current graph.</p>
        </article>
        <article class="graph-story-step">
          <span>2</span>
          <h4>Connect</h4>
          <p>${explicitEdges.length} explicit edges establish source-backed structure; ${inferredEdges.length} inferred edges expand retrieval.</p>
        </article>
        <article class="graph-story-step risk">
          <span>3</span>
          <h4>Govern</h4>
          <p>${escapeHtml(candidateCopy)}</p>
          ${candidateAction}
        </article>
        <article class="graph-story-step">
          <span>4</span>
          <h4>Apply</h4>
          <p>The Actor Twin can use approved-first paths for chat answers, skill context, and review workflows.</p>
        </article>
      </section>
      <section class="graph-story-grid">
        <div class="graph-story-panel">
          <div class="graph-story-panel-head">
            <span class="badge">Most connected memory</span>
            <small>Click to inspect detail</small>
          </div>
          <div class="graph-story-node-list">${narrativeNodes || renderEmptyState("No connected nodes in view.")}</div>
        </div>
        <div class="graph-story-panel">
          <div class="graph-story-panel-head">
            <span class="badge">Relationship shape</span>
            <small>${availableEdges.length} available edges</small>
          </div>
          <div class="graph-story-relations">${relationMarkup || renderEmptyState("No relation data in view.")}</div>
        </div>
        <div class="graph-story-panel graph-story-callout">
          <span class="badge">Executive takeaway</span>
          <h4>The graph makes the twin inspectable.</h4>
          <p>Every answer path can show whether it came from approved memory, inferred context, or a candidate relationship still waiting for governance.</p>
          ${firstCandidate ? `<small>Top governance item: ${escapeHtml(labelizeGraph(firstCandidate.relation_type || firstCandidate.edge_type || "candidate"))} between ${escapeHtml(nodeMap.get(firstCandidate.source)?.title || firstCandidate.source)} and ${escapeHtml(nodeMap.get(firstCandidate.target)?.title || firstCandidate.target)}.</small>` : "<small>No unresolved candidate selected in this view.</small>"}
        </div>
      </section>
      ${selectedEdgePanel}
    </div>
  `;
}

function renderGraphStorySelectedEdge(edge, source = {}, target = {}) {
  const relation = edge.relation_type || edge.edge_type || "related";
  return `
    <section class="graph-story-selected-edge ${safeGraphClass(relation)}">
      <div>
        <span class="badge">Selected story edge</span>
        <h4>${escapeHtml(labelizeGraph(relation))}</h4>
        <p>${escapeHtml(source.title || edge.source)} → ${escapeHtml(target.title || edge.target)}</p>
      </div>
      ${renderGraphReasoningPanel(edge, source, target)}
    </section>
  `;
}

function graphStoryReadinessScore(nodes, edges) {
  if (!nodes.length) return 0;
  const approvedShare = nodes.filter((node) => node.review_state === "approved").length / nodes.length;
  const candidateShare = edges.length ? edges.filter((edge) => graphEdgeClass(edge) === "candidate").length / edges.length : 0;
  const explicitShare = edges.length ? edges.filter((edge) => graphEdgeClass(edge) === "explicit").length / edges.length : 0;
  const score = approvedShare * 62 + explicitShare * 28 + Math.max(0, 1 - candidateShare) * 10;
  return Math.max(0, Math.min(100, Math.round(score)));
}

function renderGraphHoverInspector() {
  const target = $("#graphHoverInspector");
  if (!target) return;
  const graph = state.okfGraph || {};
  const nodes = filteredGraphNodes();
  const nodeKeys = new Set(nodes.map((node) => node.node_key));
  const edges = (graph.edges || []).filter((edge) => nodeKeys.has(edge.source) && nodeKeys.has(edge.target));
  target.innerHTML = renderGraphHoverInspectorMarkup(nodes, edges);
}

function renderGraphHoverInspectorMarkup(nodes, edges) {
  const edge = edges.find((item) => item.edge_key === state.hoveredGraphEdgeKey)
    || edges.find((item) => item.edge_key === state.selectedGraphEdgeKey);
  if (edge) {
    const nodeMap = new Map(nodes.map((node) => [node.node_key, node]));
    const source = nodeMap.get(edge.source) || {};
    const target = nodeMap.get(edge.target) || {};
    const relation = edge.relation_type || edge.edge_type || "related";
    return `
      <span class="badge">${escapeHtml(labelizeGraph(relation))}</span>
      <strong>${escapeHtml(source.title || edge.source)} → ${escapeHtml(target.title || edge.target)}</strong>
      <small>${escapeHtml(edge.review_state || "unreviewed")} · confidence ${escapeHtml(edge.confidence ?? "-")} · ${escapeHtml(graphEdgeClass(edge))}</small>
    `;
  }
  const node = nodes.find((item) => item.node_key === state.hoveredGraphNodeKey)
    || nodes.find((item) => item.node_key === state.selectedGraphNodeKey);
  if (!node) {
    return `
      <span class="badge">Inspect</span>
      <strong>Hover or select a node</strong>
      <small>Review evidence density, governance state, and direct connectivity.</small>
    `;
  }
  const degree = graphNodeDegree(node, edges);
  const evidenceLinks = edges.filter((edge) => edge.source === node.node_key || edge.target === node.node_key)
    .filter((edge) => String(edge.relation_type || edge.edge_type || "").includes("evidence") || String(edge.source).startsWith("evidence:") || String(edge.target).startsWith("evidence:"))
    .length;
  return `
    <span class="badge">${escapeHtml(labelizeGraph(node.node_type || "node"))}</span>
    <strong>${escapeHtml(node.title || node.node_key)}</strong>
    <small>${escapeHtml(node.review_state || "unknown")} · ${degree} links · ${evidenceLinks} evidence paths</small>
  `;
}

function renderGraphEdgeWorkbench(nodes, edges) {
  const edge = edges.find((item) => item.edge_key === state.selectedGraphEdgeKey);
  if (!edge) return "";
  const nodeMap = new Map(nodes.map((node) => [node.node_key, node]));
  const source = nodeMap.get(edge.source) || {};
  const target = nodeMap.get(edge.target) || {};
  const relation = edge.relation_type || edge.edge_type || "related";
  const candidate = String(graphEdgeClass(edge)).includes("candidate");
  const reviewState = edge.review_state || "unreviewed";
  const pending = candidate && reviewState === "unreviewed";
  return `
    <div class="graph-edge-workbench ${safeGraphClass(relation)} ${safeGraphClass(reviewState)}">
      <div class="graph-edge-workbench-main">
        <div>
          <span class="badge">Selected edge</span>
          <strong>${escapeHtml(labelizeGraph(relation))}</strong>
          <small>${escapeHtml(source.title || edge.source)} → ${escapeHtml(target.title || edge.target)} · confidence ${escapeHtml(edge.confidence ?? "-")} · ${escapeHtml(reviewState)}</small>
        </div>
        <div class="graph-edge-review-actions">
          <button class="small secondary" type="button" data-graph-node="${escapeHtml(edge.source)}">Source</button>
          <button class="small secondary" type="button" data-graph-node="${escapeHtml(edge.target)}">Target</button>
          ${candidate ? renderGraphProposalButton(edge) : ""}
          ${pending ? `
            <button class="small secondary" type="button" data-graph-edge-key="${escapeHtml(edge.edge_key)}" data-graph-edge-action="accepted">Accept</button>
            <button class="small danger" type="button" data-graph-edge-key="${escapeHtml(edge.edge_key)}" data-graph-edge-action="rejected">Reject</button>
            <button class="small secondary" type="button" data-graph-edge-key="${escapeHtml(edge.edge_key)}" data-graph-edge-action="needs-rework">Needs rework</button>
          ` : ""}
        </div>
      </div>
      ${renderGraphReasoningPanel(edge, source, target)}
    </div>
  `;
}

function renderGraphReasoningPanel(edge, source = {}, target = {}) {
  const relation = edge.relation_type || edge.edge_type || "related";
  const edgeClass = graphEdgeClass(edge);
  const reviewState = edge.review_state || "unreviewed";
  const policy = graphEdgeUsagePolicy(edge);
  const confidencePercent = graphEdgeConfidencePercent(edge);
  const confidenceLabel = confidencePercent ? `${confidencePercent}%` : "not scored";
  const explanation = graphRelationExplanation(edge, source, target, policy);
  const eligibility = graphEdgeEvidenceEligibility(edge, source, target, explanation);
  const copyText = formatGraphRelationExplanation(edge, source, target, explanation);
  return `
    <section class="graph-reasoning-card ${safeGraphClass(edgeClass)} ${safeGraphClass(reviewState)}">
      <div class="graph-reasoning-head">
        <div>
          <span class="badge">Explain this path</span>
          <h5>${escapeHtml(source.title || edge.source || "Source")} → ${escapeHtml(target.title || edge.target || "Target")}</h5>
          <p>${escapeHtml(graphRelationMeaning(edge, source, target))}</p>
        </div>
        <button class="small secondary source-copy-btn" type="button" data-copy-value="${escapeHtml(copyText)}">Copy path</button>
      </div>
      <div class="graph-path-explainer ${safeGraphClass(explanation.level)}">
        <article>
          <span>${escapeHtml(graphNodeInitial(source))}</span>
          <strong>${escapeHtml(truncateGraphLabel(source.title || edge.source || "Source", 34))}</strong>
          <small>${escapeHtml(labelizeGraph(source.review_state || "unknown"))}</small>
        </article>
        <i></i>
        <article class="relation">
          <span>${escapeHtml(confidencePercent ? String(confidencePercent) : "?")}</span>
          <strong>${escapeHtml(labelizeGraph(relation))}</strong>
          <small>${escapeHtml(explanation.levelLabel)}</small>
        </article>
        <i></i>
        <article>
          <span>${escapeHtml(graphNodeInitial(target))}</span>
          <strong>${escapeHtml(truncateGraphLabel(target.title || edge.target || "Target", 34))}</strong>
          <small>${escapeHtml(labelizeGraph(target.review_state || "unknown"))}</small>
        </article>
      </div>
      <div class="graph-path-verdict ${safeGraphClass(explanation.level)}">
        <strong>${escapeHtml(explanation.actorDecision)}</strong>
        <span>${escapeHtml(explanation.reason)}</span>
      </div>
      ${renderGraphActorGovernanceDecision(edge, source, target, explanation)}
      ${renderGraphEdgeEvidenceEligibility(eligibility)}
      <dl class="detail-list compact">
        ${detailRow("Relation", labelizeGraph(relation))}
        ${detailRow("Evidence class", labelizeGraph(edgeClass))}
        ${detailRow("Governance", reviewState)}
        ${detailRow("AI use", policy.label)}
        ${detailRow("Confidence", confidenceLabel)}
      </dl>
      <ol class="graph-ai-steps">
        <li><strong>Why it matters</strong><span>${escapeHtml(policy.why)}</span></li>
        <li><strong>When to use</strong><span>${escapeHtml(policy.use)}</span></li>
        <li><strong>Escalation</strong><span>${escapeHtml(policy.escalate)}</span></li>
      </ol>
    </section>
  `;
}

function graphEdgeEvidenceEligibility(edge = {}, source = {}, target = {}, explanation = graphRelationExplanation(edge, source, target)) {
  const edgeClass = graphEdgeClass(edge);
  const reviewState = edge.review_state || "unreviewed";
  const confidence = graphEdgeConfidencePercent(edge);
  const sourceState = source.review_state || "unknown";
  const targetState = target.review_state || "unknown";
  const sourceApproved = sourceState === "approved";
  const targetApproved = targetState === "approved";
  const hasEvidenceRef = Boolean(edge.evidence_path || edge.source_path || edge.source_deep_link || edge.evidence_ref || edge.source_ref);
  const blocked = ["rejected", "needs-rework"].includes(reviewState)
    || explanation.level === "blocked"
    || String(edgeClass).includes("contradiction");
  const candidate = String(edgeClass).includes("candidate") || ["draft", "unreviewed", "candidate"].includes(reviewState);
  const trusted = !blocked && edgeClass === "explicit" && sourceApproved && targetApproved && hasEvidenceRef && confidence >= 70;
  const selectedPending = !blocked && !trusted && (candidate || edgeClass === "inferred" || hasEvidenceRef);
  const className = trusted ? "ready" : selectedPending ? "caution" : "blocked";
  const retrievalPolicy = trusted ? "trusted-retrieval" : selectedPending ? "selected-pending" : "hold";
  const label = trusted ? "Trusted relation evidence" : selectedPending ? "Candidate relation evidence" : "Relation held out";
  const detail = trusted
    ? "Relation is explicit, evidence-linked, sufficiently confident, and both endpoints are approved."
    : selectedPending
      ? "Relation can support exploration or selected context, but requires attribution or review before trusted retrieval."
      : "Relation is blocked by governance, missing evidence, low confidence, or unapproved endpoints.";
  return {
    className,
    label,
    detail,
    retrievalPolicy,
    edgeClass,
    reviewState,
    confidence,
    hasEvidenceRef,
    sourceState,
    targetState,
  };
}

function renderGraphEdgeEvidenceEligibility(eligibility = {}) {
  return `
    <section class="graph-edge-evidence-eligibility ${safeGraphClass(eligibility.className || "blocked")}">
      <div>
        <span class="badge">Relation eligibility</span>
        <strong>${escapeHtml(eligibility.label || "Relation held out")}</strong>
        <p>${escapeHtml(eligibility.detail || "")}</p>
      </div>
      <div class="graph-edge-evidence-grid">
        <span class="${safeGraphClass(eligibility.className || "blocked")}"><strong>${escapeHtml(eligibility.retrievalPolicy || "hold")}</strong><small>retrieval policy</small></span>
        <span><strong>${escapeHtml(labelizeGraph(eligibility.edgeClass || "unknown"))}</strong><small>relation class</small></span>
        <span class="${eligibility.hasEvidenceRef ? "ready" : "blocked"}"><strong>${escapeHtml(eligibility.hasEvidenceRef ? "linked" : "missing")}</strong><small>source evidence</small></span>
        <span class="${eligibility.sourceState === "approved" && eligibility.targetState === "approved" ? "ready" : "caution"}"><strong>${escapeHtml(`${labelizeGraph(eligibility.sourceState || "unknown")} / ${labelizeGraph(eligibility.targetState || "unknown")}`)}</strong><small>endpoints</small></span>
      </div>
    </section>
  `;
}

function graphRelationExplanation(edge = {}, source = {}, target = {}, policy = graphEdgeUsagePolicy(edge)) {
  const edgeClass = graphEdgeClass(edge);
  const relation = edge.relation_type || edge.edge_type || "related";
  const reviewState = edge.review_state || "unreviewed";
  const confidence = graphEdgeConfidencePercent(edge);
  const sourceApproved = source.review_state === "approved";
  const targetApproved = target.review_state === "approved";
  if (relation === "contradiction_candidate" || reviewState === "rejected") {
    return {
      level: "blocked",
      levelLabel: "blocked",
      actorDecision: "Do not use for autonomous steering",
      reason: "This path can create inconsistent actor behavior until a human resolves the contradiction.",
    };
  }
  if (String(edgeClass).includes("candidate") || reviewState === "needs-rework") {
    return {
      level: "govern",
      levelLabel: "govern",
      actorDecision: "Use only as a review cue",
      reason: "The relation is useful for curation, but should not steer the twin until accepted or corrected.",
    };
  }
  if (edgeClass === "explicit" && sourceApproved && targetApproved && confidence >= 70) {
    return {
      level: "trusted",
      levelLabel: "trusted",
      actorDecision: "Safe grounding path",
      reason: "Both endpoints are approved and the relation is source-backed, so the twin may use it with citation.",
    };
  }
  if (edgeClass === "explicit") {
    return {
      level: "grounded",
      levelLabel: "grounded",
      actorDecision: "Use with source attribution",
      reason: "The edge is explicit, but at least one endpoint still needs stronger approval or evidence maturity.",
    };
  }
  return {
    level: "exploratory",
    levelLabel: "inferred",
    actorDecision: policy.label || "Use with attribution",
    reason: "The path broadens recall but should be backed by cited source nodes before decision use.",
  };
}

function formatGraphRelationExplanation(edge = {}, source = {}, target = {}, explanation = graphRelationExplanation(edge, source, target)) {
  const relation = edge.relation_type || edge.edge_type || "related";
  return [
    `Graph path: ${source.title || edge.source || "Source"} -> ${labelizeGraph(relation)} -> ${target.title || edge.target || "Target"}`,
    `Actor decision: ${explanation.actorDecision}`,
    `Reason: ${explanation.reason}`,
    `Governance: ${edge.review_state || "unreviewed"}`,
    `Confidence: ${graphEdgeConfidencePercent(edge) || edge.confidence || "not scored"}`,
  ].join("\n");
}

function renderGraphActorGovernanceDecision(edge = {}, source = {}, target = {}, explanation = graphRelationExplanation(edge, source, target)) {
  const relation = edge.relation_type || edge.edge_type || "related";
  const policy = graphEdgeUsagePolicy(edge);
  const candidate = String(graphEdgeClass(edge)).includes("candidate");
  const unresolved = ["unreviewed", "needs-rework", "rejected"].includes(String(edge.review_state || "unreviewed"));
  const requiresHuman = relation === "contradiction_candidate" || candidate || unresolved;
  const actorMode = requiresHuman ? "consult-before-use" : "available-for-steering";
  const outputRule = requiresHuman
    ? "Actor may mention the path as a hypothesis or review cue, not as decision authority."
    : "Actor may use this path for grounded answer synthesis with source attribution.";
  return `
    <div class="graph-actor-governance ${safeGraphClass(actorMode)}">
      <div>
        <span class="badge">Actor governance</span>
        <strong>${escapeHtml(requiresHuman ? "Human/curator gate before steering" : "Usable for actor steering")}</strong>
        <small>${escapeHtml(outputRule)}</small>
      </div>
      <ul>
        <li><strong>Decision</strong><span>${escapeHtml(explanation.actorDecision || policy.label)}</span></li>
        <li><strong>Boundary</strong><span>${escapeHtml(policy.escalate || "Escalate when external action depends on this relation.")}</span></li>
        <li><strong>Action</strong><span>${escapeHtml(requiresHuman ? "Review relation or create a proposal." : "Apply to chat or skill runner as bounded context.")}</span></li>
      </ul>
    </div>
  `;
}

function graphRelationMeaning(edge, source = {}, target = {}) {
  const relation = edge.relation_type || edge.edge_type || "related";
  const sourceLabel = source.title || edge.source || "the source node";
  const targetLabel = target.title || edge.target || "the target node";
  const meanings = {
    derived_from: `${sourceLabel} is grounded in ${targetLabel}. This is source evidence, not a speculative relation.`,
    supported_by: `${sourceLabel} is supported by ${targetLabel}. The target can be cited as evidence when the twin answers.`,
    validates: `${sourceLabel} validates ${targetLabel}. Prefer this path when explaining why a concept is trusted.`,
    validated_by: `${sourceLabel} is validated by ${targetLabel}. Prefer this path when explaining why a concept is trusted.`,
    member_of_cluster: `${sourceLabel} belongs to ${targetLabel}. This helps retrieval group related work patterns.`,
    uses_context: `${sourceLabel} uses ${targetLabel} as actor context. This affects skill steering and tone.`,
    related_by_profile: `${sourceLabel} and ${targetLabel} are related through persona or profile signals.`,
    duplicate_candidate: `${sourceLabel} may duplicate ${targetLabel}. Review before merging or using as a single fact.`,
    contradiction_candidate: `${sourceLabel} may contradict ${targetLabel}. Resolve before relying on either node for steering.`,
  };
  return meanings[relation] || `${sourceLabel} is connected to ${targetLabel}. Treat this as graph context and inspect governance before using it for decisions.`;
}

function graphEdgeUsagePolicy(edge) {
  const relation = edge.relation_type || edge.edge_type || "";
  const reviewState = edge.review_state || "unreviewed";
  const edgeClass = graphEdgeClass(edge);
  if (reviewState === "rejected") {
    return {
      label: "excluded from retrieval",
      why: "Rejected graph edges must not be used as memory or reasoning support.",
      use: "Keep visible only as audit history and as a signal for curator refinement.",
      escalate: "Create a new candidate only after source evidence changes.",
    };
  }
  if (reviewState === "needs-rework") {
    return {
      label: "cockpit-only until reworked",
      why: "The relation may be plausible but needs stronger evidence or clearer wording.",
      use: "Use only as a review task; do not use as answer or skill context.",
      escalate: "Add evidence anchors or clarify the relation before promotion.",
    };
  }
  if (reviewState === "accepted" || reviewState === "approved") {
    return {
      label: "trusted after human review",
      why: "The relation has passed the graph promotion gate.",
      use: "Use for grounded answers, skill context assembly, and graph reasoning with attribution.",
      escalate: "Escalate only if the connected concept itself is not approved or needs rework.",
    };
  }
  if (relation === "contradiction_candidate") {
    return {
      label: "blocked for autonomous use",
      why: "Contradictions can steer the Actor Twin toward inconsistent decisions.",
      use: "Use only to explain that there is a conflict requiring human or curator review.",
      escalate: "Create a rework proposal or mark the edge needs rework before production use.",
    };
  }
  if (relation === "duplicate_candidate") {
    return {
      label: reviewState === "accepted" ? "usable as equivalent context" : "review before merge",
      why: "Duplicate candidates can reduce noise, but merging them changes memory structure.",
      use: "Use as a hint for retrieval until accepted; do not silently collapse concepts.",
      escalate: "Prepare a merge proposal when the concepts truly describe the same knowledge.",
    };
  }
  if (edgeClass === "explicit") {
    return {
      label: "safe for grounded retrieval",
      why: "Explicit edges come from source-backed OKF structure or accepted governance.",
      use: "Use for answer paths, evidence citations, and skill context assembly.",
      escalate: "Escalate only if the connected concept itself is not approved or needs rework.",
    };
  }
  return {
    label: "usable with attribution",
    why: "Inferred edges improve recall but are weaker than source-backed edges.",
    use: "Use to broaden context, then cite the supporting nodes and confidence.",
    escalate: "Escalate if a decision depends primarily on inferred context.",
  };
}

function graphTopology(nodes, edges, densityMode = "balanced", layoutMode = "topology") {
  const width = 1120;
  const density = {
    compact: { height: 620, ring: 56, base: 230, labelScale: 0.9 },
    balanced: { height: 720, ring: 72, base: 252, labelScale: 1 },
    spacious: { height: 820, ring: 84, base: 284, labelScale: 1.1 },
  }[densityMode] || { height: 680, ring: 78, base: 150, labelScale: 1 };
  const height = density.height;
  const center = { x: width / 2, y: height / 2 };
  const typeOrder = ["cluster", "concept", "evidence", "skill", "task", "node"];
  const groups = graphGroupBy(nodes, (node) => node.node_type || "node");
  const positions = new Map();
  const lanes = [];
  if (layoutMode === "cluster") {
    return graphClusterTopology(nodes, edges, groups, width, height);
  }
  if (layoutMode === "evidence") {
    return graphEvidenceTopology(nodes, edges, groups, width, height);
  }
  if (layoutMode === "governance") {
    return graphGovernanceTopology(nodes, edges, width, height);
  }
  typeOrder
    .filter((type) => groups[type]?.length)
    .forEach((type, ringIndex) => {
      const groupNodes = [...groups[type]].sort((a, b) => graphNodeDegree(b, edges) - graphNodeDegree(a, edges));
      const radius = type === "cluster"
        ? Math.max(96, Math.min(132, groupNodes.length * 13))
        : density.base + ringIndex * density.ring;
      const startAngle = -Math.PI / 2 + ringIndex * 0.42;
      lanes.push({ type, count: groupNodes.length });
      groupNodes.forEach((node, index) => {
        const angle = startAngle + (2 * Math.PI * index) / Math.max(groupNodes.length, 1);
        const reviewOffset = node.review_state === "approved" ? -12 : 16;
        positions.set(node.node_key, {
          x: Math.round(center.x + Math.cos(angle) * (radius + reviewOffset)),
          y: Math.round(center.y + Math.sin(angle) * (radius * 0.88 + reviewOffset)),
        });
      });
    });
  Object.entries(groups)
    .filter(([type]) => !typeOrder.includes(type))
    .forEach(([type, groupNodes], extraIndex) => {
      lanes.push({ type, count: groupNodes.length });
      groupNodes.forEach((node, index) => {
        positions.set(node.node_key, {
          x: 120 + index * 118,
          y: height - 70 - extraIndex * 54,
        });
      });
    });
  return graphTopologyWithLabelPolicy(
    { width, height, positions, lanes, labelScale: density.labelScale },
    nodes,
    edges,
    layoutMode,
    densityMode,
  );
}

function graphClusterTopology(nodes, edges, groups, width, height) {
  const positions = new Map();
  const clusters = [...(groups.cluster || [])].sort((a, b) => graphNodeDegree(b, edges) - graphNodeDegree(a, edges));
  const otherNodes = nodes.filter((node) => node.node_type !== "cluster");
  const clusterSlots = Math.max(clusters.length, 1);
  const columnWidth = state.graphDensityMode === "compact" ? 320 : state.graphDensityMode === "spacious" ? 460 : 390;
  const dynamicWidth = Math.max(width, clusterSlots * columnWidth + 180);
  const zones = [];
  clusters.forEach((node, index) => {
    const x = 90 + columnWidth * index + columnWidth / 2;
    positions.set(node.node_key, { x: Math.round(x), y: 126 });
  });
  const clusterKeys = new Set(clusters.map((node) => node.node_key));
  const byCluster = new Map();
  otherNodes.forEach((node) => {
    const edge = edges.find((item) => item.source === node.node_key && clusterKeys.has(item.target))
      || edges.find((item) => item.target === node.node_key && clusterKeys.has(item.source));
    const clusterKey = edge ? (clusterKeys.has(edge.target) ? edge.target : edge.source) : "unclustered";
    if (!byCluster.has(clusterKey)) byCluster.set(clusterKey, []);
    byCluster.get(clusterKey).push(node);
  });
  byCluster.forEach((items, clusterKey) => {
    const clusterPos = positions.get(clusterKey) || { x: dynamicWidth / 2, y: 160 };
    const sortedItems = [...items].sort((a, b) => graphNodeDegree(b, edges) - graphNodeDegree(a, edges));
    const cols = Math.max(1, Math.min(state.graphDensityMode === "compact" ? 3 : 4, Math.ceil(Math.sqrt(sortedItems.length))));
    const xStep = state.graphDensityMode === "compact" ? 104 : state.graphDensityMode === "spacious" ? 138 : 122;
    const yStep = state.graphDensityMode === "compact" ? 104 : state.graphDensityMode === "spacious" ? 126 : 114;
    const firstY = 318;
    const rows = Math.max(1, Math.ceil(sortedItems.length / cols));
    const zoneWidth = Math.max(286, (cols - 1) * xStep + 238);
    const zoneHeight = Math.max(314, rows * yStep + 206);
    const clusterNode = clusters.find((node) => node.node_key === clusterKey);
    zones.push({
      key: clusterKey,
      title: clusterNode?.title || (clusterKey === "unclustered" ? "Unclustered" : clusterKey),
      count: sortedItems.length,
      x: Math.round(clusterPos.x - zoneWidth / 2),
      y: 56,
      width: Math.round(zoneWidth),
      height: Math.round(zoneHeight),
      reviewMix: countBy(sortedItems, (node) => node.review_state || "unknown"),
    });
    sortedItems
      .forEach((node, index) => {
        const col = index % cols;
        const row = Math.floor(index / cols);
        positions.set(node.node_key, {
          x: Math.round(clusterPos.x - ((cols - 1) * xStep) / 2 + col * xStep),
          y: Math.round(firstY + row * yStep),
        });
      });
  });
  const maxY = Math.max(...Array.from(positions.values()).map((pos) => pos.y), height);
  const maxZoneY = Math.max(...zones.map((zone) => zone.y + zone.height), maxY + 120, height);
  return graphTopologyWithLabelPolicy(
    { width: dynamicWidth, height: Math.max(height, maxZoneY + 40), positions, lanes: graphTopologyLanes(nodes), zones, labelScale: 1 },
    nodes,
    edges,
    "cluster",
    state.graphDensityMode,
  );
}

function graphEvidenceTopology(nodes, edges, groups, width, height) {
  const positions = new Map();
  const lanes = [
    { type: "evidence", y: 150, values: groups.evidence || [] },
    { type: "concept", y: 350, values: groups.concept || [] },
    { type: "skill", y: 550, values: [...(groups.skill || []), ...(groups.task || [])] },
  ];
  lanes.forEach((lane) => {
    lane.values
      .sort((a, b) => graphNodeDegree(b, edges) - graphNodeDegree(a, edges))
      .forEach((node, index) => {
        positions.set(node.node_key, {
          x: Math.round(100 + ((width - 200) * (index + 0.5)) / Math.max(lane.values.length, 1)),
          y: lane.y,
        });
      });
  });
  const placed = new Set(positions.keys());
  nodes
    .filter((node) => !placed.has(node.node_key))
    .forEach((node, index, rest) => {
      positions.set(node.node_key, {
        x: Math.round(100 + ((width - 200) * (index + 0.5)) / Math.max(rest.length, 1)),
        y: 700,
      });
    });
  return graphTopologyWithLabelPolicy(
    { width, height: Math.max(height, 780), positions, lanes: graphTopologyLanes(nodes), labelScale: 1 },
    nodes,
    edges,
    "evidence",
    state.graphDensityMode,
  );
}

function graphGovernanceTopology(nodes, edges, width, height) {
  const positions = new Map();
  const stateOrder = ["approved", "pending-review", "needs-rework", "rejected", "unknown"];
  const stateY = {
    approved: 150,
    "pending-review": 320,
    "needs-rework": 500,
    rejected: 650,
    unknown: 650,
  };
  const groups = graphGroupBy(nodes, (node) => node.review_state || "unknown");
  stateOrder.forEach((reviewState) => {
    const items = groups[reviewState] || [];
    items
      .sort((a, b) => graphNodeDegree(b, edges) - graphNodeDegree(a, edges))
      .forEach((node, index) => {
        positions.set(node.node_key, {
          x: Math.round(100 + ((width - 200) * (index + 0.5)) / Math.max(items.length, 1)),
          y: stateY[reviewState] || 650,
        });
      });
  });
  return graphTopologyWithLabelPolicy(
    { width, height: Math.max(height, 760), positions, lanes: graphTopologyLanes(nodes, (node) => node.review_state || "unknown"), labelScale: 1 },
    nodes,
    edges,
    "governance",
    state.graphDensityMode,
  );
}

function graphTopologyLanes(nodes, groupFn = (node) => node.node_type || "node") {
  return Object.entries(graphGroupBy(nodes, groupFn))
    .sort((a, b) => b[1].length - a[1].length || a[0].localeCompare(b[0]))
    .map(([type, values]) => ({ type, count: values.length }));
}

function graphTopologyWithLabelPolicy(topology, nodes, edges, layoutMode, densityMode) {
  const budget = graphLabelBudget(nodes.length, layoutMode, densityMode);
  const selectedKeys = new Set([state.selectedGraphNodeKey].filter(Boolean));
  const rankedKeys = [...nodes]
    .sort((a, b) => graphNodeLabelScore(b, edges, selectedKeys, layoutMode) - graphNodeLabelScore(a, edges, selectedKeys, layoutMode))
    .slice(0, budget)
    .map((node) => node.node_key);
  return {
    ...topology,
    labelNodeKeys: new Set([...rankedKeys, ...selectedKeys]),
    labelBudget: budget,
    layoutMode,
  };
}

function graphLabelBudget(nodeCount, layoutMode, densityMode) {
  const base = {
    compact: 8,
    balanced: 13,
    spacious: 20,
  }[densityMode] || 12;
  const layoutBoost = {
    cluster: 6,
    evidence: 4,
    governance: 5,
    decision: 8,
  }[layoutMode] || 0;
  return Math.max(6, Math.min(nodeCount, base + layoutBoost));
}

function graphNodeLabelScore(node, edges, selectedKeys = new Set(), layoutMode = "topology") {
  let score = graphNodeDegree(node, edges) * 9;
  if (selectedKeys.has(node.node_key)) score += 1000;
  if (node.node_type === "cluster") score += 220;
  if (node.review_state === "approved") score += 70;
  if (node.review_state === "needs-rework") score += 60;
  if (node.node_type === "skill" || node.node_type === "task") score += 44;
  if (layoutMode === "cluster" && node.node_type === "concept") score += 20;
  if (layoutMode === "evidence" && node.node_type === "evidence") score += 45;
  return score;
}

function renderGraphSvgZone(zone) {
  const approved = zone.reviewMix?.approved || 0;
  const pending = (zone.reviewMix?.["pending-review"] || 0) + (zone.reviewMix?.pending_review || 0);
  return `
    <g class="graph-svg-zone" data-graph-zone="${escapeHtml(zone.key || zone.title || "zone")}">
      <rect x="${zone.x}" y="${zone.y}" width="${zone.width}" height="${zone.height}" rx="22"></rect>
      <rect class="graph-svg-zone-header" x="${zone.x + 8}" y="${zone.y + 8}" width="${Math.max(120, zone.width - 16)}" height="56" rx="16"></rect>
      <text x="${zone.x + 18}" y="${zone.y + 30}">${escapeHtml(truncateGraphLabel(zone.title || "Cluster", 34))}</text>
      <text class="graph-svg-zone-count" x="${zone.x + 18}" y="${zone.y + 50}">${escapeHtml(String(zone.count || 0))} grouped · ${escapeHtml(String(approved))} approved · ${escapeHtml(String(pending))} pending</text>
    </g>
  `;
}

function renderGraphOverviewPanel(topology, nodes, edges, activePath = null, totalEdgeCount = edges.length) {
  const positionedNodes = nodes.filter((node) => topology.positions.has(node.node_key));
  if (!positionedNodes.length) return "";
  const maxDegree = Math.max(1, ...positionedNodes.map((node) => graphNodeDegree(node, edges)));
  const viewWidth = 220;
  const viewHeight = 132;
  const pad = 14;
  const scaleX = (viewWidth - pad * 2) / Math.max(topology.width || 1, 1);
  const scaleY = (viewHeight - pad * 2) / Math.max(topology.height || 1, 1);
  const edgeSvg = edges
    .filter((edge) => topology.positions.has(edge.source) && topology.positions.has(edge.target))
    .slice(0, 160)
    .map((edge) => {
      const source = topology.positions.get(edge.source);
      const target = topology.positions.get(edge.target);
      const edgeClass = graphEdgeClass(edge);
      return `<line class="${safeGraphClass(edgeClass)}" x1="${Math.round(pad + source.x * scaleX)}" y1="${Math.round(pad + source.y * scaleY)}" x2="${Math.round(pad + target.x * scaleX)}" y2="${Math.round(pad + target.y * scaleY)}"></line>`;
    })
    .join("");
  const nodeSvg = positionedNodes
    .map((node) => {
      const pos = topology.positions.get(node.node_key);
      const degree = graphNodeDegree(node, edges);
      const radius = Math.max(2.8, Math.min(7.5, 2.8 + (degree / maxDegree) * 5));
      const active = activePath?.nodeKeys?.has(node.node_key) || state.selectedGraphNodeKey === node.node_key;
      return `<circle class="${safeGraphClass(node.review_state || "unknown")} ${active ? "active" : ""}" data-graph-node="${escapeHtml(node.node_key)}" tabindex="0" role="button" aria-label="Focus ${escapeHtml(node.title || node.node_key)}" cx="${Math.round(pad + pos.x * scaleX)}" cy="${Math.round(pad + pos.y * scaleY)}" r="${radius.toFixed(1)}"></circle>`;
    })
    .join("");
  const highDegree = [...positionedNodes]
    .sort((a, b) => graphNodeDegree(b, edges) - graphNodeDegree(a, edges))
    .slice(0, 3)
    .map((node) => `<button type="button" data-graph-node="${escapeHtml(node.node_key)}">${escapeHtml(truncateGraphLabel(node.title || node.node_key, 28))}</button>`)
    .join("");
  const edgeClasses = countBy(edges, (edge) => graphEdgeClass(edge));
  const reductionLabel = totalEdgeCount > edges.length
    ? `${edges.length}/${totalEdgeCount} relation lines`
    : `${edges.length} relation lines`;
  return `
    <section class="graph-overview-panel" aria-label="Knowledge graph overview">
      <div>
        <span class="badge">Map overview</span>
        <strong>${escapeHtml(labelizeGraph(state.graphLayoutMode))} · ${escapeHtml(labelizeGraph(state.graphDensityMode))}</strong>
        <small>${positionedNodes.length} nodes mapped · ${escapeHtml(reductionLabel)} · labels prioritize high-signal nodes</small>
        <div class="graph-overview-focus">${highDegree || "<span>No focus nodes</span>"}</div>
        <div class="graph-overview-layers">
          <span>${escapeHtml(String(edgeClasses.explicit || 0))} explicit</span>
          <span>${escapeHtml(String(edgeClasses.inferred || 0))} inferred</span>
          <span>${escapeHtml(String((edgeClasses.candidate || 0) + (edgeClasses["duplicate-candidate"] || 0) + (edgeClasses["contradiction-candidate"] || 0)))} governed</span>
        </div>
      </div>
      <svg viewBox="0 0 ${viewWidth} ${viewHeight}" role="img" aria-label="Miniature graph overview">
        <rect x="1" y="1" width="${viewWidth - 2}" height="${viewHeight - 2}" rx="12"></rect>
        <g class="overview-edges">${edgeSvg}</g>
        <g class="overview-nodes">${nodeSvg}</g>
      </svg>
    </section>
  `;
}

function renderGraphSvgEdge(edge, positions, layer = "visible", activePath = null) {
  const source = positions.get(edge.source);
  const target = positions.get(edge.target);
  if (!source || !target) return "";
  const relation = edge.relation_type || edge.edge_type || "related";
  const review = edge.review_state || "unreviewed";
  const midX = (source.x + target.x) / 2;
  const midY = (source.y + target.y) / 2 - 16;
  const curve = `M${source.x} ${source.y} Q${Math.round(midX)} ${Math.round(midY)} ${target.x} ${target.y}`;
  const isActivePath = activePath?.edge === edge;
  const isSelected = state.selectedGraphEdgeKey === edge.edge_key;
  const isRecentlyReviewed = state.lastGraphEdgeReview?.edgeKey === edge.edge_key;
  const confidenceBand = graphEdgeConfidenceBand(edge);
  const visual = graphEdgeVisualWeight(edge);
  if (layer === "hit") {
    return `
      <path
        class="graph-svg-edge-hit"
        data-graph-edge="${escapeHtml(edge.edge_key || "")}"
        tabindex="0"
        d="${curve}"
      ></path>
    `;
  }
  return `
    <g class="graph-svg-edge-group" data-graph-edge="${escapeHtml(edge.edge_key || "")}">
      <path
        class="graph-svg-edge ${safeGraphClass(relation)} ${safeGraphClass(graphEdgeClass(edge))} ${safeGraphClass(review)} confidence-${safeGraphClass(confidenceBand.key)} ${isSelected ? "selected" : ""} ${isActivePath ? "active-path" : ""} ${isRecentlyReviewed ? "recently-reviewed" : ""}"
        style="--edge-width: ${visual.width}; --edge-opacity: ${visual.opacity};"
        data-graph-edge="${escapeHtml(edge.edge_key || "")}"
        d="${curve}"
        marker-end="url(#graphArrow)"
      >
        <title>${escapeHtml(labelizeGraph(relation))} · ${escapeHtml(review)} · ${escapeHtml(confidenceBand.label)}</title>
      </path>
    </g>
  `;
}

function renderGraphSvgEdgeLabel(edge, positions, activePath = null) {
  const source = positions.get(edge.source);
  const target = positions.get(edge.target);
  if (!source || !target) return "";
  const isActivePath = activePath?.edge === edge;
  const isSelected = state.selectedGraphEdgeKey === edge.edge_key;
  const label = graphEdgeInlineLabel(edge, { active: isActivePath, selected: isSelected });
  if (!label) return "";
  const midX = (source.x + target.x) / 2;
  const midY = (source.y + target.y) / 2 - 52;
  return `
    <g class="graph-svg-edge-label ${safeGraphClass(graphEdgeClass(edge))} ${isActivePath ? "active-path" : ""}" data-graph-edge="${escapeHtml(edge.edge_key || "")}" transform="translate(${Math.round(midX)} ${Math.round(midY)})">
      <rect x="-48" y="-14" width="96" height="24" rx="12"></rect>
      <text y="3">${escapeHtml(label)}</text>
    </g>
  `;
}

function graphEdgeInlineLabel(edge, flags = {}) {
  const edgeClass = graphEdgeClass(edge);
  const review = String(edge.review_state || "unreviewed");
  const confidence = graphEdgeConfidencePercent(edge);
  const shouldShow =
    flags.active
    || flags.selected
    || review === "needs-rework"
    || edgeClass.includes("candidate");
  if (!shouldShow) return "";
  if (flags.active) return `path ${confidence || "?"}%`;
  if (review === "needs-rework") return "rework";
  if (edgeClass.includes("candidate")) return `candidate ${confidence || "?"}%`;
  if (flags.selected) return `${labelizeGraph(edgeClass)} ${confidence || "?"}%`;
  return `${confidence}%`;
}

function graphEdgeConfidencePercent(edge) {
  const raw = Number(edge.confidence ?? 0);
  if (!Number.isFinite(raw) || raw <= 0) return 0;
  return raw <= 1 ? Math.round(raw * 100) : Math.round(raw);
}

function graphEdgeConfidenceBand(edge = {}) {
  return graphConfidenceBandMeta(graphEdgeConfidenceBandKey(edge));
}

function graphEdgeConfidenceBandKey(edge = {}) {
  const confidence = graphEdgeConfidencePercent(edge);
  if (!confidence) return "unscored";
  if (confidence >= 75) return "high";
  if (confidence >= 45) return "medium";
  return "low";
}

function graphConfidenceBandMeta(key = "unscored") {
  const bands = {
    high: {
      key: "high",
      label: "High confidence",
      detail: "strong enough for primary retrieval when governance allows",
    },
    medium: {
      key: "medium",
      label: "Medium confidence",
      detail: "usable with citation and context check",
    },
    low: {
      key: "low",
      label: "Low confidence",
      detail: "weak signal; prefer review before decisions",
    },
    unscored: {
      key: "unscored",
      label: "Unscored",
      detail: "relation lacks confidence metadata",
    },
  };
  return bands[key] || bands.unscored;
}

function graphEdgeVisualWeight(edge = {}) {
  const confidence = graphEdgeConfidencePercent(edge);
  const band = graphEdgeConfidenceBandKey(edge);
  if (band === "unscored") return { width: "1.7px", opacity: "0.48" };
  const width = 1.8 + Math.min(100, Math.max(0, confidence)) / 100 * 2.3;
  const opacity = 0.48 + Math.min(100, Math.max(0, confidence)) / 100 * 0.44;
  return {
    width: `${width.toFixed(2)}px`,
    opacity: opacity.toFixed(2),
  };
}

function renderGraphSvgNode(node, pos, edges, activePath = null, topology = {}) {
  const selected = state.selectedGraphNodeKey === node.node_key ? " selected" : "";
  const active = activePath?.nodeKeys?.has(node.node_key) ? " active-path" : "";
  const degree = graphNodeDegree(node, edges);
  const radius = Math.max(18, Math.min(34, 18 + degree * 2));
  const labelPolicy = graphNodeLabelPolicy(node, degree, activePath, topology);
  const label = truncateGraphLabel(node.title || node.node_key, labelPolicy.maxLength);
  const labelWidth = Math.max(68, Math.min(210, label.length * 6.2 + 22));
  const labelY = radius + 15;
  const labelMarkup = labelPolicy.visible
    ? `
      <g class="graph-svg-label-wrap ${escapeHtml(labelPolicy.className)}" transform="translate(0 ${labelY})">
        <rect x="${Math.round(-labelWidth / 2)}" y="-10" width="${Math.round(labelWidth)}" height="22" rx="11"></rect>
        <text class="graph-svg-label ${escapeHtml(labelPolicy.className)}" y="5">${escapeHtml(label)}</text>
      </g>
    `
    : "";
  return `
    <g class="graph-svg-node ${safeGraphClass(node.node_type || "node")} ${safeGraphClass(node.review_state || "unknown")}${selected}${active}" data-graph-node="${escapeHtml(node.node_key)}" transform="translate(${pos.x} ${pos.y})">
      <circle r="${radius}"></circle>
      <text y="4">${escapeHtml(graphNodeInitial(node))}</text>
      ${labelMarkup}
      <title>${escapeHtml(node.title || node.node_key)} · ${escapeHtml(node.review_state || "unknown")} · ${degree} links</title>
    </g>
  `;
}

function graphNodeLabelPolicy(node, degree, activePath = null, topology = {}) {
  const selected = state.selectedGraphNodeKey === node.node_key;
  const active = activePath?.nodeKeys?.has(node.node_key);
  const budgeted = topology.labelNodeKeys?.has?.(node.node_key);
  const highSignal = selected || active || degree >= 5 || node.review_state === "approved" || node.node_type === "cluster";
  const mediumSignal = degree >= 3 || node.node_type === "skill" || node.node_type === "task";
  const density = state.graphDensityMode;
  if (!selected && !active && !budgeted) return { className: "hidden-label", maxLength: 0, visible: false };
  if (density === "compact" && !highSignal) return { className: "low-priority-label", maxLength: 15, visible: true };
  if (!highSignal && !mediumSignal) return { className: "low-priority-label", maxLength: density === "spacious" ? 22 : 16, visible: true };
  const maxLength = topology.layoutMode === "cluster"
    ? density === "spacious" ? 30 : 22
    : density === "spacious" ? 34 : 26;
  return { className: "primary-label", maxLength, visible: true };
}

function graphNodeDegree(node, edges) {
  return edges.filter((edge) => edge.source === node.node_key || edge.target === node.node_key).length;
}

function graphNodeInitial(node) {
  const type = String(node.node_type || "node").trim();
  if (type === "cluster") return "K";
  if (type === "evidence") return "E";
  if (type === "concept") return "C";
  if (type === "skill") return "S";
  if (type === "task") return "T";
  return "N";
}

function truncateGraphLabel(value, maxLen) {
  const text = String(value || "").replace(/\s+/g, " ").trim();
  return text.length <= maxLen ? text : `${text.slice(0, maxLen - 1).trim()}…`;
}

function renderGraphInferenceVisual(graph, nodes, edges) {
  const target = $("#graphInferenceVisual");
  if (!target) return;
  if (!nodes.length) {
    target.innerHTML = "";
    return;
  }
  const explicitEdges = edges.filter((edge) => graphEdgeClass(edge) === "explicit");
  const inferredEdges = edges.filter((edge) => graphEdgeClass(edge) === "inferred");
  const candidateEdges = edges.filter((edge) => graphEdgeClass(edge) === "candidate");
  const reviewedEdges = edges.filter((edge) => edge.review_state && edge.review_state !== "unreviewed");
  const approvedNodes = nodes.filter((node) => node.review_state === "approved").length;
  const draftNodes = nodes.length - approvedNodes;
  target.innerHTML = `
    <section class="kg-visual-panel">
      <div>
        <span>1 · Plain OKF</span>
        <strong>Concepts and evidence</strong>
        <p>Markdown nodes remain the authoring source of truth.</p>
      </div>
      ${knowledgeGraphMiniSvg("plain", approvedNodes, draftNodes, explicitEdges.length, 0, 0)}
      <small>${approvedNodes} approved · ${draftNodes} draft/pending</small>
    </section>
    <section class="kg-visual-panel">
      <div>
        <span>2 · Knowledge graph</span>
        <strong>Typed relationships</strong>
        <p>Clusters, sources, skills, and actor context become queryable edges.</p>
      </div>
      ${knowledgeGraphMiniSvg("graph", approvedNodes, draftNodes, explicitEdges.length, inferredEdges.length, 0)}
      <small>${explicitEdges.length} explicit · ${inferredEdges.length} inferred</small>
    </section>
    <section class="kg-visual-panel inference">
      <div>
        <span>3 · Inference overlay</span>
        <strong>Governed candidates</strong>
        <p>Duplicate and contradiction candidates wait for human graph review.</p>
      </div>
      ${knowledgeGraphMiniSvg("inference", approvedNodes, draftNodes, explicitEdges.length, inferredEdges.length, candidateEdges.length)}
      <small>${candidateEdges.length} candidates · ${reviewedEdges.length} reviewed</small>
    </section>
  `;
}

function renderGraphInterpretationPanel(graph, nodes, edges) {
  const target = $("#graphInterpretationPanel");
  if (!target) return;
  if (!nodes.length) {
    target.innerHTML = "";
    return;
  }
  const nodeStates = countBy(nodes, (node) => node.review_state || "unknown");
  const edgeKinds = countBy(edges, (edge) => graphEdgeClass(edge));
  const relationCounts = countBy(edges, (edge) => edge.relation_type || edge.edge_type || "related");
  const topRelations = Object.entries(relationCounts)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, 5)
    .map(([relation, count]) => `<span>${escapeHtml(labelizeGraph(relation))} · ${count}</span>`)
    .join("");
  const candidateCount = edgeKinds.candidate || 0;
  const approvedCount = nodeStates.approved || 0;
  const draftCount = nodes.length - approvedCount;
  const inferencePosture = candidateCount
    ? "Candidate edges are advisory only until accepted in governance review."
    : "No unresolved inference candidates in the current view.";
  target.innerHTML = `
    <section class="graph-meaning-card lead">
      <span class="badge">Reading guide</span>
      <h3>Approved memory first. Drafts and inference stay visible, but governed.</h3>
      <p>The graph separates source-backed OKF concepts from AI-proposed relationships so the twin can use context without silently promoting weak knowledge.</p>
      <div class="graph-meaning-metrics">
        <strong>${approvedCount}<span>approved nodes</span></strong>
        <strong>${draftCount}<span>draft or pending nodes</span></strong>
        <strong>${edgeKinds.explicit || 0}<span>explicit edges</span></strong>
        <strong>${edgeKinds.inferred || 0}<span>inferred edges</span></strong>
        <strong>${candidateCount}<span>review candidates</span></strong>
      </div>
    </section>
    <section class="graph-meaning-card compact">
      <span class="badge">Legend</span>
      <div class="graph-legend-grid">
        <span><i class="legend-node approved"></i>Approved concept</span>
        <span><i class="legend-node pending-review"></i>Draft or pending</span>
        <span><i class="legend-node needs-rework"></i>Needs rework</span>
        <span><i class="legend-edge explicit"></i>Source-backed edge</span>
        <span><i class="legend-edge inferred"></i>AI-inferred edge</span>
        <span><i class="legend-edge candidate"></i>Candidate edge</span>
        <span><i class="legend-edge duplicate-candidate"></i>Duplicate candidate</span>
        <span><i class="legend-edge contradiction-candidate"></i>Contradiction candidate</span>
      </div>
      <div class="graph-relation-preview">${topRelations || "<span>No visible relation types</span>"}</div>
    </section>
    <section class="graph-meaning-card compact">
      <span class="badge">AI usage</span>
      <ol class="graph-ai-steps">
        <li><strong>Retrieve</strong><span>Rank approved concepts, then include drafts only when explicitly allowed.</span></li>
        <li><strong>Reason</strong><span>Use explicit and inferred paths as explainable answer context.</span></li>
        <li><strong>Govern</strong><span>${escapeHtml(inferencePosture)}</span></li>
      </ol>
    </section>
  `;
}

function knowledgeGraphMiniSvg(mode, approvedNodes, draftNodes, explicitEdges, inferredEdges, candidateEdges) {
  const showInference = mode === "inference";
  const showGraph = mode !== "plain";
  const safeCounts = {
    approvedNodes: Math.min(approvedNodes, 99),
    draftNodes: Math.min(draftNodes, 99),
    explicitEdges: Math.min(explicitEdges, 99),
    inferredEdges: Math.min(inferredEdges, 99),
    candidateEdges: Math.min(candidateEdges, 99),
  };
  return `
    <svg class="kg-mini-svg" viewBox="0 0 340 170" role="img" aria-label="${escapeHtml(labelizeGraph(mode))} knowledge graph visualization">
      <defs>
        <marker id="kg-arrow-${mode}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto">
          <path d="M0,0 L8,4 L0,8 Z"></path>
        </marker>
      </defs>
      <line class="kg-edge explicit" x1="70" y1="54" x2="162" y2="86"></line>
      <line class="kg-edge explicit" x1="70" y1="116" x2="162" y2="86"></line>
      ${showGraph ? '<line class="kg-edge inferred" x1="162" y1="86" x2="270" y2="48"></line><line class="kg-edge inferred" x1="162" y1="86" x2="270" y2="124"></line>' : ""}
      ${showInference ? '<path class="kg-edge candidate" d="M72 54 C156 18, 210 18, 270 48"></path><path class="kg-edge candidate contradiction" d="M72 116 C150 150, 214 150, 270 124"></path>' : ""}
      <g class="kg-node approved" transform="translate(70 54)">
        <circle r="20"></circle><text y="5">C</text>
      </g>
      <g class="kg-node evidence" transform="translate(70 116)">
        <rect x="-20" y="-16" width="40" height="32" rx="8"></rect><text y="5">E</text>
      </g>
      <g class="kg-node cluster" transform="translate(162 86)">
        <circle r="24"></circle><text y="5">K</text>
      </g>
      ${showGraph ? '<g class="kg-node skill" transform="translate(270 48)"><rect x="-24" y="-16" width="48" height="32" rx="8"></rect><text y="5">S</text></g><g class="kg-node draft" transform="translate(270 124)"><circle r="20"></circle><text y="5">D</text></g>' : ""}
      <text class="kg-count" x="18" y="22">${safeCounts.approvedNodes} approved</text>
      <text class="kg-count" x="178" y="22">${safeCounts.explicitEdges} explicit</text>
      ${showGraph ? `<text class="kg-count" x="178" y="154">${safeCounts.inferredEdges} inferred</text>` : ""}
      ${showInference ? `<text class="kg-count candidate" x="18" y="154">${safeCounts.candidateEdges} candidates</text>` : ""}
    </svg>
  `;
}

function graphEdgeClass(edge) {
  const edgeClass = String(edge.edge_class || "").toLowerCase();
  const edgeType = String(edge.edge_type || "").toLowerCase();
  const relation = String(edge.relation_type || "").toLowerCase();
  const reviewState = String(edge.review_state || "").toLowerCase();
  const signals = [edgeClass, edgeType, relation, reviewState];
  if (signals.some((value) => value === "contradiction_candidate" || value.includes("contradiction"))) return "contradiction-candidate";
  if (signals.some((value) => value === "duplicate_candidate" || value.includes("duplicate"))) return "duplicate-candidate";
  if (signals.some((value) => value.includes("candidate"))) return "candidate";
  if (edgeClass.includes("explicit") || edgeType.includes("explicit")) return "explicit";
  if (edgeClass.includes("inferred") || edgeType.includes("inferred") || relation.includes("inferred")) return "inferred";
  if (["derived_from", "member_of_cluster", "validated_by", "supported_by", "uses_context"].includes(relation || edgeType)) return "explicit";
  if (reviewState === "approved" || reviewState === "accepted") return "explicit";
  return "inferred";
}

function applyGraphEdgeFilters(edges = []) {
  return edges
    .filter((edge) => state.graphEdgeTypeFilter === "all" || (edge.relation_type || edge.edge_type || "related") === state.graphEdgeTypeFilter)
    .filter((edge) => state.graphEdgeClassFilter === "all" || graphEdgeMatchesClassFilter(edge, state.graphEdgeClassFilter));
}

function graphEdgeMatchesClassFilter(edge = {}, filter = "all") {
  if (!filter || filter === "all") return true;
  const edgeClass = graphEdgeClass(edge);
  if (filter === "candidate") return String(edgeClass).includes("candidate");
  return edgeClass === filter;
}

function graphPositions(nodes, width, height) {
  const centerX = width / 2;
  const centerY = height / 2;
  const radiusX = width * 0.39;
  const radiusY = height * 0.36;
  const groups = graphGroupBy(nodes, (node) => node.node_type || "node");
  const ordered = Object.values(groups).flatMap((values) => values);
  const positions = new Map();
  ordered.forEach((node, index) => {
    const angle = (2 * Math.PI * index) / Math.max(ordered.length, 1) - Math.PI / 2;
    const weight = node.review_state === "approved" ? 0.72 : 1;
    positions.set(node.node_key, {
      x: Math.round(centerX + Math.cos(angle) * radiusX * weight),
      y: Math.round(centerY + Math.sin(angle) * radiusY * weight),
    });
  });
  return positions;
}

async function openGraphNode(nodeKey) {
  state.selectedGraphNodeKey = nodeKey;
  renderGraphCockpit();
  if (staticPagesMode) {
    state.okfGraphNodeDetail = buildStaticGraphNodeDetail(nodeKey);
    renderGraphNodeDetail();
    return;
  }
  try {
    const [detail] = await Promise.all([
      getJson(`/api/okf/graph/node?node_key=${encodeURIComponent(nodeKey)}&twin=${encodeURIComponent(state.activeTwin)}&include_drafts=true`),
      refreshGraphEdgeReviews(),
    ]);
    state.okfGraphNodeDetail = detail;
    renderGraphNodeDetail();
  } catch (error) {
    $("#graphNodeDetail").innerHTML = `<p class="warning-copy">Node detail failed: ${escapeHtml(compactError(error.message))}</p>`;
  }
}

function buildStaticGraphNodeDetail(nodeKey) {
  const graph = state.okfGraph || {};
  const nodes = graph.nodes || [];
  const edges = graph.edges || [];
  const node = nodes.find((item) => item.node_key === nodeKey);
  if (!node) return { node: null, edges: [], neighbors: [], evidence: [] };
  const directEdges = edges.filter((edge) => edge.source === nodeKey || edge.target === nodeKey);
  const neighborKeys = new Set(directEdges.map((edge) => (edge.source === nodeKey ? edge.target : edge.source)));
  const neighbors = nodes.filter((item) => neighborKeys.has(item.node_key));
  const evidence = [
    {
      title: node.source_anchor || node.title || "Static OKF source",
      path: node.okf_path || node.path || "",
      evidence_path: node.okf_path || node.path || "",
      excerpt: node.summary || "",
    },
  ].filter((item) => item.path || item.title);
  return { node, edges: directEdges, neighbors, evidence };
}

async function refreshGraphEdgeReviews(force = false) {
  if (!force && state.graphEdgeReviewsLoadedFor === state.activeTwin) return state.graphEdgeReviews;
  const result = await getJson(`/api/okf/graph/edge-reviews?twin=${encodeURIComponent(state.activeTwin)}&limit=300`);
  state.graphEdgeReviews = result.reviews || [];
  state.graphEdgeReviewsLoadedFor = state.activeTwin;
  return state.graphEdgeReviews;
}

function renderGraphNodeDetail() {
  const detail = state.okfGraphNodeDetail;
  if (!detail?.node) {
    $("#graphNodeDetail").innerHTML = "Select a node to inspect evidence, neighbors, and governance state.";
    return;
  }
  const node = detail.node;
  const graph = state.okfGraph || {};
  const graphEdges = graph.edges || [];
  const graphNodes = graph.nodes || [];
  const directEdges = detail.edges || [];
  const evidenceLinks = directEdges.filter((edge) => {
    const relation = edge.relation_type || edge.edge_type || "";
    return relation === "derived_from" || edge.evidence_path || String(edge.source).startsWith("evidence:") || String(edge.target).startsWith("evidence:");
  });
  const governanceEdges = directEdges.filter((edge) => String(edge.relation_type || edge.edge_type || "").includes("candidate"));
  const evidence = (detail.evidence || [])
    .slice(0, 6)
    .map((item) => {
      const path = item.path || item.okf_path || item.evidence_path || "";
      return `
        <li class="graph-evidence-item">
          <span>${escapeHtml(item.title || path || item.node_key || "Evidence")}</span>
          ${path ? `<code>${escapeHtml(path)}</code>` : ""}
        </li>
      `;
    })
    .join("");
  const neighbors = (detail.neighbors || [])
    .slice(0, 8)
    .map((item) => {
      const relationCount = graphEdges.filter((edge) =>
        (edge.source === node.node_key && edge.target === item.node_key)
        || (edge.target === node.node_key && edge.source === item.node_key),
      ).length;
      return `
        <li>
          <button class="graph-neighbor-button" type="button" data-graph-node="${escapeHtml(item.node_key)}">
            <span>${escapeHtml(item.title || item.node_key)}</span>
            <small>${escapeHtml(labelizeGraph(item.node_type || "node"))} · ${relationCount} relation${relationCount === 1 ? "" : "s"}</small>
          </button>
        </li>
      `;
    })
    .join("");
  const conceptPath = node.path || node.okf_path || "";
  const reviewButton = conceptPath && node.node_type === "concept"
    ? `<button class="secondary small" type="button" data-graph-review-path="${escapeHtml(conceptPath)}">Open concept review</button>`
    : "";
  const detailNodeMap = new Map([node, ...(detail.neighbors || [])].map((item) => [item.node_key, item]));
  graphNodes.forEach((item) => {
    if (!detailNodeMap.has(item.node_key)) detailNodeMap.set(item.node_key, item);
  });
  const relations = (detail.edges || [])
    .slice(0, 10)
    .map((edge) => {
      const relation = edge.relation_type || edge.edge_type || "related";
      const reviewState = edge.review_state || "unreviewed";
      const candidate = String(relation).includes("candidate");
      const isOutgoing = edge.source === node.node_key;
      const otherKey = isOutgoing ? edge.target : edge.source;
      const other = detailNodeMap.get(otherKey) || {};
      const direction = isOutgoing ? "to" : "from";
      const reviewActions = candidate && reviewState === "unreviewed"
        ? `
          <span class="graph-edge-review-actions">
            <button class="small secondary" type="button" data-graph-edge-key="${escapeHtml(edge.edge_key)}" data-graph-edge-action="accepted">Accept</button>
            <button class="small danger" type="button" data-graph-edge-key="${escapeHtml(edge.edge_key)}" data-graph-edge-action="rejected">Reject</button>
            <button class="small secondary" type="button" data-graph-edge-key="${escapeHtml(edge.edge_key)}" data-graph-edge-action="needs-rework">Needs rework</button>
          </span>
        `
        : "";
      const proposalButton = candidate ? renderGraphProposalButton(edge) : "";
      const selected = state.selectedGraphEdgeKey === edge.edge_key ? " selected" : "";
      const usage = graphEdgeUsagePolicy(edge);
      return `
        <li class="graph-edge-line ${safeGraphClass(reviewState)}${selected}" data-graph-edge="${escapeHtml(edge.edge_key || "")}">
          <span>${escapeHtml(labelizeGraph(relation))} ${escapeHtml(direction)} ${escapeHtml(other.title || otherKey || "node")}</span>
          <small>${escapeHtml(graphRelationMeaning(edge, node, other))}</small>
          <small>confidence ${escapeHtml(edge.confidence ?? "-")} · ${escapeHtml(reviewState)} · ${escapeHtml(usage.label)}${edge.review_note ? ` · ${escapeHtml(edge.review_note)}` : ""}</small>
          ${reviewActions}
          ${proposalButton}
        </li>
      `;
    })
    .join("");
  const nodeDegree = directEdges.length || graphNodeDegree(node, graphEdges);
  const evidenceCount = Math.max((detail.evidence || []).length, evidenceLinks.length);
  const governanceLabel = governanceEdges.length ? `${governanceEdges.length} candidate gate${governanceEdges.length === 1 ? "" : "s"}` : "no candidate gates";
  const sourceKind = node.node_type === "evidence" ? "Source evidence" : node.node_type === "cluster" ? "Derived cluster" : "OKF concept";
  const readiness = graphNodeActorReadiness(node, evidenceCount, governanceEdges, directEdges);
  const provenance = graphNodeProvenanceRef(node);
  const sourceActions = renderGraphNodeSourceActions(node, provenance);
  const insight = graphNodeInsightPack(node, directEdges, detailNodeMap, evidenceCount, governanceEdges, readiness, provenance);
  const governanceQueue = renderGraphNodeGovernanceQueue(node, governanceEdges, detailNodeMap);
  const reviewFeedback = renderGraphNodeReviewFeedback(node, detailNodeMap);
  const reviewHistory = renderGraphNodeReviewHistory(node, detailNodeMap);
  const relationLayerSummary = renderGraphNodeRelationLayerSummary(directEdges);
  const promotionReadiness = graphNodePromotionReadiness(node, directEdges);
  const evidenceEligibility = graphNodeEvidenceEligibility(node, evidenceCount, governanceEdges, directEdges);
  const actorUse = graphNodeActorUseClassification(node, readiness, evidenceEligibility, governanceEdges, directEdges);
  const sourceEvidenceContract = renderGraphNodeSourceEvidenceContract(node, provenance, evidenceEligibility, evidenceCount, governanceEdges, directEdges);
  $("#graphNodeDetail").innerHTML = `
    <div class="graph-detail-card ${safeGraphClass(node.review_state || "unknown")}">
      <div class="graph-detail-hero">
        <span class="badge">${escapeHtml(labelizeGraph(node.node_type || "node"))}</span>
        <h4>${escapeHtml(node.title || node.node_key)}</h4>
        <p>${escapeHtml(node.summary || node.description || "No summary available.")}</p>
      </div>
      ${renderGraphNodeActorUseClassification(actorUse)}
      ${renderGraphNodeInsightPanel(insight)}
      <div class="graph-detail-health">
        <strong>${nodeDegree}<span>relations</span></strong>
        <strong>${evidenceCount}<span>evidence</span></strong>
        <strong>${escapeHtml(node.review_state || "unknown")}<span>review</span></strong>
      </div>
      ${renderGraphConsumerBadges(node)}
      ${renderGraphNodeActorReadiness(readiness)}
      ${renderGraphNodeEvidenceEligibility(evidenceEligibility)}
      ${sourceEvidenceContract}
      ${relationLayerSummary}
      ${governanceQueue}
      ${reviewFeedback}
      ${reviewHistory}
      ${renderGraphNodePromotionReadiness(promotionReadiness)}
      <section class="graph-detail-section">
        <div class="graph-detail-section-head">
          <h5>Source and governance</h5>
          <span class="graph-detail-actions">${sourceActions}${reviewButton}</span>
        </div>
        <p class="graph-detail-note">Snapshot actions export the current projection with this selected node, source evidence, relation context, and governance history.</p>
        <dl class="detail-list">
          ${detailRow("Source type", sourceKind)}
          ${detailRow("Cluster", node.cluster || node.metadata?.cluster || "-")}
          ${detailRow("Maturity", node.okf_maturity || node.evidence_strength || "-")}
          ${detailRow("Governance", governanceLabel)}
          ${detailRow("Path", conceptPath || "-")}
        </dl>
      </section>
      <section class="graph-detail-section">
        <div class="graph-detail-section-head">
          <h5>Evidence</h5>
          <span>${evidenceCount} linked</span>
        </div>
        <ul class="graph-evidence-list">${evidence || "<li class=\"graph-evidence-item\"><span>No direct evidence linked.</span></li>"}</ul>
      </section>
      <section class="graph-detail-section">
        <div class="graph-detail-section-head">
          <h5>Relation reasoning</h5>
          <span>${directEdges.length} direct</span>
        </div>
        <ul class="graph-relation-list">${relations || "<li>No direct relation edges.</li>"}</ul>
      </section>
      <section class="graph-detail-section">
        <div class="graph-detail-section-head">
          <h5>Neighbors</h5>
          <span>${(detail.neighbors || []).length} nodes</span>
        </div>
        <ul class="graph-neighbor-list">${neighbors || "<li>No direct neighbors.</li>"}</ul>
      </section>
    </div>
  `;
  bindGraphRelationLayerControls($("#graphNodeDetail"));
  bindGraphEdgeReviewControls($("#graphNodeDetail"));
  renderGraphQualityActions();
}

function graphNodePromotionReadiness(node = {}, directEdges = []) {
  const nodePath = node.path || node.okf_path || "";
  const nodeKey = node.node_key || "";
  const approvedHandoffs = (state.knowledgeFabricIngestQueue || []).filter((item) => {
    if (item.review_state !== "approved") return false;
    const paths = [item.concept_path, item.evidence_path, item.transcript_path].filter(Boolean);
    const pathMatch = nodePath && paths.includes(nodePath);
    const edgeMatch = (Array.isArray(item.candidate_edges) ? item.candidate_edges : []).some((edge) => {
      const values = [edge.source, edge.target, edge.source_path, edge.target_path, edge.path].filter(Boolean).map(String);
      return values.includes(nodeKey) || (nodePath && values.includes(nodePath));
    });
    return pathMatch || edgeMatch;
  });
  const classCounts = directEdges.reduce((counts, edge) => {
    const edgeClass = graphEdgeClass(edge);
    counts[edgeClass] = (counts[edgeClass] || 0) + 1;
    return counts;
  }, {});
  const accepted = directEdges.filter((edge) => ["approved", "accepted"].includes(String(edge.review_state || ""))).length;
  const blocked = directEdges.filter((edge) => ["rejected", "needs-rework"].includes(String(edge.review_state || ""))).length;
  const candidate = directEdges.filter((edge) => String(graphEdgeClass(edge)).includes("candidate") || String(edge.review_state || "").includes("candidate")).length;
  const explicit = classCounts.explicit || 0;
  const inferred = classCounts.inferred || 0;
  const queueCandidateEdges = approvedHandoffs.reduce((count, item) => count + (Array.isArray(item.candidate_edges) ? item.candidate_edges.length : 0), 0);
  const readyForPr = approvedHandoffs.length > 0 && blocked === 0;
  const status = readyForPr && candidate === 0
    ? "ready"
    : approvedHandoffs.length || accepted || candidate
      ? "caution"
      : "blocked";
  const summary = status === "ready"
    ? "Relations are ready for knowledge-repo graph promotion after PR review."
    : status === "caution"
      ? "Some relation evidence exists, but candidate or queue gates still need curator review."
      : "No approved handoff is linked to this node yet; keep relations out of trusted graph promotion.";
  return {
    status,
    summary,
    approvedHandoffs,
    queueCandidateEdges,
    explicit,
    inferred,
    candidate,
    accepted,
    blocked,
    nextAction: status === "ready"
      ? "Use approved PR handoff, then apply accepted graph edges after merge."
      : status === "caution"
        ? "Review candidate edges and resolve blocked relations before vector refresh."
        : "Approve a Knowledge Fabric handoff or attach source evidence first.",
  };
}

