function renderGraphPostgresMirrorStatus(status = {}) {
  const stateLabel = status?.status || "unknown";
  const ready = stateLabel === "ready";
  const blockers = status?.blockers || [];
  return `
    <div class="graph-postgres-status ${safeGraphClass(stateLabel)}">
      <div>
        <span class="badge">Hosted mirror</span>
        <strong>${escapeHtml(ready ? "Postgres graph snapshot available" : `Postgres ${stateLabel}`)}</strong>
        <small>${escapeHtml(ready
          ? `Snapshot ${status.snapshot_hash || "-"} can be used for hosted graph checks.`
          : blockers[0] || status.next_action || "Local file-backed graph is active.")}</small>
      </div>
      <span>${escapeHtml(status?.database_configured ? "DATABASE_URL set" : "local-first")}</span>
    </div>
  `;
}

function renderGraphReviewTimeline() {
  const reviews = (state.graphEdgeReviews || []).slice(0, 8);
  const tasks = (state.graphRecommendationTasks || []).slice(0, 4);
  const items = [
    ...reviews.map((review) => ({
      type: "edge review",
      title: `${labelizeGraph(review.relation_type || review.edge_type || "relation")} ${review.decision || "reviewed"}`,
      status: review.decision || "reviewed",
      timestamp: review.reviewed_at || "",
      detail: review.note || review.edge_key || "",
      path: review.path || "",
    })),
    ...tasks.map((task) => ({
      type: "task",
      title: task.title || labelizeGraph(task.recommendation_type || "recommendation"),
      status: task.status || "pending_review",
      timestamp: task.reviewed_at || task.created_at || "",
      detail: task.benefit || task.detail || "",
      path: task.path || "",
    })),
  ].sort((a, b) => String(b.timestamp).localeCompare(String(a.timestamp))).slice(0, 8);
  return `
    <div class="graph-review-timeline">
      <div class="graph-context-tool-head">
        <div>
          <strong>Graph review timeline</strong>
          <p>Recent human decisions and queued graph tasks that influence actor reliability.</p>
        </div>
        <span class="badge">${items.length} events</span>
      </div>
      ${items.length ? `<ol>${items.map((item) => `
        <li class="${safeGraphClass(item.status)}">
          <span>${escapeHtml(item.type)}</span>
          <strong>${escapeHtml(item.title)}</strong>
          <small>${escapeHtml([item.timestamp, item.detail].filter(Boolean).join(" · "))}</small>
          ${item.path ? `<code>${escapeHtml(item.path)}</code>` : ""}
        </li>
      `).join("")}</ol>` : '<p class="empty">No graph review events yet.</p>'}
    </div>
  `;
}

function applyGraphActorRecommendationPrompt(mode = "projection") {
  if (!state.okfGraph?.nodes?.length) {
    showToast("Graph unavailable", "Refresh the graph before preparing an actor prompt.", "error");
    return;
  }
  const snapshot = buildGraphSnapshotJson();
  const selectedRelation = selectedGraphRelationContextPacket();
  const selectedNode = selectedGraphContextPacket();
  const lines = [
    "## Actor-agent recommendation request",
    `Twin: ${state.activeTwin}`,
    `Mode: ${mode}`,
    "",
    "### Goal",
    "Recommend how the intellectual twin should use this OKF graph projection when answering or activating a skill.",
    "",
    "### Actor decision rules",
    "- Prefer approved concepts and explicit source-backed relations.",
    "- Use inferred relations only with attribution.",
    "- Treat candidate, contradiction, unreviewed, and needs-rework paths as governance gates.",
    "- Recommend human approval before external actions or decisions based on weak graph paths.",
    "",
    "### Current projection",
    formatGraphProjectionExplainPrompt(snapshot),
  ];
  if (selectedRelation) {
    lines.push("", "### Selected relation", formatSelectedGraphRelationContextPacket(selectedRelation));
  } else if (selectedNode) {
    lines.push("", "### Selected node", formatSelectedGraphContextPacket(selectedNode));
  }
  const target = $("#chatSkillKnowledge");
  if (!target) {
    showToast("Chat unavailable", "Open chat before applying actor recommendation context.", "error");
    return;
  }
  target.value = [target.value.trim(), lines.join("\n")].filter(Boolean).join("\n\n");
  target.dispatchEvent(new Event("input", { bubbles: true }));
  setLegacyManualRequestValue("Recommend how the twin should use this graph context for safe actor steering.");
  showView("chat");
  const details = $("#chatSkillContext");
  if (details) details.open = true;
  $("#n8nChatMount")?.scrollIntoView({ block: "center", behavior: "smooth" });
  showToast("Actor prompt prepared", "Graph governance context was added to chat.", "success");
}

async function prepareGraphQuestionPath() {
  const input = $("#graphQuestionPathQuery");
  const query = (input?.value || state.graphQuestionPathQuery || state.graphSearch || "").trim();
  const status = $("#graphStatus");
  if (!query) {
    showToast("Question required", "Enter a question before building a graph reasoning path.", "error");
    if (status) status.textContent = "Graph question path needs a question.";
    return;
  }
  state.graphQuestionPathQuery = query;
  if (status) status.textContent = `Building graph reasoning path for "${query}"...`;
  try {
    const packet = await getJson(
      `/api/okf/graph/rank-context?query=${encodeURIComponent(query)}&twin=${encodeURIComponent(state.activeTwin)}&include_drafts=${state.graphIncludeDrafts}&limit=8`,
    );
    state.graphQuestionPathPacket = {
      ...packet,
      projection: {
        twin: state.activeTwin,
        preset: "question-path",
        layout: state.graphLayoutMode,
        density: state.graphDensityMode,
        include_drafts: state.graphIncludeDrafts,
        prepared_at: new Date().toISOString(),
      },
    };
    state.graphReplayContext = {
      kind: "question-path",
      query,
      packet: state.graphQuestionPathPacket,
    };
    const firstNode = (packet.nodes || [])[0];
    state.selectedGraphNodeKey = firstNode?.node_key || "";
    state.selectedGraphEdgeKey = (packet.edges || [])[0]?.edge_key || "";
    state.graphReasoningPreset = "custom";
    state.graphSearch = query;
    renderGraphCockpit();
    if (state.selectedGraphNodeKey) await openGraphNode(state.selectedGraphNodeKey);
    if (status) status.textContent = `Question path ready: ${(packet.nodes || []).length} nodes, ${(packet.edges || []).length} relations.`;
    showToast("Question path ready", `${(packet.nodes || []).length} ranked nodes`, "success");
  } catch (error) {
    if (status) status.textContent = `Question path failed: ${compactError(error.message)}`;
    showToast("Question path failed", compactError(error.message), "error");
  }
}

function renderGraphQuestionPathPacket(packet) {
  const nodes = packet.nodes || [];
  const edges = packet.edges || [];
  const answerPath = packet.answer_path || [];
  const copyValue = escapeHtml(JSON.stringify(packet, null, 2));
  const nodeMarkup = nodes.slice(0, 5).map((node, index) => `
    <li>
      <strong>${index + 1}. ${escapeHtml(node.title || node.node_key)}</strong>
      <span>${escapeHtml(labelizeGraph(node.node_type || node.metadata?.type || "node"))} · ${escapeHtml(node.review_state || "unknown")} · ${escapeHtml(node.path || node.okf_path || "source pending")}</span>
    </li>
  `).join("");
  const pathMarkup = answerPath.slice(0, 4).map((path) => {
    const evidence = Array.isArray(path.evidence) ? path.evidence.length : 0;
    const related = Array.isArray(path.related) ? path.related.length : 0;
    return `<span>${escapeHtml(path.title || path.node_key || "node")} · ${evidence} evidence · ${related} related</span>`;
  }).join("");
  return `
    <div class="graph-context-packet graph-question-packet">
      <div class="graph-question-packet-head">
        <span class="badge">Question path</span>
        <strong>${escapeHtml(packet.query || state.graphQuestionPathQuery || "Graph question")}</strong>
      </div>
      <div class="graph-context-kpis">
        <strong>${nodes.length}<span>ranked nodes</span></strong>
        <strong>${edges.length}<span>relations</span></strong>
        <strong>${answerPath.length}<span>answer steps</span></strong>
      </div>
      <div class="graph-context-relations">${pathMarkup || "<span>No answer path returned</span>"}</div>
      <ul>${nodeMarkup || "<li>No nodes ranked for this question.</li>"}</ul>
      <div class="graph-context-actions">
        <button class="secondary small" type="button" data-graph-question-path-action="copy" data-copy-value="${copyValue}">Copy JSON</button>
        <button class="secondary small" type="button" data-graph-question-path-action="download-json">Download JSON</button>
        <button class="secondary small" type="button" data-graph-question-path-action="apply-chat">Apply to chat</button>
        <button class="secondary small" type="button" data-graph-question-path-action="apply-runner">Apply to skill runner</button>
        <button class="secondary small" type="button" data-graph-question-path-action="clear">Clear path</button>
      </div>
    </div>
  `;
}

function formatGraphQuestionPathPacket(packet = state.graphQuestionPathPacket) {
  if (!packet) return "";
  const lines = [
    "## OKF graph reasoning path",
    `Question: ${packet.query || state.graphQuestionPathQuery || "-"}`,
    `Twin: ${packet.projection?.twin || state.activeTwin}`,
    `Usage: ${packet.usage || "graph_augmented_retrieval"}`,
    "",
    "### Ranked context",
  ];
  (packet.nodes || []).slice(0, 8).forEach((node, index) => {
    lines.push(`${index + 1}. ${node.title || node.node_key}`);
    lines.push(`   - Type: ${node.node_type || node.metadata?.type || "node"}; Review: ${node.review_state || "unknown"}; Path: ${node.path || node.okf_path || "-"}`);
    if (node.summary || node.description) lines.push(`   - Summary: ${node.summary || node.description}`);
  });
  lines.push("", "### Answer path");
  (packet.answer_path || []).slice(0, 6).forEach((step, index) => {
    lines.push(`${index + 1}. ${step.title || step.node_key}`);
    lines.push(`   - Review: ${step.review_state || "unknown"}; Source: ${step.okf_path || "-"}`);
    if ((step.evidence || []).length) {
      lines.push(`   - Evidence: ${(step.evidence || []).map((item) => item.title || item.path || "evidence").join("; ")}`);
    }
    if ((step.related || []).length) {
      lines.push(`   - Related: ${(step.related || []).map((item) => `${item.title || "node"} (${labelizeGraph(item.relation || "related")})`).join("; ")}`);
    }
  });
  lines.push("", "### Actor-use rule");
  lines.push("- Use approved/source-backed nodes first.");
  lines.push("- Treat inferred and candidate relations as explanatory, not as autonomous decision authority.");
  lines.push("- Cite source paths and escalate unresolved contradictions before external commitments.");
  return lines.join("\n");
}

async function copyGraphQuestionPathPacket(button) {
  const value = button?.dataset?.copyValue || JSON.stringify(state.graphQuestionPathPacket || {}, null, 2);
  await navigator.clipboard.writeText(value);
  showToast("Question path copied", "Graph reasoning packet copied to clipboard.", "success");
}

function downloadGraphQuestionPathPacket() {
  if (!state.graphQuestionPathPacket) return;
  const blob = new Blob([JSON.stringify(state.graphQuestionPathPacket, null, 2)], { type: "application/json;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  triggerDownload(url, `okf-graph-question-path-${Date.now()}.json`);
  URL.revokeObjectURL(url);
  showToast("Question path downloaded", "JSON packet saved locally.", "success");
}

function applyGraphQuestionPathPacket(surface) {
  const formatted = formatGraphQuestionPathPacket();
  if (!formatted) return;
  const selector = surface === "runner" ? "#skillRunKnowledge" : "#chatSkillKnowledge";
  const target = $(selector);
  if (!target) {
    showToast("Target unavailable", "Open chat or skill runner before applying this packet.", "error");
    return;
  }
  target.value = [target.value.trim(), formatted].filter(Boolean).join("\n\n");
  if (surface === "runner") showView("skills");
  else showView("chat");
  showToast("Question path applied", surface === "runner" ? "Added to skill runner context." : "Added to chat context.", "success");
}

async function prepareGraphInsightPacket() {
  const status = $("#graphStatus");
  if (status) status.textContent = "Preparing graph insight packet...";
  try {
    const result = await postJson(
      `/api/okf/graph/insight-packet?twin=${encodeURIComponent(state.activeTwin)}&include_drafts=${state.graphIncludeDrafts}`,
      { export_context: graphExportContext() },
    );
    state.graphInsightPacket = result;
    renderGraphTools(state.okfGraph || {});
    const artifactPath = result.path || "derived/knowledge-graph/insight-packets";
    if (status) status.textContent = `Graph insight packet ready: ${artifactPath}`;
    showToast("Graph insight packet ready", artifactPath, "success");
  } catch (error) {
    if (status) status.textContent = `Graph insight packet failed: ${compactError(error.message)}`;
    showToast("Graph insight packet failed", compactError(error.message), "error");
  }
}

function renderGraphInsightPacket(packet) {
  const artifact = packet.artifact || {};
  const summary = packet.summary || artifact.summary || {};
  const narrative = artifact.narrative || [];
  const actions = artifact.recommended_actions || [];
  const candidates = artifact.governance_candidates || [];
  const copyValue = escapeHtml(JSON.stringify(artifact || packet, null, 2));
  return `
    <div class="graph-context-packet graph-insight-packet">
      <div class="graph-context-kpis graph-insight-kpis">
        <strong>${summary.nodes || 0}<span>nodes</span></strong>
        <strong>${summary.relations || 0}<span>relations</span></strong>
        <strong>${summary.candidate_relations || 0}<span>candidate gates</span></strong>
        <strong>${summary.approved_concepts || 0}<span>approved concepts</span></strong>
      </div>
      <div class="graph-insight-path">
        <span>${escapeHtml(packet.path || "not written")}</span>
        <small>${escapeHtml(artifact.artifact_hash || packet.artifact_hash || "")}</small>
      </div>
      <div class="graph-context-relations">
        <span>Explicit · ${summary.explicit_relations || 0}</span>
        <span>Inferred · ${summary.inferred_relations || 0}</span>
        <span>Draft-aware · ${artifact.include_drafts ? "yes" : "no"}</span>
      </div>
      <ul>
        ${narrative.slice(0, 3).map((item) => `<li><strong>${escapeHtml(item)}</strong></li>`).join("") || "<li>No narrative generated.</li>"}
      </ul>
      <div class="graph-insight-boundary">
        <strong>Boundary</strong>
        <span>${escapeHtml(packet.boundary || artifact.boundary || "Review artifact only.")}</span>
      </div>
      <div class="graph-insight-preview">
        <span>${actions.length} recommendations carried forward</span>
        <span>${candidates.length} governance candidates included</span>
      </div>
      <div class="graph-context-actions">
        <button class="secondary small" type="button" data-graph-insight-packet-action="copy" data-copy-value="${copyValue}">Copy JSON</button>
        <button class="secondary small" type="button" data-graph-insight-packet-action="download-json">Download JSON</button>
        <button class="secondary small" type="button" data-graph-insight-packet-action="apply-chat">Apply to chat</button>
        <button class="secondary small" type="button" data-graph-insight-packet-action="apply-runner">Apply to skill runner</button>
      </div>
    </div>
  `;
}

async function prepareGraphSkillContextPacket() {
  const status = $("#graphStatus");
  const query = graphSkillContextQuery();
  if (status) status.textContent = `Preparing skill graph context for "${query}"...`;
  try {
    const packet = await getJson(
      `/api/okf/graph/skill-context?query=${encodeURIComponent(query)}&twin=${encodeURIComponent(state.activeTwin)}&include_drafts=${state.graphIncludeDrafts}&limit=8`,
    );
    state.graphSkillContextPacket = {
      ...packet,
      projection: {
        twin: state.activeTwin,
        preset: state.graphReasoningPreset,
        layout: state.graphLayoutMode,
        density: state.graphDensityMode,
        include_drafts: state.graphIncludeDrafts,
        node_filter: state.graphNodeTypeFilter,
        edge_filter: state.graphEdgeTypeFilter,
        review_filter: state.graphReviewFilter,
        search: state.graphSearch,
        prepared_at: new Date().toISOString(),
      },
    };
    renderGraphTools(state.okfGraph || {});
    if (status) status.textContent = `Skill graph context ready: ${(packet.nodes || []).length} nodes, ${(packet.edges || []).length} relations.`;
    showToast("Skill graph context ready", `${(packet.nodes || []).length} nodes · ${(packet.edges || []).length} relations`, "success");
  } catch (error) {
    if (status) status.textContent = `Skill graph context failed: ${compactError(error.message)}`;
    showToast("Skill graph context failed", compactError(error.message), "error");
  }
}

function graphSkillContextQuery() {
  if (state.graphSearch.trim()) return state.graphSearch.trim();
  const presetQueries = {
    explain: "actor steering decision principles work patterns skills",
    decide: "decision principles contradictions risks governance",
    meeting: "meeting notes decisions outcomes stakeholder alignment",
    skill: "skills tasks work patterns actor steering",
    custom: "skills tasks decision principles actor steering",
  };
  return presetQueries[state.graphReasoningPreset] || presetQueries.custom;
}

function renderGraphSkillContextPacket(packet) {
  const nodes = packet.nodes || [];
  const edges = packet.edges || [];
  const projection = packet.projection || {};
  const nodePreview = nodes
    .slice(0, 5)
    .map((node) => `
      <li>
        <strong>${escapeHtml(node.title || node.node_key)}</strong>
        <span>${escapeHtml(labelizeGraph(node.metadata?.type || node.node_type || "node"))} · ${escapeHtml(node.review_state || "unknown")} · ${escapeHtml(node.path || node.okf_path || "no path")}</span>
      </li>
    `)
    .join("");
  const relationCounts = countBy(edges, (edge) => edge.relation_type || edge.edge_type || "related");
  const relationPreview = Object.entries(relationCounts)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, 4)
    .map(([relation, count]) => `<span>${escapeHtml(labelizeGraph(relation))} · ${count}</span>`)
    .join("");
  return `
    <div class="graph-context-packet">
      <div class="graph-context-kpis">
        <strong>${nodes.length}<span>nodes</span></strong>
        <strong>${edges.length}<span>relations</span></strong>
        <strong>${escapeHtml(labelizeGraph(projection.preset || "graph"))}<span>preset</span></strong>
      </div>
      <div class="graph-context-relations">${relationPreview || "<span>No relations selected</span>"}</div>
      <ul>${nodePreview || "<li>No graph nodes selected for this packet.</li>"}</ul>
      <div class="graph-context-actions">
        <button class="secondary small" type="button" data-graph-skill-context-action="copy">Copy packet</button>
        <button class="secondary small" type="button" data-graph-skill-context-action="download-json">Download JSON</button>
        <button class="secondary small" type="button" data-graph-skill-context-action="apply-chat">Apply to chat</button>
        <button class="secondary small" type="button" data-graph-skill-context-action="apply-runner">Apply to skill runner</button>
      </div>
    </div>
  `;
}

function formatGraphSkillContextPacket(packet = state.graphSkillContextPacket) {
  if (!packet) return "";
  const projection = packet.projection || {};
  const lines = [
    "## AI-ready OKF graph context",
    `Usage: ${packet.usage || "skill_context_graph"}`,
    `Query: ${packet.query || graphSkillContextQuery()}`,
    `Twin: ${projection.twin || state.activeTwin}`,
    `Projection: ${projection.preset || state.graphReasoningPreset} / ${projection.layout || state.graphLayoutMode}`,
    "",
    "### Nodes",
  ];
  (packet.nodes || []).slice(0, 8).forEach((node, index) => {
    lines.push(`${index + 1}. ${node.title || node.node_key}`);
    lines.push(`   - Type: ${node.metadata?.type || node.node_type || "node"}; Review: ${node.review_state || "unknown"}; Path: ${node.path || node.okf_path || "-"}`);
    if (node.summary || node.description) lines.push(`   - Summary: ${node.summary || node.description}`);
  });
  lines.push("", "### Relations");
  (packet.edges || []).slice(0, 12).forEach((edge, index) => {
    lines.push(`${index + 1}. ${edge.source} -> ${edge.target}`);
    lines.push(`   - Relation: ${edge.relation_type || edge.edge_type || "related"}; Confidence: ${edge.confidence ?? "-"}; Review: ${edge.review_state || "unreviewed"}`);
  });
  lines.push("", "### Runtime guidance");
  lines.push("- Use approved concepts first.");
  lines.push("- Treat candidate or unreviewed edges as advisory until reviewed.");
  lines.push("- Escalate to the human before external commitments or irreversible actions.");
  return lines.join("\n");
}

function formatGraphInsightPacket(packet = state.graphInsightPacket) {
  if (!packet) return "";
  return JSON.stringify(packet.artifact || packet, null, 2);
}

async function copyGraphInsightPacket(button) {
  const text = formatGraphInsightPacket();
  const copied = text ? await copyTextToClipboard(text) : false;
  markButtonDone(button, copied ? "Copied" : "No packet");
  showToast(
    copied ? "Graph insight copied" : "No graph insight packet",
    copied ? "Paste it into a reviewer, keynote workflow, or production handoff." : "Prepare an insight packet first.",
    copied ? "success" : "error",
  );
}

function downloadGraphInsightPacket(button) {
  const packet = state.graphInsightPacket;
  if (!packet) {
    markButtonDone(button, "No packet");
    showToast("No graph insight packet", "Prepare an insight packet first.", "error");
    return;
  }
  const payload = packet.artifact || packet;
  const filename = `meids-okf-graph-insight-${(payload.artifact_hash || packet.artifact_hash || "packet").slice(0, 8)}.json`;
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  triggerDownload(url, filename);
  URL.revokeObjectURL(url);
  markButtonDone(button, "Downloaded");
  showToast("Graph insight JSON exported", filename, "success");
}

function graphInsightPacketMarkdown(packet = state.graphInsightPacket) {
  if (!packet) return "";
  const artifact = packet.artifact || packet;
  const summary = packet.summary || artifact.summary || {};
  const view = artifact.view || {};
  const selected = artifact.selected || {};
  const topNodes = Array.isArray(artifact.top_connected_nodes) ? artifact.top_connected_nodes : [];
  const candidates = Array.isArray(artifact.governance_candidates) ? artifact.governance_candidates : [];
  const narrative = Array.isArray(artifact.narrative) ? artifact.narrative : [];
  const lines = [
    "## OKF graph insight packet",
    `Artifact: ${packet.path || artifact.path || "local graph insight"}`,
    `Twin: ${artifact.twin || state.activeTwin}`,
    `View: ${view.reasoning_preset || state.graphReasoningPreset} / ${view.layout_mode || state.graphLayoutMode}`,
    `Boundary: ${packet.boundary || artifact.boundary || "Review artifact only; no approval or graph mutation."}`,
    "",
    "### Summary",
    `- Nodes: ${summary.nodes || 0}`,
    `- Relations: ${summary.relations || 0}`,
    `- Approved concepts: ${summary.approved_concepts || 0}`,
    `- Candidate relations: ${summary.candidate_relations || 0}`,
    `- Selected node: ${selected.node_key || "-"}`,
    `- Selected relation: ${selected.edge_key || "-"}`,
    "",
    "### Usage guidance",
  ];
  (narrative.length ? narrative : [
    "Use approved concepts first.",
    "Use inferred and candidate relations only with attribution.",
    "Escalate before relying on unresolved governance candidates.",
  ]).slice(0, 5).forEach((item) => lines.push(`- ${item}`));
  lines.push("", "### Top connected graph nodes");
  topNodes.slice(0, 8).forEach((node, index) => {
    lines.push(`${index + 1}. ${node.title || node.node_key || "node"} (${node.node_type || "node"}, ${node.review_state || "unknown"}, ${node.degree || 0} links)`);
    if (node.path) lines.push(`   - Path: ${node.path}`);
  });
  if (!topNodes.length) lines.push("- No connected nodes included.");
  lines.push("", "### Governance candidates");
  candidates.slice(0, 8).forEach((edge, index) => {
    lines.push(`${index + 1}. ${edge.source || edge.edge_key || "source"} -> ${edge.target || "target"}`);
    lines.push(`   - Relation: ${edge.relation_type || "candidate"}; confidence: ${edge.confidence || "-"}; review: ${edge.review_state || "unreviewed"}`);
  });
  if (!candidates.length) lines.push("- No governance candidates included.");
  return lines.join("\n");
}

function applyGraphInsightPacket(surface) {
  const text = graphInsightPacketMarkdown();
  if (!text) {
    showToast("No graph insight packet", "Prepare an insight packet first.", "error");
    return;
  }
  const selector = surface === "runner" ? "#skillRunKnowledge" : "#chatSkillKnowledge";
  const field = $(selector);
  if (!field) return;
  const existing = field.value.trim();
  field.value = existing ? `${existing}\n\n${text}` : text;
  field.dispatchEvent(new Event("input", { bubbles: true }));
  showToast(
    surface === "runner" ? "Graph insight applied to skill runner" : "Graph insight applied to chat",
    "The packet was added as bounded OKF context.",
    "success",
  );
  if (surface === "runner") {
    showView("skills");
  } else {
    showView("chat");
    $("#chatSkillContext")?.setAttribute("open", "");
  }
}

