function graphGroupBy(items, getKey) {
  return items.reduce((acc, item) => {
    const key = getKey(item);
    acc[key] = acc[key] || [];
    acc[key].push(item);
    return acc;
  }, {});
}

function labelizeGraph(value) {
  return String(value || "")
    .replace(/[-_]+/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function humanizeId(value) {
  return labelizeGraph(value);
}

function safeGraphClass(value) {
  return String(value || "unknown").toLowerCase().replace(/[^a-z0-9-]+/g, "-");
}

function renderEmptyState(message, actionLabel = "", action = "") {
  return `
    <article class="empty-state state-card empty-state-card">
      <p>${escapeHtml(message)}</p>
      ${actionLabel && action ? `<button class="secondary small" type="button" data-cockpit-action="${escapeHtml(action)}">${escapeHtml(actionLabel)}</button>` : ""}
    </article>
  `;
}

function renderStateCard(type, title, detail = "", actionLabel = "", action = "") {
  return `
    <article class="state-card ${escapeHtml(type)}">
      <span>${escapeHtml(type)}</span>
      <strong>${escapeHtml(title)}</strong>
      ${detail ? `<p>${escapeHtml(detail)}</p>` : ""}
      ${actionLabel && action ? `<button class="secondary small" type="button" data-cockpit-action="${escapeHtml(action)}">${escapeHtml(actionLabel)}</button>` : ""}
    </article>
  `;
}

function renderLoadingState(label = "Loading data...") {
  return renderStateCard("loading", label, "Refreshing the local workspace state.");
}

function renderErrorState(title, detail = "Restart the local MVP server, then refresh this view.") {
  return renderStateCard("error", title, detail);
}

function renderStatusText(type, title, detail = "") {
  return [type.toUpperCase(), title, detail].filter(Boolean).join("\n");
}

function setOutputStatus(selector, type, title, detail = "") {
  const node = $(selector);
  if (!node) return;
  node.classList.remove("output-success", "output-error", "output-loading");
  node.classList.add(`output-${type}`);
  node.textContent = renderStatusText(type, title, detail);
}

function setChatSkillStatus(message, type = "info") {
  const node = $("#chatSkillStatus");
  if (!node) return;
  node.className = `muted-inline status-inline ${type}`;
  node.textContent = message;
}

function showToast(title, detail = "", type = "info", timeoutMs = 4200) {
  const center = $("#toastCenter");
  if (!center) return;
  const id = `toast-${++state.toastSeq}`;
  const node = document.createElement("article");
  node.id = id;
  node.className = `toast ${type}`;
  node.innerHTML = `
    <div>
      <strong>${escapeHtml(title)}</strong>
      ${detail ? `<p>${escapeHtml(detail)}</p>` : ""}
    </div>
    <button type="button" aria-label="Dismiss notification">Close</button>
  `;
  const dismiss = () => {
    node.classList.add("leaving");
    window.setTimeout(() => node.remove(), 180);
  };
  node.querySelector("button").addEventListener("click", dismiss);
  center.appendChild(node);
  if (timeoutMs) window.setTimeout(dismiss, timeoutMs);
}

function requestDecision({
  eyebrow = "Review action",
  title = "Confirm action",
  body = "",
  confirmLabel = "Confirm",
  cancelLabel = "Cancel",
  danger = false,
  input = false,
  inputLabel = "Input",
  inputValue = "",
  inputPlaceholder = "",
} = {}) {
  const dialog = $("#decisionDialog");
  if (!dialog?.showModal) {
    return Promise.resolve(input ? null : false);
  }
  $("#decisionEyebrow").textContent = eyebrow;
  $("#decisionTitle").textContent = title;
  $("#decisionBody").textContent = body;
  $("#decisionConfirmBtn").textContent = confirmLabel;
  $("#decisionCancelBtn").textContent = cancelLabel;
  $("#decisionConfirmBtn").className = danger ? "danger" : "";
  const inputWrap = $("#decisionInputWrap");
  const inputNode = $("#decisionInput");
  inputWrap.hidden = !input;
  $("#decisionInputLabel").textContent = inputLabel;
  inputNode.value = inputValue;
  inputNode.placeholder = inputPlaceholder;
  return new Promise((resolve) => {
    const onClose = () => {
      dialog.removeEventListener("close", onClose);
      if (dialog.returnValue !== "confirm") {
        resolve(input ? null : false);
        return;
      }
      resolve(input ? inputNode.value.trim() : true);
    };
    dialog.addEventListener("close", onClose, { once: true });
    dialog.showModal();
    if (input) inputNode.focus();
  });
}

function bindChat() {
  document.addEventListener("click", (event) => {
    const action = event.target.closest("[data-chat-action]");
    const suggestion = event.target.closest("[data-chat-suggestion]");
    if (suggestion) {
      const suggestedPrompt = suggestion.dataset.chatSuggestion || "";
      setLegacyManualRequestValue(suggestedPrompt);
      renderSkillPreflight();
      if (runtimeConfig.n8nChatEnabled) {
        $("#n8nChatMount")?.scrollIntoView({ block: "center", behavior: "smooth" });
        showToast("Prompt prepared", "Paste or type it into the embedded n8n Actor Twin chat.", "success");
        return;
      }
      return;
    }
    if (!action) return;
    if (action.dataset.chatAction === "focus-query") {
      const n8nMount = $("#n8nChatMount");
      n8nMount?.scrollIntoView({ block: "center", behavior: "smooth" });
      n8nMount?.querySelector("textarea, input, [contenteditable='true']")?.focus();
      if (!runtimeConfig.n8nChatEnabled) {
        showToast("n8n chat disabled", "Enable the embedded n8n Actor Twin chat in runtime config.", "error");
      }
      return;
    }
    if (action.dataset.chatAction === "open-skill-context") {
      $("#chatSkillContext").open = true;
      $("#chatSkillEmail").focus();
      return;
    }
    if (action.dataset.chatAction === "open-interaction-setup") {
      $("#chatInteractionSetup").open = true;
      $("#appliedSkillsMenu").open = true;
      $("#appliedSkillsSummary")?.scrollIntoView({ block: "center", behavior: "smooth" });
      return;
    }
    if (action.dataset.chatAction === "continue-run") {
      openSkillRunInChat(action.dataset.runId || "");
      return;
    }
    if (action.dataset.chatAction === "open-run-detail") {
      openSkillRunDrawerFromChat(action.dataset.runId || "");
      return;
    }
    if (action.dataset.chatAction === "open-run-graph") {
      replaySkillRunGraphContext(action.dataset.runId || "");
      return;
    }
    if (action.dataset.chatAction === "focus-run-review") {
      action.closest(".skill-run-card")?.querySelector(".skill-run-review")?.scrollIntoView({ behavior: "smooth", block: "center" });
      return;
    }
    if (action.dataset.chatAction === "propose-run-refinement") {
      proposeRunRefinementFromCard(action.dataset.runId || "", action);
      return;
    }
    if (action.dataset.chatAction === "ack-agent-approval") {
      acknowledgeAgentApproval(action);
      return;
    }
    if (action.dataset.chatAction === "copy-agent-approval") {
      copyAgentApproval(action);
      return;
    }
    if (action.dataset.chatAction === "copy-agent-resume") {
      copyAgentApprovalResumePayload(action);
      return;
    }
    if (action.dataset.chatAction === "resume-agent-approval") {
      resumeAgentApproval(action);
      return;
    }
    if (action.dataset.chatAction === "refresh-agent-runtime-state") {
      safeRefreshBackendAgentRuntimeState();
      return;
    }
    if (action.dataset.chatAction === "open-agent-trace") {
      openAgentTraceFromChat(action.dataset.traceId || action.dataset.requestId || "");
    }
  });
  $("#reloadN8nContextBtn")?.addEventListener("click", () => {
    reloadN8nChatContext();
  });
  $("#riskPostureSelect")?.addEventListener("change", (event) => {
    state.riskPosture = event.target.value || "balanced";
    renderChatSkillMode();
  });
  $("#chatInteractionModeSelect")?.addEventListener("change", (event) => {
    state.activeChatInteractionMode = event.target.value || "actor_twin";
    state.chatContractActionResult = null;
    if (state.activeChatInteractionMode === "source_context") {
      $("#chatSkillContext").open = true;
    }
    if (state.activeChatInteractionMode === "skill_activation") {
      $("#chatInteractionSetup").open = true;
      $("#appliedSkillsMenu").open = true;
      $("#chatSkillContext").open = true;
    }
    renderChatSkillMode();
  });
  $("#appliedSkillsList")?.addEventListener("change", (event) => {
    if (!event.target.matches(".applied-skill-filter")) return;
    state.appliedChatSkillIds = $$(".applied-skill-filter:checked").map((input) => input.value);
    state.activeChatSkillId = state.appliedChatSkillIds[0] || N8N_CHAT_MODE;
    state.activeChatInteractionMode = state.appliedChatSkillIds.length ? "skill_activation" : "actor_twin";
    state.chatContractActionResult = null;
    renderChatSkillMode();
    safeRefreshSkillInputPresets();
  });
  $("#webSearchFilter")?.addEventListener("change", (event) => {
    state.webSearchEnabled = Boolean(event.target.checked);
    renderChatSkillMode();
  });
  $("#voiceAnswerFilter")?.addEventListener("change", (event) => {
    state.voiceAnswerEnabled = Boolean(event.target.checked);
    renderChatSkillMode();
  });
  $("#retrievalModeSelect")?.addEventListener("change", () => {
    renderChatSkillMode();
  });
  $$(".type-filter").forEach((input) => {
    input.addEventListener("change", renderChatSkillMode);
  });
  ["#chatSkillEmail", "#chatSkillCalendar", "#chatSkillTeams", "#chatSkillKnowledge", "#queryInput"].forEach((selector) => {
    $(selector)?.addEventListener("input", renderSkillPreflight);
  });
  $("#saveChatPresetBtn")?.addEventListener("click", saveChatInputPreset);
  $("#updateChatPresetBtn")?.addEventListener("click", updateChatInputPreset);
  $("#loadChatPresetBtn")?.addEventListener("click", loadChatInputPreset);
  $("#deleteChatPresetBtn")?.addEventListener("click", deleteChatInputPreset);
  $("#chatForm")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    $("#n8nChatMount")?.scrollIntoView({ block: "center", behavior: "smooth" });
    showToast("Use n8n chat", "The local Actor Twin composer is disabled. Ask through the embedded n8n chat.", "success");
  });
}

function selectedConceptTypes() {
  const checked = $$(".type-filter:checked").map((input) => input.value);
  const types = checked.filter((value) => value !== "core");
  if (checked.includes("core")) {
    types.push(
      "Decision Principle",
      "Client Relationship",
      "Domain Term",
      "Playbook",
      "Meeting Note",
      "Voice Sample",
      "Objection Response",
      "Legacy Story",
      "Diagnostic Frame",
    );
  }
  return types;
}

function bindTwinSwitch() {
  $("#twinSelect").addEventListener("change", async (event) => {
    const twin = event.target.value;
    try {
      if (staticPagesMode) {
        state.selectedTwinId = twin;
        await activateSelectedTwin();
        return;
      }
      markTwinSwitch(state.activeTwin);
      await postJson("/api/twins/active", { twin_id: twin, actor: "local-user" });
      state.activeTwin = twin;
      state.selectedTwinId = twin;
      await refreshAll();
    } catch (error) {
      setOutputStatus("#twinResult", "error", "Could not activate twin", error.message);
      renderTwinOptions();
    }
  });
}

