function renderVoiceLoopUatResult(result, title) {
  const rows = (result.results || []).map((item) => `
    <li>
      <strong>${escapeHtml(item.category || "category")}</strong>
      <span>${escapeHtml(item.final_ready ? "ready" : "not ready")} · consistency ${Math.round((item.consistency_score || 0) * 100)}% · eligibility ${Math.round((item.eligibility_score || 0) * 100)}%</span>
      <small>${escapeHtml(item.initial_question || "")}</small>
      ${item.error ? `<small class="warning-copy">${escapeHtml(compactError(item.error))}</small>` : ""}
    </li>
  `).join("");
  const emptyMessage = result.message ? `<p>${escapeHtml(result.message)}</p>` : "";
  const reportPath = result.report_path
    ? `<code>${escapeHtml(result.report_path)}</code>`
    : "";
  return `
    <div class="voice-uat-result ${result.ok ? "ready" : "warning"}">
      <strong>${escapeHtml(title)} ${escapeHtml(result.status || "checked")}</strong>
      <p>Each category starts incomplete, receives a clarification, and must become eligible before saving.</p>
      ${emptyMessage}
      ${rows ? `<ol>${rows}</ol>` : ""}
      ${reportPath ? `<p>Report saved: ${reportPath}</p>` : ""}
    </div>
  `;
}

