async function startRecording() {
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    state.audioChunks = [];
    state.mediaRecorder = new MediaRecorder(stream);
    state.mediaRecorder.addEventListener("dataavailable", (event) => {
      if (event.data.size > 0) state.audioChunks.push(event.data);
    });
    state.mediaRecorder.addEventListener("stop", () => {
      state.recordedBlob = new Blob(state.audioChunks, { type: "audio/webm" });
      $("#audioPreview").src = URL.createObjectURL(state.recordedBlob);
      $("#uploadAudioBtn").disabled = false;
      stream.getTracks().forEach((track) => track.stop());
    });
    state.mediaRecorder.start();
    $("#recordBtn").disabled = true;
    $("#stopBtn").disabled = false;
    $("#transcriptBox").textContent = "Recording...";
    $("#voiceEvidence").innerHTML = "";
    $("#voiceConceptAssessment").innerHTML = "";
    $("#voicePromotionReviewNote").value = "";
    setVoiceConversationStatus("recording", "Listening. Stop the recording when the thought is complete.");
    $("#voiceDraftBtn").disabled = true;
    $("#voiceAgentHandoffBtn").disabled = true;
    $("#voiceCommitBtn").disabled = true;
    updateVoiceClarificationPrompt();
  } catch (error) {
    $("#transcriptBox").textContent = `Microphone unavailable: ${error.message}`;
    setVoiceConversationStatus("error", "Microphone unavailable. Check browser permission and recording device.");
  }
}

function stopRecording() {
  if (!state.mediaRecorder) return;
  state.mediaRecorder.stop();
  $("#recordBtn").disabled = false;
  $("#stopBtn").disabled = true;
  $("#transcriptBox").textContent = "Recording ready. Send it for transcription.";
  setVoiceConversationStatus("pending", "Recording ready. Transcribe it to start the Persona Modeler interview.");
}

async function uploadAudio() {
  if (!state.recordedBlob) return;
  if (!state.openAIConfigured) {
    $("#transcriptBox").textContent = "OpenAI is not configured. Set OPENAI_API_KEY before using direct transcription.";
    return;
  }
  if (!(await confirmTwinScopedAction("transcribe and clarify this recording"))) return;
  const form = new FormData();
  form.append("file", state.recordedBlob, `voice-${Date.now()}.webm`);
  form.append("twin", state.activeTwin);
  form.append("category", $("#voiceConceptCategory").value);
  $("#transcriptBox").textContent = "Transcribing and asking Persona Modeler...";
  setVoiceConversationStatus("pending", "Transcribing and preparing the first Persona Modeler question.");
  try {
    const result = await postForm("/api/voice/concepts/transcribe", form);
    state.voiceConceptSession = {
      transcript: result.transcript || "",
      category: result.category || $("#voiceConceptCategory").value,
      evidence: result.evidence || null,
      replies: [],
      questionHistory: [],
      assessment: result.assessment || null,
      agent: result.agent || null,
    };
    $("#transcriptBox").textContent = result.transcript || JSON.stringify(result, null, 2);
    $("#voiceConceptCategory").value = state.voiceConceptSession.category;
    renderVoiceConceptAssessment();
    $("#voiceClarifyBtn").disabled = false;
    $("#voiceDraftBtn").disabled = false;
    $("#voiceAgentHandoffBtn").disabled = false;
    $("#voiceCommitBtn").disabled = !state.voiceConceptSession.assessment?.ready;
    $("#voiceEvidence").innerHTML = result.evidence
      ? `<strong>Transcript evidence stored:</strong> <code>${escapeHtml(result.evidence.path)}</code>`
      : "";
    await safeRefreshActivity();
    await safeRefreshSyncStatus();
  } catch (error) {
    $("#transcriptBox").textContent = `Audio ingest failed: ${error.message}`;
    setVoiceConversationStatus("error", "Audio ingest failed. Keep the recording and try again.");
  }
}

async function startVoiceConceptFromPastedTranscript() {
  const transcript = $("#voiceTranscriptPaste").value.trim();
  if (!transcript) {
    setVoiceConversationStatus("pending", "Paste a transcript before starting the Persona Modeler interview.");
    return;
  }
  if (!(await confirmTwinScopedAction("start a voice concept conversation from pasted transcript"))) return;
  state.voiceConceptSession = {
    transcript,
    category: $("#voiceConceptCategory").value,
    evidence: null,
    replies: [],
    questionHistory: [],
    assessment: null,
    agent: null,
  };
  $("#transcriptBox").textContent = transcript;
  $("#voiceEvidence").innerHTML = '<span class="muted-inline">Started from pasted transcript. No audio evidence file was created.</span>';
  renderVoiceTranscriptSyncStatus();
  $("#voiceConceptAssessment").innerHTML = "";
  $("#voicePromotionReviewNote").value = "";
  $("#voiceClarifyBtn").disabled = false;
  $("#voiceDraftBtn").disabled = false;
  $("#voiceAgentHandoffBtn").disabled = false;
  $("#voiceCommitBtn").disabled = true;
  updateVoiceClarificationPrompt();
  setVoiceConversationStatus("pending", "Persona Modeler is assessing the pasted transcript.");
  await assessVoiceConcept();
}

async function safeRefreshVoiceConceptUatSamples() {
  try {
    const result = await getJson("/api/voice/concepts/ui-uat-samples");
    state.voiceConceptUatSamples = result.samples || [];
  } catch (error) {
    console.warn("Voice concept UI UAT sample refresh failed", error);
  }
}

async function loadVoiceUatSample() {
  if (!state.voiceConceptUatSamples.length) await safeRefreshVoiceConceptUatSamples();
  const category = $("#voiceConceptCategory").value || "knowledge";
  const sample = (state.voiceConceptUatSamples || []).find((item) => item.category === category);
  const status = $("#voiceSampleStatus");
  if (!sample) {
    if (status) status.textContent = "No sample found for selected category";
    return;
  }
  state.voiceConceptLoadedSample = sample;
  $("#voiceTranscriptPaste").value = sample.initial_transcript || "";
  $("#voiceClarificationInput").value = sample.suggested_clarification || "";
  $("#transcriptBox").textContent = "Sample loaded. Start from transcript, then add the suggested clarification if needed.";
  $("#voiceEvidence").innerHTML = `
    <strong>Loaded UAT sample:</strong> ${escapeHtml(sample.label || sample.category)}<br>
    <span class="muted-inline">Expected first question: ${escapeHtml(sample.expected_question || "")}</span>
  `;
  if (status) status.textContent = `Loaded ${sample.label || sample.category} sample`;
  setVoiceConversationStatus("pending", "Sample loaded. Start the transcript to test the real Persona Modeler loop.");
}

async function runVoiceSampleWalkthrough() {
  if (!state.voiceConceptUatSamples.length) await safeRefreshVoiceConceptUatSamples();
  const category = $("#voiceConceptCategory").value || "knowledge";
  const sample = (state.voiceConceptUatSamples || []).find((item) => item.category === category);
  const status = $("#voiceSampleStatus");
  if (!sample) {
    if (status) status.textContent = "No sample found for selected category";
    return;
  }
  if (!(await confirmTwinScopedAction(`run a ${category} voice concept walkthrough`))) return;
  state.voiceConceptLoadedSample = sample;
  const transcript = sample.initial_transcript || "";
  const clarification = sample.suggested_clarification || "";
  $("#voiceTranscriptPaste").value = transcript;
  $("#voiceClarificationInput").value = clarification;
  $("#transcriptBox").textContent = transcript || "No sample transcript available.";
  $("#voiceConceptAssessment").innerHTML = "";
  $("#voicePromotionReviewNote").value = "";
  $("#voiceEvidence").innerHTML = `
    <strong>Running UAT walkthrough:</strong> ${escapeHtml(sample.label || sample.category)}<br>
    <span class="muted-inline">The Persona Modeler will ask, receive the sample clarification, and recheck readiness.</span>
  `;
  state.voiceConceptSession = {
    transcript,
    category,
    evidence: null,
    replies: [],
    questionHistory: [],
    assessment: null,
    agent: null,
  };
  $("#voiceClarifyBtn").disabled = false;
  $("#voiceDraftBtn").disabled = false;
  $("#voiceAgentHandoffBtn").disabled = false;
  $("#voiceCommitBtn").disabled = true;
  if (status) status.textContent = `Running ${sample.label || sample.category} walkthrough`;
  setVoiceConversationStatus("pending", "Sample walkthrough started. Persona Modeler is asking the first question.");
  await assessVoiceConcept();

  const firstQuestion = state.voiceConceptSession.assessment?.next_question || sample.expected_question || "";
  if (firstQuestion) state.voiceConceptSession.questionHistory.push(firstQuestion);
  if (clarification) state.voiceConceptSession.replies.push(clarification);
  $("#voiceClarificationInput").value = "";
  setVoiceConversationStatus("pending", "Sample clarification applied. Rechecking readiness.");
  await assessVoiceConcept();

  $("#voiceEvidence").innerHTML = `
    <strong>Sample walkthrough complete:</strong> ${escapeHtml(sample.label || sample.category)}<br>
    <span class="muted-inline">Review the ready concept, then save it manually if this UAT result is acceptable.</span>
  `;
  if (status) status.textContent = "Walkthrough complete; save remains manual";
}

async function safeRefreshVoiceCriteria() {
  try {
    state.voiceConceptCriteria = await getJson("/api/voice/concepts/criteria");
    renderVoiceCriteria();
  } catch (error) {
    console.warn("Voice concept criteria refresh failed", error);
  }
}

async function safeRefreshVoiceConceptPreflight() {
  const target = $("#voicePreflight");
  if (!target) return;
  try {
    state.voiceConceptPreflight = await getJson(`/api/voice/concepts/preflight?twin=${encodeURIComponent(state.activeTwin)}`);
    renderVoiceConceptPreflight();
  } catch (error) {
    console.warn("Voice concept preflight refresh failed", error);
    target.innerHTML = `<span class="warning-copy">Preflight unavailable: ${escapeHtml(compactError(error.message))}</span>`;
  }
}

function renderVoiceConceptPreflight() {
  const target = $("#voicePreflight");
  const preflight = state.voiceConceptPreflight;
  if (!target || !preflight) return;
  const summary = preflight.summary || {};
  const headline = summary.n8n_ready
    ? "Ready for n8n UAT"
    : summary.local_uat_ready
      ? "Ready for local UAT"
      : "Setup needed";
  const checks = preflight.checks || [];
  target.innerHTML = `
    <div class="voice-preflight-head">
      <strong>${escapeHtml(headline)}</strong>
      <span>${escapeHtml(preflight.criteria?.approval_state || "unknown")} criteria · ${escapeHtml(preflight.agent?.mode || "local")}</span>
    </div>
    ${summary.n8n_ready ? "" : `<p class="voice-preflight-note">${escapeHtml(voiceN8nReadinessNote(preflight))}</p>`}
    <div class="voice-preflight-grid">
      ${checks.map((check) => `
        <div class="voice-preflight-item ${escapeHtml(check.state || "warning")}">
          <span>${escapeHtml(check.label || check.key || "Check")}</span>
          <strong>${escapeHtml(check.state || "unknown")}</strong>
          <p>${escapeHtml(check.message || "")}</p>
        </div>
      `).join("")}
    </div>
    ${renderVoicePreflightActions(checks)}
  `;
}

function voiceN8nReadinessNote(preflight) {
  const criteriaState = preflight.criteria?.approval_state || "unknown";
  const n8nConfigured = Boolean(preflight.agent?.n8n_configured);
  if (criteriaState !== "approved" && !n8nConfigured) {
    return "Approve the readiness criteria and configure the n8n webhook before treating external Persona Modeler results as production-ready.";
  }
  if (criteriaState !== "approved") {
    return "n8n can be tested, but production use waits for human-approved readiness criteria.";
  }
  if (!n8nConfigured) {
    return "Criteria are approved; configure the n8n webhook to compare the external Persona Modeler loop.";
  }
  return "Finish the open setup checks before production n8n use.";
}

function renderVoicePreflightActions(checks) {
  const openActions = (checks || []).filter((check) => check.state !== "ready" && check.action);
  if (!openActions.length) return "";
  return `
    <div class="voice-preflight-actions">
      <span>Next fixes</span>
      <ol>
        ${openActions.map((check) => `<li><strong>${escapeHtml(check.label || check.key || "Check")}:</strong> ${escapeHtml(check.action || "")}</li>`).join("")}
      </ol>
    </div>
  `;
}

async function safeRefreshVoiceConceptUatReports(force = false) {
  const target = $("#voiceUatReports");
  if (!target) return;
  if (!force && !isVoiceAdvancedOpen()) {
    target.innerHTML = "";
    return;
  }
  try {
    const [result, guides] = await Promise.all([
      getJson("/api/voice/concepts/uat-reports?limit=5"),
      getJson("/api/voice/concepts/n8n-setup-guides?limit=3"),
    ]);
    state.voiceConceptUatReports = result.reports || [];
    state.voiceConceptN8nSetupGuides = guides.guides || [];
    renderVoiceConceptUatReports();
  } catch (error) {
    console.warn("Voice concept UAT report refresh failed", error);
    state.voiceConceptUatReports = [];
    state.voiceConceptN8nSetupGuides = [];
    target.innerHTML = isVoiceAdvancedOpen()
      ? `<span class="muted-inline">Diagnostics unavailable: ${escapeHtml(compactError(error.message))}</span>`
      : "";
  }
}

async function safeRefreshVoiceConceptRealCoverage() {
  try {
    state.voiceConceptRealCoverage = await getJson(`/api/voice/concepts/real-coverage?twin=${encodeURIComponent(state.activeTwin)}`);
    renderVoiceConceptUatReports();
  } catch (error) {
    console.warn("Voice concept real coverage refresh failed", error);
    state.voiceConceptRealCoverage = null;
  }
}

async function safeRefreshVoiceConceptReadinessGates(force = false) {
  if (!force && !isVoiceAdvancedOpen()) return;
  try {
    state.voiceConceptReadinessGates = await getJson(`/api/voice/concepts/readiness-gates?twin=${encodeURIComponent(state.activeTwin)}`);
    renderVoiceConceptUatReports();
  } catch (error) {
    console.warn("Voice concept readiness gates refresh failed", error);
    state.voiceConceptReadinessGates = null;
  }
}

function renderVoiceConceptUatReports() {
  const target = $("#voiceUatReports");
  if (!target) return;
  const reports = state.voiceConceptUatReports || [];
  const setupGuides = state.voiceConceptN8nSetupGuides || [];
  if (!reports.length) {
    target.innerHTML = `${renderVoiceReadinessGates(state.voiceConceptReadinessGates)}${renderVoiceN8nSetupGuides(setupGuides)}${renderVoiceRealConceptCoverage(state.voiceConceptRealCoverage)}`;
    return;
  }
  target.innerHTML = `
    ${renderVoiceReadinessGates(state.voiceConceptReadinessGates)}
    ${renderVoiceN8nSetupGuides(setupGuides)}
    <div class="voice-uat-report-head">
      <strong>Recent UAT reports</strong>
      <span>${reports.length} shown</span>
    </div>
    ${renderVoiceUatCoverage(reports)}
    ${renderVoiceRealConceptCoverage(state.voiceConceptRealCoverage)}
    <ol>
      ${reports.map((report) => `
        <li class="${report.ok ? "ready" : "warning"}">
          <span>${escapeHtml(report.agent_mode || "voice concept")} · ${escapeHtml(report.status || "unknown")}</span>
          <code>${escapeHtml(report.path || "")}</code>
          <small>${escapeHtml(report.created_at || "")} · ${escapeHtml((report.categories_tested || []).join(", ") || report.message || "no categories")}</small>
          <button class="secondary small" type="button" data-voice-uat-report="${escapeHtml(report.path || "")}">View</button>
        </li>
      `).join("")}
    </ol>
  `;
}

function renderVoiceN8nSetupGuides(guides) {
  if (!guides?.length) return "";
  const latest = guides[0];
  return `
    <div class="voice-uat-coverage ready">
      <strong>Latest n8n setup guide</strong>
      <div>
        <span class="ready">${escapeHtml(latest.title || "n8n Persona Modeler Setup")}</span>
      </div>
      <small>${escapeHtml(latest.created_at || "")} · <code>${escapeHtml(latest.path || "")}</code></small>
    </div>
  `;
}

function renderVoiceReadinessGates(data) {
  if (!data) return "";
  const gates = data.gates || [];
  const localSteps = data.local_next_steps || [];
  const localOpen = data.local_open_gate_count ?? gates.filter((gate) => (gate.scope || "local") === "local" && gate.state !== "ready").length;
  const productionOpen = data.production_open_gate_count ?? gates.filter((gate) => gate.scope === "production" && gate.state !== "ready").length;
  return `
    <div class="voice-readiness-gates ${data.local_mvp_ready ? "ready" : "warning"}">
      <div class="voice-uat-report-head">
        <strong>Voice Concept readiness gates</strong>
        <span>${data.local_mvp_ready ? "local MVP ready" : `${escapeHtml(String(localOpen))} local open`} · ${data.production_ready ? "production ready" : `${escapeHtml(String(productionOpen))} n8n open`}</span>
      </div>
      ${renderVoiceLocalSummary(data.local_summary)}
      ${renderVoiceLocalNextSteps(localSteps, data.local_mvp_ready)}
      <div class="voice-gate-grid">
        ${gates
          .map((gate) => `
            <article class="voice-gate ${escapeHtml(gate.state || "warning")}">
              <span>${escapeHtml(gate.label || gate.key || "Gate")} · ${escapeHtml(gate.scope || "local")}</span>
              <strong>${escapeHtml(gate.state || "unknown")}</strong>
              <p>${escapeHtml(gate.message || "")}</p>
              ${gate.state === "ready" ? "" : `<small>${escapeHtml(gate.next_action || "")}</small>${renderVoiceGateAction(gate)}`}
            </article>
          `)
          .join("")}
      </div>
    </div>
  `;
}

function renderVoiceLocalSummary(summary) {
  if (!summary) return "";
  return `
    <div class="voice-local-summary ${summary.ready ? "ready" : "warning"}">
      <div>
        <span>Criteria</span>
        <strong>${summary.criteria_approved ? "approved" : "open"}</strong>
      </div>
      <div>
        <span>Local UAT</span>
        <strong>${summary.local_uat_passed ? "passed" : "open"}</strong>
      </div>
      <div>
        <span>Real concepts</span>
        <strong>${escapeHtml(String(summary.real_category_count || 0))}/${escapeHtml(String(summary.required_category_count || 0))}</strong>
      </div>
      <div class="summary-action">
        <span>Next</span>
        <strong>${escapeHtml(summary.next_action || "Local MVP gates are complete.")}</strong>
        ${summary.next_action_id ? `<button class="secondary small voice-gate-action" type="button" data-voice-gate-action="${escapeHtml(summary.next_action_id)}">${escapeHtml(localStepButtonLabel(summary.next_action_id))}</button>` : ""}
      </div>
    </div>
  `;
}

function renderVoiceLocalNextSteps(steps, complete) {
  if (complete) {
    return `
      <div class="voice-local-path ready">
        <strong>Local MVP path complete</strong>
        <span>Ready for local voice concept ingestion review; n8n remains a production extension.</span>
      </div>
    `;
  }
  if (!steps?.length) return "";
  return `
    <div class="voice-local-path">
      <strong>Next local MVP actions</strong>
      <ol>
        ${steps.map((step) => `
          <li>
            <span>${escapeHtml(step.label || step.gate_key || "Gate")}</span>
            <small>${escapeHtml(step.action || "")}</small>
            ${step.action_id ? `<button class="secondary small voice-gate-action" type="button" data-voice-gate-action="${escapeHtml(step.action_id)}">${escapeHtml(localStepButtonLabel(step.action_id))}</button>` : ""}
          </li>
        `).join("")}
      </ol>
    </div>
  `;
}

function localStepButtonLabel(actionId) {
  const labels = {
    "approve-criteria": "Approve",
    "run-local-uat": "Run check",
    "load-missing-sample": "Capture real concept",
    "show-n8n-setup": "Show setup",
    "run-n8n-uat": "Run n8n UAT",
  };
  return labels[actionId] || "Open";
}

function renderVoiceGateAction(gate) {
  const actions = {
    criteria_approval: ["approve-criteria", "Approve criteria"],
    local_uat: ["run-local-uat", "Run local UAT"],
    real_concepts: ["load-missing-sample", "Load missing sample"],
    n8n_adapter: ["show-n8n-setup", "Show setup"],
    n8n_uat: ["run-n8n-uat", "Run n8n UAT"],
  };
  const action = actions[gate.key];
  if (!action) return "";
  return `<button class="secondary small voice-gate-action" type="button" data-voice-gate-action="${escapeHtml(action[0])}">${escapeHtml(action[1])}</button>`;
}

async function handleVoiceGateActionClick(event) {
  const button = event.target.closest("[data-voice-gate-action]");
  if (!button) return;
  const action = button.dataset.voiceGateAction || "";
  if (action === "approve-criteria") {
    await approveVoiceConceptCriteria();
  } else if (action === "run-local-uat") {
    await runVoiceLocalUat();
  } else if (action === "run-n8n-uat") {
    await runVoiceN8nUat();
  } else if (action === "show-n8n-payload") {
    await showVoiceN8nSamplePayload();
  } else if (action === "show-n8n-setup") {
    await showVoiceN8nSetup();
  } else if (action === "load-missing-sample") {
    await loadFirstMissingVoiceConceptSample();
  }
}

async function loadFirstMissingVoiceConceptSample() {
  const missing = state.voiceConceptRealCoverage?.missing_categories || [];
  const category = missing[0] || $("#voiceConceptCategory").value || "knowledge";
  $("#voiceConceptCategory").value = category;
  renderVoiceCriteria();
  state.voiceConceptLoadedSample = null;
  state.voiceConceptSession = null;
  $("#voiceTranscriptPaste").value = "";
  $("#voiceClarificationInput").value = "";
  $("#voicePromotionReviewNote").value = "";
  $("#transcriptBox").textContent = `Ready for a real ${category.replace("_", " ")} voice concept. Paste a transcript or record audio, then let the Persona Modeler clarify it.`;
  $("#voiceConceptAssessment").innerHTML = "";
  $("#voiceEvidence").innerHTML = `
    <strong>Real concept capture:</strong> ${escapeHtml(category.replace("_", " "))}<br>
    <span class="muted-inline">Use a real spoken thought, not a UAT sample, so this category counts toward Local MVP readiness.</span>
  `;
  $("#voiceClarifyBtn").disabled = true;
  $("#voiceDraftBtn").disabled = true;
  $("#voiceAgentHandoffBtn").disabled = true;
  $("#voiceCommitBtn").disabled = true;
  $("#voiceSampleStatus").textContent = `Capturing real ${category.replace("_", " ")} concept`;
  updateVoiceClarificationPrompt();
  setVoiceConversationStatus("pending", "Paste or record a real concept. The Persona Modeler will ask until it is ready.");
  $("#voiceTranscriptPaste")?.focus();
  showToast("Real concept capture ready", `Paste or record a ${category.replace("_", " ")} concept, then save it after clarification.`, "info");
}

function renderVoiceUatCoverage(reports) {
  const required = ["knowledge", "personality", "skill_input"];
  const covered = new Set();
  (reports || []).forEach((report) => {
    if (!report.ok) return;
    (report.categories_tested || []).forEach((category) => covered.add(category));
  });
  const complete = required.every((category) => covered.has(category));
  return `
    <div class="voice-uat-coverage ${complete ? "ready" : "warning"}">
      <strong>${complete ? "All categories covered by passing UAT" : "Category UAT coverage incomplete"}</strong>
      <div>
        ${required
          .map((category) => `<span class="${covered.has(category) ? "ready" : "missing"}">${escapeHtml(category.replace("_", " "))}</span>`)
          .join("")}
      </div>
      <small>${complete ? "Use this as baseline before n8n production comparison." : "Run local or n8n UAT until each category has a passing report."}</small>
    </div>
  `;
}

function renderVoiceRealConceptCoverage(coverage) {
  if (!coverage) return "";
  const items = coverage.coverage || [];
  const complete = coverage.status === "complete";
  return `
    <div class="voice-uat-coverage real ${complete ? "ready" : "warning"}">
      <strong>${complete ? "Real saved concepts cover all categories" : "Real saved concept coverage incomplete"}</strong>
      <div>
        ${items
          .map((item) => `
            <span class="${item.covered ? "ready" : "missing"}" title="${escapeHtml(item.latest_path || "No saved concept yet")}">
              ${escapeHtml(item.label || item.category || "category")} · ${escapeHtml(String(item.count || 0))}
            </span>
          `)
          .join("")}
      </div>
      <small>${complete ? "The active twin has at least one saved voice concept per required category." : `Missing: ${escapeHtml((coverage.missing_categories || []).join(", ") || "none")}. Save one real concept per category before final production signoff.`}</small>
    </div>
  `;
}

async function handleVoiceUatReportClick(event) {
  const button = event.target.closest("[data-voice-uat-report]");
  if (!button) return;
  const path = button.dataset.voiceUatReport || "";
  const evidence = $("#voiceEvidence");
  if (!path || !evidence) return;
  button.disabled = true;
  try {
    const report = await postJson("/api/voice/concepts/uat-reports/detail", { path });
    evidence.innerHTML = renderVoiceUatReportDetail(report);
  } catch (error) {
    evidence.innerHTML = `<span class="warning-copy">Report detail failed: ${escapeHtml(compactError(error.message))}</span>`;
  } finally {
    button.disabled = false;
  }
}

function renderVoiceUatReportDetail(report) {
  const rows = (report.results || []).map((item) => `
    <li>
      <strong>${escapeHtml(item.category || "category")}</strong>
      <span>${escapeHtml(item.final_ready ? "ready" : "not ready")} · consistency ${Math.round((item.consistency_score || 0) * 100)}% · eligibility ${Math.round((item.eligibility_score || 0) * 100)}%</span>
      ${item.missing_dimensions?.length ? `<small>Open: ${escapeHtml(item.missing_dimensions.join(", "))}</small>` : ""}
      ${renderVoiceUatParity(item)}
    </li>
  `).join("");
  return `
    <div class="voice-uat-result ${report.ok ? "ready" : "warning"}">
      <strong>UAT report detail · ${escapeHtml(report.status || "unknown")}</strong>
      <p>${escapeHtml(report.agent_mode || "voice concept")} · ${escapeHtml(report.created_at || "")}</p>
      <p>Criteria: ${escapeHtml(report.criteria?.version || "unversioned")} · ${escapeHtml(report.criteria?.approval_state || "unknown")}</p>
      ${report.message ? `<p>${escapeHtml(report.message)}</p>` : ""}
      ${rows ? `<ol>${rows}</ol>` : ""}
      <p>Report: <code>${escapeHtml(report.path || "")}</code></p>
    </div>
  `;
}

function renderVoiceUatParity(item) {
  if (!item.parity && !item.local_baseline) return "";
  const parity = item.parity || {};
  const baseline = item.local_baseline || {};
  const readyMatch = Boolean(parity.ready_matches_local);
  const missingMatch = Boolean(parity.missing_dimensions_match_local);
  return `
    <small class="${readyMatch && missingMatch ? "ready-copy" : "warning-copy"}">
      Local parity: ready ${readyMatch ? "match" : "diff"} · missing dimensions ${missingMatch ? "match" : "diff"} · max score delta ${escapeHtml(String(parity.max_score_delta ?? "-"))}
    </small>
    <small>Local baseline: ${escapeHtml(baseline.final_ready ? "ready" : "not ready")} · consistency ${Math.round((baseline.consistency_score || 0) * 100)}% · eligibility ${Math.round((baseline.eligibility_score || 0) * 100)}%</small>
  `;
}

async function safeRefreshVoiceConceptDrafts() {
  const select = $("#voiceDraftSelect");
  if (!select) return;
  try {
    const result = await getJson(`/api/voice/concepts/drafts?twin=${encodeURIComponent(state.activeTwin)}&limit=20`);
    state.voiceConceptDrafts = result.drafts || [];
    renderVoiceConceptDraftSelect();
    renderVoiceDraftQueue();
  } catch (error) {
    console.warn("Voice concept draft refresh failed", error);
    state.voiceConceptDrafts = [];
    select.innerHTML = '<option value="">No drafts loaded</option>';
    const queue = $("#voiceDraftQueue");
    if (queue) queue.innerHTML = '<span class="muted-inline">Drafts unavailable right now. Continue with a new recording or pasted transcript.</span>';
  }
}

function renderVoiceConceptDraftSelect() {
  const select = $("#voiceDraftSelect");
  if (!select) return;
  if (!state.voiceConceptDrafts.length) {
    select.innerHTML = '<option value="">No drafts yet</option>';
    return;
  }
  select.innerHTML = [
    '<option value="">Choose draft...</option>',
    ...state.voiceConceptDrafts.map((draft) => {
      const score = Math.round((((draft.consistency_score || 0) + (draft.eligibility_score || 0)) / 2) * 100);
      const criteria = draft.criteria_version ? ` · criteria ${draft.criteria_version}/${draft.criteria_approval_state || "unknown"}` : "";
      const duplicate = draft.is_duplicate ? ` · duplicate x${draft.duplicate_count || 2}` : "";
      const fingerprint = draft.conversation_fingerprint ? ` · #${shortVoiceFingerprint(draft.conversation_fingerprint)}` : "";
      const label = `${draft.category_label || draft.category || "Draft"} · ${score}%${criteria}${duplicate}${fingerprint} · ${draft.created_at || draft.path}`;
      return `<option value="${escapeHtml(draft.path)}">${escapeHtml(label)}</option>`;
    }),
  ].join("");
}

function renderVoiceDraftQueue() {
  const target = $("#voiceDraftQueue");
  if (!target) return;
  const drafts = state.voiceConceptDrafts || [];
  if (!drafts.length) {
    target.innerHTML = '<p class="muted-inline">No open voice concept drafts.</p>';
    return;
  }
  target.innerHTML = `
    <div class="voice-draft-queue-head">
      <strong>Draft review queue</strong>
      <span>${escapeHtml(String(drafts.length))} open</span>
    </div>
    ${drafts.map(renderVoiceDraftQueueItem).join("")}
  `;
}

function renderVoiceDraftQueueItem(draft) {
  const score = Math.round((((draft.consistency_score || 0) + (draft.eligibility_score || 0)) / 2) * 100);
  const ready = Boolean(draft.ready);
  const duplicate = draft.is_duplicate
    ? `<span class="voice-draft-flag warning">duplicate x${escapeHtml(String(draft.duplicate_count || 2))}</span>`
    : "";
  const fingerprint = draft.conversation_fingerprint
    ? `<span class="voice-draft-flag">#${escapeHtml(shortVoiceFingerprint(draft.conversation_fingerprint))}</span>`
    : "";
  return `
    <article class="voice-draft-card ${ready ? "ready" : "pending"}">
      <div>
        <strong>${escapeHtml(draft.category_label || draft.category || "Voice draft")}</strong>
        <span>${escapeHtml(ready ? "ready to save" : "needs clarification")} · ${escapeHtml(String(score))}% · ${escapeHtml(draft.created_at || "")}</span>
        ${draft.next_question ? `<small>${escapeHtml(draft.next_question)}</small>` : ""}
        <div class="voice-draft-flags">${duplicate}${fingerprint}</div>
      </div>
      <div class="voice-draft-actions">
        <button class="secondary small" type="button" data-voice-draft-load="${escapeHtml(draft.path)}">Load</button>
        ${draft.is_duplicate ? `<button class="secondary small" type="button" data-voice-draft-resolve="${escapeHtml(draft.path)}">Keep this</button>` : ""}
        <button class="danger small" type="button" data-voice-draft-delete="${escapeHtml(draft.path)}">Delete</button>
      </div>
    </article>
  `;
}

function shortVoiceFingerprint(value) {
  return String(value || "").slice(0, 10);
}

function voiceDraftDuplicateMeta(fingerprint) {
  if (!fingerprint) return null;
  return (state.voiceConceptDrafts || []).find((draft) => draft.conversation_fingerprint === fingerprint && draft.is_duplicate) || null;
}

function renderVoiceFingerprintMeta(fingerprint, duplicate) {
  if (!fingerprint) return "";
  const duplicateLine = duplicate
    ? `<span class="voice-fingerprint-duplicate">Possible duplicate draft group: ${escapeHtml(String(duplicate.duplicate_count || 2))} matching captures</span>`
    : "";
  return `
    <div class="voice-fingerprint">
      <span>Conversation fingerprint</span>
      <code>${escapeHtml(shortVoiceFingerprint(fingerprint))}</code>
      ${duplicateLine}
    </div>
  `;
}

async function handleVoiceDraftQueueClick(event) {
  const loadButton = event.target.closest("[data-voice-draft-load]");
  if (loadButton) {
    const path = loadButton.dataset.voiceDraftLoad || "";
    if ($("#voiceDraftSelect")) $("#voiceDraftSelect").value = path;
    await loadSelectedVoiceConceptDraft(path);
    return;
  }
  const resolveButton = event.target.closest("[data-voice-draft-resolve]");
  if (resolveButton) {
    await resolveVoiceConceptDraftDuplicates(resolveButton.dataset.voiceDraftResolve || "");
    return;
  }
  const deleteButton = event.target.closest("[data-voice-draft-delete]");
  if (!deleteButton) return;
  await deleteVoiceConceptDraft(deleteButton.dataset.voiceDraftDelete || "");
}

async function resolveVoiceConceptDraftDuplicates(path) {
  if (!path) return;
  if (!(await confirmTwinScopedAction("keep this voice draft and delete matching duplicates"))) return;
  try {
    const result = await postJson("/api/voice/concepts/drafts/resolve-duplicates", {
      keep_path: path,
      actor: "local-user",
    });
    showToast("Duplicate drafts resolved", `${result.deleted_count || 0} duplicate draft(s) removed`, "success");
    if ($("#voiceDraftSelect")) $("#voiceDraftSelect").value = result.kept || path;
    await safeRefreshVoiceConceptDrafts();
    await safeRefreshVoiceConceptPreflight();
    await safeRefreshActivity();
  } catch (error) {
    $("#voiceEvidence").innerHTML = `<span class="warning-copy">Duplicate resolution failed: ${escapeHtml(compactError(error.message))}</span>`;
    setVoiceConversationStatus("error", "Duplicate resolution failed. Try refreshing the draft queue.");
  }
}

async function deleteVoiceConceptDraft(path) {
  if (!path) return;
  if (!(await confirmTwinScopedAction("delete this voice concept draft"))) return;
  try {
    const result = await deleteJson("/api/voice/concepts/drafts", {
      path,
      actor: "local-user",
    });
    showToast("Voice draft deleted", result.path || path, "success");
    if ($("#voiceDraftSelect")?.value === path) $("#voiceDraftSelect").value = "";
    await safeRefreshVoiceConceptDrafts();
    await safeRefreshVoiceConceptPreflight();
    await safeRefreshActivity();
  } catch (error) {
    $("#voiceEvidence").innerHTML = `<span class="warning-copy">Draft delete failed: ${escapeHtml(compactError(error.message))}</span>`;
    setVoiceConversationStatus("error", "Draft delete failed. Try refreshing the draft queue.");
  }
}

function renderVoiceCriteria() {
  const target = $("#voiceCriteriaBox");
  if (!target || !state.voiceConceptCriteria) return;
  const categoryKey = $("#voiceConceptCategory")?.value || "knowledge";
  const readiness = state.voiceConceptCriteria.readiness || {};
  const metadata = state.voiceConceptCriteria.metadata || {};
  const category = state.voiceConceptCriteria.categories?.[categoryKey] || {};
  const dimensions = Object.entries(category.dimensions || {});
  const history = Array.isArray(metadata.approval_history) ? metadata.approval_history : [];
  const latestApproval = history.length ? history[history.length - 1] : null;
  target.innerHTML = `
    <p class="muted-inline">${escapeHtml(category.description || "No category description configured.")}</p>
    <p class="muted-inline">Criteria ${escapeHtml(metadata.version || "unversioned")} · ${escapeHtml(metadata.approval_state || "provisional")} · ${escapeHtml(metadata.updated_at || "")}</p>
    <p class="muted-inline">Agent mode: ${escapeHtml(state.voiceConceptCriteria.agent_mode || "local")} · n8n configured: ${escapeHtml(String(Boolean(state.voiceConceptCriteria.n8n_configured)))}</p>
    <div class="criteria-governance">
      <span><strong>Approval source</strong>${escapeHtml(metadata.approval_source || "system_prompt")}</span>
      <span><strong>Ledger</strong>${escapeHtml(metadata.approval_record || "not created yet")}</span>
      <span><strong>Latest event</strong>${latestApproval ? `${escapeHtml(latestApproval.approval_state || "updated")} by ${escapeHtml(latestApproval.actor || "unknown")} · ${escapeHtml(latestApproval.timestamp || "")}` : "No approval event yet"}</span>
    </div>
    <div class="voice-score-grid">
      <span>Consistency >= ${escapeHtml(readiness.consistency_threshold ?? "-")}</span>
      <span>Eligibility >= ${escapeHtml(readiness.eligibility_threshold ?? "-")}</span>
      <span>Missing <= ${escapeHtml(readiness.max_missing_dimensions ?? "-")}</span>
      <span>Words >= ${escapeHtml(readiness.minimum_words ?? "-")}</span>
    </div>
    <ul class="criteria-list">
      ${dimensions
        .map(([key, value]) => `<li><strong>${escapeHtml(key)}</strong><span>${escapeHtml(value.question || "")}</span></li>`)
        .join("")}
    </ul>
    <code>${escapeHtml(state.voiceConceptCriteria.source || "")}</code>
  `;
  renderVoiceCriteriaApproval(metadata);
}

function renderVoiceCriteriaApproval(metadata) {
  const button = $("#voiceApproveCriteriaBtn");
  const status = $("#voiceCriteriaApprovalStatus");
  if (!button || !status) return;
  const approvalState = metadata.approval_state || "provisional";
  button.disabled = approvalState === "approved";
  status.textContent = approvalState === "approved"
    ? `Approved by ${metadata.approved_by || metadata.owner || "human"} at ${metadata.approved_at || metadata.updated_at || ""}`
    : `${approvalState}. Human approval required before production n8n use.`;
}

async function addVoiceClarification() {
  const answer = $("#voiceClarificationInput").value.trim();
  if (!answer || !state.voiceConceptSession?.transcript) return;
  const activeQuestion = state.voiceConceptSession.assessment?.next_question || "";
  if (activeQuestion) state.voiceConceptSession.questionHistory.push(activeQuestion);
  state.voiceConceptSession.replies.push(answer);
  $("#voiceClarificationInput").value = "";
  setVoiceConversationStatus("pending", "Rechecking the concept with your clarification.");
  await assessVoiceConcept();
}

async function handleVoiceClarificationKeydown(event) {
  if (event.key !== "Enter" || !event.ctrlKey) return;
  event.preventDefault();
  if ($("#voiceClarifyBtn").disabled) return;
  await addVoiceClarification();
}

async function assessVoiceConcept() {
  if (!state.voiceConceptSession?.transcript) return;
  state.voiceConceptSession.category = $("#voiceConceptCategory").value;
  try {
    const result = await postJson("/api/voice/concepts/assess", {
      transcript: state.voiceConceptSession.transcript,
      category: state.voiceConceptSession.category,
      replies: state.voiceConceptSession.replies,
      question_history: state.voiceConceptSession.questionHistory || [],
      twin: state.activeTwin,
    });
    state.voiceConceptSession.assessment = result.assessment;
    state.voiceConceptSession.agent = result.agent || state.voiceConceptSession.agent;
    state.voiceConceptSession.conversation = result.conversation || state.voiceConceptSession.conversation || null;
    renderVoiceConceptAssessment();
    $("#voiceCommitBtn").disabled = !result.assessment?.ready;
    $("#voiceDraftBtn").disabled = false;
    $("#voiceAgentHandoffBtn").disabled = false;
  } catch (error) {
    $("#voiceConceptAssessment").innerHTML = `<p class="warning-copy">Assessment failed: ${escapeHtml(error.message)}</p>`;
    setVoiceConversationStatus("error", "Assessment failed. The transcript is still available for retry.");
  }
}

async function prepareVoiceAgentHandoff() {
  if (!state.voiceConceptSession?.transcript) return;
  const target = prompt("Prepare handoff for which target? mcp, n8n, or github", "mcp");
  if (target === null) return;
  const normalizedTarget = target.trim().toLowerCase() || "mcp";
  const note = prompt("Optional human review note for this handoff payload", "") || "";
  if (!(await confirmTwinScopedAction(`prepare a ${normalizedTarget} agent handoff payload from this transcript`))) return;
  $("#voiceAgentHandoffBtn").disabled = true;
  setVoiceConversationStatus("pending", "Preparing local agent handoff payload...");
  try {
    const result = await postJson("/api/voice/concepts/agent-handoff", {
      transcript: state.voiceConceptSession.transcript,
      category: state.voiceConceptSession.category || $("#voiceConceptCategory").value,
      replies: state.voiceConceptSession.replies || [],
      question_history: state.voiceConceptSession.questionHistory || [],
      evidence_path: state.voiceConceptSession.evidence?.path || "",
      target: normalizedTarget,
      purpose: "prepare_agent_context",
      human_note: note,
      twin: state.activeTwin,
      actor: "local-user",
    });
    state.voiceConceptSession.evidence = result.evidence || state.voiceConceptSession.evidence;
    $("#voiceEvidence").innerHTML = `
      <strong>Agent handoff prepared:</strong> <code>${escapeHtml(result.handoff_path || "")}</code><br>
      <span class="muted-inline">Target: ${escapeHtml(result.target || normalizedTarget)} · Payload hash: ${escapeHtml(result.payload_hash || "")}</span><br>
      <span class="muted-inline">Transcript evidence: <code>${escapeHtml(result.evidence?.path || "")}</code></span><br>
      <span class="muted-inline">${escapeHtml(result.approval_boundary || "Review required before external execution.")}</span>
    `;
    setVoiceConversationStatus("ready", "Local handoff payload prepared. Review it before any external agent execution.");
    showToast("Agent handoff prepared", result.handoff_path || "voice transcript handoff", "success");
    await safeRefreshVoiceTranscriptHandoffs();
    await safeRefreshActivity();
  } catch (error) {
    $("#voiceEvidence").innerHTML = `<span class="warning-copy">Agent handoff failed: ${escapeHtml(compactError(error.message))}</span>`;
    setVoiceConversationStatus("error", "Agent handoff failed. The transcript remains available.");
  } finally {
    $("#voiceAgentHandoffBtn").disabled = !state.voiceConceptSession?.transcript || Boolean(state.voiceConceptSession?.saved);
  }
}

async function refreshVoiceTranscriptHandoffs() {
  const result = await getJson("/api/voice/concepts/agent-handoffs?limit=8");
  state.voiceTranscriptHandoffs = result.handoffs || [];
  renderVoiceAgentHandoffLedger();
}

async function safeRefreshVoiceTranscriptHandoffs() {
  try {
    await refreshVoiceTranscriptHandoffs();
  } catch (error) {
    state.voiceTranscriptHandoffs = [];
    renderVoiceAgentHandoffLedger("Handoff ledger unavailable. Restart the local MVP server.");
    console.warn("Voice transcript handoff refresh failed", error);
  }
}

function renderVoiceTranscriptSyncStatus() {
  const target = $("#voiceTranscriptSyncStatus");
  if (!target) return;
  const evidencePath = state.voiceConceptSession?.evidence?.path || "";
  const sync = state.syncStatus || {};
  const preview = Array.isArray(sync.preview) ? sync.preview : [];
  const transcriptEvents = preview.filter((entry) => {
    const details = entry.details || {};
    const path = details.path || details.deleted_file || "";
    return details.artifact_class === "voice-transcript" || String(path).startsWith("evidence/transcripts/");
  });
  const currentEvent = evidencePath
    ? transcriptEvents.find((entry) => (entry.details || {}).path === evidencePath || (entry.details || {}).deleted_file === evidencePath)
    : null;
  if (!evidencePath && !transcriptEvents.length) {
    target.innerHTML = '<span class="muted-inline">No transcript evidence is active in this session.</span>';
    return;
  }
  const latestEvent = currentEvent || transcriptEvents[0] || null;
  const syncLabel = currentEvent
    ? "Current transcript is queued for GitHub/MCP sync."
    : evidencePath
      ? "Current transcript evidence exists; refresh sync preview to confirm export queue."
      : `${transcriptEvents.length} transcript evidence item${transcriptEvents.length === 1 ? "" : "s"} in recent sync queue.`;
  target.innerHTML = `
    <strong>Transcript sync status</strong><br>
    <span class="muted-inline">${escapeHtml(syncLabel)}</span><br>
    ${evidencePath ? `<code>${escapeHtml(evidencePath)}</code><br>` : ""}
    ${latestEvent ? `<span class="muted-inline">Latest sync event: ${escapeHtml(latestEvent.action || "")} · ${escapeHtml(latestEvent.timestamp || "")}</span>` : ""}
  `;
}

function renderVoiceAgentHandoffLedger(message = "") {
  const target = $("#voiceAgentHandoffLedger");
  if (!target) return;
  const items = state.voiceTranscriptHandoffs || [];
  renderVoiceTranscriptSyncStatus();
  if (message) {
    target.innerHTML = `<p class="warning-copy">${escapeHtml(message)}</p>`;
    return;
  }
  if (!items.length) {
    target.innerHTML = '<p class="empty">No transcript agent handoffs yet.</p>';
    return;
  }
  target.innerHTML = `
    <h3>Transcript Handoffs</h3>
    ${items.map((item) => renderVoiceAgentHandoffRow(item)).join("")}
    ${state.voiceTranscriptHandoffDetail ? renderVoiceAgentHandoffDetail(state.voiceTranscriptHandoffDetail) : ""}
  `;
}

function renderVoiceAgentHandoffRow(item) {
  const approved = item.approval_state === "approved_for_execution";
  const rejected = item.approval_state === "rejected";
  const routed = Boolean(item.mcp_call_id || item.routing_state);
  return `
    <article class="activity-row queue-card ${approved ? "priority-low" : rejected ? "priority-high" : "priority-medium"}">
      <div class="activity-meta">
        <span class="type">${escapeHtml(item.target || "agent")}</span>
        <span>${escapeHtml((item.approval_state || "prepared").replaceAll("_", " "))}</span>
        ${routed ? `<span>${escapeHtml((item.routing_state || "mcp queued").replaceAll("_", " "))}</span>` : ""}
        <span>${escapeHtml(item.created_at || item.modified_at || "")}</span>
      </div>
      <h4>${escapeHtml(item.category || "voice transcript")} handoff</h4>
      <p>${escapeHtml(item.evidence_path || "No evidence path recorded.")}</p>
      ${item.mcp_call_id ? `<p class="muted-inline">MCP queue item: <code>${escapeHtml(item.mcp_call_id)}</code></p>` : ""}
      <code>${escapeHtml(item.path || "")}</code>
      <div class="button-row tight">
        <button class="secondary small" type="button" data-voice-handoff-detail="${escapeHtml(item.path || "")}">Detail</button>
        <button class="secondary small" type="button" data-voice-handoff-review="approve" data-voice-handoff-path="${escapeHtml(item.path || "")}" ${approved ? "disabled" : ""}>Approve</button>
        <button class="secondary small" type="button" data-voice-handoff-route="${escapeHtml(item.path || "")}" ${!approved || routed ? "disabled" : ""}>Route to MCP</button>
        <button class="secondary small danger" type="button" data-voice-handoff-review="reject" data-voice-handoff-path="${escapeHtml(item.path || "")}" ${rejected ? "disabled" : ""}>Reject</button>
      </div>
    </article>
  `;
}

function renderVoiceHandoffProofTimeline(detail, mcpCall, mcpHistory, productionReadiness) {
  const githubHistory = Array.isArray(detail.github_sync_history) ? detail.github_sync_history : [];
  const reviewHistory = Array.isArray(detail.review_history) ? detail.review_history : [];
  const routeHistory = Array.isArray(detail.route_history) ? detail.route_history : [];
  const latestGithubEvent = githubHistory[githubHistory.length - 1] || {};
  const latestMcpEvent = mcpHistory[mcpHistory.length - 1] || {};
  const canPrepareGithubEvidence = Boolean(detail.path && (mcpHistory.length || mcpCall?.status));
  const canExportGithubPayload = Boolean(detail.github_evidence_path || canPrepareGithubEvidence);
  const canPrepareCanaryPacket = Boolean(
    productionReadiness?.can_prepare_canary_packet ||
      (detail.github_sync_payload_path && detail.github_evidence_path && ["approved", "executed_mock"].includes(mcpCall?.status || "")),
  );
  const steps = [
    {
      label: "Prepared",
      state: "ready",
      timestamp: detail.created_at || "",
      detail: detail.payload_hash ? `Payload ${String(detail.payload_hash).slice(0, 12)}` : detail.path || "Handoff artifact created.",
      actions: detail.path
        ? [{ label: "Copy path", attrs: `class="secondary small source-copy-btn" data-copy-value="${escapeHtml(detail.path)}"` }]
        : [],
    },
    {
      label: "Human review",
      state: detail.approval_state === "approved_for_execution" ? "ready" : detail.approval_state === "rejected" ? "blocked" : "open",
      timestamp: detail.reviewed_at || reviewHistory[reviewHistory.length - 1]?.timestamp || "",
      detail: detail.reviewed_by ? `${detail.reviewed_by} · ${(detail.approval_state || "").replaceAll("_", " ")}` : "Awaiting handoff approval.",
    },
    {
      label: "MCP route",
      state: detail.mcp_call_id ? "ready" : "open",
      timestamp: detail.routed_at || routeHistory[routeHistory.length - 1]?.timestamp || "",
      detail: detail.mcp_call_id || "Route approved handoff to MCP queue.",
    },
    {
      label: "Mock trace",
      state: mcpCall?.status === "executed_mock" ? "ready" : mcpCall ? "open" : "blocked",
      timestamp: latestMcpEvent.timestamp || "",
      detail: mcpCall?.status === "executed_mock"
        ? `${latestMcpEvent.event || "mock executed"} · external execution false`
        : mcpCall
          ? `MCP status ${mcpCall.status || "pending"}`
          : "MCP queue item missing.",
    },
    {
      label: "GitHub evidence",
      state: detail.github_evidence_path ? "ready" : "open",
      timestamp: detail.github_sync_updated_at || latestGithubEvent.timestamp || "",
      detail: detail.github_evidence_path || "Prepare handoff evidence for sync.",
      actions: detail.github_evidence_path
        ? [
            { label: "Open evidence", attrs: `class="secondary small" data-concept-open="${escapeHtml(detail.github_evidence_path)}"` },
            { label: "Copy path", attrs: `class="secondary small source-copy-btn" data-copy-value="${escapeHtml(detail.github_evidence_path)}"` },
          ]
        : [
            {
              label: "Prepare",
              attrs: `class="secondary small" data-handoff-github-evidence="${escapeHtml(detail.path || "")}" ${canPrepareGithubEvidence ? "" : "disabled"}`,
            },
          ],
    },
    {
      label: "Payload export",
      state: detail.github_sync_payload_path ? "ready" : detail.github_sync_payload_hash ? "open" : "blocked",
      timestamp: latestGithubEvent.event === "payload_exported" ? latestGithubEvent.timestamp : "",
      detail: detail.github_sync_payload_path || detail.github_sync_payload_hash || "Export reviewed sync payload.",
      actions: detail.github_sync_payload_path
        ? [
            { label: "Copy payload", attrs: `class="secondary small source-copy-btn" data-copy-value="${escapeHtml(detail.github_sync_payload_path)}"` },
            { label: "Copy hash", attrs: `class="secondary small source-copy-btn" data-copy-value="${escapeHtml(detail.github_sync_payload_hash || "")}"` },
          ]
        : [
            {
              label: "Export",
              attrs: `class="secondary small" data-handoff-sync-package="export" data-handoff-path="${escapeHtml(detail.path || "")}" ${canExportGithubPayload ? "" : "disabled"}`,
            },
          ],
    },
    {
      label: "Canary packet",
      state: detail.production_canary_package_path ? "ready" : productionReadiness?.can_prepare_canary_packet ? "open" : "blocked",
      timestamp: detail.production_canary_package_path ? latestGithubEvent.timestamp || detail.github_sync_updated_at || "" : "",
      detail: detail.production_canary_package_path || productionReadiness?.status || "Prepare production canary review packet.",
      actions: detail.production_canary_package_path
        ? [
            { label: "Open packet", attrs: `class="secondary small" data-handoff-open-canary="${escapeHtml(detail.production_canary_package_path)}"` },
            { label: "Copy path", attrs: `class="secondary small source-copy-btn" data-copy-value="${escapeHtml(detail.production_canary_package_path)}"` },
          ]
        : [
            {
              label: "Prepare",
              attrs: `class="secondary small" data-handoff-canary-package="${escapeHtml(detail.path || "")}" ${canPrepareCanaryPacket ? "" : "disabled"}`,
            },
          ],
    },
    {
      label: "Hosted gate",
      state: productionReadiness?.can_request_hosted_canary ? "ready" : "open",
      timestamp: "",
      detail: productionReadiness?.can_request_hosted_canary ? "Ready for hosted canary gate." : productionReadiness?.status || "Hosted MCP config still gated.",
      actions: [{ label: "Hosted setup", attrs: 'class="secondary small" data-cockpit-action="openHostedConfig"' }],
    },
  ];
  return `
    <section class="voice-proof-timeline" aria-label="Voice proof chain timeline">
      ${steps.map((step, index) => `
        <article class="${escapeHtml(step.state)}">
          <span>${escapeHtml(String(index + 1))}</span>
          <div>
            <strong>${escapeHtml(step.label)}</strong>
            <p>${escapeHtml(step.detail || "")}</p>
            ${step.timestamp ? `<small>${escapeHtml(formatShortDate(step.timestamp))}</small>` : ""}
            ${step.actions?.length ? `
              <div class="voice-proof-actions">
                ${step.actions.map((action) => `<button type="button" ${action.attrs}>${escapeHtml(action.label)}</button>`).join("")}
              </div>
            ` : ""}
          </div>
        </article>
      `).join("")}
    </section>
  `;
}

function renderVoiceHandoffGithubPrGuidance(detail) {
  const payloadPath = detail.github_sync_payload_path || "";
  if (!payloadPath) return "";
  const localAppPath = 'C:\\Users\\e729958\\Downloads\\INtellectual twin\\03. Local MVP\\intellectual-twin-web';
  const localBundlePath = 'C:\\Users\\e729958\\Downloads\\INtellectual twin\\03. Local MVP\\florian-twin';
  const knowledgeRepoPath = 'C:\\Users\\e729958\\Documents\\MeIDs-Knowledge-Base-';
  const normalizedPayload = String(payloadPath).replaceAll("/", "\\");
  const absolutePayloadPath = `${localBundlePath}\\${normalizedPayload}`;
  const dryRunCommand = [
    `cd "${localAppPath}"`,
    'powershell.exe -ExecutionPolicy Bypass -File ".\\scripts\\github_sync_pr.ps1" `',
    `  -PayloadPath "${absolutePayloadPath}" \``,
    `  -KnowledgeRepoPath "${knowledgeRepoPath}" \``,
    '  -DryRun',
  ].join("\n");
  const applyCommand = [
    `cd "${localAppPath}"`,
    'powershell.exe -ExecutionPolicy Bypass -File ".\\scripts\\github_sync_pr.ps1" `',
    `  -PayloadPath "${absolutePayloadPath}" \``,
    `  -KnowledgeRepoPath "${knowledgeRepoPath}" \``,
    '  -CommitMessage "Sync MeIDs voice handoff evidence" `',
    '  -PrTitle "Sync MeIDs voice handoff evidence" `',
    '  -OpenPullRequest',
  ].join("\n");
  return `
    <article class="sync-approval-state ready voice-github-pr-guidance">
      <span>GitHub PR handoff</span>
      <strong>Payload exported. Apply it to the local knowledge repository, then open a human-reviewed PR.</strong>
      <p>Run the dry-run first if the repository was just cloned or the payload branch was already pushed. The script requires a local Git checkout and Git/GitHub authentication on this machine.</p>
      <div class="sync-active-filters compact">
        <span><strong>Payload</strong>${escapeHtml(payloadPath)}</span>
        <span><strong>Hash</strong>${escapeHtml((detail.github_sync_payload_hash || "").slice(0, 16) || "not recorded")}</span>
        <span><strong>Script</strong>scripts/github_sync_pr.ps1</span>
        <span><strong>Review gate</strong>merge only after human PR review</span>
      </div>
      <div class="voice-github-pr-command-grid">
        ${renderProductionCommand("Dry-run payload apply", dryRunCommand, { compact: true, reason: "Checks the payload and target repo without writing files." })}
        ${renderProductionCommand("Apply payload and open PR", applyCommand, { compact: true, reason: "Applies operations, commits to the sync branch, pushes, and opens the compare/PR flow when GitHub CLI is available." })}
      </div>
      <p class="voice-github-pr-fallback">Manual fallback: open the payload JSON, copy its operations into the cloned GitHub repository branch, commit, push, and create the pull request from GitHub. Keep merge approval human-controlled.</p>
    </article>
  `;
}

function renderVoiceAgentHandoffDetail(detail) {
  const mcpCall = detail.mcp_tool_call || null;
  const requestJson = mcpCall?.request_json || {};
  const blockedActions = requestJson.blocked_external_actions || detail.routing?.blocked_actions_without_approval || [];
  const canApproveMcp = mcpCall?.status === "pending_approval";
  const canExecuteMcp = mcpCall?.status === "approved";
  const mcpHistory = Array.isArray(detail.mcp_event_history) ? detail.mcp_event_history : [];
  const lastMcpEvent = detail.mcp_last_event || mcpHistory[mcpHistory.length - 1] || null;
  const productionReadiness = detail.production_readiness || {};
  const productionChecks = Array.isArray(productionReadiness.checks) ? productionReadiness.checks : [];
  const canPrepareGithubEvidence = Boolean(detail.path && (mcpHistory.length || mcpCall?.status));
  const canExportGithubPayload = Boolean(detail.github_evidence_path || canPrepareGithubEvidence);
  const canPrepareCanaryPacket = Boolean(productionReadiness.can_prepare_canary_packet || (detail.github_sync_payload_path && detail.github_evidence_path && ["approved", "executed_mock"].includes(mcpCall?.status || "")));
  return `
    <details class="sync-payload-json handoff-detail" open>
      <summary>Selected handoff detail</summary>
      <div class="mcp-readiness-checks">
        <article class="${detail.approval_state === "approved_for_execution" ? "ready" : "blocked"}">
          <span>Handoff approval</span>
          <strong>${escapeHtml((detail.approval_state || "prepared").replaceAll("_", " "))}</strong>
          <p>${escapeHtml(detail.execution_boundary || detail.approval_boundary || "Review required before routing.")}</p>
        </article>
        <article class="${mcpCall ? (mcpCall.status === "executed_mock" ? "ready" : "attention") : "blocked"}">
          <span>MCP queue</span>
          <strong>${escapeHtml(mcpCall?.status || detail.routing_state || "not queued")}</strong>
          <p>${mcpCall ? `Call ${escapeHtml(mcpCall.call_id || "")} · ${escapeHtml(mcpCall.connector || "")}/${escapeHtml(mcpCall.tool_name || "")}` : "Route the approved handoff before MCP review."}</p>
        </article>
        <article class="${productionReadiness.can_request_hosted_canary ? "ready" : productionReadiness.can_prepare_canary_packet ? "attention" : "blocked"}">
          <span>Production bridge</span>
          <strong>${escapeHtml(productionReadiness.status || "not evaluated")}</strong>
          <p>${escapeHtml(`${productionReadiness.ready_count ?? 0}/${productionReadiness.check_count ?? 0} checks · ${productionReadiness.boundary || "Local readiness only."}`)}</p>
        </article>
      </div>
      ${renderVoiceHandoffProofTimeline(detail, mcpCall, mcpHistory, productionReadiness)}
      ${productionChecks.length ? `
        <div class="voice-gate-grid compact">
          ${productionChecks.map((check) => `
            <article class="voice-gate ${check.ready ? "ready" : "warning"}">
              <span>${escapeHtml(check.label || check.key || "Check")}</span>
              <strong>${escapeHtml(check.ready ? "ready" : "open")}</strong>
              ${check.ready ? "" : `<small>${escapeHtml(check.next_action || "")}</small>`}
            </article>
          `).join("")}
        </div>
      ` : ""}
      <div class="sync-active-filters compact">
        <span><strong>Evidence</strong>${escapeHtml(detail.evidence?.path || requestJson.evidence_path || "not recorded")}</span>
        <span><strong>Target</strong>${escapeHtml(detail.target || requestJson.handoff_target || "agent")}</span>
        <span><strong>Payload</strong>${escapeHtml((detail.payload_hash || "").slice(0, 16) || "not recorded")}</span>
        <span><strong>Blocked</strong>${escapeHtml(blockedActions.join(", ") || "external writes")}</span>
        <span><strong>MCP events</strong>${escapeHtml(mcpHistory.length)}</span>
        <span><strong>GitHub evidence</strong>${escapeHtml(detail.github_evidence_path || "not prepared")}</span>
        <span><strong>Sync state</strong>${escapeHtml((detail.github_sync_state || "not packaged").replaceAll("_", " "))}</span>
        <span><strong>Sync payload</strong>${escapeHtml(detail.github_sync_payload_path || (detail.github_sync_payload_hash || "").slice(0, 16) || "not exported")}</span>
        <span><strong>Canary packet</strong>${escapeHtml(detail.production_canary_package_path || (detail.production_canary_state || "not prepared"))}</span>
      </div>
      ${renderVoiceHandoffGithubPrGuidance(detail)}
      ${lastMcpEvent ? `
        <article class="sync-approval-state ready">
          <span>Last MCP trace event</span>
          <strong>${escapeHtml((lastMcpEvent.event || "mcp event").replaceAll("_", " "))} · ${escapeHtml(lastMcpEvent.mcp_status || "")}</strong>
          <p>${escapeHtml(`${lastMcpEvent.timestamp || ""} · ${lastMcpEvent.actor || ""} · external execution: ${lastMcpEvent.external_execution ? "true" : "false"}`)}</p>
        </article>
      ` : ""}
      ${mcpCall ? `
        <div class="button-row tight">
          <button class="secondary small" type="button" data-handoff-mcp-review="approve" data-call-id="${escapeHtml(mcpCall.call_id || "")}" data-handoff-path="${escapeHtml(detail.path || "")}" ${canApproveMcp ? "" : "disabled"}>Approve MCP route</button>
          <button class="secondary small danger" type="button" data-handoff-mcp-review="reject" data-call-id="${escapeHtml(mcpCall.call_id || "")}" data-handoff-path="${escapeHtml(detail.path || "")}" ${canApproveMcp ? "" : "disabled"}>Reject MCP route</button>
          <button class="secondary small" type="button" data-handoff-mcp-execute="${escapeHtml(mcpCall.call_id || "")}" data-handoff-path="${escapeHtml(detail.path || "")}" ${canExecuteMcp ? "" : "disabled"}>Mock execute</button>
          <button class="secondary small" type="button" data-handoff-github-evidence="${escapeHtml(detail.path || "")}" ${canPrepareGithubEvidence ? "" : "disabled"}>Prepare GitHub evidence</button>
          <button class="secondary small" type="button" data-handoff-sync-package="approve" data-handoff-path="${escapeHtml(detail.path || "")}" ${canExportGithubPayload ? "" : "disabled"}>Prepare + approve sync</button>
          <button class="secondary small" type="button" data-handoff-sync-package="export" data-handoff-path="${escapeHtml(detail.path || "")}" ${canExportGithubPayload ? "" : "disabled"}>Export GitHub payload</button>
          <button class="secondary small" type="button" data-handoff-canary-package="${escapeHtml(detail.path || "")}" ${canPrepareCanaryPacket ? "" : "disabled"}>Prepare canary packet</button>
          <button class="secondary small" type="button" data-handoff-open-canary="${escapeHtml(detail.production_canary_package_path || "")}" ${detail.production_canary_package_path ? "" : "disabled"}>Review in MCP cockpit</button>
        </div>
      ` : ""}
      <pre class="output compact-output">${escapeHtml(JSON.stringify(detail, null, 2))}</pre>
    </details>
  `;
}

async function handleVoiceAgentHandoffLedgerClick(event) {
  const copyButton = event.target.closest(".source-copy-btn");
  const conceptOpenButton = event.target.closest("[data-concept-open]");
  const detailButton = event.target.closest("[data-voice-handoff-detail]");
  const reviewButton = event.target.closest("[data-voice-handoff-review]");
  const routeButton = event.target.closest("[data-voice-handoff-route]");
  const mcpReviewButton = event.target.closest("[data-handoff-mcp-review]");
  const mcpExecuteButton = event.target.closest("[data-handoff-mcp-execute]");
  const githubEvidenceButton = event.target.closest("[data-handoff-github-evidence]");
  const syncPackageButton = event.target.closest("[data-handoff-sync-package]");
  const canaryPackageButton = event.target.closest("[data-handoff-canary-package]");
  const openCanaryButton = event.target.closest("[data-handoff-open-canary]");
  if (copyButton) {
    const value = copyButton.dataset.copyValue || "";
    const copied = value ? await copyTextToClipboard(value) : false;
    markButtonDone(copyButton, copied ? "Copied" : "No value");
    handleCopySideEffect(copyButton, copied);
    return;
  }
  if (conceptOpenButton) {
    await openConceptDrawer(conceptOpenButton.dataset.conceptOpen || "");
    return;
  }
  if (detailButton) {
    await openVoiceAgentHandoffDetail(detailButton.dataset.voiceHandoffDetail || "");
    return;
  }
  if (openCanaryButton) {
    await openVoiceHandoffCanaryPacket(openCanaryButton.dataset.handoffOpenCanary || "");
    return;
  }
  if (canaryPackageButton) {
    await prepareVoiceHandoffCanaryPackage(canaryPackageButton.dataset.handoffCanaryPackage || "");
    return;
  }
  if (syncPackageButton) {
    await prepareVoiceHandoffSyncPackage(
      syncPackageButton.dataset.handoffPath || "",
      syncPackageButton.dataset.handoffSyncPackage === "export",
    );
    return;
  }
  if (githubEvidenceButton) {
    await prepareVoiceHandoffGithubEvidence(githubEvidenceButton.dataset.handoffGithubEvidence || "");
    return;
  }
  if (mcpReviewButton) {
    await reviewMcpToolCallFromHandoff(
      mcpReviewButton.dataset.callId || "",
      mcpReviewButton.dataset.handoffMcpReview || "approve",
      mcpReviewButton.dataset.handoffPath || "",
    );
    return;
  }
  if (mcpExecuteButton) {
    await executeMockMcpToolCallFromHandoff(mcpExecuteButton.dataset.handoffMcpExecute || "", mcpExecuteButton.dataset.handoffPath || "");
    return;
  }
  if (routeButton) {
    await routeVoiceAgentHandoff(routeButton.dataset.voiceHandoffRoute || "");
    return;
  }
  if (reviewButton) {
    await reviewVoiceAgentHandoff(
      reviewButton.dataset.voiceHandoffPath || "",
      reviewButton.dataset.voiceHandoffReview || "approve",
    );
  }
}

async function openVoiceAgentHandoffDetail(path) {
  if (!path) return;
  try {
    state.voiceTranscriptHandoffDetail = await getJson(`/api/voice/concepts/agent-handoff?path=${encodeURIComponent(path)}`);
    renderVoiceAgentHandoffLedger();
  } catch (error) {
    showToast("Handoff detail failed", error.message, "error");
  }
}

async function reviewVoiceAgentHandoff(path, decision) {
  if (!path) return;
  const note = prompt(`${decision === "approve" ? "Approval" : "Rejection"} note`, "") || "";
  if (!(await confirmTwinScopedAction(`${decision} this transcript agent handoff`))) return;
  try {
    const result = await postJson("/api/voice/concepts/agent-handoff-review", {
      path,
      decision,
      actor: "local-user",
      note,
    });
    state.voiceTranscriptHandoffDetail = result.handoff || null;
    await safeRefreshVoiceTranscriptHandoffs();
    showToast("Handoff reviewed", result.status || decision, "success");
  } catch (error) {
    showToast("Handoff review failed", error.message, "error");
  }
}

async function routeVoiceAgentHandoff(path) {
  if (!path) return;
  const connector = prompt("MCP connector", "knowledge") || "knowledge";
  const toolName = prompt("MCP tool name", "route_voice_transcript_handoff") || "route_voice_transcript_handoff";
  const note = prompt("Routing note", "Route approved transcript evidence to MCP approval queue.") || "";
  if (!(await confirmTwinScopedAction("route this approved transcript handoff to the MCP approval queue"))) return;
  try {
    const result = await postJson("/api/voice/concepts/agent-handoff-route", {
      path,
      connector,
      tool_name: toolName,
      actor: "local-user",
      note,
    });
    state.voiceTranscriptHandoffDetail = result.handoff || null;
    await safeRefreshVoiceTranscriptHandoffs();
    await safeRefreshMcpStatus();
    await safeRefreshReviewDashboard();
    showToast("Handoff queued for MCP approval", result.mcp_call_id || result.status, "success");
  } catch (error) {
    showToast("MCP routing failed", error.message, "error");
  }
}

async function reviewMcpToolCallFromHandoff(callId, decision, handoffPath) {
  if (!callId || !decision) return;
  await reviewMcpToolCall(callId, decision, {
    inputValue: "Reviewed from transcript handoff detail.",
    refreshHandoffPath: handoffPath,
  });
}

async function executeMockMcpToolCallFromHandoff(callId, handoffPath) {
  if (!callId) return;
  await executeMockMcpToolCall(callId, { refreshHandoffPath: handoffPath });
}

async function prepareVoiceHandoffGithubEvidence(path) {
  if (!path) return;
  const note = prompt("GitHub evidence note", "Prepare handoff trace evidence for GitHub sync review.") || "";
  if (!(await confirmTwinScopedAction("prepare GitHub-syncable evidence for this transcript handoff"))) return;
  try {
    const result = await postJson("/api/voice/concepts/agent-handoff-github-evidence", {
      path,
      actor: "local-user",
      note,
    });
    await openVoiceAgentHandoffDetail(path);
    await safeRefreshActivity();
    await safeRefreshSyncStatus();
    showToast("GitHub evidence prepared", result.path || result.status, "success");
  } catch (error) {
    showToast("GitHub evidence failed", error.message, "error");
  }
}

async function prepareVoiceHandoffSyncPackage(path, exportPayload = false) {
  if (!path) return;
  const note = prompt(
    exportPayload ? "GitHub payload export note" : "GitHub sync approval note",
    exportPayload
      ? "Prepare evidence, approve the payload hash, and export the local GitHub payload."
      : "Prepare evidence and approve the current GitHub sync payload hash for local export.",
  ) || "";
  const action = exportPayload
    ? "prepare evidence, approve, and export the local GitHub sync payload"
    : "prepare evidence and approve the GitHub sync payload hash";
  if (!(await confirmTwinScopedAction(action))) return;
  try {
    const result = await postJson("/api/voice/concepts/agent-handoff-sync-package", {
      path,
      actor: "local-user",
      note,
      target: "github",
      approve_for_export: true,
      export_payload: Boolean(exportPayload),
    });
    state.voiceTranscriptHandoffDetail = result.handoff || null;
    if (result.preview) state.syncPayloadPreview = result.preview;
    if (result.export) state.lastSyncExport = result.export;
    await safeRefreshVoiceTranscriptHandoffs();
    await safeRefreshActivity();
    await safeRefreshSyncStatus();
    renderVoiceAgentHandoffLedger();
    showToast(
      exportPayload ? "GitHub payload exported" : "GitHub payload approved",
      result.export?.path || result.preview?.payload?.payload_hash || result.status,
      "success",
    );
  } catch (error) {
    showToast(exportPayload ? "GitHub payload export failed" : "GitHub sync approval failed", error.message, "error");
  }
}

async function prepareVoiceHandoffCanaryPackage(path) {
  if (!path) return;
  const note = prompt("Production canary packet note", "Bind this handoff evidence, MCP mock trace, and exported payload into a canary approval packet.") || "";
  if (!(await confirmTwinScopedAction("prepare a production canary approval packet for this handoff"))) return;
  try {
    const result = await postJson("/api/voice/concepts/agent-handoff-canary-package", {
      path,
      actor: "local-user",
      note,
      connector: "github",
    });
    state.voiceTranscriptHandoffDetail = result.handoff || null;
    state.mcpCanaryApprovalPackage = result;
    await safeRefreshVoiceTranscriptHandoffs();
    await safeRefreshMcpStatus();
    await safeRefreshReviewDashboard();
    renderVoiceAgentHandoffLedger();
    showToast("Canary packet prepared", result.path || result.proof_hash || result.status, "success");
  } catch (error) {
    showToast("Canary packet failed", error.message, "error");
  }
}

async function openVoiceHandoffCanaryPacket(path) {
  if (!path) return;
  await openMcpCanaryPackage(path);
  showView("quality");
  setQualityGroup("production");
  $(".mcp-cockpit")?.scrollIntoView({ block: "start", behavior: "smooth" });
}

async function commitVoiceConcept() {
  if (!state.voiceConceptSession?.transcript) return;
  if (state.voiceConceptCommitInProgress) return;
  const assessment = state.voiceConceptSession.assessment || {};
  if (!assessment.ready) {
    $("#voiceEvidence").innerHTML = `<span class="warning-copy">Concept is not ready yet. Add clarification or save it as a draft.</span>`;
    setVoiceConversationStatus("pending", "Concept is not ready yet. Answer the next Persona Modeler question or save a draft.");
    return;
  }
  state.voiceConceptCommitInProgress = true;
  $("#voiceCommitBtn").disabled = true;
  $("#voiceDraftBtn").disabled = true;
  $("#voiceAgentHandoffBtn").disabled = true;
  renderVoiceConceptAssessment();
  setVoiceConversationStatus("pending", "Saving ready concept to the knowledge base...");
  try {
    const result = await postJson("/api/voice/concepts/commit", {
      transcript: state.voiceConceptSession.transcript,
      category: state.voiceConceptSession.category,
      replies: state.voiceConceptSession.replies,
      question_history: state.voiceConceptSession.questionHistory || [],
      evidence_path: state.voiceConceptSession.evidence?.path || "",
      source_label: "voice-concept-conversation",
      title_hint: assessment.summary || "",
      promotion_review_note: $("#voicePromotionReviewNote").value.trim(),
      promotion_review_actor: "local-user",
      twin: state.activeTwin,
    });
    $("#voiceEvidence").innerHTML = `
      <strong>Concept saved:</strong> <code>${escapeHtml(result.concept?.path || "-")}</code><br>
      <strong>Readiness:</strong> ${escapeHtml(String(result.assessment?.consistency_score || "-"))} consistency · ${escapeHtml(String(result.assessment?.eligibility_score || "-"))} eligibility<br>
      <strong>Evidence:</strong> <code>${escapeHtml(result.evidence?.path || result.concept?.metadata?.voice_evidence_path || "-")}</code><br>
      ${renderVoiceFingerprintMeta(result.conversation_fingerprint || "", null)}
      <strong>Review note:</strong> ${escapeHtml($("#voicePromotionReviewNote").value.trim() || "No review note added.")}<br>
      <span class="muted-inline">Conversation turns saved: ${escapeHtml(String(result.conversation?.turn_count || 0))}</span>
    `;
    $("#voiceCommitBtn").disabled = true;
    $("#voiceDraftBtn").disabled = true;
    $("#voiceAgentHandoffBtn").disabled = true;
    state.voiceConceptSession.saved = true;
    setVoiceConversationStatus("ready", "Concept saved to the knowledge base and visible in review.");
    await refreshConcepts();
    await safeRefreshReviewDashboard();
    await safeRefreshActivity();
    await safeRefreshVoiceConceptPreflight();
    await safeRefreshVoiceConceptRealCoverage();
    await safeRefreshVoiceConceptReadinessGates(true);
    const coverage = state.voiceConceptRealCoverage;
    const savedCategory = result.assessment?.category_label || result.assessment?.category || state.voiceConceptSession.category;
    const missing = coverage?.missing_categories || [];
    const coverageLine = coverage?.status === "complete"
      ? "Real concept coverage is now complete for all categories."
      : `Still missing real concepts: ${missing.join(", ") || "none"}.`;
    $("#voiceEvidence").innerHTML += `
      <br><strong>Category credited:</strong> ${escapeHtml(savedCategory || "-")}<br>
      <span class="muted-inline">${escapeHtml(coverageLine)}</span>
    `;
    showToast("Voice concept saved", coverageLine, coverage?.status === "complete" ? "success" : "info");
  } catch (error) {
    $("#voiceEvidence").innerHTML = `<span class="warning-copy">Save failed: ${escapeHtml(compactError(error.message))}</span>`;
    setVoiceConversationStatus("error", "Save failed. The concept conversation is still available.");
    $("#voiceCommitBtn").disabled = !assessment.ready;
    $("#voiceDraftBtn").disabled = false;
    $("#voiceAgentHandoffBtn").disabled = false;
  } finally {
    state.voiceConceptCommitInProgress = false;
    renderVoiceConceptAssessment();
  }
}

async function saveVoiceConceptDraft() {
  if (!state.voiceConceptSession?.transcript) return;
  try {
    const result = await postJson("/api/voice/concepts/draft", {
      transcript: state.voiceConceptSession.transcript,
      category: state.voiceConceptSession.category,
      replies: state.voiceConceptSession.replies,
      question_history: state.voiceConceptSession.questionHistory || [],
      evidence_path: state.voiceConceptSession.evidence?.path || "",
      source_label: "voice-concept-conversation",
      title_hint: state.voiceConceptSession.assessment?.summary || "",
      draft_note: "Saved from guided voice capture before concept readiness.",
      twin: state.activeTwin,
    });
    $("#voiceEvidence").innerHTML = `
      <strong>Draft saved:</strong> <code>${escapeHtml(result.draft?.path || "-")}</code><br>
      <strong>Evidence:</strong> <code>${escapeHtml(result.evidence?.path || "-")}</code><br>
      ${renderVoiceFingerprintMeta(result.conversation_fingerprint || "", null)}
      <span class="muted-inline">Continue the conversation later, then save as a concept when ready.</span>
    `;
    state.voiceConceptSession.evidence = result.evidence || state.voiceConceptSession.evidence;
    $("#voiceAgentHandoffBtn").disabled = false;
    setVoiceConversationStatus("draft", "Draft saved. Continue the interview later before committing it as knowledge.");
    await safeRefreshVoiceConceptDrafts();
    await safeRefreshActivity();
    await safeRefreshSyncStatus();
    await safeRefreshVoiceConceptPreflight();
  } catch (error) {
    $("#voiceEvidence").innerHTML = `<span class="warning-copy">Draft save failed: ${escapeHtml(compactError(error.message))}</span>`;
    setVoiceConversationStatus("error", "Draft save failed. The current conversation remains open.");
  }
}

async function loadSelectedVoiceConceptDraft(selectedPath = "") {
  const path = selectedPath || $("#voiceDraftSelect")?.value || "";
  if (!path) {
    setVoiceConversationStatus("pending", "Choose a voice concept draft to resume.");
    return;
  }
  try {
    const draft = await postJson("/api/voice/concepts/drafts/detail", { path });
    state.voiceConceptSession = {
      transcript: draft.transcript || "",
      category: draft.category || "knowledge",
      evidence: draft.evidence_path ? { path: draft.evidence_path } : null,
      replies: draft.replies || [],
      questionHistory: draft.question_history || [],
      conversation: draft.conversation || null,
      conversationFingerprint: draft.conversation_fingerprint || "",
      assessment: draft.assessment || null,
      agent: { agent_mode: draft.metadata?.agent_mode || "draft-resume", n8n_ready: true },
    };
    $("#voiceConceptCategory").value = state.voiceConceptSession.category;
    $("#transcriptBox").textContent = state.voiceConceptSession.transcript || "Draft has no transcript.";
    $("#voiceClarificationInput").value = "";
    $("#voicePromotionReviewNote").value = draft.metadata?.voice_promotion_review_note || "";
    renderVoiceCriteria();
    renderVoiceConceptAssessment();
    $("#voiceClarifyBtn").disabled = false;
    $("#voiceDraftBtn").disabled = false;
    $("#voiceAgentHandoffBtn").disabled = false;
    $("#voiceCommitBtn").disabled = !state.voiceConceptSession.assessment?.ready;
    const criteria = draft.criteria?.version
      ? `<br><span class="muted-inline">Criteria: ${escapeHtml(draft.criteria.version)} · ${escapeHtml(draft.criteria.approval_state || "unknown")}</span>`
      : "";
    $("#voiceEvidence").innerHTML = `
      <strong>Draft loaded:</strong> <code>${escapeHtml(draft.path)}</code>${criteria}
      ${renderVoiceFingerprintMeta(draft.conversation_fingerprint || "", voiceDraftDuplicateMeta(draft.conversation_fingerprint || ""))}
    `;
  } catch (error) {
    setVoiceConversationStatus("error", "Draft could not be loaded.");
    $("#voiceEvidence").innerHTML = `<span class="warning-copy">Draft load failed: ${escapeHtml(compactError(error.message))}</span>`;
  }
}

function setVoiceConversationStatus(stateName, message) {
  const target = $("#voiceConversationStatus");
  if (!target) return;
  target.className = `voice-conversation-status ${stateName || "pending"}`;
  target.textContent = message;
}

function renderVoiceConceptAssessment() {
  const session = state.voiceConceptSession;
  const target = $("#voiceConceptAssessment");
  if (!session?.assessment || !target) return;
  const assessment = session.assessment;
  const saved = Boolean(session.saved);
  const replies = session.replies || [];
  const questionHistory = session.questionHistory || [];
  const readinessScore = Math.min(100, Math.round((((assessment.consistency_score || 0) + (assessment.eligibility_score || 0)) / 2) * 100));
  const missing = assessment.missing_dimensions || [];
  const covered = assessment.covered_dimensions || [];
  const blockers = assessment.blocking_reasons || [];
  const statusMessage = assessment.ready
    ? saved
      ? "Saved. The concept is now in the knowledge base."
      : "Ready to save. The concept meets the active consistency and eligibility gate."
    : `Needs clarification. ${missing.length ? `Open dimensions: ${missing.join(", ")}.` : "Answer the next question to improve readiness."}`;
  setVoiceConversationStatus(assessment.ready ? "ready" : "pending", statusMessage);
  target.innerHTML = `
    <div class="voice-score-grid">
      <span class="${assessment.ready ? "ready" : "pending"}">${assessment.ready ? "Ready" : "Needs clarification"}</span>
      <span>Consistency ${Math.round((assessment.consistency_score || 0) * 100)}%</span>
      <span>Eligibility ${Math.round((assessment.eligibility_score || 0) * 100)}%</span>
      <span>Words ${escapeHtml(String(assessment.word_count || 0))}</span>
    </div>
    <div class="voice-readiness-meter" aria-label="Voice concept readiness">
      <span style="width: ${readinessScore}%"></span>
    </div>
    <div class="voice-question-card">
      <span>${saved ? "Knowledge base" : assessment.ready ? "Persona Modeler verdict" : "Persona Modeler asks"}</span>
      <strong>${escapeHtml(saved ? "Concept saved. Continue with the next missing category when ready." : assessment.next_question || "Clarify the concept.")}</strong>
      ${saved
        ? renderSavedVoiceConceptNextAction()
        : assessment.ready
        ? `<button class="secondary small" type="button" data-voice-save-ready ${state.voiceConceptCommitInProgress ? "disabled" : ""}>${state.voiceConceptCommitInProgress ? "Saving..." : "Save concept"}</button>`
        : `<button class="secondary small" type="button" data-voice-answer-next>Answer this</button>`}
    </div>
    ${assessment.ready || !blockers.length ? "" : `
      <div class="voice-blocking-reasons">
        <strong>Before saving</strong>
        <ul>${blockers.map((reason) => `<li>${escapeHtml(reason)}</li>`).join("")}</ul>
      </div>
    `}
    <p class="muted-inline">Agent mode: ${escapeHtml(session.agent?.agent_mode || "local-persona-modeler")} · n8n adapter-ready: ${escapeHtml(String(session.agent?.n8n_ready ?? true))}</p>
    <div class="voice-dimension-grid">
      <div>
        <span>Covered</span>
        <strong>${escapeHtml(covered.join(", ") || "none")}</strong>
      </div>
      <div>
        <span>Open</span>
        <strong>${escapeHtml(missing.join(", ") || "none")}</strong>
      </div>
    </div>
    ${renderVoiceConversationTimeline(session)}
  `;
  updateVoiceClarificationPrompt();
}

async function handleVoiceAssessmentActionClick(event) {
  if (event.target.closest("[data-voice-capture-next-category]")) {
    await loadFirstMissingVoiceConceptSample();
    return;
  }
  if (event.target.closest("[data-voice-save-ready]")) {
    await commitVoiceConcept();
    return;
  }
  if (!event.target.closest("[data-voice-answer-next]")) return;
  updateVoiceClarificationPrompt();
  $("#voiceClarificationInput")?.focus();
}

function renderSavedVoiceConceptNextAction() {
  const coverage = state.voiceConceptRealCoverage;
  if (coverage?.status === "complete") {
    return '<span class="ready-copy">All voice concept categories are covered.</span>';
  }
  const missing = coverage?.missing_categories || [];
  const label = missing.length ? `Capture ${missing[0].replace("_", " ")}` : "Capture next category";
  return `<button class="secondary small" type="button" data-voice-capture-next-category>${escapeHtml(label)}</button>`;
}

function updateVoiceClarificationPrompt() {
  const input = $("#voiceClarificationInput");
  const assessment = state.voiceConceptSession?.assessment || null;
  const question = assessment?.next_question || "";
  if (!input) return;
  if (state.voiceConceptSession?.saved) {
    input.placeholder = "Concept saved. Start another real concept when ready...";
    return;
  }
  if (!assessment) {
    input.placeholder = "Answer the Persona Modeler's next question...";
    return;
  }
  input.placeholder = question && !assessment.ready
    ? `Answer: ${question}`
    : "Concept is ready. Save it, or add optional clarification before saving...";
}

function renderVoiceConversationTimeline(session) {
  const normalizedTurns = session.conversation?.turns || [];
  const replies = normalizedTurns.length ? normalizedTurns.map((turn) => turn.human_answer || "") : (session.replies || []);
  const questionHistory = normalizedTurns.length ? normalizedTurns.map((turn) => turn.persona_modeler_question || "") : (session.questionHistory || []);
  const turns = [];
  if (session.transcript) {
    turns.push(`
      <li>
        <span class="voice-turn-role">You</span>
        <p>${escapeHtml(session.transcript)}</p>
      </li>
    `);
  }
  replies.forEach((reply, index) => {
    const question = questionHistory[index] || "";
    turns.push(`
      <li>
        <span class="voice-turn-role">Clarification ${index + 1}</span>
        ${question ? `<em>Persona Modeler: ${escapeHtml(question)}</em>` : ""}
        <p>${escapeHtml(reply)}</p>
      </li>
    `);
  });
  if (!turns.length) return "";
  return `<ol class="voice-replies">${turns.join("")}</ol>`;
}

