async function refreshWorkspace() {
  try {
    await refreshAll();
    showToast("Workspace refreshed", `${state.activeTwin} is current`, "success");
  } catch (error) {
    showToast("Refresh failed", error.message, "error");
  }
}

async function refreshTwins() {
  if (staticPagesMode) {
    refreshStaticTwinState();
    renderTwinOptions();
    renderTwinCatalog(state.twinActivity);
    fillTwinForm(state.selectedTwinId);
    updateLandingStatus();
    renderTwinContextNotices();
    renderWorkspaceIntro();
    renderSkillRoutingPanel();
    renderSetupStepDetail();
    renderDesignCockpitBoard();
    return;
  }
  const result = await getJson("/api/twins?include_archived=true");
  state.twins = result.twins || [];
  state.twinActivity = result.activity || [];
  state.activeTwin = result.active_twin || state.activeTwin;
  if (!state.selectedTwinId || !state.twins.some((twin) => twin.twin_id === state.selectedTwinId)) {
    state.selectedTwinId = state.activeTwin;
  }
  renderTwinOptions();
  renderTwinCatalog(state.twinActivity);
  fillTwinForm(state.selectedTwinId);
  updateLandingStatus();
  renderTwinContextNotices();
  renderWorkspaceIntro();
  renderSkillRoutingPanel();
  renderSetupStepDetail();
  renderDesignCockpitBoard();
}

async function refreshDeepHealth() {
  const [health, architecture] = await Promise.all([
    getJson("/api/health/deep"),
    getJson("/api/okf/architecture"),
  ]);
  state.deepHealth = health;
  state.okfArchitecture = architecture;
  renderDeepHealthPanel();
  renderOkfArchitecturePanel();
}

async function safeRefreshDeepHealth() {
  try {
    await refreshDeepHealth();
  } catch (error) {
    const status = $("#deepHealthStatus");
    if (status) status.textContent = "Deep health endpoint unavailable. Restart the local MVP server.";
    const panel = $("#deepHealthPanel");
    if (panel) panel.innerHTML = "";
    console.warn("Deep health refresh failed", error);
  }
}

async function exportOkfArchitectureRoadmap() {
  const status = $("#deepHealthStatus");
  if (status) status.textContent = "Exporting OKF compounding roadmap...";
  try {
    const result = await postJson("/api/okf/architecture/export", {});
    state.okfArchitecture = result;
    state.okfArchitectureArtifact = result.artifact || null;
    renderOkfArchitecturePanel();
    if (status) status.textContent = `OKF roadmap exported: ${result.artifact?.path || "OKF_COMPOUNDING_ROADMAP.md"}`;
    showToast("OKF roadmap exported", result.artifact?.path || "OKF_COMPOUNDING_ROADMAP.md", "success");
  } catch (error) {
    if (status) status.textContent = `OKF roadmap export failed: ${error.message}`;
    showToast("OKF roadmap export failed", error.message, "error");
  }
}

function renderDeepHealthPanel() {
  const target = $("#deepHealthPanel");
  const status = $("#deepHealthStatus");
  if (!target || !status) return;
  const health = state.deepHealth || {};
  const checks = Array.isArray(health.checks) ? health.checks : [];
  const summary = health.summary || {};
  status.textContent = `${health.status || "unknown"} · ${summary.ok ?? 0}/${summary.total ?? checks.length} checks passing`;
  target.innerHTML = `
    <div class="sync-active-filters">
      <span><strong>Status</strong>${escapeHtml(health.status || "unknown")}</span>
      <span><strong>Active twin</strong>${escapeHtml(health.active_twin || state.activeTwin || "-")}</span>
      <span><strong>Checks</strong>${escapeHtml(`${summary.ok ?? 0}/${summary.total ?? checks.length}`)}</span>
      <span><strong>Build</strong>${escapeHtml(health.frontend_build_tag || FRONTEND_BUILD_TAG)}</span>
    </div>
    <div class="migration-step-list">
      ${checks.map((check) => `
        <span class="${check.ok ? "ready" : "missing"}">
          <strong>${escapeHtml(check.name || "check")}</strong>
          <small>${escapeHtml(`${check.category || "runtime"} · ${check.detail || ""}`)}</small>
        </span>
      `).join("") || '<p class="empty">No health checks returned.</p>'}
    </div>
  `;
}

function renderOkfArchitecturePanel() {
  const target = $("#okfArchitecturePanel");
  if (!target) return;
  const architecture = state.okfArchitecture || {};
  const counts = architecture.counts || {};
  const path = state.okfArchitectureArtifact?.path || architecture.artifact?.path || "OKF_COMPOUNDING_ROADMAP.md";
  const stages = Array.isArray(architecture.compounding_path) ? architecture.compounding_path : [];
  const agentModel = architecture.agent_operating_model || {};
  const topAgents = Array.isArray(agentModel.top_level_agents) ? agentModel.top_level_agents : [];
  target.innerHTML = `
    <div class="sync-active-filters">
      <span><strong>Twins</strong>${escapeHtml(`${counts.active_twins ?? 0}/${counts.registered_twins ?? 0}`)}</span>
      <span><strong>Concepts</strong>${escapeHtml(counts.concept_files ?? 0)}</span>
      <span><strong>Evidence</strong>${escapeHtml(counts.evidence_files ?? 0)}</span>
      <span><strong>Skills</strong>${escapeHtml(counts.skill_packages ?? 0)}</span>
    </div>
    <article class="sync-approval-state ready">
      <span>Roadmap artifact</span>
      <strong>${escapeHtml(path)}</strong>
      <p>Markdown remains the portable OKF authoring format; hosted Postgres becomes the governed runtime mirror.</p>
    </article>
    <div class="migration-step-list">
      ${stages.map((stage) => `
        <span class="ready">
          <strong>${escapeHtml(stage.stage || "stage")}</strong>
          <small>${escapeHtml(stage.description || "")}</small>
        </span>
      `).join("") || '<p class="empty">No OKF compounding stages returned.</p>'}
    </div>
    <article class="sync-approval-state ready">
      <span>Agent operating model</span>
      <strong>${escapeHtml(topAgents.length ? "3 top-level agents approved" : "No agent model returned")}</strong>
      <p>Actor Twin decides, Knowledge Fabric Agent maintains OKF, Agentic Butler executes approved skills.</p>
    </article>
    <div class="migration-step-list">
      ${topAgents.map((agent) => `
        <span class="ready">
          <strong>${escapeHtml(agent.name || agent.id || "agent")}</strong>
          <small>${escapeHtml(agent.purpose || "")}</small>
        </span>
      `).join("") || '<p class="empty">No top-level agents returned.</p>'}
    </div>
  `;
}

async function safeRefreshTwins() {
  try {
    await refreshTwins();
  } catch (error) {
    console.warn("Twin refresh failed", error);
    $("#twinCatalog").innerHTML = '<p class="empty">Twin registry unavailable. Restart the local MVP server.</p>';
  }
}

function renderTwinOptions() {
  const activeTwins = state.twins.filter((twin) => twin.status === "active");
  $("#twinSelect").innerHTML = activeTwins
    .map((twin) => `<option value="${escapeHtml(twin.twin_id)}">${escapeHtml(twin.display_name || twin.twin_id)}</option>`)
    .join("");
  if (activeTwins.some((twin) => twin.twin_id === state.activeTwin)) {
    $("#twinSelect").value = state.activeTwin;
  }
  renderSidebarTwinProfile();
}

function renderSidebarTwinProfile() {
  const active = state.twins.find((twin) => twin.twin_id === state.activeTwin);
  const target = $("#sidebarTwinProfile");
  if (!target || !active) return;
  target.innerHTML = `
    ${renderTwinAvatar(active, "twin-avatar sidebar-avatar")}
    <div>
      <strong>${escapeHtml(active.display_name || active.twin_id)}</strong>
      <span>${escapeHtml(active.role_context || active.purpose || "Active workspace twin")}</span>
    </div>
  `;
}

function twinPictureUrl(twin) {
  const picturePath = twin?.picture_path || "";
  if (!picturePath) return "";
  const separator = picturePath.includes("?") ? "&" : "?";
  const version = encodeURIComponent(twin.picture_uploaded_at || twin.updated_at || "");
  return `${resolveAssetUrl(picturePath)}${separator}v=${version}`;
}

function twinInitials(twin) {
  const label = String(twin?.display_name || twin?.twin_id || "IT").trim();
  const words = label.split(/\s+/).filter(Boolean);
  if (!words.length) return "IT";
  if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
  return `${words[0][0] || ""}${words[1][0] || ""}`.toUpperCase();
}

function renderTwinAvatar(twin, className = "twin-avatar") {
  const label = twin?.display_name || twin?.twin_id || "Twin";
  const url = twinPictureUrl(twin);
  if (url) {
    const focusX = Number.isFinite(Number(twin?.picture_focus_x)) ? Number(twin.picture_focus_x) : 50;
    const focusY = Number.isFinite(Number(twin?.picture_focus_y)) ? Number(twin.picture_focus_y) : 50;
    return `<img class="${className}" src="${escapeHtml(url)}" alt="${escapeHtml(label)} picture" style="object-position: ${focusX}% ${focusY}%" />`;
  }
  return `<span class="${className} placeholder">${escapeHtml(twinInitials(twin))}</span>`;
}

function renderTwinPicturePreview(twin) {
  const preview = $("#twinPicturePreview");
  if (!preview) return;
  preview.innerHTML = renderTwinAvatar(twin, "twin-avatar preview");
}

function renderTwinCatalog(activity = []) {
  const target = $("#twinCatalog");
  if (!state.twins.length) {
    target.innerHTML = '<p class="empty">No twins registered yet.</p>';
    return;
  }
  target.innerHTML = state.twins
    .map((twin) => {
      const selected = twin.twin_id === state.selectedTwinId ? " selected" : "";
      const active = twin.twin_id === state.activeTwin ? '<span class="pill">active</span>' : "";
      const archived = twin.status === "archived" ? '<span class="pill muted-pill">archived</span>' : "";
      const completeness = Math.round((twin.profile_completeness || 0) * 100);
      return `
        <button class="twin-card${selected}" type="button" data-twin-id="${escapeHtml(twin.twin_id)}">
          ${renderTwinAvatar(twin)}
          <span>
            <strong>${escapeHtml(twin.display_name || twin.twin_id)}</strong>
            <small>${escapeHtml(twin.role_context || twin.purpose || "No role context yet")}</small>
            <small>${escapeHtml(twin.workstreams || "No workstreams captured yet")}</small>
          </span>
          <span class="twin-card-meta">
            ${active}${archived}
            <small>${completeness}% profile</small>
          </span>
        </button>
      `;
    })
    .join("");
  $$(".twin-card").forEach((button) => {
    button.addEventListener("click", () => {
      state.selectedTwinId = button.dataset.twinId;
      renderTwinCatalog(activity);
      fillTwinForm(state.selectedTwinId);
    });
  });
  $("#twinActivity").innerHTML = activity.length
    ? activity
        .map(
          (event) => `
            <div class="activity-item">
              <strong>${escapeHtml(event.action || "twin_event")}</strong>
              <span>${escapeHtml(event.twin_id || event.active_twin || "")}</span>
              <small>${escapeHtml(event.timestamp || "")}</small>
            </div>
          `,
        )
        .join("")
    : '<p class="empty">No twin lifecycle events yet.</p>';
  renderArchivedTwins();
}

function renderArchivedTwins() {
  const archived = state.twins.filter((twin) => twin.status === "archived");
  $("#archivedTwinList").innerHTML = archived.length
    ? archived
        .map(
          (twin) => `
            <article class="activity-row">
              <h3>${escapeHtml(twin.display_name || twin.twin_id)}</h3>
              <p>${escapeHtml(twin.role_context || twin.purpose || "Archived twin")}</p>
              <button class="secondary small archived-select" type="button" data-id="${escapeHtml(twin.twin_id)}">Review</button>
            </article>
          `,
        )
        .join("")
    : '<p class="empty">No archived twins.</p>';
  $$("#archivedTwinList .archived-select").forEach((button) => {
    button.addEventListener("click", () => {
      state.selectedTwinId = button.dataset.id;
      renderTwinCatalog(state.twinActivity);
      fillTwinForm(state.selectedTwinId);
    });
  });
}

function fillTwinForm(twinId) {
  const twin = state.twins.find((item) => item.twin_id === twinId);
  if (!twin) return;
  $("#twinDisplayName").value = twin.display_name || "";
  $("#twinOrganization").value = twin.organization || "";
  $("#twinDefaultLanguage").value = twin.default_language || "en";
  $("#twinRoleContext").value = twin.role_context || "";
  $("#twinTone").value = twin.tone || "";
  $("#twinWorkstreams").value = twin.workstreams || "";
  $("#twinStakeholders").value = twin.stakeholders || "";
  $("#twinRiskPosture").value = twin.risk_posture || "balanced";
  $("#twinPurpose").value = twin.purpose || "";
  $("#twinDecisionPrinciples").value = twin.decision_principles || "";
  $("#twinEscalationBoundaries").value = twin.escalation_boundaries || "";
  $("#twinSuccessMetrics").value = twin.success_metrics || "";
  $("#twinSourceIntakeNotes").value = twin.source_intake_notes || "";
  $("#twinVoiceProvider").value = twin.voice_provider || "openai";
  $("#twinVoiceId").value = twin.voice_id || "";
  $("#twinVoiceLabel").value = twin.voice_label || "";
  $("#twinVoiceInstructions").value = twin.voice_instructions || "";
  $("#twinVoiceConsentRef").value = twin.voice_consent_ref || "";
  $("#activateTwinBtn").disabled = twin.status !== "active" || twin.twin_id === state.activeTwin;
  $("#archiveTwinBtn").disabled = twin.status === "archived";
  $("#updateTwinBtn").disabled = twin.status === "archived";
  $("#restoreTwinBtn").disabled = twin.status !== "archived";
  $("#uploadTwinPictureBtn").disabled = twin.status === "archived";
  $("#removeTwinPictureBtn").disabled = twin.status === "archived" || !twin.picture_path;
  $("#saveTwinPicturePositionBtn").disabled = twin.status === "archived" || !twin.picture_path;
  $("#twinPictureFocusControls").classList.toggle("disabled", !twin.picture_path);
  $("#twinPictureFocusX").value = twin.picture_focus_x ?? 50;
  $("#twinPictureFocusY").value = twin.picture_focus_y ?? 50;
  $("#twinPictureInput").value = "";
  renderTwinPicturePreview(twin);
  renderTwinProfileCue(twin);
  renderDesignCockpitBoard();
}

function renderTwinProfileCue(twin) {
  const result = $("#twinResult");
  if (!result || result.textContent.trim() !== "No twin action yet.") return;
  const missing = setupProgressCategories(twin).filter((item) => !item.done);
  result.textContent = missing.length
    ? `Next setup cue: complete ${missing[0].label.toLowerCase()} to improve this twin's steering quality.`
    : "This twin profile is ready for skill work. Run a skill, ingest evidence, or review outcomes.";
}

function readTwinForm() {
  return {
    display_name: $("#twinDisplayName").value.trim(),
    organization: $("#twinOrganization").value.trim(),
    default_language: $("#twinDefaultLanguage").value.trim() || "en",
    role_context: $("#twinRoleContext").value.trim(),
    tone: $("#twinTone").value.trim(),
    workstreams: $("#twinWorkstreams").value.trim(),
    stakeholders: $("#twinStakeholders").value.trim(),
    risk_posture: $("#twinRiskPosture").value,
    purpose: $("#twinPurpose").value.trim(),
    decision_principles: $("#twinDecisionPrinciples").value.trim(),
    escalation_boundaries: $("#twinEscalationBoundaries").value.trim(),
    success_metrics: $("#twinSuccessMetrics").value.trim(),
    source_intake_notes: $("#twinSourceIntakeNotes").value.trim(),
    voice_provider: $("#twinVoiceProvider").value.trim() || "openai",
    voice_id: $("#twinVoiceId").value.trim(),
    voice_label: $("#twinVoiceLabel").value.trim(),
    voice_instructions: $("#twinVoiceInstructions").value.trim(),
    voice_consent_ref: $("#twinVoiceConsentRef").value.trim(),
    actor: "local-user",
  };
}

function updateLandingStatus() {
  // Landing stays intentionally static and quiet; workspace context appears after entry.
}

function setupProgressCategories(twin) {
  return [
    { label: "Identity", done: Boolean(twin.display_name && twin.purpose) },
    { label: "Context", done: Boolean(twin.role_context && twin.workstreams) },
    { label: "Style", done: Boolean(twin.tone && twin.risk_posture) },
    { label: "Boundaries", done: Boolean(twin.decision_principles && twin.escalation_boundaries) },
    { label: "Sources", done: Boolean(twin.source_intake_notes) },
  ];
}

function renderTwinContextNotices() {
  const active = state.twins.find((twin) => twin.twin_id === state.activeTwin);
  const label = active?.display_name || state.activeTwin;
  const warning = recentTwinSwitchWarning();
  const text = `Active twin: ${label}. New sources, concepts, traces, and skill runs are scoped to this twin.${warning ? ` ${warning}` : ""}`;
  ["#voiceTwinNotice", "#ingestTwinNotice", "#conceptTwinNotice"].forEach((selector) => {
    const node = $(selector);
    if (node) node.textContent = text;
  });
}

function markTwinSwitch(previousTwinId) {
  if (!previousTwinId) return;
  state.previousTwinId = previousTwinId;
  state.lastTwinSwitchAt = Date.now();
}

function recentTwinSwitchWarning() {
  if (!state.previousTwinId || !state.lastTwinSwitchAt || state.previousTwinId === state.activeTwin) return "";
  if (Date.now() - state.lastTwinSwitchAt > 10 * 60 * 1000) return "";
  const previous = state.twins.find((twin) => twin.twin_id === state.previousTwinId);
  const current = state.twins.find((twin) => twin.twin_id === state.activeTwin);
  const previousLabel = previous?.display_name || state.previousTwinId;
  const currentLabel = current?.display_name || state.activeTwin;
  return `Twin changed from ${previousLabel} to ${currentLabel}. Check scope before ingesting sources or running skills.`;
}

async function confirmTwinScopedAction(actionLabel) {
  const warning = recentTwinSwitchWarning();
  if (!warning) return true;
  return requestDecision({
    eyebrow: "Twin context",
    title: "Continue with active twin?",
    body: `${warning}\n\nContinue to ${actionLabel} for the active twin?`,
    confirmLabel: "Continue",
  });
}

function renderWorkspaceIntro() {
  const active = state.twins.find((twin) => twin.twin_id === state.activeTwin);
  if (!active) return;
  const workstreams = active.workstreams || "No workstreams captured yet.";
  const boundaries = active.escalation_boundaries || "Human approval required for external action.";
  $("#chatWorkspaceIntro").innerHTML = `
    <details class="workspace-context">
      <summary>
        <span class="active-twin-summary">
          ${renderTwinAvatar(active, "twin-avatar")}
          <span>
            <span class="badge">Active twin</span>
            <strong>${escapeHtml(active.display_name || active.twin_id)}</strong>
          </span>
        </span>
        <span class="workspace-context-line">${escapeHtml(active.purpose || active.role_context || "Grounded assistant workspace")}</span>
      </summary>
      <div class="workspace-context-grid">
        <div>
          <span>Workstreams</span>
          <p>${escapeHtml(workstreams)}</p>
        </div>
        <div>
          <span>Boundaries</span>
          <p>${escapeHtml(boundaries)}</p>
        </div>
        ${renderLatestSkillRunShortcut()}
      </div>
    </details>
  `;
}

function renderLatestSkillRunShortcut() {
  const latest = latestSkillRunForActiveTwin();
  if (!latest) {
    return `
      <div class="continue-card muted">
        <span>Recent artifact</span>
        <strong>No skill run yet</strong>
        <p>Choose a skill in Chat to create the first reusable work artifact.</p>
      </div>
    `;
  }
  const readiness = sourceReadiness(latest.inputs || {});
  return `
    <div class="continue-card">
      <span>Recent artifact</span>
      <strong>${escapeHtml(latest.skill_name || latest.skill_id || "Skill run")}</strong>
      <p>${escapeHtml(formatShortDate(latest.created_at))} · ${escapeHtml(latest.review_state || "unreviewed")} · ${escapeHtml(readiness.label)}</p>
      <button class="small secondary" type="button" data-chat-action="continue-run" data-run-id="${escapeHtml(latest.run_id || "")}">Continue</button>
    </div>
  `;
}

function latestSkillRunForActiveTwin() {
  return [...state.skillRuns]
    .filter((run) => !run.twin || run.twin === state.activeTwin)
    .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")))[0] || null;
}

function renderSetupStepDetail() {
  const selected = state.twins.find((twin) => twin.twin_id === state.selectedTwinId);
  const detail = setupStepDetails(selected || {});
  const validation = setupStepValidation(state.activeSetupStep);
  $$(".setup-step").forEach((button) => button.classList.toggle("active", button.dataset.step === state.activeSetupStep));
  $("#setupStepDetail").innerHTML = `
    <strong>${escapeHtml(detail.title)}</strong>
    <p>${escapeHtml(detail.description)}</p>
    <span>${escapeHtml(detail.status)}</span>
    ${renderSetupValidation(validation)}
    <div class="setup-step-actions">
      <button id="setupFocusBtn" class="small secondary" type="button">Focus fields</button>
      <button id="setupSaveBtn" class="small" type="button">Save step</button>
    </div>
  `;
  $("#setupFocusBtn")?.addEventListener("click", () => focusSetupStep(state.activeSetupStep));
  $("#setupSaveBtn")?.addEventListener("click", updateSelectedTwin);
  markSetupFields(validation);
}

function renderDesignCockpitBoard() {
  const target = $("#designCockpitBoard");
  if (!target) return;
  const selected = state.twins.find((twin) => twin.twin_id === state.selectedTwinId) || {};
  const label = $("#twinDisplayName")?.value?.trim() || selected.display_name || selected.twin_id || "New twin";
  const completeness = Math.round((selected.profile_completeness || 0) * 100);
  const isActive = selected.twin_id && selected.twin_id === state.activeTwin;
  const activeLabel = isActive ? "Active actor" : "Draft actor";
  const cards = designCockpitCards(selected);
  const readyCount = cards.filter((card) => card.ready).length;
  target.innerHTML = `
    <div class="design-cockpit-hero">
      <div>
        <span class="badge">Design Cockpit</span>
        <h2>${escapeHtml(label)} steering model</h2>
        <p>Shape the human context the Actor Twin uses before skills execute work or produce artifacts.</p>
      </div>
      <div class="design-cockpit-summary">
        <span><strong>${escapeHtml(activeLabel)}</strong>${escapeHtml(`${readyCount}/${cards.length} setup domains ready`)}</span>
        <span><strong>${escapeHtml(`${completeness}%`)}</strong>profile completeness</span>
      </div>
    </div>
    <div class="design-cockpit-grid">
      ${cards.map((card) => `
        <button class="design-cockpit-card ${card.ready ? "ready" : "open"}" type="button" data-design-focus="${escapeHtml(card.focus)}" data-step="${escapeHtml(card.step)}">
          <span>${escapeHtml(card.index)}</span>
          <strong>${escapeHtml(card.title)}</strong>
          <small>${escapeHtml(card.description)}</small>
          <em>${escapeHtml(card.ready ? "Ready" : "Needs input")}</em>
        </button>
      `).join("")}
    </div>
  `;
}

function designCockpitCards(twin) {
  const value = (selector, fallback = "") => String($(selector)?.value || fallback || "").trim();
  return [
    {
      index: "01",
      step: "identity",
      title: "Identity",
      description: "Name, purpose, organization, and default language.",
      ready: Boolean(value("#twinDisplayName", twin.display_name) && value("#twinPurpose", twin.purpose)),
      focus: "#twinDisplayName",
    },
    {
      index: "02",
      step: "context",
      title: "Work context",
      description: "Role, workstreams, stakeholders, and repeated duties.",
      ready: Boolean(value("#twinRoleContext", twin.role_context) && value("#twinWorkstreams", twin.workstreams)),
      focus: "#twinRoleContext",
    },
    {
      index: "03",
      step: "style",
      title: "Voice and judgment",
      description: "Tone, decision principles, and risk posture.",
      ready: Boolean(value("#twinTone", twin.tone) && value("#twinDecisionPrinciples", twin.decision_principles)),
      focus: "#twinTone",
    },
    {
      index: "04",
      step: "style",
      title: "Boundaries",
      description: "Escalation rules for external actions and irreversible decisions.",
      ready: Boolean(value("#twinEscalationBoundaries", twin.escalation_boundaries)),
      focus: "#twinEscalationBoundaries",
    },
    {
      index: "05",
      step: "sources",
      title: "Source intake",
      description: "Preferred evidence exports, source habits, and update cadence.",
      ready: Boolean(value("#twinSourceIntakeNotes", twin.source_intake_notes)),
      focus: "#twinSourceIntakeNotes",
    },
  ];
}

function handleDesignCockpitBoardClick(event) {
  const button = event.target.closest("[data-design-focus]");
  if (!button) return;
  state.activeSetupStep = button.dataset.step || state.activeSetupStep || "identity";
  renderSetupStepDetail();
  const node = $(button.dataset.designFocus);
  if (!node) return;
  node.scrollIntoView({ block: "center", behavior: "smooth" });
  if (typeof node.focus === "function") node.focus();
}

function focusSetupStep(step) {
  const selectorByStep = {
    identity: "#twinDisplayName",
    context: "#twinRoleContext",
    style: "#twinTone",
    sources: "#twinSourceIntakeNotes",
    activate: "#activateTwinBtn",
  };
  const node = $(selectorByStep[step] || "#twinDisplayName");
  if (!node) return;
  node.scrollIntoView({ block: "center", behavior: "smooth" });
  if (typeof node.focus === "function") node.focus();
}

function twinProfileFieldIds() {
  return [
    "twinDisplayName",
    "twinOrganization",
    "twinDefaultLanguage",
    "twinRoleContext",
    "twinTone",
    "twinWorkstreams",
    "twinStakeholders",
    "twinRiskPosture",
    "twinPurpose",
    "twinDecisionPrinciples",
    "twinEscalationBoundaries",
    "twinSuccessMetrics",
    "twinSourceIntakeNotes",
  ];
}

function setupStepValidation(step) {
  const checks = {
    identity: [
      { id: "twinDisplayName", label: "Name", done: Boolean($("#twinDisplayName").value.trim()) },
      { id: "twinPurpose", label: "Purpose", done: Boolean($("#twinPurpose").value.trim()) },
      { id: "twinDefaultLanguage", label: "Default language", done: Boolean($("#twinDefaultLanguage").value.trim()) },
    ],
    context: [
      { id: "twinRoleContext", label: "Role context", done: Boolean($("#twinRoleContext").value.trim()) },
      { id: "twinWorkstreams", label: "Workstreams", done: Boolean($("#twinWorkstreams").value.trim()) },
      { id: "twinStakeholders", label: "Stakeholders", done: Boolean($("#twinStakeholders").value.trim()) },
    ],
    style: [
      { id: "twinTone", label: "Tone", done: Boolean($("#twinTone").value.trim()) },
      { id: "twinRiskPosture", label: "Risk posture", done: Boolean($("#twinRiskPosture").value.trim()) },
      { id: "twinDecisionPrinciples", label: "Decision principles", done: Boolean($("#twinDecisionPrinciples").value.trim()) },
      { id: "twinEscalationBoundaries", label: "Escalation boundaries", done: Boolean($("#twinEscalationBoundaries").value.trim()) },
    ],
    sources: [
      { id: "twinSourceIntakeNotes", label: "Source intake notes", done: Boolean($("#twinSourceIntakeNotes").value.trim()) },
      { id: "twinSuccessMetrics", label: "Success metrics", done: Boolean($("#twinSuccessMetrics").value.trim()) },
    ],
    activate: [
      { id: "activateTwinBtn", label: "Selected twin is active", done: state.selectedTwinId === state.activeTwin },
      { id: "twinEscalationBoundaries", label: "Approval boundaries captured", done: Boolean($("#twinEscalationBoundaries").value.trim()) },
      { id: "twinSourceIntakeNotes", label: "Source intake captured", done: Boolean($("#twinSourceIntakeNotes").value.trim()) },
    ],
  };
  return checks[step] || checks.identity;
}

function renderSetupValidation(items) {
  return `
    <div class="setup-validation">
      ${items.map((item) => `<span class="${item.done ? "ready" : "open"}">${escapeHtml(item.done ? "Ready" : "Open")}: ${escapeHtml(item.label)}</span>`).join("")}
    </div>
  `;
}

function markSetupFields(items) {
  twinProfileFieldIds().forEach((fieldId) => $(`#${fieldId}`)?.classList.remove("field-open", "field-ready"));
  items.forEach((item) => {
    const node = $(`#${item.id}`);
    if (node && node.tagName !== "BUTTON") node.classList.add(item.done ? "field-ready" : "field-open");
  });
}

function setupStepDetails(twin) {
  const details = {
    identity: {
      title: "Name and purpose",
      description: "Clarify who this twin represents and what work it should support.",
      status: twin.display_name && twin.purpose ? "Ready" : "Add name and purpose.",
    },
    context: {
      title: "Role and work context",
      description: "Capture responsibilities, workstreams, stakeholders, and repeated duties.",
      status: twin.role_context && twin.workstreams ? "Ready" : "Add role context and workstreams.",
    },
    style: {
      title: "Tone and risk posture",
      description: "Define how the Actor Twin should steer communication and decisions.",
      status: twin.tone && twin.risk_posture ? "Ready" : "Add tone and risk posture.",
    },
    sources: {
      title: "Source intake",
      description: "Document preferred source formats and ingestion habits for this twin.",
      status: twin.source_intake_notes ? "Ready" : "Add source intake notes.",
    },
    activate: {
      title: "Activate and start learning",
      description: "Select this twin, ingest sources, run skills, and review outcomes.",
      status: twin.twin_id === state.activeTwin ? "Active now" : "Set this twin active when ready.",
    },
  };
  return details[state.activeSetupStep] || details.identity;
}

async function createTwin() {
  try {
    if (staticPagesMode) {
      const form = readTwinForm();
      const existingIds = new Set(state.twins.map((twin) => twin.twin_id));
      let twinId = staticTwinSlug(form.display_name);
      let suffix = 2;
      while (existingIds.has(twinId)) {
        twinId = `${staticTwinSlug(form.display_name)}-${suffix}`;
        suffix += 1;
      }
      const twin = normalizeStaticTwin({ ...form, twin_id: twinId, status: "active" });
      state.twins = [twin, ...state.twins];
      state.selectedTwinId = twin.twin_id;
      appendStaticTwinActivity("created", twin.twin_id, "Created in GitHub Pages local registry.");
      writeStaticTwinStore(state.twins, state.activeTwin, state.twinActivity);
      $("#twinResult").textContent = JSON.stringify({ status: "created_local", twin }, null, 2);
      await refreshTwins();
      showToast("Twin created locally", twin.display_name || twin.twin_id, "success");
      return;
    }
    const result = await postJson("/api/twins", readTwinForm());
    state.selectedTwinId = result.twin?.twin_id || result.active_twin;
    $("#twinResult").textContent = JSON.stringify(result, null, 2);
    await refreshAll();
    showToast("Twin created", result.twin?.display_name || state.selectedTwinId, "success");
  } catch (error) {
    $("#twinResult").textContent = `Create twin failed: ${error.message}`;
    showToast("Create twin failed", error.message, "error");
  }
}

async function updateSelectedTwin() {
  if (!state.selectedTwinId) return;
  try {
    if (staticPagesMode) {
      const index = state.twins.findIndex((twin) => twin.twin_id === state.selectedTwinId);
      if (index === -1) throw new Error("Selected twin is not available in the local registry.");
      const updated = normalizeStaticTwin(readTwinForm(), state.twins[index]);
      state.twins[index] = updated;
      appendStaticTwinActivity("updated", updated.twin_id, "Updated in GitHub Pages local registry.");
      writeStaticTwinStore(state.twins, state.activeTwin, state.twinActivity);
      $("#twinResult").textContent = JSON.stringify({ status: "updated_local", twin: updated }, null, 2);
      await refreshTwins();
      showToast("Twin updated locally", updated.display_name || updated.twin_id, "success");
      return;
    }
    const result = await postJson("/api/twins/update", {
      twin_id: state.selectedTwinId,
      ...readTwinForm(),
    });
    $("#twinResult").textContent = JSON.stringify(result, null, 2);
    await safeRefreshTwins();
    showToast("Twin updated", result.twin?.display_name || state.selectedTwinId, "success");
  } catch (error) {
    $("#twinResult").textContent = `Update twin failed: ${error.message}`;
    showToast("Update twin failed", error.message, "error");
  }
}

async function activateSelectedTwin() {
  if (!state.selectedTwinId) return;
  try {
    if (staticPagesMode) {
      const selected = state.twins.find((twin) => twin.twin_id === state.selectedTwinId);
      if (!selected || selected.status !== "active") throw new Error("Only active twins can be selected.");
      markTwinSwitch(state.activeTwin);
      state.activeTwin = state.selectedTwinId;
      appendStaticTwinActivity("activated", state.activeTwin, "Activated in GitHub Pages local registry.");
      writeStaticTwinStore(state.twins, state.activeTwin, state.twinActivity);
      $("#twinResult").textContent = JSON.stringify({ status: "activated_local", active_twin: state.activeTwin }, null, 2);
      await refreshStaticPagesWorkspace();
      showToast("Active twin switched locally", state.activeTwin, "success");
      return;
    }
    markTwinSwitch(state.activeTwin);
    const result = await postJson("/api/twins/active", { twin_id: state.selectedTwinId, actor: "local-user" });
    $("#twinResult").textContent = JSON.stringify(result, null, 2);
    await refreshAll();
    showToast("Active twin switched", state.selectedTwinId, "success");
  } catch (error) {
    $("#twinResult").textContent = `Activate twin failed: ${error.message}`;
    showToast("Activate twin failed", error.message, "error");
  }
}

async function archiveSelectedTwin() {
  if (!state.selectedTwinId) return;
  const twin = state.twins.find((item) => item.twin_id === state.selectedTwinId);
  const label = twin?.display_name || state.selectedTwinId;
  const confirmed = await requestDecision({
    eyebrow: "Twin archive",
    title: `Archive ${label}?`,
    body: "Knowledge and logs stay on disk, but this twin will leave the active workspace.",
    confirmLabel: "Archive twin",
    danger: true,
  });
  if (!confirmed) {
    return;
  }
  try {
    if (staticPagesMode) {
      const index = state.twins.findIndex((item) => item.twin_id === state.selectedTwinId);
      if (index === -1) throw new Error("Selected twin is not available in the local registry.");
      state.twins[index] = normalizeStaticTwin({ status: "archived" }, state.twins[index]);
      appendStaticTwinActivity("archived", state.selectedTwinId, $("#twinArchiveRationale").value.trim() || "Archived from Twins cockpit.");
      if (state.activeTwin === state.selectedTwinId) {
        state.activeTwin = state.twins.find((item) => item.status === "active")?.twin_id || state.twins[index].twin_id;
      }
      state.selectedTwinId = state.activeTwin;
      writeStaticTwinStore(state.twins, state.activeTwin, state.twinActivity);
      $("#twinResult").textContent = JSON.stringify({ status: "archived_local", active_twin: state.activeTwin }, null, 2);
      await refreshTwins();
      showToast("Twin archived locally", label, "success");
      return;
    }
    const result = await postJson("/api/twins/archive", {
      twin_id: state.selectedTwinId,
      actor: "local-user",
      rationale: $("#twinArchiveRationale").value.trim() || "Archived from Twins cockpit.",
    });
    state.selectedTwinId = result.active_twin || state.activeTwin;
    $("#twinResult").textContent = JSON.stringify(result, null, 2);
    await refreshAll();
    showToast("Twin archived", label, "success");
  } catch (error) {
    $("#twinResult").textContent = `Archive twin failed: ${error.message}`;
    showToast("Archive twin failed", error.message, "error");
  }
}

async function restoreSelectedTwin() {
  if (!state.selectedTwinId) return;
  try {
    if (staticPagesMode) {
      const index = state.twins.findIndex((item) => item.twin_id === state.selectedTwinId);
      if (index === -1) throw new Error("Selected twin is not available in the local registry.");
      state.twins[index] = normalizeStaticTwin({ status: "active" }, state.twins[index]);
      appendStaticTwinActivity("restored", state.selectedTwinId, "Restored in GitHub Pages local registry.");
      writeStaticTwinStore(state.twins, state.activeTwin, state.twinActivity);
      $("#twinResult").textContent = JSON.stringify({ status: "restored_local", twin: state.twins[index] }, null, 2);
      await refreshTwins();
      showToast("Twin restored locally", state.selectedTwinId, "success");
      return;
    }
    const result = await postJson("/api/twins/restore", { twin_id: state.selectedTwinId, actor: "local-user" });
    state.selectedTwinId = result.active_twin || state.selectedTwinId;
    $("#twinResult").textContent = JSON.stringify(result, null, 2);
    await refreshAll();
    showToast("Twin restored", state.selectedTwinId, "success");
  } catch (error) {
    $("#twinResult").textContent = `Restore twin failed: ${error.message}`;
    showToast("Restore twin failed", error.message, "error");
  }
}

function previewSelectedTwinPicture() {
  const file = $("#twinPictureInput").files[0];
  if (!file) {
    renderTwinPicturePreview(state.twins.find((item) => item.twin_id === state.selectedTwinId));
    return;
  }
  if (!file.type.startsWith("image/")) {
    $("#twinResult").textContent = "Choose a PNG, JPG, WebP, or GIF image.";
    $("#twinPictureInput").value = "";
    return;
  }
  if (state.twinPicturePreviewUrl) URL.revokeObjectURL(state.twinPicturePreviewUrl);
  state.twinPicturePreviewUrl = URL.createObjectURL(file);
  $("#twinPicturePreview").innerHTML = `<img class="twin-avatar preview" src="${state.twinPicturePreviewUrl}" alt="Selected twin picture preview" />`;
}

function renderSelectedTwinPictureFocusPreview() {
  const previewImage = $("#twinPicturePreview img");
  if (!previewImage) return;
  previewImage.style.objectPosition = `${$("#twinPictureFocusX").value}% ${$("#twinPictureFocusY").value}%`;
}

function readFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(reader.error || new Error("Could not read selected image."));
    reader.readAsDataURL(file);
  });
}

async function uploadTwinPicture() {
  if (!state.selectedTwinId) return;
  const file = $("#twinPictureInput").files[0];
  if (!file) {
    $("#twinResult").textContent = "Choose a picture first.";
    return;
  }
  const form = new FormData();
  form.append("twin_id", state.selectedTwinId);
  form.append("actor", "local-user");
  form.append("file", file);
  $("#twinResult").textContent = `Uploading picture for ${state.selectedTwinId}...`;
  try {
    if (staticPagesMode) {
      if (file.size > 1_200_000) {
        throw new Error("Static Pages can store small profile pictures only. Choose an image under 1.2 MB or use the hosted backend.");
      }
      const index = state.twins.findIndex((item) => item.twin_id === state.selectedTwinId);
      if (index === -1) throw new Error("Selected twin is not available in the local registry.");
      const dataUrl = await readFileAsDataUrl(file);
      state.twins[index] = normalizeStaticTwin(
        {
          picture_path: dataUrl,
          picture_uploaded_at: new Date().toISOString(),
          picture_focus_x: Number($("#twinPictureFocusX").value) || 50,
          picture_focus_y: Number($("#twinPictureFocusY").value) || 50,
        },
        state.twins[index],
      );
      appendStaticTwinActivity("picture_updated", state.selectedTwinId, "Profile picture stored in browser local registry.");
      writeStaticTwinStore(state.twins, state.activeTwin, state.twinActivity);
      $("#twinResult").textContent = JSON.stringify({ status: "picture_updated_local", twin_id: state.selectedTwinId }, null, 2);
      if (state.twinPicturePreviewUrl) {
        URL.revokeObjectURL(state.twinPicturePreviewUrl);
        state.twinPicturePreviewUrl = "";
      }
      await refreshTwins();
      showToast("Twin picture stored locally", state.selectedTwinId, "success");
      return;
    }
    const result = await postForm("/api/twins/picture", form);
    $("#twinResult").textContent = JSON.stringify(result, null, 2);
    if (state.twinPicturePreviewUrl) {
      URL.revokeObjectURL(state.twinPicturePreviewUrl);
      state.twinPicturePreviewUrl = "";
    }
    await safeRefreshTwins();
    showToast("Twin picture updated", state.selectedTwinId, "success");
  } catch (error) {
    $("#twinResult").textContent = `Upload picture failed: ${error.message}`;
    showToast("Upload picture failed", error.message, "error");
  }
}

async function removeTwinPicture() {
  if (!state.selectedTwinId) return;
  const twin = state.twins.find((item) => item.twin_id === state.selectedTwinId);
  if (!twin?.picture_path) {
    $("#twinResult").textContent = "This twin has no picture to remove.";
    return;
  }
  const label = twin.display_name || state.selectedTwinId;
  const confirmed = await requestDecision({
    eyebrow: "Twin picture",
    title: `Remove picture for ${label}?`,
    body: "The twin profile will keep all other information.",
    confirmLabel: "Remove picture",
    danger: true,
  });
  if (!confirmed) return;
  try {
    if (staticPagesMode) {
      const index = state.twins.findIndex((item) => item.twin_id === state.selectedTwinId);
      if (index === -1) throw new Error("Selected twin is not available in the local registry.");
      state.twins[index] = normalizeStaticTwin(
        {
          picture_path: "",
          picture_uploaded_at: "",
          picture_focus_x: 50,
          picture_focus_y: 50,
        },
        state.twins[index],
      );
      appendStaticTwinActivity("picture_removed", state.selectedTwinId, "Profile picture removed from browser local registry.");
      writeStaticTwinStore(state.twins, state.activeTwin, state.twinActivity);
      $("#twinResult").textContent = JSON.stringify({ status: "picture_removed_local", twin_id: state.selectedTwinId }, null, 2);
      await refreshTwins();
      showToast("Twin picture removed locally", label, "success");
      return;
    }
    const result = await deleteJson("/api/twins/picture", { twin_id: state.selectedTwinId, actor: "local-user" });
    $("#twinResult").textContent = JSON.stringify(result, null, 2);
    await safeRefreshTwins();
    showToast("Twin picture removed", label, "success");
  } catch (error) {
    $("#twinResult").textContent = `Remove picture failed: ${error.message}`;
    showToast("Remove picture failed", error.message, "error");
  }
}

async function saveTwinPicturePosition() {
  if (!state.selectedTwinId) return;
  try {
    if (staticPagesMode) {
      const index = state.twins.findIndex((item) => item.twin_id === state.selectedTwinId);
      if (index === -1) throw new Error("Selected twin is not available in the local registry.");
      state.twins[index] = normalizeStaticTwin(
        {
          picture_focus_x: Number($("#twinPictureFocusX").value),
          picture_focus_y: Number($("#twinPictureFocusY").value),
        },
        state.twins[index],
      );
      appendStaticTwinActivity("picture_focus_updated", state.selectedTwinId, "Profile picture focus stored in browser local registry.");
      writeStaticTwinStore(state.twins, state.activeTwin, state.twinActivity);
      $("#twinResult").textContent = JSON.stringify({ status: "picture_focus_updated_local", twin_id: state.selectedTwinId }, null, 2);
      await refreshTwins();
      showToast("Picture focus saved locally", state.selectedTwinId, "success");
      return;
    }
    const result = await postJson("/api/twins/picture/position", {
      twin_id: state.selectedTwinId,
      focus_x: Number($("#twinPictureFocusX").value),
      focus_y: Number($("#twinPictureFocusY").value),
      actor: "local-user",
    });
    $("#twinResult").textContent = JSON.stringify(result, null, 2);
    await safeRefreshTwins();
    showToast("Picture focus saved", state.selectedTwinId, "success");
  } catch (error) {
    $("#twinResult").textContent = `Save picture focus failed: ${error.message}`;
    showToast("Save picture focus failed", error.message, "error");
  }
}

function bindSkills() {
  $("#elicitSkillBtn").addEventListener("click", elicitSkill);
  $("#decomposeSkillBtn").addEventListener("click", decomposeSelectedSkill);
  $("#approveSkillBtn").addEventListener("click", () => approveSelectedSkill("approve"));
  $("#rejectSkillBtn").addEventListener("click", () => approveSelectedSkill("reject"));
  $("#runSkillBtn").addEventListener("click", runSelectedSkill);
  $("#refreshSkillRunsBtn").addEventListener("click", safeRefreshSkillRuns);
  $("#refreshSkillRefinementsBtn").addEventListener("click", safeRefreshSkillRefinements);
  $("#compareRunsBtn").addEventListener("click", renderSelectedRunComparison);
  $("#runQualityFilter").addEventListener("change", (event) => {
    state.skillRunQualityFilter = event.target.value;
    renderSkillRunHistory();
  });
}

async function refreshReviewDashboard() {
  setDashboardLoading();
  const result = await getJson(`/api/review-dashboard?twin=${encodeURIComponent(state.activeTwin)}&limit=8`);
  state.reviewDashboard = result;
  result.refreshed_at = new Date().toISOString();
  renderReviewDashboard(result);
}

async function safeRefreshReviewDashboard() {
  if (staticPagesMode) {
    const result = buildStaticPagesReviewDashboard();
    state.reviewDashboard = result;
    result.refreshed_at = new Date().toISOString();
    renderReviewDashboard(result);
    return;
  }
  try {
    await refreshReviewDashboard();
  } catch (error) {
    $("#dashConceptStates").textContent = "Dashboard endpoint unavailable. Restart the local MVP server.";
    ["#dashPendingConcepts", "#dashReworkConcepts", "#dashRejectedConcepts", "#dashLatestTraces", "#dashAgentTraceHistory", "#dashGraphPromotionHistory", "#dashOkfGraphPackage", "#dashKnowledgeGraphHandoff", "#dashSkillQueue", "#dashRefinementQueue", "#dashVoiceProofChain", "#dashMcpQueue", "#dashActions"].forEach((selector) => {
      const node = $(selector);
      if (node) node.innerHTML = renderErrorState("Dashboard unavailable");
    });
    console.warn("Review dashboard refresh failed", error);
  }
}

function setDashboardLoading() {
  $("#cockpitOverview").innerHTML = '<div class="skeleton-block"></div><div class="skeleton-block"></div>';
  ["#dashPendingConcepts", "#dashReworkConcepts", "#dashRejectedConcepts", "#dashLatestTraces", "#dashAgentTraceHistory", "#dashGraphPromotionHistory", "#dashOkfGraphPackage", "#dashKnowledgeGraphHandoff", "#dashSkillQueue", "#dashRefinementQueue", "#dashVoiceProofChain", "#dashMcpQueue", "#dashActions"].forEach((selector) => {
    const node = $(selector);
    if (node) node.innerHTML = renderLoadingState("Loading cockpit data");
  });
}

function setSkillCatalogLoading() {
  const node = $("#skillCatalog");
  if (node) node.innerHTML = renderLoadingState("Loading skills");
}

function setSkillRunsLoading() {
  const node = $("#skillRunHistory");
  if (node) node.innerHTML = renderLoadingState("Loading skill runs");
}

function setSkillRefinementsLoading() {
  const node = $("#skillRefinements");
  if (node) node.innerHTML = renderLoadingState("Loading refinement proposals");
}

function setUpdatedStamp(selector, value = new Date()) {
  const node = $(selector);
  if (!node) return;
  node.textContent = `Updated ${formatShortDate(value.toISOString())}`;
}

function renderReviewDashboard(result) {
  const concept = result.concept_review || {};
  const trace = result.trace_review || {};
  const persona = result.persona_quality || {};
  renderCockpitOverview(result);
  renderDashboardFilterCounts(result);
  renderDashboardInsights(result);
  renderDashboardClusterScope(result);
  renderDashboardTraceScope(result);
  $("#dashConceptTotal").textContent = concept.total ?? 0;
  $("#dashConceptStates").textContent = formatInlineCounts(concept.states || {});
  $("#dashTraceTotal").textContent = trace.total ?? 0;
  $("#dashTraceStates").textContent = formatInlineCounts(trace.states || {});
  $("#dashPersonaScore").textContent = persona.score === undefined ? "-" : persona.score;
  $("#dashPersonaStatus").textContent = persona.status || "No report yet";
  $("#dashSkillTotal").textContent = result.skills?.total ?? 0;
  $("#dashSkillStates").textContent = formatInlineCounts(result.skills?.states || {});
  $("#dashRefinementTotal").textContent = result.skills?.refinements?.total ?? 0;
  $("#dashRefinementStates").textContent = formatInlineCounts(result.skills?.refinements?.states || {});
  renderDashboardConcepts("#dashPendingConcepts", concept.pending || [], "No pending concepts.");
  renderDashboardVoiceConcepts(concept.voice_created || []);
  renderDashboardConcepts("#dashReworkConcepts", concept.needs_rework || [], "No concepts need rework.");
  renderDashboardConcepts("#dashRejectedConcepts", concept.rejected || [], "No rejected concepts.");
  renderDashboardEvidenceStateGaps(result);
  renderDashboardTraces(trace.latest || []);
  renderDashboardAgentTraceHistory();
  renderDashboardGraphDecisionQueue();
  renderDashboardGraphPromotionHistory();
  renderDashboardOkfGraphPackage();
  renderDashboardKnowledgeGraphHandoff();
  renderDashboardSkillQueue(result.skills?.pending_approval || []);
  renderDashboardRefinementQueue(result.skills?.refinements || {}, result.skills?.runs || {});
  renderDashboardVoiceProofChain(result.mcp_tool_calls?.voice_proof_chain || {});
  renderDashboardMcpQueue(result.mcp_tool_calls || {});
  renderDashboardActions(result.actions || []);
  renderDashboardFilter();
}

function renderDashboardInsights(result) {
  const maturity = dashboardMaturityScores(result);
  renderMaturityRadar(maturity);
  renderConfidenceBands(result.trace_review?.latest || []);
  renderTraceScatter(result.trace_review?.latest || []);
  renderTraceQualityQuadrants(result.trace_review?.latest || []);
  renderUsageBars(result, maturity);
  renderClusterHealth(result.concept_review?.cluster_health || []);
  renderSkillOutcomeMatrix(result.skills?.runs || {});
  renderDecisionBoundaryHeatmap(result);
}

function renderDashboardClusterScope(result = state.reviewDashboard || {}) {
  const target = $("#dashboardClusterScope");
  if (!target) return;
  const cluster = state.dashboardClusterFilter || "";
  if (!cluster) {
    target.hidden = true;
    target.innerHTML = "";
    return;
  }
  const concepts = dashboardAllConcepts(result.concept_review || {}).filter((concept) => dashboardConceptMatchesCluster(concept, cluster));
  const pending = concepts.filter((concept) => String(concept.review_state || "").includes("pending")).length;
  const weak = concepts.filter((concept) => Number(concept.confidence || 0) < 70).length;
  target.hidden = false;
  target.innerHTML = `
    <div>
      <span class="badge">Cluster scope</span>
      <strong>${escapeHtml(cluster)}</strong>
      <small>${escapeHtml(concepts.length)} visible concept${concepts.length === 1 ? "" : "s"} · ${escapeHtml(pending)} pending · ${escapeHtml(weak)} low-confidence</small>
    </div>
    <div class="dashboard-scope-actions">
      <button class="secondary small" type="button" id="copyDashboardClusterPacketBtn">Copy cleanup packet</button>
      <button class="secondary small" type="button" id="openDashboardClusterKnowledgeBtn">Open in Knowledge Browser</button>
      <button class="secondary small" type="button" id="clearDashboardClusterBtn">Clear cluster</button>
    </div>
  `;
  $("#clearDashboardClusterBtn")?.addEventListener("click", () => {
    state.dashboardClusterFilter = "";
    renderReviewDashboard(state.reviewDashboard || {});
  });
  $("#openDashboardClusterKnowledgeBtn")?.addEventListener("click", () => {
    const search = $("#conceptSearch");
    if (search) search.value = cluster;
    showView("concepts");
    renderConcepts();
  });
  $("#copyDashboardClusterPacketBtn")?.addEventListener("click", () => copyDashboardClusterPacket(cluster, concepts));
}

function renderDashboardTraceScope(result = state.reviewDashboard || {}) {
  const target = $("#dashboardTraceScope");
  if (!target) return;
  const quadrant = state.dashboardTraceQuadrant || "";
  if (!quadrant) {
    target.hidden = true;
    target.innerHTML = "";
    return;
  }
  const traces = (result.trace_review?.latest || []).filter((trace) => traceQuadrant(trace) === quadrant);
  target.hidden = false;
  target.innerHTML = `
    <div>
      <span class="badge">Trace scope</span>
      <strong>${escapeHtml(traceQuadrantLabel(quadrant))}</strong>
      <small>${escapeHtml(traces.length)} trace${traces.length === 1 ? "" : "s"} in this quality quadrant</small>
    </div>
    <div class="dashboard-scope-actions">
      <button class="secondary small" type="button" id="clearDashboardTraceScopeBtn">Clear trace scope</button>
    </div>
  `;
  $("#clearDashboardTraceScopeBtn")?.addEventListener("click", () => {
    state.dashboardTraceQuadrant = "";
    renderReviewDashboard(state.reviewDashboard || {});
  });
}

function dashboardMaturityScores(result) {
  const concept = result.concept_review || {};
  const trace = result.trace_review || {};
  const persona = result.persona_quality || {};
  const skills = result.skills || {};
  const runs = skills.runs || {};
  const mcp = result.mcp_tool_calls || {};
  const conceptStates = concept.states || {};
  const traceStates = trace.states || {};
  const skillStates = skills.states || {};
  const runStates = runs.states || {};
  const approvedConcepts = Number(conceptStates.approved || 0);
  const conceptTotal = Math.max(Number(concept.total || 0), 1);
  const reviewedConcepts = conceptTotal - Number(conceptStates["pending-review"] || 0);
  const traceTotal = Math.max(Number(trace.total || 0), 1);
  const reviewedTraces = traceTotal - Number(traceStates.unreviewed || 0);
  const approvedSkills = Number(skillStates.approved || 0);
  const skillTotal = Math.max(Number(skills.total || 0), 1);
  const usefulRuns = Number(runStates.useful || 0);
  const runTotal = Math.max(Number(runs.total || 0), 1);
  const mcpTotal = Number(mcp.total || 0);
  const mcpPending = Number(mcp.states?.pending_approval || 0);
  const externalReadiness = mcpTotal ? clampScore(((mcpTotal - mcpPending) / mcpTotal) * 100) : 35;
  return [
    { key: "persona", label: "Persona", value: clampScore(Number(persona.score ?? 0)), hint: persona.status || "persona quality" },
    { key: "knowledge", label: "Knowledge", value: clampScore((approvedConcepts / conceptTotal) * 100), hint: `${approvedConcepts}/${concept.total || 0} approved` },
    { key: "review", label: "Review", value: clampScore((reviewedConcepts / conceptTotal) * 100), hint: `${reviewedConcepts}/${concept.total || 0} reviewed` },
    { key: "answers", label: "Answers", value: clampScore((reviewedTraces / traceTotal) * 100), hint: `${reviewedTraces}/${trace.total || 0} traces reviewed` },
    { key: "skills", label: "Skills", value: clampScore((approvedSkills / skillTotal) * 100), hint: `${approvedSkills}/${skills.total || 0} approved` },
    { key: "outcomes", label: "Outcomes", value: clampScore((usefulRuns / runTotal) * 100), hint: `${usefulRuns}/${runs.total || 0} useful runs` },
    { key: "tools", label: "Tools", value: externalReadiness, hint: mcpTotal ? `${mcpPending} MCP pending` : "MCP planned" },
  ];
}

function renderMaturityRadar(scores) {
  const target = $("#maturityRadar");
  if (!target) return;
  const size = 230;
  const center = size / 2;
  const radius = 82;
  const points = scores.map((item, index) => radarPoint(index, scores.length, center, radius * (item.value / 100)));
  const gridLevels = [0.25, 0.5, 0.75, 1];
  const polygon = points.map((point) => `${point.x.toFixed(1)},${point.y.toFixed(1)}`).join(" ");
  const avg = Math.round(scores.reduce((sum, item) => sum + item.value, 0) / Math.max(scores.length, 1));
  const lowest = scores.reduce((min, item) => (item.value < min.value ? item : min), scores[0] || { label: "-", value: 0 });
  $("#maturityScoreLabel").textContent = `${avg}/100`;
  $("#maturityNarrative").textContent = `Strongest signal should move with usage. Current bottleneck: ${lowest.label} (${Math.round(lowest.value)}/100).`;
  target.innerHTML = `
    <svg viewBox="0 0 ${size} ${size}" aria-hidden="true">
      ${gridLevels.map((level) => {
        const grid = scores.map((_, index) => radarPoint(index, scores.length, center, radius * level));
        return `<polygon class="radar-grid" points="${grid.map((point) => `${point.x.toFixed(1)},${point.y.toFixed(1)}`).join(" ")}"></polygon>`;
      }).join("")}
      ${scores.map((item, index) => {
        const edge = radarPoint(index, scores.length, center, radius);
        const label = radarPoint(index, scores.length, center, radius + 24);
        return `
          <line class="radar-axis" x1="${center}" y1="${center}" x2="${edge.x.toFixed(1)}" y2="${edge.y.toFixed(1)}"></line>
          <text class="radar-label" x="${label.x.toFixed(1)}" y="${label.y.toFixed(1)}">${escapeHtml(item.label)}</text>
        `;
      }).join("")}
      <polygon class="radar-area" points="${polygon}"></polygon>
      <polyline class="radar-line" points="${polygon} ${points[0] ? `${points[0].x.toFixed(1)},${points[0].y.toFixed(1)}` : ""}"></polyline>
      ${points.map((point, index) => `<circle class="radar-point interactive" tabindex="0" role="button" data-dashboard-target="${escapeHtml(radarTargetForScore(scores[index].key))}" cx="${point.x.toFixed(1)}" cy="${point.y.toFixed(1)}" r="4"><title>${escapeHtml(scores[index].label)}: ${Math.round(scores[index].value)}/100 · ${escapeHtml(scores[index].hint)}</title></circle>`).join("")}
    </svg>
  `;
  bindDashboardChartDrilldowns(target);
}

function radarPoint(index, total, center, radius) {
  const angle = -Math.PI / 2 + (Math.PI * 2 * index) / total;
  return {
    x: center + Math.cos(angle) * radius,
    y: center + Math.sin(angle) * radius,
  };
}

function radarTargetForScore(key) {
  return {
    persona: "quality",
    knowledge: "concepts",
    review: "concepts",
    answers: "traces",
    skills: "skills",
    outcomes: "skills",
    tools: "mcp",
  }[key] || "all";
}

function renderTraceScatter(traces) {
  const target = $("#traceScatter");
  if (!target) return;
  const width = 320;
  const height = 210;
  const pad = 32;
  const maxSources = Math.max(5, ...traces.map((trace) => Number(trace.source_count || 0)));
  const points = traces.slice(0, 18).map((trace) => {
    const confidence = clampScore(Number(trace.confidence || 0));
    const sources = Number(trace.source_count || 0);
    return {
      title: trace.title || trace.query || "Trace",
      path: trace.path || "",
      confidence,
      sources,
      review: trace.review_state || "unreviewed",
      x: pad + (sources / maxSources) * (width - pad * 2),
      y: height - pad - (confidence / 100) * (height - pad * 2),
    };
  });
  const grounded = points.filter((point) => point.confidence >= 60 && point.sources >= 2).length;
  $("#traceInsightLabel").textContent = `${grounded}/${points.length || 0} grounded`;
  const confidenceLineY = height - pad - 0.6 * (height - pad * 2);
  const sourceLineX = pad + (Math.min(2, maxSources) / maxSources) * (width - pad * 2);
  target.innerHTML = `
    <svg viewBox="0 0 ${width} ${height}" aria-hidden="true">
      <rect class="scatter-quadrant weak" x="${pad}" y="${confidenceLineY.toFixed(1)}" width="${(sourceLineX - pad).toFixed(1)}" height="${(height - pad - confidenceLineY).toFixed(1)}"></rect>
      <rect class="scatter-quadrant evidence" x="${sourceLineX.toFixed(1)}" y="${confidenceLineY.toFixed(1)}" width="${(width - pad - sourceLineX).toFixed(1)}" height="${(height - pad - confidenceLineY).toFixed(1)}"></rect>
      <rect class="scatter-quadrant thin" x="${pad}" y="${pad}" width="${(sourceLineX - pad).toFixed(1)}" height="${(confidenceLineY - pad).toFixed(1)}"></rect>
      <rect class="scatter-quadrant grounded" x="${sourceLineX.toFixed(1)}" y="${pad}" width="${(width - pad - sourceLineX).toFixed(1)}" height="${(confidenceLineY - pad).toFixed(1)}"></rect>
      <line class="chart-axis" x1="${pad}" y1="${height - pad}" x2="${width - pad}" y2="${height - pad}"></line>
      <line class="chart-axis" x1="${pad}" y1="${pad}" x2="${pad}" y2="${height - pad}"></line>
      <text class="chart-label" x="${width - pad}" y="${height - 8}">sources</text>
      <text class="chart-label" x="8" y="${pad - 10}">confidence</text>
      <line class="chart-guide" x1="${pad}" y1="${confidenceLineY.toFixed(1)}" x2="${width - pad}" y2="${confidenceLineY.toFixed(1)}"></line>
      <line class="chart-guide" x1="${sourceLineX.toFixed(1)}" y1="${pad}" x2="${sourceLineX.toFixed(1)}" y2="${height - pad}"></line>
      ${points.map((point) => `
        <circle class="scatter-point ${point.sources ? "grounded" : "thin"} interactive ${state.dashboardTraceQuadrant && traceQuadrant(point) !== state.dashboardTraceQuadrant ? "muted" : ""}" tabindex="0" role="button" data-trace-path="${escapeHtml(point.path)}" cx="${point.x.toFixed(1)}" cy="${point.y.toFixed(1)}" r="${point.sources ? 5 : 3}">
          <title>${escapeHtml(point.title)} · confidence ${point.confidence} · sources ${point.sources} · ${escapeHtml(point.review)}</title>
        </circle>
      `).join("")}
    </svg>
  `;
  bindDashboardChartDrilldowns(target);
}

function renderTraceQualityQuadrants(traces) {
  const target = $("#traceQualityQuadrants");
  if (!target) return;
  const rows = ["grounded", "confident-thin", "evidence-low-confidence", "weak"].map((key) => ({
    key,
    label: traceQuadrantLabel(key),
    count: traces.filter((trace) => traceQuadrant(trace) === key).length,
  }));
  target.innerHTML = rows.map((row) => `
    <button class="trace-quadrant ${state.dashboardTraceQuadrant === row.key ? "active" : ""}" type="button" data-trace-quadrant="${escapeHtml(row.key)}">
      <strong>${escapeHtml(row.count)}</strong>
      <span>${escapeHtml(row.label)}</span>
    </button>
  `).join("");
  target.querySelectorAll("[data-trace-quadrant]").forEach((button) => {
    button.addEventListener("click", () => {
      state.dashboardTraceQuadrant = state.dashboardTraceQuadrant === button.dataset.traceQuadrant ? "" : button.dataset.traceQuadrant;
      state.dashboardFilter = "traces";
      renderReviewDashboard(state.reviewDashboard || {});
      $("#dashLatestTraces")?.scrollIntoView({ block: "center", behavior: "smooth" });
    });
  });
}

function traceQuadrant(trace = {}) {
  const confidence = clampScore(Number(trace.confidence || 0));
  const sources = Number(trace.source_count ?? trace.sources ?? 0);
  if (confidence >= 60 && sources >= 2) return "grounded";
  if (confidence >= 60 && sources < 2) return "confident-thin";
  if (confidence < 60 && sources >= 2) return "evidence-low-confidence";
  return "weak";
}

function traceQuadrantLabel(key) {
  return {
    grounded: "Grounded answers",
    "confident-thin": "Confident but thin",
    "evidence-low-confidence": "Evidence with low confidence",
    weak: "Weak grounding",
  }[key] || key;
}

function renderConfidenceBands(traces) {
  const target = $("#confidenceBands");
  if (!target) return;
  const confidenceValues = traces.map((trace) => clampScore(Number(trace.confidence || 0)));
  const bands = [
    { key: "strong", label: "Strong", range: ">= 75", count: confidenceValues.filter((value) => value >= 75).length },
    { key: "usable", label: "Usable", range: "50-74", count: confidenceValues.filter((value) => value >= 50 && value < 75).length },
    { key: "weak", label: "Weak", range: "< 50", count: confidenceValues.filter((value) => value < 50).length },
  ];
  const total = Math.max(confidenceValues.length, 1);
  const average = confidenceValues.length
    ? Math.round(confidenceValues.reduce((sum, value) => sum + value, 0) / confidenceValues.length)
    : 0;
  const weakCount = bands.find((band) => band.key === "weak")?.count || 0;
  $("#confidenceInsightLabel").textContent = confidenceValues.length ? `${average}% avg` : "No traces";
  $("#confidenceNarrative").textContent = confidenceValues.length
    ? `${weakCount} recent trace${weakCount === 1 ? "" : "s"} need stronger grounding or human review.`
    : "Ask the twin a few grounded questions to start collecting confidence signals.";
  target.innerHTML = bands.map((band) => {
    const width = Math.max(4, (band.count / total) * 100);
    return `
      <div class="confidence-band ${escapeHtml(band.key)}">
        <div>
          <strong>${escapeHtml(band.label)}</strong>
          <span>${escapeHtml(band.range)}</span>
        </div>
        <div class="confidence-track" aria-hidden="true"><span style="width: ${width.toFixed(1)}%"></span></div>
        <b>${escapeHtml(band.count)}</b>
      </div>
    `;
  }).join("");
}

function renderUsageBars(result, maturityScores) {
  const target = $("#usageBars");
  if (!target) return;
  const concept = result.concept_review || {};
  const trace = result.trace_review || {};
  const skills = result.skills || {};
  const runs = skills.runs || {};
  const refinements = skills.refinements || {};
  const approvalLoad = Number(runs.approval_pending?.length || 0) + Number(skills.pending_approval?.length || 0) + Number(refinements.pending?.length || 0);
  const max = Math.max(concept.total || 0, trace.total || 0, skills.total || 0, runs.total || 0, approvalLoad, 1);
  const rows = [
    { label: "Concepts", value: concept.total || 0, detail: formatInlineCounts(concept.states || {}) },
    { label: "Answer traces", value: trace.total || 0, detail: formatInlineCounts(trace.states || {}) },
    { label: "Skill runs", value: runs.total || 0, detail: formatInlineCounts(runs.states || {}) },
    { label: "Skills", value: skills.total || 0, detail: formatInlineCounts(skills.states || {}) },
    { label: "Human queue", value: approvalLoad, detail: "approval and review load" },
  ];
  const maturityAvg = Math.round(maturityScores.reduce((sum, item) => sum + item.value, 0) / Math.max(maturityScores.length, 1));
  $("#usageInsightLabel").textContent = `${maturityAvg}% maturity`;
  target.innerHTML = rows.map((row) => `
    <div class="usage-bar-row">
      <div>
        <strong>${escapeHtml(row.label)}</strong>
        <span>${escapeHtml(row.detail || "-")}</span>
      </div>
      <div class="usage-track" aria-hidden="true"><span style="width: ${Math.max(4, (Number(row.value || 0) / max) * 100).toFixed(1)}%"></span></div>
      <b>${escapeHtml(row.value)}</b>
    </div>
  `).join("");
}

function renderClusterHealth(clusters) {
  const target = $("#clusterHealth");
  if (!target) return;
  const rows = Array.isArray(clusters) ? clusters.slice(0, 6) : [];
  const weakClusters = rows.filter((cluster) => Number(cluster.review_needed || 0) || Number(cluster.low_confidence || 0)).length;
  $("#clusterInsightLabel").textContent = rows.length ? `${weakClusters}/${rows.length} need care` : "No clusters";
  if (!rows.length) {
    target.innerHTML = renderEmptyState("No knowledge clusters yet.", "Add knowledge", "openKnowledge");
    return;
  }
  target.innerHTML = `
    ${rows.map((cluster) => {
      const score = clampScore(Number(cluster.health_score || 0));
      const stateText = formatInlineCounts(cluster.states || {});
      return `
      <button class="cluster-health-row" type="button" data-cluster="${escapeHtml(cluster.cluster || "")}">
        <div>
          <strong>${escapeHtml(cluster.cluster || "Unclustered")}</strong>
          <span>${escapeHtml(cluster.total || 0)} concepts · ${escapeHtml(stateText || "no states")}</span>
        </div>
        <div class="cluster-health-track" aria-hidden="true"><span style="width: ${Math.max(4, score).toFixed(1)}%"></span></div>
        <b>${escapeHtml(score)}%</b>
        <small>${escapeHtml(cluster.review_needed || 0)} review · ${escapeHtml(cluster.low_confidence || 0)} weak</small>
      </button>
      `;
    }).join("")}
  `;
  bindClusterHealthDrilldowns(target);
}

function renderSkillOutcomeMatrix(runs = {}) {
  const target = $("#skillOutcomeMatrix");
  if (!target) return;
  const skills = Array.isArray(runs.skills) ? runs.skills.slice(0, 7) : [];
  const total = Number(runs.total || 0);
  const corrective = Number(runs.corrective_without_proposal?.length || 0);
  const approvalPending = Number(runs.approval_pending?.length || 0);
  $("#skillOutcomeInsightLabel").textContent = total ? `${total} runs` : "No runs";
  if (!skills.length) {
    target.innerHTML = renderEmptyState("No skill outcome memory yet.", "Open Skills", "openSkills");
    return;
  }
  target.innerHTML = skills.map((skill) => {
    const useful = Number(skill.review_states?.useful || 0);
    const needsRework = Number(skill.review_states?.needs_rework || 0) + Number(skill.review_states?.wrong_priority || 0) + Number(skill.review_states?.missing_context || 0) + Number(skill.review_states?.rejected || 0);
    const totalRuns = Math.max(Number(skill.run_count || 0), 1);
    const score = clampScore(Number(skill.outcome_score ?? skill.health_score ?? 0));
    const skillName = skill.name || skill.skill_name || skill.skill_id || "Skill";
    const latestRun = skill.last_run_at || skill.latest_run_at || "";
    return `
      <button class="outcome-matrix-row" type="button" data-skill-target="${escapeHtml(skill.skill_id || skillName || "")}">
        <div>
          <strong>${escapeHtml(skillName)}</strong>
          <span>${escapeHtml(skill.status || "unknown")} · ${escapeHtml(latestRun ? formatShortDate(latestRun) : "no recent run")}</span>
        </div>
        <span class="matrix-cell ready">${escapeHtml(useful)}</span>
        <span class="matrix-cell review">${escapeHtml(needsRework)}</span>
        <span class="matrix-cell ${skill.approval_pending ? "blocked" : "ready"}">${escapeHtml(skill.approval_pending || 0)}</span>
        <b>${escapeHtml(score)}%</b>
        <div class="outcome-track" aria-hidden="true"><span style="width: ${Math.max(4, (useful / totalRuns) * 100).toFixed(1)}%"></span></div>
      </button>
    `;
  }).join("");
  target.insertAdjacentHTML("beforeend", `
    <p class="insight-note">${escapeHtml(corrective)} corrective run${corrective === 1 ? "" : "s"} need proposals · ${escapeHtml(approvalPending)} approval action${approvalPending === 1 ? "" : "s"} pending.</p>
  `);
  target.querySelectorAll("[data-skill-target]").forEach((button) => {
    button.addEventListener("click", () => {
      state.dashboardFilter = "skills";
      renderDashboardFilter();
      $("#dashSkillQueue")?.scrollIntoView({ block: "center", behavior: "smooth" });
    });
  });
}

function renderDecisionBoundaryHeatmap(result = {}) {
  const target = $("#decisionBoundaryHeatmap");
  if (!target) return;
  const concept = result.concept_review || {};
  const trace = result.trace_review || {};
  const skills = result.skills || {};
  const runs = skills.runs || {};
  const mcp = result.mcp_tool_calls || {};
  const rows = [
    {
      key: "concepts",
      label: "Knowledge promotion",
      count: (concept.pending || []).length + (concept.needs_rework || []).length + (concept.rejected || []).length,
      detail: "approve, rework, or reject source-backed concepts",
    },
    {
      key: "traces",
      label: "Answer correction",
      count: (trace.latest || []).filter((item) => item.review_state !== "useful").length,
      detail: "review weak answers before they shape refinements",
    },
    {
      key: "skills",
      label: "Skill actions",
      count: (skills.pending_approval || []).length + (runs.approval_pending || []).length,
      detail: "approve versions and gated send/schedule actions",
    },
    {
      key: "refinements",
      label: "Refinement changes",
      count: (skills.refinements?.pending || []).length + (skills.refinements?.approved_pending_apply || []).length,
      detail: "turn grounded feedback into governed skill updates",
    },
    {
      key: "mcp",
      label: "External tools",
      count: (mcp.active || mcp.pending || []).filter((item) => item.status === "pending_approval").length,
      detail: "MCP and connector writes stay human-gated",
    },
  ];
  const open = rows.reduce((sum, row) => sum + Number(row.count || 0), 0);
  $("#decisionBoundaryInsightLabel").textContent = `${open} open`;
  target.innerHTML = rows.map((row) => {
    const level = row.count > 4 ? "blocked" : row.count > 0 ? "review" : "ready";
    return `
      <button class="boundary-row ${level}" type="button" data-boundary-target="${escapeHtml(row.key)}">
        <span>${escapeHtml(level)}</span>
        <strong>${escapeHtml(row.label)}</strong>
        <b>${escapeHtml(row.count)}</b>
        <small>${escapeHtml(row.detail)}</small>
      </button>
    `;
  }).join("");
  target.querySelectorAll("[data-boundary-target]").forEach((button) => {
    button.addEventListener("click", () => {
      state.dashboardFilter = button.dataset.boundaryTarget || "all";
      renderDashboardFilter();
      const section = state.dashboardFilter === "traces" ? $("#dashLatestTraces") : state.dashboardFilter === "skills" ? $("#dashSkillQueue") : state.dashboardFilter === "refinements" ? $("#dashRefinementQueue") : state.dashboardFilter === "mcp" ? $("#dashMcpQueue") : $("#dashPendingConcepts");
      section?.scrollIntoView({ block: "center", behavior: "smooth" });
    });
  });
}

function bindDashboardChartDrilldowns(target) {
  target.querySelectorAll("[data-dashboard-target]").forEach((node) => {
    const activate = () => {
      const targetFilter = node.dataset.dashboardTarget || "all";
      if (targetFilter === "quality") {
        showView("quality");
        setQualityGroup("persona");
        return;
      }
      state.dashboardFilter = targetFilter;
      renderDashboardFilter();
      const section = targetFilter === "traces" ? $("#dashLatestTraces") : targetFilter === "skills" ? $("#dashSkillQueue") : targetFilter === "mcp" ? $("#dashMcpQueue") : $("#dashPendingConcepts");
      section?.scrollIntoView({ block: "center", behavior: "smooth" });
      showToast("Dashboard drill-down", `${dashboardFilterLabel(targetFilter)} queue`, "info");
    };
    node.addEventListener("click", activate);
    node.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        activate();
      }
    });
  });
  target.querySelectorAll("[data-trace-path]").forEach((node) => {
    const activate = () => {
      const path = node.dataset.tracePath || "";
      if (path) {
        openAnswerTraceDrawer(path);
        return;
      }
      state.dashboardFilter = "traces";
      renderDashboardFilter();
      $("#dashLatestTraces")?.scrollIntoView({ block: "center", behavior: "smooth" });
    };
    node.addEventListener("click", activate);
    node.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        activate();
      }
    });
  });
}

function bindClusterHealthDrilldowns(target) {
  target.querySelectorAll(".cluster-health-row").forEach((button) => {
    button.addEventListener("click", () => {
      state.dashboardClusterFilter = button.dataset.cluster || "";
      state.dashboardFilter = "concepts";
      renderReviewDashboard(state.reviewDashboard || {});
      $("#dashPendingConcepts")?.scrollIntoView({ block: "center", behavior: "smooth" });
      showToast("Cluster drill-down", button.dataset.cluster || "Knowledge cluster", "info");
    });
  });
}

function clampScore(value) {
  const number = Number.isFinite(value) ? value : 0;
  return Math.max(0, Math.min(100, number));
}

function renderDashboardFilterCounts(result) {
  const concept = result.concept_review || {};
  const trace = result.trace_review || {};
  const refinements = result.skills?.refinements || {};
  const counts = {
    concepts: (concept.pending || []).length + (concept.needs_rework || []).length + (concept.rejected || []).length,
    traces: (trace.latest || []).length,
    graph: graphPromotionHistoryItems().length,
    skills: (result.skills?.pending_approval || []).length,
    refinements:
      (refinements.pending || []).length +
      (refinements.approved_pending_apply || []).length +
      (refinements.applied_pending_skill_approval || []).length,
    mcp:
      (result.mcp_tool_calls?.active || result.mcp_tool_calls?.pending || []).length +
      (result.mcp_tool_calls?.readiness?.blockers?.length || 0) +
      (result.mcp_tool_calls?.canary_packages?.packages || []).length,
  };
  counts.all = counts.concepts + counts.traces + counts.graph + counts.skills + counts.refinements + counts.mcp;
  $$(".dashboard-filter").forEach((button) => {
    const key = button.dataset.dashboardFilter || "all";
    const label = dashboardFilterLabel(key);
    button.textContent = `${label} (${counts[key] ?? 0})`;
  });
}

function dashboardFilterLabel(key) {
  return {
    all: "All review",
    concepts: "Concept review",
    traces: "Trace review",
    graph: "Graph review",
    skills: "Skill approvals",
    refinements: "Refinements",
    mcp: "MCP and sync",
  }[key] || key;
}

function dashboardActionText(action, fallback = "") {
  if (!action) return fallback;
  if (typeof action === "string") return action;
  if (typeof action === "object") {
    return [action.title, action.detail || action.status].filter(Boolean).join(" · ") || fallback;
  }
  return String(action);
}

function renderCockpitOverview(result) {
  const target = $("#cockpitOverview");
  if (!target) return;
  const active = state.twins.find((twin) => twin.twin_id === state.activeTwin);
  const concept = result.concept_review || {};
  const trace = result.trace_review || {};
  const pendingSkills = result.skills?.pending_approval?.length || 0;
  const pendingRefinements = result.skills?.refinements?.pending?.length || 0;
  const mcpPending = (result.mcp_tool_calls?.active || result.mcp_tool_calls?.pending || []).filter((call) => call.status === "pending_approval").length;
  const humanActions = pendingSkills + pendingRefinements + mcpPending + (result.skills?.runs?.approval_pending || []).length;
  const reviewLoad = (concept.pending?.length || 0) + (concept.needs_rework?.length || 0) + (trace.latest?.length || 0);
  const actions = result.actions || [];
  const graphQueueCount = (result.concept_review?.cluster_health || []).filter((cluster) => Number(cluster.review_count || cluster.pending_review || 0) > 0).length;
  const lanes = [
    {
      label: "Concept review",
      action: "reviewConcepts",
      count: (concept.pending?.length || 0) + (concept.needs_rework?.length || 0),
      detail: "Approve, rework, reject, or delete concepts from the governed queue.",
    },
    {
      label: "Graph review",
      action: "openGraph",
      count: graphQueueCount,
      detail: "Inspect inferred relations, clusters, duplicates, and graph provenance.",
    },
    {
      label: "Trace review",
      action: "openTraceReview",
      count: trace.latest?.length || 0,
      detail: "Review answer evidence, quality signals, and refinement triggers.",
    },
    {
      label: "Sync and MCP",
      action: "openMcpQueue",
      count: mcpPending,
      detail: "Approve tool calls, sync evidence, and keep external writes gated.",
    },
    {
      label: "Production checks",
      action: "openProductionCockpit",
      count: result.production?.blockers?.length || 0,
      detail: "Track hosted readiness, GitHub/GitLab handoff, and deployment gates.",
    },
  ];
  target.innerHTML = `
    <div class="review-cockpit-hero">
      <div class="active-twin-summary">
        ${renderTwinAvatar(active, "twin-avatar large")}
        <div>
          <span class="badge">Review Cockpit</span>
          <h2>${escapeHtml(active?.display_name || state.activeTwin)} behavior governance</h2>
          <p>${escapeHtml("Concept review, graph review, traces, sync, and production checks stay here. The main workspace remains focused on interaction.")}</p>
          <small class="updated-stamp">Updated ${escapeHtml(formatShortDate(result.refreshed_at || new Date().toISOString()))}</small>
        </div>
      </div>
      <div class="cockpit-overview-grid review-cockpit-kpis">
        <span class="${humanActions ? "attention" : "ready"}"><strong>${escapeHtml(humanActions)}</strong> human decisions</span>
        <span><strong>${escapeHtml(reviewLoad)}</strong> review items</span>
        <span><strong>${escapeHtml(trace.total || 0)}</strong> traces stored</span>
        <span><strong>${escapeHtml(pendingRefinements)}</strong> refinements</span>
      </div>
    </div>
    <div class="review-cockpit-lanes">
      ${lanes.map((lane) => `
        <button class="review-cockpit-lane" type="button" data-cockpit-action="${escapeHtml(lane.action)}">
          <span>${escapeHtml(lane.label)}</span>
          <strong>${escapeHtml(lane.count)}</strong>
          <small>${escapeHtml(lane.detail)}</small>
        </button>
      `).join("")}
    </div>
    <p class="cockpit-next">${escapeHtml(dashboardActionText(actions[0], "No urgent cockpit action. Continue improving source quality and reviewing skill outcomes."))}</p>
    <div class="cockpit-actions">
      <button class="secondary small" type="button" data-cockpit-action="reviewConcepts">Review concepts</button>
      <button class="secondary small" type="button" data-cockpit-action="openGraph">Review graph</button>
      <button class="secondary small" type="button" data-cockpit-action="openTraceReview">Review traces</button>
      <button class="secondary small" type="button" data-cockpit-action="openSkills">Open skills</button>
      <button class="secondary small" type="button" data-cockpit-action="openProductionCockpit">Production checks</button>
    </div>
  `;
}

function dashboardPriorityClass(kind, stateValue = "") {
  const stateText = String(stateValue || "").toLowerCase();
  if (kind === "mcp" || stateText.includes("approval") || stateText.includes("rework") || stateText.includes("rejected")) return "needs-action";
  if (kind === "graph" && (stateText.includes("candidate") || stateText.includes("draft") || stateText.includes("unreviewed"))) return "review";
  if (kind === "trace" && stateText.includes("unreviewed")) return "review";
  if (stateText.includes("approved") || stateText.includes("done")) return "ready";
  return "review";
}

function renderQueueMeta(items) {
  return `<span class="queue-meta">${escapeHtml(items.filter(Boolean).join(" · "))}</span>`;
}

function renderReviewCue(kind, item = {}) {
  const cue = dashboardReviewCue(kind, item);
  const requestJson = item.request_json || {};
  const handoffDetail =
    kind === "mcp" && requestJson.source === "voice_transcript_handoff"
      ? `
        <div class="sync-active-filters compact">
          <span><strong>Evidence</strong>${escapeHtml(requestJson.evidence_path || "not recorded")}</span>
          <span><strong>Handoff</strong>${escapeHtml(requestJson.handoff_path || "not recorded")}</span>
          <span><strong>Blocked</strong>${escapeHtml((requestJson.blocked_external_actions || []).join(", ") || "external writes")}</span>
        </div>
      `
      : "";
  return `
    <details class="queue-review-cue">
      <summary>${escapeHtml(cue.title)}</summary>
      <div>
        <span>${escapeHtml(cue.decision)}</span>
        <p>${escapeHtml(cue.reason)}</p>
        <small>${escapeHtml(cue.boundary)}</small>
        ${handoffDetail}
      </div>
    </details>
  `;
}

function dashboardReviewCue(kind, item = {}) {
  const reviewState = String(item.review_state || item.status || "pending").replace(/_/g, "-");
  if (kind === "concept") {
    return {
      title: reviewState === "needs-rework" ? "Resolve concept quality" : "Review knowledge claim",
      decision: "Decide: approve, request rework, reject, or keep pending.",
      reason: item.description || item.path || "Concept must be human-reviewed before it can strengthen the twin persona.",
      boundary: "Human review changes the knowledge state; the Actor can cite only governed evidence.",
    };
  }
  if (kind === "trace") {
    return {
      title: "Evaluate answer quality",
      decision: "Decide whether the answer was useful, needs evidence, or should be corrected.",
      reason: item.query || item.title || "Trace review trains the improvement loop on grounded outcomes.",
      boundary: "Trace decisions can trigger refinement proposals, but cannot auto-change approved skills.",
    };
  }
  if (kind === "skill") {
    return {
      title: "Approval gate",
      decision: "Approve or reject the skill version after checking scope, risk, and outputs.",
      reason: item.description || "Pending skills stay inactive until human approval.",
      boundary: "Server-side approval is required before the skill can become active.",
    };
  }
  if (kind === "refinement") {
    return {
      title: "Refinement gate",
      decision: "Review the proposed instruction or boundary change before creating a new version.",
      reason: item.rationale || item.summary || item.reason || "Refinement must be grounded in run feedback.",
      boundary: "A proposal never edits an approved skill directly; approval creates a governed version path.",
    };
  }
  if (kind === "approval") {
    return {
      title: "External action gate",
      decision: "Approve or reject the proposed action before the skill can continue.",
      reason: item.action || item.reason || "The skill detected a send, schedule, commit, or external-impact step.",
      boundary: "The orchestrator must pause here; only a human can release this action.",
    };
  }
  if (kind === "mcp") {
    return {
      title: "Tool action gate",
      decision: "Approve, reject, or execute only after checking external impact.",
      reason: item.request_summary || "External tool calls need least-privilege and human approval.",
      boundary: "External writes, sends, meetings, and commits remain human-gated.",
    };
  }
  return {
    title: "Review cue",
    decision: "Review this queue item before promoting behavior.",
    reason: item.summary || item.reason || "This item affects twin quality or governance.",
    boundary: "Human ratification remains the production boundary.",
  };
}

