function filteredConceptsForContractStrip() {
  const filter = ($("#conceptSearch")?.value || "").toLowerCase();
  return (state.concepts || []).filter((concept) =>
    conceptSearchText(concept).includes(filter)
      && matchesConceptReviewFilter(concept)
      && matchesConceptTypeFilter(concept)
      && matchesConceptProfileFilter(concept)
      && matchesConceptSourceFilter(concept)
      && matchesConceptClusterFilter(concept),
  );
}

function mergeStaticN8nReplayStatus(replayStatus = {}) {
  if (!state.n8nAgentContracts || !Array.isArray(state.n8nAgentContracts.contracts)) return;
  const replayByAgent = new Map((replayStatus.agents || []).map((agent) => [agent.agent_id, agent]));
  state.n8nAgentContracts = {
    ...state.n8nAgentContracts,
    replay_status: replayStatus.status || "unknown",
    replay_case_count: Number(replayStatus.case_count || 0),
    replay_fixture_count: Number(replayStatus.fixture_count || 0),
    replay_generated_at: replayStatus.generated_at || "",
    contracts: state.n8nAgentContracts.contracts.map((contract) => {
      const replay = replayByAgent.get(contract.agent_id);
      if (!replay) return contract;
      const configured = Boolean(contract.webhook_configured);
      const runtimeReadiness = agentRuntimeReadiness(contract.agent_id);
      return {
        ...contract,
        contract_version: replay.contract_version || contract.contract_version,
        replay_status: replay.status || "unknown",
        replay_case_count: Number(replay.case_count || 0),
        tested_cases: replay.tested_cases || [],
        live_probe_payload: replay.live_probe_payload || contract.live_probe_payload || null,
        live_status: configured ? runtimeReadiness.status : (replay.live_status || "not_configured"),
        statuses: [
          "documented",
          replay.status === "passed" ? "fixture ready" : "blocked",
          replay.status === "passed" ? "contract tested" : "blocked",
          configured ? runtimeReadiness.status : "missing URL",
        ],
        blocker: configured ? "Webhook URL configured; run live probe before production approval." : replay.blocker || contract.blocker,
      };
    }),
  };
}

function renderAgentOperatingModelPanel() {
  const target = $("#agentOperatingModelPanel");
  const productionTarget = $("#productionAgentRuntimeBoundaryPanel");
  const model = state.agentOperatingModel || {};
  const agents = Array.isArray(model.top_level_agents) ? model.top_level_agents : [];
  if (!agents.length) {
    if (target) target.innerHTML = renderEmptyState("No top-level agent model loaded.");
    if (productionTarget) productionTarget.innerHTML = renderEmptyState("No top-level agent runtime model loaded.");
    return;
  }
  const readinessPanel = renderN8nContractReadinessPanel(agents);
  if (target) {
    target.innerHTML = `
      <div class="agent-model-grid top-level-agent-grid">
        ${agents.map((agent) => `
          <article class="top-level-agent-card ${safeGraphClass(agent.id || "agent")}">
            <div class="activity-meta">
              <span class="badge">${escapeHtml(agent.group || "agent")}</span>
              <small>${escapeHtml(agent.n8n_contract || "no contract")}</small>
            </div>
            <h3>${escapeHtml(agent.name || agent.id || "Agent")}</h3>
            <p>${escapeHtml(agent.purpose || "")}</p>
            <div class="agent-consumer-list">
              ${(agent.owns || []).slice(0, 5).map((item) => `<span>${escapeHtml(item)}</span>`).join("")}
            </div>
            ${renderInternalAgentComponents(agent)}
            <small>${escapeHtml((agent.subagents || []).length)} subagents · approval remains human-gated</small>
          </article>
        `).join("")}
      </div>
      ${readinessPanel}
    `;
  }
  if (productionTarget) {
    productionTarget.innerHTML = readinessPanel;
  }
}

function renderInternalAgentComponents(agent = {}) {
  const components = Array.isArray(agent.internal_components) ? agent.internal_components : [];
  if (!components.length) return "";
  return `
    <div class="internal-component-list">
      ${components.map((component) => `
        <span>
          <strong>${escapeHtml(component.name || component.id || "Internal component")}</strong>
          <small>${escapeHtml(component.purpose || "Internal runtime component")}</small>
        </span>
      `).join("")}
    </div>
  `;
}

function renderN8nContractReadinessPanel(agents = []) {
  const contracts = state.n8nAgentContracts?.contracts || [];
  const contractByAgent = new Map(contracts.map((contract) => [contract.agent_id, contract]));
  const replaySummary = state.n8nAgentContracts?.replay_status
    ? ` · replay ${state.n8nAgentContracts.replay_status}: ${state.n8nAgentContracts.replay_case_count || 0} cases`
    : "";
  return `
    <div class="agent-contract-readiness-head">
      <span class="badge">n8n runtime boundary</span>
      <small>${escapeHtml(`${state.n8nAgentContracts?.configured_count ?? 0}/${state.n8nAgentContracts?.contract_count ?? agents.length} webhooks configured${replaySummary}`)}</small>
    </div>
    ${renderZielmodus4ReadinessCard()}
    <div class="agent-contract-readiness">
      ${agents.map((agent) => renderN8nContractReadiness(agent, contractByAgent.get(agent.id))).join("")}
    </div>
    ${renderN8nRuntimeSetupActions(agents, contractByAgent)}
    ${renderN8nFixtureLiveComparison(agents, contractByAgent)}
    ${renderAgentContractActionResult()}
  `;
}

function renderZielmodus4ReadinessCard() {
  const readiness = state.zielmodus4ReadinessStatus;
  if (!readiness) return "";
  const status = readiness.status || "unknown";
  const summary = readiness.summary || {};
  const live = readiness.live_n8n || {};
  const liveProbe = readiness.live_probe_evidence || {};
  const missingAgents = Array.isArray(live.missing_live_agents) ? live.missing_live_agents : [];
  const missingProbeAgents = Array.isArray(liveProbe.missing_probe_agents) ? liveProbe.missing_probe_agents : [];
  const nextActions = Array.isArray(readiness.next_actions) ? readiness.next_actions : [];
  const requirementLabel = `${summary.ready_requirement_count ?? 0}/${summary.requirement_count ?? 0} requirements`;
  const qaLabel = `${summary.passed_qa_check_count ?? 0}/${summary.qa_check_count ?? 0} QA`;
  const liveLabel = summary.live_ready ? "live-ready" : "live URL blocked";
  return `
    <section class="zielmodus-readiness-card ${safeGraphClass(status)}" aria-label="Zielmodus 4 readiness gate">
      <div class="zielmodus-readiness-head">
        <div>
          <span class="badge">Zielmodus gate</span>
          <strong>${escapeHtml(status.replaceAll("_", " "))}</strong>
          <p>${escapeHtml(`${requirementLabel} · ${qaLabel} · ${liveLabel}`)}</p>
        </div>
        <div class="button-row tight">
          <a class="secondary small" href="${escapeHtml(githubBlobUrl("frontend/assets/zielmodus-4-readiness-status.json"))}" target="_blank" rel="noreferrer">Open artifact</a>
          <a class="secondary small" href="${escapeHtml(githubBlobUrl("docs/production/zielmodus-4-readiness-audit.md"))}" target="_blank" rel="noreferrer">Open audit</a>
          <a class="secondary small" href="${escapeHtml(githubBlobUrl("docs/production/zielmodus-4-live-completion-plan.md"))}" target="_blank" rel="noreferrer">Completion plan</a>
          <a class="secondary small" href="${escapeHtml(githubBlobUrl("frontend/assets/zielmodus-4-live-completion-checklist.json"))}" target="_blank" rel="noreferrer">Checklist JSON</a>
        </div>
      </div>
      <div class="zielmodus-readiness-metrics">
        <span><strong>${escapeHtml(requirementLabel)}</strong><small>public-safe evidence</small></span>
        <span><strong>${escapeHtml(qaLabel)}</strong><small>browser and trace checks</small></span>
        <span><strong>${escapeHtml(String(live.configured_count ?? 0))}/${escapeHtml(String((live.required_agents || []).length || 3))} agents</strong><small>${escapeHtml(live.detail || "Runtime URL status unknown.")}</small></span>
      </div>
      ${missingAgents.length ? `
        <div class="zielmodus-readiness-blocker">
          <strong>Blocked live agents</strong>
          <p>${missingAgents.map(agentDisplayName).map(escapeHtml).join(", ")}</p>
        </div>
      ` : ""}
      <div class="zielmodus-live-proof-summary" aria-label="Remaining live proof">
        <span><strong>${escapeHtml(String(missingAgents.length))}</strong><small>missing live URLs</small></span>
        <span><strong>${escapeHtml(String(missingProbeAgents.length))}</strong><small>missing probe traces</small></span>
        <span><strong>45-90 min</strong><small>estimated integration after URLs exist</small></span>
      </div>
      ${nextActions.length ? `
        <ol class="zielmodus-readiness-actions">
          ${nextActions.slice(0, 4).map((item) => `<li>${escapeHtml(item)}</li>`).join("")}
        </ol>
      ` : ""}
      ${renderZielmodus4LiveHandoffGrid()}
    </section>
  `;
}

function renderZielmodus4LiveHandoffGrid() {
  const agentIds = ["actor_twin", "knowledge_fabric_agent", "agentic_butler"];
  const probeAgents = Array.isArray(state.n8nLiveProbeEvidenceStatus?.agents)
    ? state.n8nLiveProbeEvidenceStatus.agents
    : [];
  const preflight = state.n8nLiveReadinessPreflight || {};
  const preflightSummary = preflight.summary || {};
  const preflightActions = Array.isArray(preflight.next_actions) ? preflight.next_actions : [];
  const handoff = state.n8nLiveHandoffCommands || {};
  const handoffSummary = handoff.summary || {};
  const handoffAgents = Array.isArray(handoff.agents) ? handoff.agents : [];
  const readinessArtifact = githubBlobUrl("frontend/assets/n8n-runtime-readiness-status.json");
  const probeArtifact = githubBlobUrl("frontend/assets/n8n-live-probe-evidence.json");
  const preflightArtifact = githubBlobUrl("frontend/assets/n8n-live-readiness-preflight.json");
  const handoffArtifact = githubBlobUrl("frontend/assets/n8n-live-handoff-commands.json");
  const adapterArtifact = githubBlobUrl("frontend/assets/n8n-production-adapter-status.json");
  const blockerSummary = preflightActions
    .flatMap((action) => Array.isArray(action.blockers) ? action.blockers : [])
    .reduce((acc, blocker) => {
      acc[blocker] = (acc[blocker] || 0) + 1;
      return acc;
    }, {});
  return `
    <div class="zielmodus-live-handoff">
      <div class="zielmodus-live-handoff-head">
        <div>
          <span class="badge">Live n8n handoff</span>
          <strong>URL + probe evidence required</strong>
          <p>Public-safe contracts are ready. Production readiness still requires public webhook URLs, no-write probes, and non-demo trace ids.</p>
        </div>
        <div class="button-row tight">
          <a class="secondary small" href="${escapeHtml(readinessArtifact)}" target="_blank" rel="noreferrer">Runtime status</a>
          <a class="secondary small" href="${escapeHtml(probeArtifact)}" target="_blank" rel="noreferrer">Probe evidence</a>
          <a class="secondary small" href="${escapeHtml(preflightArtifact)}" target="_blank" rel="noreferrer">Preflight</a>
          <a class="secondary small" href="${escapeHtml(handoffArtifact)}" target="_blank" rel="noreferrer">Handoff commands</a>
          <a class="secondary small" href="${escapeHtml(adapterArtifact)}" target="_blank" rel="noreferrer">Adapter status</a>
          <a class="secondary small" href="${escapeHtml(githubBlobUrl("docs/production/n8n-live-probe-runbook.md"))}" target="_blank" rel="noreferrer">Probe runbook</a>
          <a class="secondary small" href="${escapeHtml(githubBlobUrl("docs/production/zielmodus-4-completion-audit.md"))}" target="_blank" rel="noreferrer">Completion audit</a>
          <a class="secondary small" href="${escapeHtml(githubBlobUrl("docs/production/zielmodus-4-live-completion-plan.md"))}" target="_blank" rel="noreferrer">Completion plan</a>
          <a class="secondary small" href="${escapeHtml(githubBlobUrl("frontend/assets/zielmodus-4-live-completion-checklist.json"))}" target="_blank" rel="noreferrer">Checklist JSON</a>
        </div>
      </div>
      ${handoff.schema_version ? `
        <div class="zielmodus-handoff-command-summary ${escapeHtml(safeGraphClass(handoff.status || "unknown"))}">
          <span><strong>${escapeHtml(String(handoffSummary.missing_live_url_count ?? 0))}</strong><small>missing live URLs</small></span>
          <span><strong>${escapeHtml(String(handoffSummary.missing_probe_trace_count ?? 0))}</strong><small>missing probe traces</small></span>
          <span><strong>${escapeHtml(handoff.status || "unknown")}</strong><small>handoff status</small></span>
          <span><strong>${escapeHtml(String((handoffSummary.strict_gate_commands || []).length))}</strong><small>strict gate commands</small></span>
        </div>
      ` : ""}
      ${preflight.schema_version ? `
        <div class="zielmodus-preflight-summary ${escapeHtml(safeGraphClass(preflight.status || "unknown"))}">
          <span><strong>${escapeHtml(String(preflightSummary.fixture_ready_count ?? 0))}/${escapeHtml(String(preflightSummary.agent_count ?? agentIds.length))}</strong><small>fixtures</small></span>
          <span><strong>${escapeHtml(String(preflightSummary.url_ready_count ?? 0))}/${escapeHtml(String(preflightSummary.agent_count ?? agentIds.length))}</strong><small>live URLs</small></span>
          <span><strong>${escapeHtml(String(preflightSummary.live_probe_ready_count ?? 0))}/${escapeHtml(String(preflightSummary.agent_count ?? agentIds.length))}</strong><small>probe traces</small></span>
          <span><strong>${escapeHtml(preflight.status || "unknown")}</strong><small>${escapeHtml(Object.keys(blockerSummary).length ? Object.entries(blockerSummary).map(([key, count]) => `${key}: ${count}`).join(" · ") : "no blockers")}</small></span>
        </div>
      ` : ""}
      ${renderN8nProductionAdapterSummary()}
      ${renderN8nAiAgentReadinessSummary()}
      ${renderN8nBrowserRuntimeShapeSummary()}
      ${renderActorTwinRoutingReadinessSummary()}
      ${renderActorTwinOrchestrationReadinessSummary()}
      ${renderZielmodus4StrictReadinessOperatorPanel(agentIds)}
      <div class="zielmodus-live-handoff-grid">
        ${agentIds.map((agentId) => {
          const runtime = agentRuntimeReadiness(agentId);
          const persistedProbe = probeAgents.find((agent) => agent.agent_id === agentId) || {};
          const handoffAgent = handoffAgents.find((agent) => agent.agent_id === agentId) || {};
          const sessionProbe = state.n8nLiveProbeResults?.[agentId] || {};
          const probeStatus = sessionProbe.status || persistedProbe.status || "awaiting_probe";
          const traceId = sessionProbe.trace_id || persistedProbe.trace_id || "";
          const connected = String(probeStatus).toLowerCase().includes("connected") && traceId && persistedProbe.demo !== true;
          const className = connected ? "ready" : runtime.configured ? "pending" : "blocked";
          const secretKey = {
            actor_twin: "GH_PAGES_N8N_ACTOR_TWIN_WEBHOOK_URL",
            knowledge_fabric_agent: "GH_PAGES_N8N_KNOWLEDGE_FABRIC_WEBHOOK_URL",
            agentic_butler: "GH_PAGES_N8N_AGENTIC_BUTLER_WEBHOOK_URL",
          }[agentId] || "GH_PAGES_N8N_WEBHOOK_URL";
          const setupCommand = handoffAgent.commands?.local_public_uat_url || `node scripts/set-n8n-agent-url.cjs --agent ${agentId} --url https://YOUR-N8N-HOST/webhook/YOUR-${agentId.toUpperCase().replace(/_/g, "-")}-UAT-PATH`;
          const expectedStatus = handoffAgent.expected_response_status || persistedProbe.expected_response_status || "completed";
          const recordCommand = persistedProbe.record_command_template || handoffAgent.commands?.record_probe || `node scripts/record-n8n-live-probe-evidence.cjs --agent ${agentId} --trace-id TRACE_ID --execution-url https://YOUR-N8N-HOST/workflow/.../executions/... --response-status ${expectedStatus}`;
          return `
            <article class="${escapeHtml(className)}">
              <span>${escapeHtml(className === "ready" ? "connected" : runtime.configured ? "probe pending" : "URL blocked")}</span>
              <strong>${escapeHtml(agentDisplayName(agentId))}</strong>
              <dl>
                <div><dt>URL</dt><dd>${escapeHtml(runtime.configured ? runtime.urlSourceLabel || "configured" : secretKey)}</dd></div>
                <div><dt>Probe</dt><dd>${escapeHtml(connected ? `trace ${traceId}` : probeStatus)}</dd></div>
                <div><dt>Expected</dt><dd>${escapeHtml(expectedStatus)}</dd></div>
              </dl>
              <p>${escapeHtml(connected ? "Live probe evidence is recorded." : runtime.nextAction || persistedProbe.next_action || "Run live probe and record trace evidence.")}</p>
              <small>Evidence command records only public-safe trace id, execution URL, URL source, and expected status.</small>
              ${runtime.configured ? "" : `<button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(setupCommand)}">Copy URL setup command</button>`}
              <button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(recordCommand)}">Copy evidence command</button>
            </article>
          `;
        }).join("")}
      </div>
      ${renderZielmodus4CompletionChecklist()}
    </div>
  `;
}

function renderN8nProductionAdapterSummary() {
  const adapter = state.n8nProductionAdapterStatus || {};
  if (!adapter.schema_version) return "";
  const summary = adapter.summary || {};
  const status = adapter.status || "unknown";
  const examples = Array.isArray(adapter.examples) ? adapter.examples : [];
  const pending = Array.isArray(adapter.next_actions) ? adapter.next_actions : [];
  return `
    <div class="zielmodus-preflight-summary ${escapeHtml(safeGraphClass(status))}" aria-label="n8n production adapter readiness">
      <span><strong>${escapeHtml(String(summary.example_count ?? examples.length))}</strong><small>adapter examples</small></span>
      <span><strong>${escapeHtml(String(summary.status_count ?? 0))}/3</strong><small>response statuses</small></span>
      <span><strong>${escapeHtml(status.replaceAll("_", " "))}</strong><small>schema validation</small></span>
      <span><strong>${escapeHtml(String(pending.length))}</strong><small>production adapter next actions</small></span>
    </div>
  `;
}

function renderN8nAiAgentReadinessSummary() {
  const readiness = state.n8nAiAgentReadinessStatus || {};
  if (!readiness.schema_version) return "";
  const summary = readiness.summary || {};
  const agents = Array.isArray(readiness.agents) ? readiness.agents : [];
  const status = readiness.status || "unknown";
  const productionVerified = summary.production_ai_logic_verified === true;
  const artifact = githubBlobUrl("frontend/assets/n8n-ai-agent-readiness-status.json");
  const runbook = githubBlobUrl("docs/production/n8n-ai-agent-activation-runbook.md");
  return `
    <section class="n8n-ai-agent-readiness ${productionVerified ? "ready" : "pending"}" aria-label="n8n AI-agent logic readiness">
      <div class="n8n-ai-agent-readiness-head">
        <div>
          <span class="badge">AI logic gate</span>
          <strong>${escapeHtml(status.replaceAll("_", " "))}</strong>
          <p>${escapeHtml(readiness.interpretation || "Distinguishes live webhook readiness from verified AI-agent execution.")}</p>
        </div>
        <div class="button-row tight">
          <a class="secondary small" href="${escapeHtml(artifact)}" target="_blank" rel="noreferrer">Open AI status</a>
          <a class="secondary small" href="${escapeHtml(runbook)}" target="_blank" rel="noreferrer">Activation runbook</a>
        </div>
      </div>
      <div class="zielmodus-preflight-summary ${escapeHtml(safeGraphClass(status))}">
        <span><strong>${escapeHtml(String(summary.ai_agent_blueprint_ready_count ?? 0))}/${escapeHtml(String(summary.agent_count ?? agents.length))}</strong><small>AI blueprints</small></span>
        <span><strong>${escapeHtml(String(summary.promoted_workflow_ready_count ?? 0))}/${escapeHtml(String(summary.agent_count ?? agents.length))}</strong><small>import targets</small></span>
        <span><strong>${escapeHtml(String(summary.live_probe_claims_ai_agent_count ?? 0))}/${escapeHtml(String(summary.agent_count ?? agents.length))}</strong><small>probe claims AI</small></span>
        <span><strong>${escapeHtml(String(summary.live_trace_recorded_count ?? 0))}/${escapeHtml(String(summary.agent_count ?? agents.length))}</strong><small>live traces</small></span>
        <span><strong>${escapeHtml(String(summary.manual_live_workflow_verification_required_count ?? 0))}</strong><small>manual verifications open</small></span>
      </div>
      <div class="n8n-ai-agent-readiness-grid">
        ${agents.map((agent) => {
          const gates = agent.gates || {};
          const readyCount = [
            gates.ai_agent_blueprint_ready,
            gates.promoted_workflow_ready,
            gates.response_adapter_ready,
            gates.live_url_configured,
            gates.live_trace_recorded,
            gates.live_probe_claims_ai_agent,
          ].filter(Boolean).length;
          const statusClass = gates.manual_live_workflow_verification_required ? "pending" : "ready";
          return `
            <article class="${escapeHtml(statusClass)}">
              <span>${escapeHtml(agent.agent_name || agentDisplayName(agent.agent_id))}</span>
              <strong>${escapeHtml(`${readyCount}/6 machine gates`)}</strong>
              <small>${escapeHtml(agent.role || "Agent role")}</small>
              <dl>
                <div><dt>Blueprint</dt><dd>${escapeHtml(gates.ai_agent_blueprint_ready ? "AI Agent node ready" : "missing")}</dd></div>
                <div><dt>Import</dt><dd>${escapeHtml(gates.promoted_workflow_ready ? "workflow target ready" : "target missing")}</dd></div>
                <div><dt>Adapter</dt><dd>${escapeHtml(gates.response_adapter_ready ? "contract ready" : "blocked")}</dd></div>
                <div><dt>Live</dt><dd>${escapeHtml(gates.live_url_configured ? "URL configured" : "URL missing")}</dd></div>
                <div><dt>Trace</dt><dd>${escapeHtml(agent.live_probe?.trace_id || "trace pending")}</dd></div>
                <div><dt>Verification</dt><dd>${escapeHtml(gates.manual_live_workflow_verification_required ? "n8n canvas check required" : "verified")}</dd></div>
              </dl>
            </article>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

