function renderN8nFixtureLiveComparison(agents = [], contractByAgent = new Map()) {
  const rows = agents.map((agent) => n8nFixtureLiveComparisonRow(agent, contractByAgent.get(agent.id)));
  const readyForLive = rows.filter((row) => row.fixtureReady && row.configured).length;
  const connected = rows.filter((row) => row.liveStatus === "connected").length;
  return `
    <section class="n8n-fixture-live-comparison">
      <div class="n8n-fixture-live-head">
        <div>
          <span class="badge">Fixture-to-live comparison</span>
          <strong>${escapeHtml(`${readyForLive}/${rows.length} ready for live UAT · ${connected}/${rows.length} probed connected`)}</strong>
          <p>Use this matrix to separate contract quality from runtime connectivity. A fixture pass is necessary, but not sufficient for production approval.</p>
        </div>
      </div>
      <div class="n8n-comparison-table" role="table" aria-label="n8n fixture and live comparison">
        <div class="n8n-comparison-row header" role="row">
          <span role="columnheader">Agent</span>
          <span role="columnheader">Fixture</span>
          <span role="columnheader">Cases</span>
          <span role="columnheader">Runtime URL</span>
          <span role="columnheader">Live probe</span>
          <span role="columnheader">Next action</span>
        </div>
        ${rows.map((row) => `
          <div class="n8n-comparison-row ${safeGraphClass(row.liveStatus)}" role="row">
            <span role="cell"><strong>${escapeHtml(row.name)}</strong><small>${escapeHtml(row.source)}</small></span>
            <span role="cell"><i class="${row.fixtureReady ? "ready" : "blocked"}">${escapeHtml(row.fixtureStatus)}</i></span>
            <span role="cell"><strong>${escapeHtml(String(row.caseCount))}</strong><small>${escapeHtml(row.caseCoverage)}</small></span>
            <span role="cell"><i class="${row.configured ? "ready" : "blocked"}">${escapeHtml(row.runtimeStatus)}</i><small>${escapeHtml(row.envVar)}</small></span>
            <span role="cell"><i class="${row.liveStatus === "connected" ? "ready" : row.liveStatus === "blocked" ? "blocked" : "pending"}">${escapeHtml(row.liveLabel)}</i><small>${escapeHtml(row.liveDetail)}</small></span>
            <span role="cell">
              <small>${escapeHtml(row.nextAction)}</small>
              ${row.liveProbePayload ? `<button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(JSON.stringify(row.liveProbePayload, null, 2))}">Copy probe payload</button>` : ""}
            </span>
          </div>
        `).join("")}
      </div>
    </section>
  `;
}

function n8nFixtureLiveComparisonRow(agent = {}, readiness = null) {
  const agentId = agent.id || readiness?.agent_id || "";
  const runtimeReadiness = agentRuntimeReadiness(agentId);
  const probe = state.n8nLiveProbeResults?.[agentId] || {};
  const testedCases = Array.isArray(readiness?.tested_cases) ? readiness.tested_cases : [];
  const liveProbePayload = readiness?.live_probe_payload || null;
  const fixtureReady = readiness?.replay_status === "passed" || readiness?.status === "passed";
  const caseCount = Number(readiness?.replay_case_count || readiness?.case_count || testedCases.length || 0);
  const requiredCases = ["request", "response", "approval_required", "failure"];
  const missingCases = requiredCases.filter((item) => !testedCases.includes(item));
  const liveStatus = probe.status || (runtimeReadiness.configured ? "configured" : "blocked");
  const liveLabel = probe.status === "connected"
    ? "connected"
    : probe.status === "failed"
      ? "failed"
      : runtimeReadiness.configured
        ? "not probed"
        : "blocked";
  const nextAction = !fixtureReady
    ? "Fix fixture replay before wiring live workflow."
    : !runtimeReadiness.configured
      ? runtimeReadiness.nextAction || "Add public UAT webhook URL or hosted secret, then probe live."
      : probe.status !== "connected"
        ? runtimeReadiness.nextAction || "Run live probe and capture trace evidence."
        : "Run UAT with approval gate and trace review.";
  return {
    id: agentId,
    name: agent.name || readiness?.agent_name || agentDisplayName(agentId),
    source: readiness?.source || agent.n8n_contract || "contract fixture",
    fixtureReady,
    fixtureStatus: fixtureReady ? "passed" : readiness?.replay_status || readiness?.status || "unknown",
    caseCount,
    caseCoverage: missingCases.length
      ? `missing ${missingCases.join(", ")}`
      : testedCases.includes("live_probe")
        ? "request, response, approval, failure, live probe"
        : "request, response, approval, failure",
    configured: runtimeReadiness.configured,
    runtimeStatus: runtimeReadiness.configured ? runtimeReadiness.status : runtimeReadiness.status || "missing URL",
    envVar: runtimeReadiness.envVar || "N8N_WEBHOOK_URL",
    liveStatus,
    liveLabel,
    liveDetail: probe.detail || runtimeReadiness.detail,
    liveProbePayload,
    nextAction,
  };
}

function renderN8nRuntimeSetupActions(agents = [], contractByAgent = new Map()) {
  const missingAgents = agents.filter((agent) => !agentRuntimeReadiness(agent.id || "").configured);
  const configuredAgents = agents.filter((agent) => agentRuntimeReadiness(agent.id || "").configured);
  const missingSnippet = buildN8nRuntimeConfigSnippet(missingAgents);
  const missingSetupPacket = buildN8nLiveUrlSetupPacket(missingAgents, contractByAgent);
  const secretRows = agents.map((agent) => {
    const readiness = agentRuntimeReadiness(agent.id || "");
    const contract = contractByAgent.get(agent.id) || {};
    return {
      id: agent.id || "",
      name: agent.name || agentDisplayName(agent.id || ""),
      envVar: readiness.envVar || contract.webhook_env_var || "N8N_WEBHOOK_URL",
      status: readiness.configured ? "configured" : "missing URL",
      detail: readiness.configured
        ? "Probe the live workflow before production use."
        : "Create/publish the n8n workflow, then add its webhook URL to runtime config.",
    };
  });
  return `
    <section class="n8n-runtime-setup-actions">
      <div class="n8n-runtime-setup-head">
        <div>
          <span class="badge">Runtime setup actions</span>
          <strong>${escapeHtml(`${configuredAgents.length}/${agents.length} live agent URLs configured`)}</strong>
          <p>${escapeHtml(missingAgents.length
            ? "Fixture replay is passing, but missing live URLs still block end-to-end Knowledge Fabric and Agentic Butler UAT."
            : "All top-level agent URLs are configured. Run live probes and UAT before production approval.")}</p>
        </div>
        <div class="button-row tight">
          <a class="secondary small" href="${escapeHtml(githubBlobUrl("docs/n8n-live-url-configuration.md"))}" target="_blank" rel="noreferrer">Open guide</a>
          <a class="secondary small" href="${escapeHtml(githubBlobUrl("frontend/assets/agent-runtime-config.json"))}" target="_blank" rel="noreferrer">Open runtime asset</a>
          ${missingSetupPacket ? `<button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(missingSetupPacket)}">Copy setup packet</button>` : ""}
          ${missingSnippet ? `<button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(missingSnippet)}">Copy missing config</button>` : ""}
        </div>
      </div>
      ${missingAgents.length ? renderN8nCurrentSupportedConfigPath(missingSnippet) : ""}
      ${missingAgents.length ? renderProductionAgentMissingUrlSetup(missingAgents) : ""}
      ${renderWorkflowScopeCredentialBlocker(missingAgents)}
      <div class="n8n-runtime-secret-grid">
        ${secretRows.map((row) => `
          <article class="${row.status === "configured" ? "ready" : "pending"}">
            <span class="queue-kind">${escapeHtml(row.status)}</span>
            <strong>${escapeHtml(row.name)}</strong>
            <code>${escapeHtml(row.envVar)}</code>
            <small>${escapeHtml(row.detail)}</small>
            ${row.status === "missing URL" ? renderAgentMissingWebhookActions(row.id, row.envVar) : ""}
          </article>
        `).join("")}
      </div>
      <details class="n8n-runtime-setup-details">
        <summary>Fixture-to-live rollout sequence</summary>
        <ol>
          <li>Keep fixture replay green for the agent contract.</li>
          <li>Create or publish the matching n8n webhook workflow.</li>
          <li>Add the webhook URL to GitHub Pages runtime config or the hosted backend secret store.</li>
          <li>Run the cockpit live probe and capture the trace.</li>
          <li>Approve production use only after UAT confirms approval gates and trace storage.</li>
        </ol>
      </details>
    </section>
  `;
}

function renderWorkflowScopeCredentialBlocker(missingAgents = []) {
  const missingNames = missingAgents.length
    ? missingAgents.map((agent) => agent.name || agentDisplayName(agent.id || "")).join(", ")
    : "No missing live agent URLs";
  const workflowPatch = githubBlobUrl("docs/production/github-pages-agent-runtime-workflow-patch.md");
  const runtimeAsset = githubBlobUrl("frontend/assets/agent-runtime-config.json");
  const guide = githubBlobUrl("docs/n8n-live-url-configuration.md");
  const scopePacket = {
    blocker: "github_workflow_scope_required",
    current_supported_path: "frontend/assets/agent-runtime-config.json for intentionally public UAT webhook URLs",
    blocked_path: ".github/workflows/intellectual-twin-pages.yml secret injection",
    required_capability: "GitHub credential or app token with workflow scope",
    missing_live_agents: missingAgents.map((agent) => ({
      agent_id: agent.id || "",
      agent_name: agent.name || agentDisplayName(agent.id || ""),
      next_action: "Create/publish public UAT n8n webhook URL, then add it via runtime asset or workflow-secret path.",
    })),
    docs: [
      "docs/n8n-live-url-configuration.md",
      "docs/production/github-pages-agent-runtime-workflow-patch.md",
    ],
  };
  return `
    <aside class="workflow-scope-blocker">
      <div>
        <span class="badge">Credential boundary</span>
        <strong>Workflow-secret deployment is prepared, but blocked by missing GitHub <code>workflow</code> scope.</strong>
        <p>Use the public runtime asset for UAT now. Apply the workflow patch only after the GitHub credential can update <code>.github/workflows/*</code>.</p>
      </div>
      <div class="workflow-scope-blocker-grid">
        <span>
          <strong>Current path</strong>
          <small>Public UAT URLs in <code>frontend/assets/agent-runtime-config.json</code></small>
        </span>
        <span>
          <strong>Blocked path</strong>
          <small>Repository-secret injection into GitHub Pages runtime config</small>
        </span>
        <span>
          <strong>Missing live agents</strong>
          <small>${escapeHtml(missingNames)}</small>
        </span>
      </div>
      <div class="button-row tight">
        <a class="secondary small" href="${escapeHtml(runtimeAsset)}" target="_blank" rel="noreferrer">Open runtime asset</a>
        <a class="secondary small" href="${escapeHtml(workflowPatch)}" target="_blank" rel="noreferrer">Open workflow patch</a>
        <a class="secondary small" href="${escapeHtml(guide)}" target="_blank" rel="noreferrer">Open live URL guide</a>
        <button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(JSON.stringify(scopePacket, null, 2))}">Copy blocker packet</button>
      </div>
    </aside>
  `;
}

function buildN8nLiveUrlSetupPacket(missingAgents = [], contractByAgent = new Map()) {
  const agents = missingAgents.filter((agent) => agent?.id);
  if (!agents.length) return "";
  const runtimeAssetPatch = buildN8nRuntimeConfigSnippet(agents);
  const packet = {
    packet_type: "meids_n8n_live_url_setup",
    packet_version: "0.1.0",
    generated_at: new Date().toISOString(),
    target: {
      runtime_asset: "frontend/assets/agent-runtime-config.json",
      setup_guide: "docs/n8n-live-url-configuration.md",
      public_uat_only: true,
      production_note: "Private production webhook URLs should move behind the hosted backend or workflow-generated runtime config.",
    },
    missing_agents: agents.map((agent) => {
      const agentId = agent.id || "";
      const readiness = agentRuntimeReadiness(agentId);
      const contract = contractByAgent.get(agentId) || {};
      const fixture = `contracts/n8n/fixtures/${agentId.replaceAll("_", "-")}.json`;
      const workflow = `workflows/n8n/${agentId.replaceAll("_", "-")}.workflow.json`;
      const gates = productionAgentRolloutGates({
        agentId,
        fixture,
        fixtureUrl: githubBlobUrl(fixture),
        workflow,
        workflowUrl: githubBlobUrl(workflow),
        configured: readiness.configured,
        approvalBoundary: contract.approval_boundary || "",
      });
      return {
        agent_id: agentId,
        agent_name: agent.name || agentDisplayName(agentId),
        env_var: readiness.envVar || contract.webhook_env_var || "N8N_WEBHOOK_URL",
        github_pages_secret: contract.github_pages_secret || "",
        production_secret: contract.production_secret || "",
        contract_fixture: fixture,
        workflow_blueprint: workflow,
        approval_boundary: contract.approval_boundary || "",
        next_action: readiness.nextAction || "Create/publish the workflow, add public UAT URL, run live probe, capture trace.",
        runtime_patch: JSON.parse(buildSingleAgentRuntimeConfigSnippet(agentId) || "{}"),
        rollout_gates: gates.map((gate) => ({
          gate: gate.key,
          label: gate.label,
          ready: gate.ready,
          detail: gate.detail,
        })),
      };
    }),
    runtime_asset_patch: runtimeAssetPatch ? JSON.parse(runtimeAssetPatch) : {},
    validation_commands: [
      "node --check frontend/app.js",
      "node scripts/validate-agent-config-export.cjs",
      "node scripts/validate-n8n-fixtures.cjs",
      "node scripts/pages-smoke-check.cjs frontend",
    ],
    uat_proof_required: [
      "Fixture replay remains passing.",
      "Public UAT webhook URL is configured in runtime asset or hosted config.",
      "Cockpit live probe reaches n8n workflow.",
      "Non-demo trace is stored for the agent.",
      "Approval-required fixture is respected before external actions.",
    ],
  };
  return JSON.stringify(packet, null, 2);
}

