function buildSingleAgentRuntimeConfigSnippet(agentId) {
  if (!agentId) return "";
  const config = {
    n8nAgentWebhooks: {
      [agentId]: "PASTE_PUBLIC_UAT_WEBHOOK_URL_HERE",
    },
    n8nAgentProbeSlots: {
      [agentId]: configuredProbeSlotSnippet(agentId),
    },
  };
  if (agentId === "knowledge_fabric_agent") config.n8nKnowledgeFabricWebhookUrl = "PASTE_PUBLIC_UAT_WEBHOOK_URL_HERE";
  if (agentId === "agentic_butler") config.n8nAgenticButlerWebhookUrl = "PASTE_PUBLIC_UAT_WEBHOOK_URL_HERE";
  if (agentId === "actor_twin") config.n8nActorTwinWebhookUrl = "PASTE_PUBLIC_UAT_WEBHOOK_URL_HERE";
  return JSON.stringify(config, null, 2);
}

function buildN8nRuntimeConfigSnippet(agents = []) {
  const missing = agents.filter((agent) => agent?.id);
  if (!missing.length) return "";
  const webhookEntries = missing.reduce((acc, agent) => {
    acc[agent.id] = "PASTE_PUBLIC_UAT_WEBHOOK_URL_HERE";
    return acc;
  }, {});
  const config = {
    n8nAgentWebhooks: webhookEntries,
    n8nAgentProbeSlots: missing.reduce((acc, agent) => {
      acc[agent.id] = configuredProbeSlotSnippet(agent.id);
      return acc;
    }, {}),
  };
  missing.forEach((agent) => {
    if (agent.id === "knowledge_fabric_agent") config.n8nKnowledgeFabricWebhookUrl = "PASTE_PUBLIC_UAT_WEBHOOK_URL_HERE";
    if (agent.id === "agentic_butler") config.n8nAgenticButlerWebhookUrl = "PASTE_PUBLIC_UAT_WEBHOOK_URL_HERE";
    if (agent.id === "actor_twin") config.n8nActorTwinWebhookUrl = "PASTE_PUBLIC_UAT_WEBHOOK_URL_HERE";
  });
  return JSON.stringify(config, null, 2);
}

function configuredProbeSlotSnippet(agentId) {
  const defaults = {
    actor_twin: {
      probe_boundary: "Public UAT webhook configured; run Actor Twin intent probe and capture n8n execution trace.",
      next_action: "Run Actor Twin UAT and capture trace evidence.",
    },
    knowledge_fabric_agent: {
      probe_boundary: "Public UAT webhook configured; run Knowledge Fabric ingest/graph handoff probe and capture n8n execution trace.",
      next_action: "Run Knowledge Fabric Agent UAT with upload/transcript fixture.",
    },
    agentic_butler: {
      probe_boundary: "Public UAT webhook configured; run approval-gated skill activation probe and capture n8n execution trace.",
      next_action: "Run Agentic Butler UAT with approved skill activation fixture.",
    },
  };
  return {
    status: "configured",
    ...(defaults[agentId] || {
      probe_boundary: "Public UAT webhook configured; run live probe and capture n8n execution trace.",
      next_action: "Run live UAT probe.",
    }),
  };
}

function renderN8nContractReadiness(agent = {}, readiness = null) {
  const contractSource = readiness?.source || agent.n8n_contract || "";
  const runtimeReadiness = agentRuntimeReadiness(agent.id || readiness?.agent_id || "");
  const configured = Boolean(readiness?.webhook_configured) || runtimeReadiness.configured;
  const probe = state.n8nLiveProbeResults?.[agent.id || readiness?.agent_id || ""];
  const replayPassed = readiness?.replay_status === "passed";
  const status = probe?.status === "connected"
    ? "live connected"
    : readiness
      ? runtimeReadiness.status
      : "missing contract";
  const statusItems = Array.isArray(readiness?.statuses)
    ? readiness.statuses
    : agentContractStatusesFor(agent.id || readiness?.agent_id || "");
  const envVar = {
    actor_twin: "N8N_ACTOR_TWIN_WEBHOOK_URL",
    knowledge_fabric_agent: "N8N_KNOWLEDGE_FABRIC_WEBHOOK_URL",
    agentic_butler: "N8N_AGENTIC_BUTLER_WEBHOOK_URL",
  }[agent.id] || readiness?.webhook_env_var || "N8N_WEBHOOK_URL";
  return `
    <article class="agent-contract-card ${configured ? "ready" : "pending"}">
      <span class="queue-kind">${escapeHtml(status)}</span>
      <strong>${escapeHtml(readiness?.webhook_env_var || envVar)}</strong>
      <p>${escapeHtml(contractSource)}</p>
      <div class="agent-runtime-readiness ${safeGraphClass(runtimeReadiness.status)}">
        <strong>${escapeHtml(runtimeReadiness.label)}</strong>
        <small>${escapeHtml(runtimeReadiness.detail)}</small>
      </div>
      <div class="agent-contract-status-strip" aria-label="Contract statuses">
        ${statusItems.map((item) => `<span class="${safeGraphClass(item)}">${escapeHtml(item)}</span>`).join("")}
      </div>
      ${readiness?.source_url || readiness?.backlog_url ? `
        <div class="agent-contract-links">
          ${readiness?.source_url ? `<a href="${escapeHtml(readiness.source_url)}" target="_blank" rel="noreferrer">Fixture</a>` : ""}
          ${readiness?.backlog_url ? `<a href="${escapeHtml(readiness.backlog_url)}" target="_blank" rel="noreferrer">Backlog</a>` : ""}
          ${state.n8nAgentContracts?.replay_status_url ? `<a href="${escapeHtml(state.n8nAgentContracts.replay_status_url)}" target="_blank" rel="noreferrer">Replay</a>` : ""}
        </div>
      ` : ""}
      <small>${escapeHtml(configured ? "Webhook env var is configured. Run UAT before production use." : "Fixture replay is local/static. Add webhook env var to activate runtime forwarding.")}</small>
      ${readiness?.replay_case_count ? `<small>${escapeHtml(`${readiness.replay_case_count} contract cases replayed locally`)}</small>` : ""}
      ${probe ? `<small class="${escapeHtml(probe.status === "connected" ? "ready" : probe.status === "blocked" ? "warning-copy" : "muted-inline")}">${escapeHtml(`Live probe: ${probe.status} · ${probe.detail || ""}`)}</small>` : ""}
      ${readiness?.blocker ? `<small>${escapeHtml(readiness.blocker)}</small>` : ""}
      ${configured ? "" : renderAgentMissingWebhookInline(agent.id || readiness?.agent_id || "", envVar)}
      <div class="button-row tight">
        <button class="secondary small" type="button" data-agent-contract-test="${escapeHtml(agent.id || "")}">Test contract</button>
        <button class="secondary small" type="button" data-agent-live-probe="${escapeHtml(agent.id || "")}">Probe live</button>
        <button class="secondary small" type="button" data-agent-uat-payload="${escapeHtml(agent.id || "")}">Show UAT payload</button>
        ${agent.id === "knowledge_fabric_agent" ? `
          <button class="secondary small" type="button" data-knowledge-fabric-dry-run="ingest">Ingest payload</button>
          <button class="secondary small" type="button" data-knowledge-fabric-dry-run="graph">Graph payload</button>
          <button class="secondary small" type="button" data-knowledge-fabric-dry-run="vector">Vector payload</button>
        ` : ""}
      </div>
    </article>
  `;
}

