function renderSkillRoutingPanel() {
  const applied = state.skills.filter((skill) => state.appliedChatSkillIds.includes(skill.skill_id));
  const active = state.twins.find((twin) => twin.twin_id === state.activeTwin);
  const switchWarning = recentTwinSwitchWarning();
  const route = state.lastActorTwinRouteDecision || null;
  const agentId = route?.target_agent || "actor_twin";
  const configured = agentId === "human" ? true : hasAgentWebhook(agentId);
  const routeLabel = route
    ? `${route.decision.replaceAll("_", " ")} -> ${agentDisplayName(agentId)}`
    : "Actor Twin routes each request";
  const content = `
      <strong>Actor pipeline</strong>
      <span>${escapeHtml(active?.display_name || state.activeTwin)} · ${escapeHtml(state.riskPosture)} posture · ${escapeHtml(routeLabel)} · ${escapeHtml(configured ? "n8n configured" : "fixture fallback")}</span>
      <p>${escapeHtml(route?.reason || "The Actor Twin decides whether to answer, use knowledge, activate an approved skill, or draft a new skill.")} ${escapeHtml(applied.length ? `${applied.length} approved skill layer${applied.length === 1 ? "" : "s"} available.` : "No approved skill layer selected.")}</p>
      ${switchWarning ? `<p class="warning-copy">${escapeHtml(switchWarning)}</p>` : ""}
    `;
  const chatPanel = $("#chatSkillRouting");
  if (chatPanel) chatPanel.innerHTML = content;
  const runPanel = $("#skillRunRouting");
  if (runPanel) runPanel.innerHTML = content;
}

function renderSkillPreflight() {
  const target = $("#chatSkillPreflight");
  if (!target) return;
  const selected = state.skills.find((skill) => skill.skill_id === state.activeChatSkillId);
  const active = state.twins.find((twin) => twin.twin_id === state.activeTwin);
  if (!selected) {
    target.innerHTML = "";
    return;
  }
  const sourceInput = {
    email_input: $("#chatSkillEmail").value,
    calendar_input: $("#chatSkillCalendar").value,
    teams_input: $("#chatSkillTeams").value,
    knowledge_context: $("#chatSkillKnowledge").value,
  };
  const readiness = sourceReadiness(sourceInput);
  const request = legacyManualRequestValue().trim();
  const decisionPrinciples = active?.decision_principles || "prioritize deadlines, decisions, response time, and stakeholder urgency";
  const twinQuestion = readiness.missing.length
    ? `Before running, ${active?.display_name || state.activeTwin} would ask whether ${readiness.missing.join(", ")} context is intentionally empty.`
    : `${active?.display_name || state.activeTwin} has enough exported context for a first pass.`;
  target.innerHTML = `
    <div>
      <span class="badge">Twin preflight</span>
      <strong>${escapeHtml(twinQuestion)}</strong>
      <p>${escapeHtml(selected.name)} will use ${escapeHtml(readiness.present.join(", ") || "manual request only")} and steer with: ${escapeHtml(decisionPrinciples)}</p>
    </div>
    <div class="source-quality ${escapeHtml(readiness.level)}">
      <strong>${escapeHtml(readiness.label)}</strong>
      <span>${escapeHtml(readiness.detail)}</span>
    </div>
    <div class="preflight-grid">
      <span>${escapeHtml(readiness.readyCount)} source blocks ready</span>
      <span>${escapeHtml(readiness.missing.length)} source blocks open</span>
      <span>${escapeHtml(request ? "request captured" : "request still open")}</span>
    </div>
    ${readiness.followUps.length ? renderPreflightFollowUps(readiness.followUps, "chat") : ""}
  `;
  bindPreflightFollowUps(target);
}

function n8nRetrievalMode() {
  return $("#retrievalModeSelect")?.value || "keyword";
}

function buildN8nChatMetadata() {
  const active = state.twins.find((twin) => twin.twin_id === state.activeTwin);
  const retrievalMode = n8nRetrievalMode();
  const conceptTypes = selectedConceptTypes();
  const retrievalFlags = {
    keyword: retrievalMode === "keyword",
    vectorCache: retrievalMode === "vector-cache",
    knowledgeGraph: retrievalMode === "graph",
    websearch: Boolean(state.webSearchEnabled),
    voiceAnswerRequested: Boolean(state.voiceAnswerEnabled),
  };
  return {
    source: "meids-intellectual-twin",
    interface: "embedded_n8n_chat",
    interfaceContract: "meids.actor_twin.embedded_chat.v1",
    activeTwin: state.activeTwin,
    twinName: active?.display_name || state.activeTwin,
    posture: state.riskPosture || "balanced",
    routingAuthority: "actor_twin_n8n",
    retrieval: {
      mode: retrievalMode,
      searchStrategy: retrievalMode,
      conceptTypes,
      ...retrievalFlags,
    },
    routingHints: {
      answerDirectFirst: true,
      useKnowledgeFabricWhen: [
        "knowledge retrieval needs OKF, vector cache, graph, evidence, or source ingestion",
        "the user asks to remember, ingest, update, classify, review, or connect knowledge",
      ],
      useAgenticButlerWhen: [
        "the user asks for a work artifact, approved skill execution, planning, drafting, synthesis, or workflow support",
        "the user asks to create or refine a new skill, task agent, or agent behavior proposal",
      ],
      approvalBoundary: "Only require approval before a generated skill/agent/task-agent becomes active, or before real external write/send/schedule/publish/delete/commit actions.",
    },
    agentTools: {
      knowledgeFabric: "call_n8n_workflow_tool",
      agenticButler: "call_n8n_workflow_tool",
    },
  };
}

function renderN8nInteractionContext() {
  const target = $("#n8nInteractionContext");
  if (!target) return;
  const context = buildN8nChatMetadata();
  const scopes = context.retrieval.conceptTypes.slice(0, 6);
  const extraCount = Math.max(0, context.retrieval.conceptTypes.length - scopes.length);
  target.innerHTML = `
    <div>
      <span class="badge">n8n routing context</span>
      <strong>${escapeHtml(context.twinName)} · ${escapeHtml(context.posture)} posture · ${escapeHtml(context.retrieval.mode)}</strong>
      <p>Actor Twin receives these settings as chat metadata. Apply after changing keyword, vector cache, graph, websearch, voice, or source-scope settings.</p>
    </div>
    <div class="n8n-context-chips" aria-label="n8n interaction context">
      <span>${escapeHtml(context.retrieval.websearch ? "websearch on" : "websearch off")}</span>
      <span>${escapeHtml(context.retrieval.voiceAnswerRequested ? "voice requested" : "voice off")}</span>
      <span>${escapeHtml(context.retrieval.keyword ? "keyword routing" : "keyword optional")}</span>
      <span>${escapeHtml(context.retrieval.vectorCache ? "vector cache" : "vector cache optional")}</span>
      <span>${escapeHtml(context.retrieval.knowledgeGraph ? "knowledge graph" : "graph optional")}</span>
      ${scopes.map((scope) => `<span>${escapeHtml(scope)}</span>`).join("")}
      ${extraCount ? `<span>+${extraCount} scopes</span>` : ""}
    </div>
  `;
}

function reloadN8nChatContext() {
  state.n8nChatLoaded = false;
  state.n8nChatLoading = false;
  const mount = $("#n8nChatMount");
  if (mount) mount.innerHTML = "";
  renderN8nInteractionContext();
  void ensureN8nChat();
}

async function ensureN8nChat() {
  const status = $("#n8nChatStatus");
  const mount = $("#n8nChatMount");
  const webhookUrl = runtimeConfig.n8nChatWebhookUrl || "";
  removeLegacyActorTwinComposer();
  if (!runtimeConfig.n8nChatEnabled) {
    if (status) status.textContent = "n8n chat is disabled in runtime config.";
    return;
  }
  if (!webhookUrl) {
    if (status) status.textContent = "n8n webhook URL is missing in runtime config.";
    return;
  }
  if (state.n8nChatLoaded || state.n8nChatLoading) return;
  state.n8nChatLoading = true;
  if (status) status.textContent = "Loading n8n chat...";
  try {
    ensureStylesheet("n8n-chat-style", N8N_CHAT_CSS_URL);
    const module = await import(N8N_CHAT_MODULE_URL);
    mount.innerHTML = "";
    module.createChat({
      webhookUrl,
      target: "#n8nChatMount",
      mode: "fullscreen",
      showWelcomeScreen: false,
      loadPreviousSession: true,
      metadata: buildN8nChatMetadata(),
      initialMessages: [
        "Hi, I'm at your Service :).",
        "Send the task or context you want this workflow to process.",
      ],
      i18n: {
        en: {
          title: "Actor Twin",
          subtitle: "n8n orchestration",
          inputPlaceholder: "Ask the Actor Twin...",
        },
      },
    });
    state.n8nChatLoaded = true;
    if (status) status.textContent = "n8n agent connected.";
  } catch (error) {
    if (status) status.textContent = `n8n chat failed to load: ${error.message}`;
    showToast("n8n chat unavailable", error.message, "error");
  } finally {
    state.n8nChatLoading = false;
  }
}

async function askTwinViaN8n(query) {
  const webhookUrl = runtimeConfig.n8nChatWebhookUrl || "";
  if (!webhookUrl) throw new Error("n8n webhook URL is missing in runtime config.");
  const appliedSkills = state.skills
    .filter((skill) => state.appliedChatSkillIds.includes(skill.skill_id))
    .map((skill) => ({
      skill_id: skill.skill_id,
      name: skill.name,
      risk_class: skill.risk_class || "",
      status: skill.status || "",
      description: skill.description || "",
    }));
  const payload = {
    action: "sendMessage",
    sessionId: state.n8nSessionId,
    chatInput: query,
    metadata: {
      source: "meids-intellectual-twin",
      activeTwin: state.activeTwin,
      riskPosture: state.riskPosture,
      websearch: state.webSearchEnabled,
      retrievalMode: $("#retrievalModeSelect")?.value || "keyword",
      conceptTypes: selectedConceptTypes(),
      appliedSkills,
      sourceContext: {
        email_input: $("#chatSkillEmail")?.value || "",
        calendar_input: $("#chatSkillCalendar")?.value || "",
        teams_input: $("#chatSkillTeams")?.value || "",
        knowledge_context: $("#chatSkillKnowledge")?.value || "",
      },
      graphContext: state.graphSkillContextPacket || null,
    },
  };
  const response = await fetch(webhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  const raw = await response.text();
  if (!response.ok) {
    throw new Error(raw || `n8n returned ${response.status}`);
  }
  let data = raw;
  try {
    data = raw ? JSON.parse(raw) : {};
  } catch {
    data = raw;
  }
  return {
    answer: extractN8nAnswer(data),
    metadata: {
      retrieval_mode: "n8n",
      confidence: 0,
      sources: [],
      n8n: {
        sessionId: state.n8nSessionId,
        riskPosture: state.riskPosture,
        websearch: state.webSearchEnabled,
        appliedSkills: appliedSkills.map((skill) => skill.name),
        graphContextAttached: Boolean(state.graphSkillContextPacket),
      },
    },
  };
}

function extractN8nAnswer(data) {
  if (typeof data === "string") return data || "n8n workflow completed without text output.";
  if (Array.isArray(data)) {
    return data.map(extractN8nAnswer).filter(Boolean).join("\n\n") || "n8n workflow completed.";
  }
  if (!data || typeof data !== "object") return "n8n workflow completed.";
  return (
    data.output ||
    data.text ||
    data.answer ||
    data.response ||
    data.message ||
    data.data?.output ||
    data.data?.text ||
    data.data?.answer ||
    JSON.stringify(data, null, 2)
  );
}

function ensureStylesheet(id, href) {
  if (document.getElementById(id)) return;
  const link = document.createElement("link");
  link.id = id;
  link.rel = "stylesheet";
  link.href = href;
  document.head.appendChild(link);
}

