function sourceReadiness(inputs) {
  const sourceMap = [
    ["email_input", "Email", "Paste recent email threads or stakeholder asks."],
    ["calendar_input", "Calendar", "Paste calendar blockers, attendees, deadlines, or meeting context."],
    ["teams_input", "Teams", "Paste Teams messages or channel updates with decisions and blockers."],
    ["knowledge_context", "Knowledge", "Paste project notes, KPIs, prior documents, or decision logs."],
  ];
  const present = sourceMap.filter(([key]) => String(inputs[key] || "").trim()).map(([, label]) => label);
  const missingItems = sourceMap.filter(([key]) => !String(inputs[key] || "").trim());
  const missing = missingItems.map(([, label]) => label.toLowerCase());
  const followUps = missingItems.map(([key, label, prompt]) => ({ key, label, prompt }));
  const readyCount = present.length;
  let level = "low";
  let label = "Manual-only context";
  let detail = "The twin can run, but priorities may be weaker without exported work sources.";
  if (readyCount >= 3) {
    level = "high";
    label = "Strong source context";
    detail = "Enough exported context for a grounded first pass.";
  } else if (readyCount >= 1) {
    level = "medium";
    label = "Partial source context";
    detail = "Usable for a draft, with follow-up needed for missing streams.";
  }
  return { present, missing, followUps, readyCount, level, label, detail };
}

async function confirmSkillFollowUpGate(inputs, surface) {
  const readiness = sourceReadiness(inputs);
  if (readiness.readyCount > 0) return true;
  const prefix = surface === "chat"
    ? "The twin has only your chat request for this skill run."
    : "The twin has only your manual request for this skill run.";
  const followUpText = readiness.followUps.map((item) => `${item.label}: ${item.prompt}`).join("\n- ");
  return requestDecision({
    eyebrow: "Source preflight",
    title: "Continue without exported sources?",
    body: `${prefix}\n\nSuggested follow-up inputs:\n- ${followUpText}`,
    confirmLabel: "Continue",
  });
}

function bindPreflightFollowUps(root = document) {
  root.querySelectorAll(".preflight-followup-btn").forEach((button) => {
    button.addEventListener("click", () => {
      const target = $(`#${CSS.escape(button.dataset.target || "")}`);
      if (!target) return;
      target.scrollIntoView({ block: "center", behavior: "smooth" });
      target.focus();
    });
  });
}

function chatAgentContractStatuses() {
  const contracts = state.n8nAgentContracts?.contracts || [];
  const byAgent = new Map(contracts.map((contract) => [contract.agent_id, contract]));
  const productionAgents = productionAgentUrlReadiness();
  const productionByAgent = new Map(productionAgents.map((agent) => [agent.agentId, agent]));
  return ["actor_twin", "knowledge_fabric_agent", "agentic_butler"].map((agentId) => {
    const contract = byAgent.get(agentId) || {};
    const productionAgent = productionByAgent.get(agentId) || {};
    const gates = productionAgentRolloutGates(productionAgent);
    const readyGateCount = gates.filter((gate) => gate.ready).length;
    const openGates = gates.filter((gate) => !gate.ready).map((gate) => gate.label.toLowerCase());
    const runtimeReadiness = agentRuntimeReadiness(agentId);
    const configured = runtimeReadiness.configured || Boolean(contract.webhook_configured);
    const contractStatuses = new Set(Array.isArray(contract.statuses) ? contract.statuses : []);
    const replayPassed = state.n8nAgentContracts?.replay_status === "passed" || contract.replay_status === "passed";
    const contractTested = replayPassed || contractStatuses.has("contract tested");
    const probe = mergedN8nProbeEvidence(agentId);
    const replayCaseCount = Number(contract.replay_case_count || contract.case_count || 0);
    const runtimeState = runtimeReadiness.status || "";
    const n8nConnected = probe?.status === "connected" && probe?.demo !== true && Boolean(probe?.trace_id);
    const webhookLabel = probe?.status === "connected"
      ? "live probe ok"
      : configured
        ? runtimeReadiness.urlSourceLabel || "URL configured"
        : runtimeState === "awaiting URL"
          ? "URL slot ready"
          : "fixture only";
    const stageItems = [
      {
        key: "documented",
        label: "Documented",
        ready: true,
        detail: contract.source || "Contract fixture documented.",
      },
      {
        key: "fixture-ready",
        label: "Fixture",
        ready: replayPassed || contractStatuses.has("fixture ready"),
        detail: replayPassed ? `${replayCaseCount || state.n8nAgentContracts?.replay_case_count || 0} replay cases passed.` : "Fixture replay has not passed.",
      },
      {
        key: "contract-tested",
        label: "Tested",
        ready: contractTested,
        detail: contractTested ? "Contract replay validation passed." : "Run fixture replay before rollout.",
      },
      {
        key: "n8n-connected",
        label: "n8n",
        ready: n8nConnected,
        detail: n8nConnected ? "Live workflow probe reached n8n." : (configured ? "URL configured; live probe pending." : "Live URL missing."),
      },
    ];
    const stateLabel = n8nConnected
      ? "n8n connected"
      : configured
        ? "configured"
        : runtimeState === "awaiting URL"
          ? "awaiting URL"
          : contract.live_status_label === "blocked"
            ? "blocked"
            : contractTested
              ? "contract tested"
              : replayPassed
                ? "fixture ready"
                : "documented";
    return {
      agentId,
      label: agentDisplayName(agentId),
      state: stateLabel,
      detail: runtimeReadiness.detail,
      nextAction: runtimeReadiness.nextAction || "",
      configured,
      replayPassed,
      contractTested,
      replayCaseCount,
      webhookLabel,
      urlSource: runtimeReadiness.urlSource || "missing",
      urlSourceLabel: runtimeReadiness.urlSourceLabel || "",
      probe,
      probeCheckedAt: probe?.checked_at || "",
      probeTraceId: probe?.trace_id || "",
      probeLastError: probe?.last_error || "",
      readyGateCount,
      totalGateCount: gates.length,
      openGates,
      stageItems,
      active: chatModeAgentId() === agentId,
    };
  });
}

function chatModeAgentId() {
  if (state.activeChatInteractionMode === "skill_activation") return "agentic_butler";
  if (state.activeChatInteractionMode === "source_context") return "knowledge_fabric_agent";
  return "actor_twin";
}

function renderChatContractBadges() {
  const target = $("#chatContractBadges");
  if (!target) return;
  target.innerHTML = chatAgentContractStatuses()
    .map((item) => `
      <span class="${item.active ? "active" : ""} ${item.configured ? "configured" : "fixture"} ${safeGraphClass(item.state)}" title="${escapeHtml(item.detail)}">
        <strong>${escapeHtml(item.label)}</strong>
        <small>${escapeHtml(item.state)}</small>
        <em>${escapeHtml(item.detail)}</em>
        ${renderChatContractStageRow(item.stageItems, { compact: true })}
      </span>
    `)
    .join("");
}

function renderChatContractStageRow(stages = [], options = {}) {
  if (!stages.length) return "";
  const compact = options.compact ? " compact" : "";
  return `
    <span class="chat-contract-stage-row${compact}" aria-label="Contract readiness stages">
      ${stages.map((stage) => `
        <span class="${stage.ready ? "ready" : "pending"} ${escapeHtml(stage.key || "")}" title="${escapeHtml(stage.detail || "")}">
          ${escapeHtml(stage.label || "")}
        </span>
      `).join("")}
    </span>
  `;
}

function persistedN8nProbeEvidence(agentId = "") {
  const agents = Array.isArray(state.n8nLiveProbeEvidenceStatus?.agents)
    ? state.n8nLiveProbeEvidenceStatus.agents
    : [];
  return agents.find((agent) => agent.agent_id === agentId) || null;
}

function mergedN8nProbeEvidence(agentId = "") {
  const persisted = persistedN8nProbeEvidence(agentId) || {};
  const session = state.n8nLiveProbeResults?.[agentId] || {};
  return {
    ...persisted,
    ...session,
    evidence: {
      ...(persisted.evidence || {}),
      ...(session.evidence || {}),
    },
    ai_agent: session.ai_agent || persisted.ai_agent || null,
  };
}

