function writeStaticConceptStore(concepts = state.concepts) {
  window.localStorage.setItem(storageKeys.concepts, JSON.stringify((concepts || []).slice(0, 250)));
}

function staticConceptPath(twin, type, title) {
  const day = new Date().toISOString().slice(0, 10);
  const folder = staticTwinSlug(type || "concept");
  const slug = staticTwinSlug(title || `concept-${Date.now().toString(36)}`);
  return `okf/static/generated/concepts/${staticTwinSlug(twin || "twin")}/${folder}/${day}-${slug}.md`;
}

function createStaticConceptFromSource({ title, description, type = "Source Upload", sourceType = "manual", sourceName = "manual source", content = "" } = {}) {
  const now = new Date().toISOString();
  const safeTitle = String(title || sourceName || "Untitled source").trim().slice(0, 120) || "Untitled source";
  const body = String(content || description || "").trim();
  const concept = {
    path: staticConceptPath(state.activeTwin, type, safeTitle),
    title: safeTitle,
    type,
    cluster: "source-intake",
    tags: [staticTwinSlug(sourceType), "pending-review"].filter(Boolean),
    description: body ? compactText(body, 220) : `Static Pages source intake for ${safeTitle}.`,
    body,
    review_state: "pending-review",
    source_anchor: sourceName,
    source_deep_link: `browser-local://${staticTwinSlug(sourceName)}`,
    curation_method: "github-pages-local",
    created_at: now,
    updated_at: now,
    fabric: {
      okf_layer: "concept",
      okf_maturity: "draft",
      retrieval_profiles: ["facts"],
      actor_signal: "pending-source-review",
      evidence_strength: "browser-local",
      vector_state: "deferred",
    },
  };
  state.concepts = [concept, ...(state.concepts || buildStaticPagesConcepts())];
  writeStaticConceptStore(state.concepts);
  appendStaticActivity("ingest", {
    action: "created_local_concept",
    title: safeTitle,
    path: concept.path,
    source: sourceName,
    timestamp: now,
  });
  return {
    status: "created_local",
    mode: "github-pages-local",
    concept,
    concept_path: concept.path,
    review_state: concept.review_state,
    note: "Stored in browser-local staging. Hosted backend is required for repository persistence.",
  };
}

function readStaticActivityStore() {
  const activity = safeParseLocalJson(storageKeys.activity, { crud: [], ingest: [], evidence: [], answer_traces: [] });
  return {
    crud: Array.isArray(activity.crud) ? activity.crud : [],
    ingest: Array.isArray(activity.ingest) ? activity.ingest : [],
    evidence: Array.isArray(activity.evidence) ? activity.evidence : [],
    answer_traces: Array.isArray(activity.answer_traces) ? activity.answer_traces : [],
  };
}

function writeStaticActivityStore(activity) {
  window.localStorage.setItem(storageKeys.activity, JSON.stringify({
    crud: (activity.crud || []).slice(0, 100),
    ingest: (activity.ingest || []).slice(0, 100),
    evidence: (activity.evidence || []).slice(0, 100),
    answer_traces: (activity.answer_traces || []).slice(0, 100),
  }));
}

function appendStaticActivity(kind, entry = {}) {
  const activity = readStaticActivityStore();
  const item = {
    ...entry,
    twin: state.activeTwin,
    actor: entry.actor || "local-user",
    timestamp: entry.timestamp || new Date().toISOString(),
    mode: "github-pages-local",
  };
  const bucket = Array.isArray(activity[kind]) ? kind : "crud";
  activity[bucket] = [item, ...activity[bucket]].slice(0, 100);
  writeStaticActivityStore(activity);
  return activity;
}

function switchChatInteractionMode(mode) {
  state.activeChatInteractionMode = mode || "actor_twin";
  state.chatContractActionResult = null;
  const select = $("#chatInteractionModeSelect");
  if (select) select.value = state.activeChatInteractionMode;
  if (state.activeChatInteractionMode === "source_context") {
    $("#chatSkillContext").open = true;
  }
  if (state.activeChatInteractionMode === "skill_activation") {
    $("#chatInteractionSetup").open = true;
  }
  renderChatSkillMode();
}

function renderChatInlineModeBadges() {
  const target = $("#chatInlineModeBadges");
  if (!target) return;
  const statuses = new Map(chatAgentContractStatuses().map((item) => [item.agentId, item]));
  target.innerHTML = chatModeButtonDefinitions().map((mode) => {
    const status = statuses.get(mode.agentId) || {};
    const active = state.activeChatInteractionMode === mode.mode;
    const stateLabel = status.state || "documented";
    const configuredLabel = status.webhookLabel || (status.configured ? "URL" : "fixture");
    const gateLabel = `${status.readyGateCount ?? 0}/${status.totalGateCount ?? 6}`;
    return `
      <button class="chat-inline-mode-badge ${active ? "active" : ""} ${status.configured ? "configured" : "fixture"} ${safeGraphClass(stateLabel)}" type="button" data-chat-mode="${escapeHtml(mode.mode)}" title="${escapeHtml(`${mode.label}: ${stateLabel}. ${status.detail || ""}`)}">
        <strong>${escapeHtml(mode.shortLabel)}</strong>
        <span>${escapeHtml(stateLabel)}</span>
        <small>${escapeHtml(`${gateLabel} · ${configuredLabel}`)}</small>
      </button>
    `;
  }).join("");
  target.querySelectorAll("[data-chat-mode]").forEach((button) => {
    button.addEventListener("click", () => switchChatInteractionMode(button.dataset.chatMode || "actor_twin"));
  });
}

function renderCompactAgentBoundary(agentIds = [], options = {}) {
  const statuses = new Map(chatAgentContractStatuses().map((item) => [item.agentId, item]));
  const items = agentIds.map((agentId) => statuses.get(agentId)).filter(Boolean);
  if (!items.length) return "";
  return `
    <section class="agent-runtime-boundary-strip" aria-label="${escapeHtml(options.label || "Agent runtime boundary")}">
      <div class="agent-runtime-boundary-head">
        <span class="badge">${escapeHtml(options.label || "Agent boundary")}</span>
        <small>${escapeHtml(options.detail || "Fixture replay and live n8n readiness are tracked separately.")}</small>
      </div>
      <div class="agent-runtime-boundary-grid">
        ${items.map((item) => {
          const configuredLabel = item.webhookLabel || (item.configured ? "URL configured" : "fixture only");
          const gateLabel = `${item.readyGateCount ?? 0}/${item.totalGateCount ?? 6} gates`;
          const replayLabel = item.replayCaseCount ? `${item.replayCaseCount} replay cases` : "no replay evidence";
          return `
            <article class="${item.configured ? "configured" : "fixture"} ${safeGraphClass(item.state || "documented")}" title="${escapeHtml(item.detail || "")}">
              <strong>${escapeHtml(item.label || agentDisplayName(item.agentId))}</strong>
              <span>${escapeHtml(item.state || "documented")}</span>
              <small>${escapeHtml(`${gateLabel} · ${configuredLabel} · ${replayLabel}`)}</small>
              ${renderChatContractStageRow(item.stageItems, { compact: true })}
            </article>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

