function renderChatRuntimeSetupShortcuts() {
  const target = $("#chatRuntimeSetupShortcuts");
  if (!target) return;
  const missing = chatAgentContractStatuses().filter((item) => !item.configured);
  if (!missing.length) {
    const configured = chatAgentContractStatuses().filter((item) => item.configured);
    target.innerHTML = configured.length ? `
      <div class="chat-runtime-setup-ready">
        <strong>Live agent URLs configured</strong>
        <span>${escapeHtml(configured.map((item) => item.label).join(", "))}</span>
      </div>
    ` : "";
    return;
  }
  const missingSnippet = buildN8nRuntimeConfigSnippet(missing.map((item) => ({ id: item.agentId })));
  const setupPacket = {
    purpose: "Add missing public UAT webhook URLs so Chat can route live requests to external n8n agents.",
    config_file: "frontend/assets/agent-runtime-config.json",
    setup_guide: "docs/n8n-live-url-configuration.md",
    missing_agents: missing.map((item) => ({
      agent_id: item.agentId,
      label: item.label,
      env_key: item.envVar || agentRuntimeReadiness(item.agentId).envVar,
      current_state: item.state,
      next_action: item.nextAction || agentRuntimeReadiness(item.agentId).nextAction,
      fixture_status: item.replayPassed ? "fixture replay passed" : "fixture documented",
    })),
  };
  const localOverrideControls = missing.map((item) => renderAgentWebhookOverrideControl(item.agentId, {
    compact: true,
    label: `${item.label} public UAT URL`,
  })).join("");
  target.innerHTML = `
    <section class="chat-runtime-missing-card">
      <div>
        <strong>Live URL setup needed</strong>
        <span>${escapeHtml(missing.map((item) => item.label).join(", "))}</span>
        <small>Fixture contracts are ready; live n8n routing waits for public UAT webhook URLs.</small>
      </div>
      <div class="button-row tight">
        <button class="secondary small" type="button" data-chat-action="open-interaction-setup">Open setup</button>
        <button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(JSON.stringify(setupPacket, null, 2))}">Copy setup packet</button>
        ${missingSnippet ? `<button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(missingSnippet)}">Copy runtime JSON</button>` : ""}
        <a class="secondary small" href="${escapeHtml(githubBlobUrl("docs/n8n-live-url-configuration.md"))}" target="_blank" rel="noreferrer">Setup guide</a>
      </div>
      ${localOverrideControls ? `
        <div class="chat-runtime-local-overrides" aria-label="Browser-local n8n UAT URL overrides">
          ${localOverrideControls}
        </div>
      ` : ""}
    </section>
  `;
  target.querySelectorAll("[data-agent-webhook-action]").forEach((button) => {
    button.addEventListener("click", () => handleAgentWebhookOverrideAction(button));
  });
}

function renderChatContractActions() {
  const target = $("#chatContractActions");
  if (!target) return;
  const activeAgentId = chatModeAgentId();
  const readiness = agentRuntimeReadiness(activeAgentId);
  const result = state.chatContractActionResult;
  const uatLabel = activeAgentId === "knowledge_fabric_agent"
    ? "Show ingest payload"
    : activeAgentId === "agentic_butler"
      ? "Show skill payload"
      : "Show answer payload";
  const configSnippet = buildSingleAgentRuntimeConfigSnippet(activeAgentId);
  target.innerHTML = `
    <div>
      <strong>${escapeHtml(agentDisplayName(activeAgentId))}</strong>
      <span>${escapeHtml(readiness.label || readiness.status || "Contract status")}</span>
      <small>${escapeHtml(readiness.nextAction || readiness.detail || "")}</small>
    </div>
    <div class="button-row tight">
      <button class="secondary small" type="button" data-chat-contract-action="show-uat" data-agent-id="${escapeHtml(activeAgentId)}">${escapeHtml(uatLabel)}</button>
      <button class="secondary small" type="button" data-chat-contract-action="probe-live" data-agent-id="${escapeHtml(activeAgentId)}">Probe live</button>
      ${readiness.configured ? "" : `
        <button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(readiness.envVar || "N8N_WEBHOOK_URL")}">Copy key</button>
        ${configSnippet ? `<button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(configSnippet)}">Copy JSON</button>` : ""}
      `}
      <a class="secondary small" href="${escapeHtml(githubBlobUrl("docs/n8n-live-url-configuration.md"))}" target="_blank" rel="noreferrer">Setup guide</a>
    </div>
    ${result ? `
      <pre class="output compact-output chat-contract-action-output">${escapeHtml(JSON.stringify(result.payload || result, null, 2))}</pre>
    ` : ""}
  `;
  target.querySelectorAll("[data-chat-contract-action]").forEach((button) => {
    button.addEventListener("click", async () => {
      const agentId = button.dataset.agentId || activeAgentId;
      if (button.dataset.chatContractAction === "show-uat") {
        state.chatContractActionResult = {
          type: "uat_payload",
          agent_id: agentId,
          status: hasAgentWebhook(agentId) ? "webhook configured" : "fixture ready",
          runtime: agentRuntimeReadiness(agentId),
          payload: buildUatEnvelope(agentId),
        };
        renderChatContractActions();
        showToast("UAT payload ready", agentDisplayName(agentId), "success");
        return;
      }
      if (button.dataset.chatContractAction === "probe-live") {
        await probeAgentContract(agentId);
        state.chatContractActionResult = {
          type: "live_probe",
          agent_id: agentId,
          status: state.n8nLiveProbeResults?.[agentId]?.status || "unknown",
          detail: state.n8nLiveProbeResults?.[agentId]?.detail || "",
          runtime: agentRuntimeReadiness(agentId),
          payload: buildAgentLiveProbeEnvelope(agentId),
        };
        renderChatContractActions();
      }
    });
  });
}

function renderActiveChatContractBadge() {
  const target = $("#activeChatContractBadge");
  if (!target) return;
  const activeAgentId = chatModeAgentId();
  const active = chatAgentContractStatuses().find((item) => item.agentId === activeAgentId) || {};
  const stateLabel = active.state || "documented";
  const detail = active.detail || "Contract status not loaded yet.";
  const configuredLabel = stateLabel === "n8n connected"
    ? "live"
    : active.configured
      ? active.webhookLabel || "URL configured"
      : active.replayPassed
        ? "fixture"
        : "planned";
  const replayLabel = active.replayCaseCount ? `${active.replayCaseCount} cases` : "no replay";
  const gateLabel = `${active.readyGateCount ?? 0}/${active.totalGateCount ?? 6} gates`;
  const blockerLabel = active.openGates?.length ? `open: ${active.openGates.join(", ")}` : "all gates ready";
  const nextAction = active.nextAction || (active.configured ? "Run live probe." : "Add live URL when available.");
  const sourceLabel = active.configured ? active.urlSourceLabel || active.webhookLabel || "URL configured" : "fixture only";
  target.className = `chat-active-contract-badge ${safeGraphClass(stateLabel)} ${active.configured ? "configured" : "fixture"}`;
  target.title = `${detail} ${nextAction}`;
  target.innerHTML = `
    <strong>${escapeHtml(active.label || agentDisplayName(activeAgentId))}</strong>
    <small>${escapeHtml(stateLabel)}</small>
    <em>${escapeHtml(`${gateLabel} · ${configuredLabel} · ${sourceLabel} · ${replayLabel}`)}</em>
    <span>${escapeHtml(`${blockerLabel}. ${nextAction}`)}</span>
    ${renderChatContractStageRow(active.stageItems, { compact: true })}
  `;
}

function agentRuntimeReadiness(agentId) {
  const webhookUrl = getAgentWebhook(agentId);
  const hasUrl = Boolean(webhookUrl);
  const urlSource = getAgentWebhookSource(agentId);
  const probe = state.n8nLiveProbeResults?.[agentId];
  const slot = n8nAgentProbeSlot(agentId);
  const runtimeStatus = n8nRuntimeReadinessFor(agentId);
  const envVar = {
    actor_twin: "N8N_ACTOR_TWIN_WEBHOOK_URL",
    knowledge_fabric_agent: "N8N_KNOWLEDGE_FABRIC_WEBHOOK_URL",
    agentic_butler: "N8N_AGENTIC_BUTLER_WEBHOOK_URL",
  }[agentId] || "N8N_WEBHOOK_URL";
  if (runtimeStatus?.runtime_ready && runtimeStatus.status === "internal_tool_via_actor_twin") {
    return {
      status: "internal n8n tool",
      label: "Actor Twin workflow tool",
      detail: runtimeStatus.detail || slot.probe_boundary || "Called by the embedded Actor Twin workflow inside n8n; no direct public worker URL is required for the frontend.",
      nextAction: runtimeStatus.next_action || slot.next_action || "Verify the Actor Twin n8n workflow calls this worker as a workflow tool during UAT.",
      configured: true,
      envVar,
      runtimeStatus,
      urlSource: "internal-n8n-tool",
      urlSourceLabel: "internal n8n tool",
    };
  }
  if (probe?.status === "connected") {
    return {
      status: "n8n connected",
      label: "Live workflow connected",
      detail: probe.detail || "Last probe reached the n8n workflow.",
      configured: true,
      envVar,
      runtimeStatus,
      urlSource,
      urlSourceLabel: agentWebhookSourceLabel(urlSource),
    };
  }
  if (hasUrl) {
    return {
      status: "configured",
      label: urlSource === "browser-local" ? "Browser-local UAT URL configured" : "Webhook URL configured",
      detail: urlSource === "browser-local"
        ? "This browser uses a local public UAT webhook override. It is not committed and does not update the static readiness artifact."
        : runtimeStatus?.detail || slot.probe_boundary || (staticPagesMode
          ? "Static Pages can hold the URL; production UAT still needs workflow confirmation."
          : "Ready for backend/live probe."),
      nextAction: runtimeStatus?.next_action || slot.next_action || "Run live probe and capture trace evidence.",
      configured: true,
      envVar,
      runtimeStatus,
      urlSource,
      urlSourceLabel: agentWebhookSourceLabel(urlSource),
    };
  }
  return {
    status: runtimeStatus?.status === "awaiting_url" || slot.status === "awaiting_url" ? "awaiting URL" : "missing URL",
    label: runtimeStatus?.status === "awaiting_url" || slot.status === "awaiting_url" ? "Probe slot ready" : "Live URL missing",
    detail: runtimeStatus?.detail || slot.probe_boundary || `${envVar} is empty in runtime config; fixture replay remains available.`,
    nextAction: runtimeStatus?.next_action || slot.next_action || `Add ${envVar} when the n8n workflow is exposed.`,
    configured: false,
    envVar,
    runtimeStatus,
    urlSource: "missing",
    urlSourceLabel: "missing URL",
  };
}

function n8nRuntimeReadinessFor(agentId) {
  const agents = Array.isArray(state.n8nRuntimeReadinessStatus?.agents)
    ? state.n8nRuntimeReadinessStatus.agents
    : [];
  return agents.find((agent) => agent.agent_id === agentId) || null;
}

function agentContractStatusesFor(agentId) {
  const runtimeReadiness = agentRuntimeReadiness(agentId);
  return [
    "documented",
    "fixture ready",
    "contract tested",
    runtimeReadiness.configured ? runtimeReadiness.status : "missing URL",
  ];
}

async function loadAgentRuntimeConfig() {
  if (!staticPagesMode) return;
  try {
    const config = await fetchFrontendAssetJson(N8N_AGENT_RUNTIME_CONFIG_PATH, { optional: true });
    if (!config) return;
    mergeAgentRuntimeConfig(config);
  } catch (error) {
    console.info("Optional agent runtime config unavailable", error);
  }
}

function mergeAgentRuntimeConfig(config = {}) {
  const agentWebhooks = {
    ...(runtimeConfig.n8nAgentWebhooks || runtimeConfig.n8n_agent_webhooks || {}),
    ...(config.n8nAgentWebhooks || config.n8n_agent_webhooks || {}),
  };
  const agentProbeSlots = {
    ...(runtimeConfig.n8nAgentProbeSlots || runtimeConfig.n8n_agent_probe_slots || {}),
    ...(config.n8nAgentProbeSlots || config.n8n_agent_probe_slots || {}),
  };
  runtimeConfig.n8nAgentWebhooks = agentWebhooks;
  runtimeConfig.n8nAgentProbeSlots = agentProbeSlots;
  runtimeConfig.n8nActorTwinWebhookUrl = runtimeConfig.n8nActorTwinWebhookUrl
    || config.n8nActorTwinWebhookUrl
    || agentWebhooks.actor_twin
    || runtimeConfig.n8nChatWebhookUrl
    || "";
  runtimeConfig.n8nKnowledgeFabricWebhookUrl = runtimeConfig.n8nKnowledgeFabricWebhookUrl
    || config.n8nKnowledgeFabricWebhookUrl
    || agentWebhooks.knowledge_fabric_agent
    || "";
  runtimeConfig.n8nAgenticButlerWebhookUrl = runtimeConfig.n8nAgenticButlerWebhookUrl
    || config.n8nAgenticButlerWebhookUrl
    || agentWebhooks.agentic_butler
    || "";
}

function n8nAgentWebhooks() {
  return runtimeConfig.n8nAgentWebhooks || runtimeConfig.n8n_agent_webhooks || {};
}

function getAgentWebhook(agentId) {
  const overrides = readAgentWebhookOverrides();
  const override = overrides[agentId] || overrides[agentId?.replaceAll("_", "-")];
  if (override) return override;
  const webhooks = n8nAgentWebhooks();
  const direct = webhooks[agentId] || webhooks[agentId?.replaceAll("_", "-")];
  if (direct) return direct;
  if (agentId === "actor_twin") return runtimeConfig.n8nActorTwinWebhookUrl || runtimeConfig.n8nChatWebhookUrl || "";
  if (agentId === "agentic_butler") return runtimeConfig.n8nAgenticButlerWebhookUrl || "";
  if (agentId === "knowledge_fabric_agent") return runtimeConfig.n8nKnowledgeFabricWebhookUrl || "";
  return "";
}

function getAgentWebhookSource(agentId) {
  const overrides = readAgentWebhookOverrides();
  if (overrides[agentId] || overrides[agentId?.replaceAll("_", "-")]) return "browser-local";
  const webhooks = n8nAgentWebhooks();
  if (webhooks[agentId] || webhooks[agentId?.replaceAll("_", "-")]) return "runtime-asset";
  if (agentId === "actor_twin" && (runtimeConfig.n8nActorTwinWebhookUrl || runtimeConfig.n8nChatWebhookUrl)) return "runtime-asset";
  if (agentId === "agentic_butler" && runtimeConfig.n8nAgenticButlerWebhookUrl) return "runtime-asset";
  if (agentId === "knowledge_fabric_agent" && runtimeConfig.n8nKnowledgeFabricWebhookUrl) return "runtime-asset";
  return "missing";
}

function agentWebhookSourceLabel(source = "") {
  return {
    "browser-local": "browser-local UAT override",
    "runtime-asset": "runtime asset",
    missing: "missing URL",
  }[source] || source || "missing URL";
}

function n8nAgentProbeSlots() {
  return runtimeConfig.n8nAgentProbeSlots || runtimeConfig.n8n_agent_probe_slots || {};
}

function n8nAgentProbeSlot(agentId) {
  const slots = n8nAgentProbeSlots();
  return slots[agentId] || slots[agentId?.replaceAll("_", "-")] || {};
}

function hasAgentWebhook(agentId) {
  return Boolean(getAgentWebhook(agentId));
}

function readAgentWebhookOverrides() {
  try {
    const raw = window.localStorage.getItem(storageKeys.agentWebhookOverrides);
    const parsed = raw ? JSON.parse(raw) : {};
    return Object.fromEntries(Object.entries(parsed).filter(([, value]) => typeof value === "string" && value.trim()));
  } catch (_error) {
    return {};
  }
}

function writeAgentWebhookOverride(agentId, value) {
  const next = readAgentWebhookOverrides();
  const normalized = normalizeAgentWebhookUrl(value);
  if (normalized) {
    next[agentId] = normalized;
  } else {
    delete next[agentId];
  }
  window.localStorage.setItem(storageKeys.agentWebhookOverrides, JSON.stringify(next));
  delete state.n8nLiveProbeResults[agentId];
  return normalized;
}

function normalizeAgentWebhookUrl(value = "") {
  const trimmed = String(value || "").trim();
  if (!trimmed) return "";
  try {
    const url = new URL(trimmed);
    if (url.protocol !== "https:") throw new Error("Unsupported protocol");
    if (!/\/webhook\//i.test(url.pathname)) throw new Error("Missing webhook path");
    return url.toString();
  } catch (_error) {
    throw new Error("Use a valid https public UAT URL with /webhook/ in the path.");
  }
}

function renderAgentWebhookOverrideControl(agentId, options = {}) {
  const overrides = readAgentWebhookOverrides();
  const value = overrides[agentId] || "";
  const compact = options.compact ? " compact" : "";
  const label = options.label || "Browser-local UAT URL";
  return `
    <div class="agent-webhook-local-override${compact}" data-agent-webhook-override="${escapeHtml(agentId)}">
      <label>
        <span>${escapeHtml(label)}</span>
        <input type="url" value="${escapeHtml(value)}" placeholder="https://.../webhook/...">
      </label>
      <div class="button-row tight">
        <button class="secondary small" type="button" data-agent-webhook-action="save" data-agent-id="${escapeHtml(agentId)}">Use locally</button>
        <button class="secondary small" type="button" data-agent-webhook-action="clear" data-agent-id="${escapeHtml(agentId)}">Clear</button>
      </div>
      <small>Local browser override only. Use public UAT URLs here; production/private endpoints still belong behind backend secrets.</small>
    </div>
  `;
}

function handleAgentWebhookOverrideAction(button) {
  const agentId = button.dataset.agentId || "";
  if (!agentId) return;
  try {
    const wrap = button.closest("[data-agent-webhook-override]");
    const input = wrap?.querySelector("input");
    const value = button.dataset.agentWebhookAction === "clear" ? "" : input?.value || "";
    const normalized = writeAgentWebhookOverride(agentId, value);
    renderAgentOperatingModelPanel();
    renderProductionKnowledgeRepoReadiness();
    renderProductionProgressHeader();
    renderChatContractBadges();
    renderActiveChatContractBadge();
    renderChatContractActions();
    showToast(
      normalized ? "Local n8n URL override saved" : "Local n8n URL override cleared",
      normalized ? `${agentDisplayName(agentId)} will use this browser-local UAT URL.` : `${agentDisplayName(agentId)} falls back to runtime asset config.`,
      "success",
    );
  } catch (error) {
    showToast("Local n8n URL override rejected", error.message, "error");
  }
}

function chatSourceContext() {
  return {
    email_input: $("#chatSkillEmail")?.value || "",
    calendar_input: $("#chatSkillCalendar")?.value || "",
    teams_input: $("#chatSkillTeams")?.value || "",
    knowledge_context: $("#chatSkillKnowledge")?.value || "",
  };
}

function graphPromotionDecision(edge = {}) {
  const reviewState = edge.review_state || "unreviewed";
  const relation = edge.relation_type || edge.edge_type || "";
  const edgeClass = graphEdgeClass(edge);
  if (reviewState === "accepted" || reviewState === "approved") {
    return {
      label: reviewState === "accepted" ? "accepted" : "approved",
      trust: "trusted",
      className: "approved",
      fixture: "contracts/okf/promotions/approve-edge-example.json",
      description: "Available to the Actor Twin for grounded retrieval and skill context.",
    };
  }
  if (reviewState === "rejected") {
    return {
      label: "rejected",
      trust: "excluded",
      className: "rejected",
      fixture: "contracts/okf/promotions/reject-edge-example.json",
      description: "Excluded from retrieval; retained only for audit and curator learning.",
    };
  }
  if (reviewState === "needs-rework") {
    return {
      label: "needs rework",
      trust: "cockpit only",
      className: "needs-rework",
      fixture: "contracts/okf/promotions/needs-rework-edge-example.json",
      description: "Requires stronger evidence or clearer relation wording before use.",
    };
  }
  if (String(edgeClass).includes("candidate") || String(relation).includes("candidate")) {
    return {
      label: "candidate",
      trust: "review required",
      className: "candidate",
      fixture: "contracts/okf/promotions/approve-edge-example.json",
      description: "Visible as a hypothesis; not trusted until a human promotion decision.",
    };
  }
  if (edgeClass === "explicit") {
    return {
      label: "explicit",
      trust: "source-backed",
      className: "approved",
      fixture: "contracts/okf/promotions/approve-edge-example.json",
      description: "Source-backed relation that can support grounded retrieval.",
    };
  }
  return {
    label: "inferred",
    trust: "use with attribution",
    className: "inferred",
    fixture: "contracts/okf/promotions/needs-rework-edge-example.json",
    description: "Useful for recall expansion; decisions should cite supporting nodes.",
  };
}

function renderGraphPromotionChips(edge = {}) {
  const decision = graphPromotionDecision(edge);
  const relation = edge.relation_type || edge.edge_type || "related";
  const edgeClass = graphEdgeClass(edge);
  return `
    <div class="graph-promotion-strip ${safeGraphClass(decision.className)}">
      <span class="graph-promotion-chip ${safeGraphClass(decision.className)}">${escapeHtml(decision.label)}</span>
      <span class="graph-promotion-chip trust">${escapeHtml(decision.trust)}</span>
      <span class="graph-promotion-chip">${escapeHtml(labelizeGraph(edgeClass))}</span>
      <span class="graph-promotion-chip">${escapeHtml(labelizeGraph(relation))}</span>
      <small>${escapeHtml(decision.description)}</small>
    </div>
  `;
}

function renderGraphPromotionFixtureLinks(edge = {}) {
  const decision = graphPromotionDecision(edge);
  const fixtures = [
    ["Approve fixture", "contracts/okf/promotions/approve-edge-example.json"],
    ["Needs rework fixture", "contracts/okf/promotions/needs-rework-edge-example.json"],
    ["Reject fixture", "contracts/okf/promotions/reject-edge-example.json"],
  ];
  return `
    <div class="graph-promotion-fixtures">
      <small>Promotion contract</small>
      ${fixtures.map(([label, path]) => `
        <a class="${path === decision.fixture ? "active" : ""}" href="${escapeHtml(githubBlobUrl(path))}" target="_blank" rel="noreferrer">${escapeHtml(label)}</a>
      `).join("")}
    </div>
  `;
}

function activePrincipal() {
  const twin = state.twins.find((item) => item.twin_id === state.activeTwin);
  return {
    twin_id: state.activeTwin || "florian",
    display_name: twin?.display_name || state.activeTwin || "Florian",
  };
}

function buildAgentContractEnvelope(agentId, intent, query, input = {}, context = {}, approval = null) {
  const traceChain = normalizeTraceChain(context.trace_chain);
  const traceChainId = context.trace_chain_id || traceChain.trace_chain_id || `chain_${Date.now().toString(36)}`;
  return {
    envelope_version: "0.1.0",
    request_id: `req_${agentId}_${Date.now().toString(36)}`,
    timestamp: new Date().toISOString(),
    agent_id: agentId,
    intent,
    principal: activePrincipal(),
    input: {
      query,
      ...input,
    },
    context: {
      source: "meids-chat",
      session_id: state.n8nSessionId,
      risk_posture: state.riskPosture,
      retrieval_mode: $("#retrievalModeSelect")?.value || "keyword",
      concept_types: selectedConceptTypes(),
      websearch: state.webSearchEnabled,
      ...context,
      trace_chain_id: traceChainId,
      trace_chain: {
        trace_chain_id: traceChainId,
        steps: traceChain.steps,
      },
    },
    approval: approval || {
      required: false,
      reason: "No external write action requested at submission time.",
    },
  };
}

function normalizeTraceChain(value = null) {
  if (Array.isArray(value)) return { trace_chain_id: "", steps: value.filter(Boolean) };
  if (value && typeof value === "object") {
    return {
      trace_chain_id: value.trace_chain_id || value.chain_id || "",
      steps: Array.isArray(value.steps) ? value.steps.filter(Boolean) : [],
    };
  }
  return { trace_chain_id: "", steps: [] };
}

function appendTraceChainStep(context = {}, step = {}) {
  const normalized = normalizeTraceChain(context.trace_chain);
  const chainId = context.trace_chain_id || normalized.trace_chain_id || `chain_${Date.now().toString(36)}`;
  return {
    ...context,
    trace_chain_id: chainId,
    trace_chain: {
      trace_chain_id: chainId,
      steps: [
        ...normalized.steps,
        {
          timestamp: new Date().toISOString(),
          agent_id: step.agent_id || "",
          request_id: step.request_id || "",
          trace_id: step.trace_id || "",
          route_decision: step.route_decision || "",
          target_agent: step.target_agent || "",
          status: step.status || "",
        },
      ].filter((item) => item.agent_id || item.trace_id || item.route_decision),
    },
  };
}

function decideActorTwinRoute(query) {
  const normalized = String(query || "").toLowerCase();
  const sourceContext = chatSourceContext();
  const sourcePresent = Object.values(sourceContext).some((value) => String(value || "").trim());
  const selectedApprovedSkill = selectedApprovedChatSkill();
  const approvedSkillAvailable = Boolean(selectedApprovedSkill);
  const identityIntent = /\b(who are you|what are you|what is your purpose|what's your purpose|describe yourself|introduce yourself)\b/i.test(query);
  const createSkillIntent = /\b(create|build|define|design|shape|draft|new)\b.*\b(skill|capability|agent)\b|\bteach\b.*\bskill\b|\bmissing skill\b/i.test(query);
  const ingestIntent = !identityIntent && (sourcePresent || /\b(remember|save|ingest|stage|upload|transcript|capture|add this|store this)\b/i.test(query));
  const retrieveIntent = !identityIntent && /\b(find|retrieve|search|evidence|source document|source file|what do i know|approved knowledge|knowledge graph|citation)\b/i.test(query);
  const executionIntent = /\b(plan my day|prepare|draft|summari[sz]e for|activate skill|use skill|run skill|brief|todo|to-do|workstream|meeting)\b/i.test(query);
  const riskyExternalAction = /\b(send|email|mail|invite|schedule|book|publish|commit|approve|delete)\b/i.test(query);
  const ambiguous = !identityIntent && (normalized.length < 8 || /\b(do the thing|handle it|make it happen)\b/i.test(query));
  const base = {
    query,
    source_context_present: sourcePresent,
    selected_skill_id: selectedApprovedSkill?.skill_id || "",
    approved_skill_available: approvedSkillAvailable,
    risk_posture: state.riskPosture,
    runtime: "deterministic_fallback",
  };
  if (createSkillIntent) {
    return actorRoute({
      ...base,
      decision: "create_skill",
      target_agent: "agentic_butler",
      intent: "create_skill",
      visible_state: "drafting_new_skill",
      approval_required: true,
      placeholder: "Drafting a new skill request through Agentic Butler...",
      reason: "The request asks for a new capability; generated skills must remain pending approval.",
    });
  }
  if (executionIntent && approvedSkillAvailable) {
    return actorRoute({
      ...base,
      decision: "activate_skill",
      target_agent: "agentic_butler",
      intent: "activate_skill",
      visible_state: "activating_skill",
      approval_required: false,
      placeholder: "Activating approved skill through Agentic Butler...",
      reason: "The request maps to an approved skill; Agentic Butler can execute autonomously under Actor Twin steering.",
    });
  }
  if (executionIntent && !approvedSkillAvailable && /\b(skill|workflow|agent|reusable)\b/i.test(query)) {
    return actorRoute({
      ...base,
      decision: "create_skill",
      target_agent: "agentic_butler",
      intent: "create_skill",
      visible_state: "drafting_new_skill",
      approval_required: true,
      placeholder: "Drafting a new skill request through Agentic Butler...",
      reason: "The request appears to need a reusable capability, but no approved skill is selected.",
    });
  }
  if (ingestIntent) {
    return actorRoute({
      ...base,
      decision: "ingest_or_stage_knowledge",
      target_agent: "knowledge_fabric_agent",
      intent: "ingest_concept",
      visible_state: "using_knowledge",
      approval_required: false,
      placeholder: "Using Knowledge Fabric to stage source context...",
      reason: "Source context should become pending OKF evidence, not trusted knowledge automatically.",
    });
  }
  if (retrieveIntent) {
    return actorRoute({
      ...base,
      decision: "retrieve_knowledge",
      target_agent: "knowledge_fabric_agent",
      intent: "retrieve_context",
      visible_state: "using_knowledge",
      approval_required: false,
      placeholder: "Using Knowledge Fabric for approved-first retrieval...",
      reason: "The request asks for context or evidence retrieval.",
    });
  }
  if (ambiguous || (state.riskPosture === "strict" && riskyExternalAction)) {
    return actorRoute({
      ...base,
      decision: "request_human_clarification",
      target_agent: "human",
      intent: "clarify_request",
      visible_state: "approval_required",
      approval_required: true,
      placeholder: "Clarifying before delegation...",
      clarification: "Please clarify the intended outcome, target audience, and whether external actions are allowed.",
      reason: "The request is ambiguous or potentially risky.",
    });
  }
  return actorRoute({
    ...base,
    decision: "answer_direct",
    target_agent: "actor_twin",
    intent: "answer_question",
    visible_state: "answering",
    approval_required: false,
    placeholder: "Asking Actor Twin...",
    reason: "Answer-only request with no required delegation.",
  });
}

function actorRoute(route) {
  return {
    route_id: `route_${Date.now().toString(36)}`,
    ...route,
  };
}

function selectedApprovedChatSkill() {
  const candidates = [
    state.activeChatSkillId,
    ...state.appliedChatSkillIds,
  ].filter(Boolean);
  return candidates
    .map((skillId) => state.skills.find((skill) => skill.skill_id === skillId))
    .find((skill) => skill?.status === "approved") || null;
}

function compactVectorContext(result = null) {
  if (!result || result.status !== "completed") return null;
  const hits = (result.results || []).flatMap((bucket) => (bucket.value || []).map((item) => ({
    index: bucket.index,
    score: item["@search.score"] || item["@search.rerankerScore"] || 0,
    title: item.title || item.okf_concept_id || "",
    summary: item.summary || "",
    chunk_text: String(item.chunk_text || "").slice(0, 1200),
    okf_concept_id: item.okf_concept_id || "",
    okf_type: item.okf_type || "",
    repo_path: item.repo_path || "",
    evidence_id: item.evidence_id || "",
    graph_node_id: item.graph_node_id || "",
    graph_cluster_id: item.graph_cluster_id || "",
    knowledge_state: item.knowledge_state || "",
    visibility_scope: item.visibility_scope || "",
    tags: Array.isArray(item.tags) ? item.tags : [],
  })));
  return {
    provider: result.provider || "azure_ai_search",
    retrieval_mode: result.retrieval_mode || "unknown",
    source_policy: result.source_policy || "approved_only",
    filter: result.filter || "",
    hits,
  };
}

async function safeSearchVectorContext(query, route = null) {
  const text = String(query || "").trim();
  if (!text || staticPagesMode) return null;
  try {
    const result = await postJson("/api/vector-index/search", {
      query: text,
      twin_id: state.activeTwin,
      organization_id: runtimeConfig.organizationId || "default",
      source_policy: route?.decision === "retrieve_knowledge" ? "approved_only" : "approved_only",
      include_shared: true,
      top: 5,
    });
    return compactVectorContext(result);
  } catch (error) {
    console.info("Vector context enrichment skipped", error);
    return null;
  }
}

async function routeActorTwinFromChat(query, route = null) {
  const vectorContext = await safeSearchVectorContext(query, route);
  const envelope = buildAgentContractEnvelope(
    "actor_twin",
    "route_request",
    query,
    { mode: "runtime_router" },
    {
      route_decision: route,
      expected_route_decisions: [
        "answer_direct",
        "retrieve_knowledge",
        "ingest_or_stage_knowledge",
        "activate_skill",
        "create_skill",
        "request_human_clarification",
      ],
      okf_refs: [],
      graph_refs: [],
      vector_retrieval: vectorContext,
      retrieval_sources: vectorContext ? ["azure_ai_search", "okf_local"] : ["okf_local"],
      source_context: chatSourceContext(),
      retrieval_policy: "approved_first_include_pending_as_draft",
    },
  );
  return postAgentContractEnvelope("actor_twin", envelope, fallbackActorTwinResponse);
}

async function routeAgenticButlerFromChat(query, route = null, chainContext = {}) {
  const selected = selectedApprovedChatSkill();
  if (selected && selected.status !== "approved") throw new Error("Agentic Butler can only activate approved skills.");
  const skillContext = selected || {
    skill_id: "actor-directed-work-artifact",
    name: "Actor-directed work artifact",
    status: "approved",
  };
  const sourceContext = chatSourceContext();
  const envelope = buildAgentContractEnvelope(
    "agentic_butler",
    "activate_skill",
    query,
    {
      skill_id: skillContext.skill_id,
      skill_name: skillContext.name,
      manual_trigger: false,
      actor_directed_work_artifact: !selected,
      email_export: sourceContext.email_input,
      calendar_export: sourceContext.calendar_input,
      teams_export: sourceContext.teams_input,
      knowledge_context: sourceContext.knowledge_context,
    },
    {
      route_decision: route,
      ...chainContext,
      actor_checkpoint_policy: "consult_actor_twin_before_prioritization_and_before_human_gates",
      skill_orchestrator: "internal_component",
      approval_policy: "autonomous_for_work_artifacts_gate_only_new_skill_or_real_external_write",
      allowed_outputs: ["email_draft", "meeting_brief", "daily_plan", "todo_table", "backlog_plan", "approval_queue"],
    },
  );
  return postAgentContractEnvelope("agentic_butler", envelope, fallbackAgenticButlerResponse);
}

async function routeAgenticButlerSkillCreationFromChat(query, route = null, chainContext = {}) {
  const sourceContext = chatSourceContext();
  const envelope = buildAgentContractEnvelope(
    "agentic_butler",
    "create_skill",
    query,
    {
      skill_idea: query,
      manual_trigger: false,
      source_summary: [sourceContext.email_input, sourceContext.calendar_input, sourceContext.teams_input, sourceContext.knowledge_context]
        .filter(Boolean)
        .join("\n\n")
        .slice(0, 6000),
      desired_outcome: "Pending SkillSpec draft and elicitation plan for human approval.",
    },
    {
      route_decision: route,
      ...chainContext,
      elicitation_agent: "start_structured_interview",
      decomposition_agent: "blocked_until_skillspec_approved",
      skill_lifecycle: "draft_to_pending_approval",
      approval_policy: "never_auto_approve_generated_skills",
      skill_orchestrator: "internal_component_after_approval",
    },
    {
      required: true,
      gate: "skill_spec_approval",
      summary: "Generated skills require human approval before decomposition or activation.",
      proposed_action: "Review and approve the SkillSpec, or revise it before decomposition.",
    },
  );
  return postAgentContractEnvelope("agentic_butler", envelope, fallbackAgenticButlerSkillCreationResponse);
}

async function routeKnowledgeFabricFromChat(query, route = null, chainContext = {}) {
  const sourceContext = chatSourceContext();
  const title = query.slice(0, 80) || "Chat source context";
  const retrieve = route?.decision === "retrieve_knowledge";
  const envelope = buildAgentContractEnvelope(
    "knowledge_fabric_agent",
    retrieve ? "retrieve_context" : "ingest_concept",
    query,
    retrieve
      ? {
          retrieval_goal: "approved_evidence",
          title,
          content: "",
          target_state: "read_only",
        }
      : {
          source_type: "chat_source_context",
          title,
          content: [sourceContext.email_input, sourceContext.calendar_input, sourceContext.teams_input, sourceContext.knowledge_context]
            .filter(Boolean)
            .join("\n\n")
            .slice(0, 12000),
          target_state: "pending_review",
        },
    {
      route_decision: route,
      ...chainContext,
      okf_namespace: `concepts/${state.activeTwin || "florian"}/inbox`,
      allowed_outputs: ["markdown", "yaml_frontmatter", "graph_candidate_edges"],
      vector_policy: "do_not_refresh_without_approved_storage",
      trust_policy: "approved_first_include_pending_as_draft",
    },
  );
  return postAgentContractEnvelope("knowledge_fabric_agent", envelope, fallbackKnowledgeFabricResponse);
}

async function runActorTwinRuntimeInteraction(query, fallbackRoute = null) {
  const actorResult = await routeActorTwinFromChat(query, fallbackRoute);
  const route = actorRouteFromRuntime(actorResult, fallbackRoute);
  const actorTraceId = actorResult.response?.trace?.trace_id || actorResult.trace_id || "";
  const actorRequestId = actorResult.response?.request_id || actorResult.request?.request_id || "";
  const chainContext = appendTraceChainStep(actorResult.request?.context || {}, {
    agent_id: "actor_twin",
    request_id: actorRequestId,
    trace_id: actorTraceId,
    route_decision: route?.decision || "",
    target_agent: route?.target_agent || "",
    status: actorResult.response?.status || "completed",
  });
  state.lastActorTwinRouteDecision = route;
  renderSkillRoutingPanel();
  if (!route || ["answer_direct", "request_human_clarification"].includes(route.decision) || route.target_agent === "actor_twin") {
    return attachAgentRuntimeChain(actorResult, {
      actorResult,
      route,
      handoffStatus: "not_required",
      chainContext,
    });
  }
  const delegate = actorResult.response?.output?.delegate_result;
  if (delegate && typeof delegate === "object") {
    return attachAgentRuntimeChain({
      ...actorResult,
      response: {
        ...(actorResult.response || {}),
        status: delegate.status || actorResult.response?.status || "completed",
        approval: delegate.approval || actorResult.response?.approval || null,
        output: {
          ...(actorResult.response?.output || {}),
          delegate_result: delegate,
        },
      },
    }, {
      actorResult,
      route,
      handoffStatus: delegate.status || "delegated_in_actor_workflow",
      chainContext,
    });
  }
  persistAgentTrace(attachAgentRuntimeChain(actorResult, {
    actorResult,
    route,
    handoffStatus: "route_decided",
    chainContext,
  }));
  let targetResult;
  if (route.target_agent === "knowledge_fabric_agent") {
    targetResult = await routeKnowledgeFabricFromChat(query, route, {
      ...chainContext,
      actor_trace_id: actorTraceId,
      actor_request_id: actorRequestId,
      handoff_status: "route_decided",
    });
    if (route.decision === "ingest_or_stage_knowledge") persistKnowledgeFabricIngest(targetResult);
  } else if (route.target_agent === "agentic_butler" && route.decision === "create_skill") {
    targetResult = await routeAgenticButlerSkillCreationFromChat(query, route, {
      ...chainContext,
      actor_trace_id: actorTraceId,
      actor_request_id: actorRequestId,
      handoff_status: "route_decided",
    });
  } else if (route.target_agent === "agentic_butler") {
    targetResult = await routeAgenticButlerFromChat(query, route, {
      ...chainContext,
      actor_trace_id: actorTraceId,
      actor_request_id: actorRequestId,
      handoff_status: "route_decided",
    });
  } else {
    return attachAgentRuntimeChain(actorResult, {
      actorResult,
      route,
      handoffStatus: "unsupported_target",
      chainContext,
    });
  }
  return attachAgentRuntimeChain(targetResult, {
    actorResult,
    route,
    handoffStatus: targetResult.response?.status || "completed",
    chainContext,
  });
}

function exposeLocalAgentRuntimeUatHook() {
  if (!["localhost", "127.0.0.1"].includes(window.location.hostname)) return;
  window.__MEIDS_AGENT_RUNTIME_UAT__ = {
    async run(query, options = {}) {
      if (Array.isArray(options.appliedSkillIds)) {
        state.appliedChatSkillIds = options.appliedSkillIds.filter(Boolean);
        state.activeChatSkillId = state.appliedChatSkillIds[0] || N8N_CHAT_MODE;
        state.activeChatInteractionMode = state.appliedChatSkillIds.length ? "skill_activation" : "actor_twin";
      }
      const sourceContext = options.sourceContext || {};
      if ($("#chatSkillEmail") && sourceContext.email_input !== undefined) $("#chatSkillEmail").value = sourceContext.email_input;
      if ($("#chatSkillCalendar") && sourceContext.calendar_input !== undefined) $("#chatSkillCalendar").value = sourceContext.calendar_input;
      if ($("#chatSkillTeams") && sourceContext.teams_input !== undefined) $("#chatSkillTeams").value = sourceContext.teams_input;
      if ($("#chatSkillKnowledge") && sourceContext.knowledge_context !== undefined) $("#chatSkillKnowledge").value = sourceContext.knowledge_context;
      renderChatSkillMode();
      const fallbackRoute = decideActorTwinRoute(query);
      const result = await runActorTwinRuntimeInteraction(query, fallbackRoute);
      persistAgentTrace(result);
      return summarizeAgentRuntimeUatResult(result, fallbackRoute);
    },
  };
}

function summarizeAgentRuntimeUatResult(result = {}, fallbackRoute = {}) {
  const response = result.response || {};
  const route = result.route || response.output?.route_decision || fallbackRoute || {};
  const trace = response.trace || result.trace || {};
  const traceChain = normalizeTraceChain(trace.trace_chain || result.trace_chain);
  return {
    agent_id: response.agent_id || result.agent_id || "",
    status: response.status || result.status || "",
    route_decision: route.decision || "",
    target_agent: route.target_agent || trace.target_agent || response.agent_id || "",
    approval_required: Boolean(response.approval?.required || route.approval_required),
    trace_id: trace.trace_id || result.trace_id || "",
    trace_chain_id: trace.trace_chain_id || result.trace_chain_id || "",
    trace_chain_steps: traceChain.steps.length,
    runtime: response.runtime || result.runtime || "",
    answer_preview: String(response.output?.answer || result.answer || "").slice(0, 240),
  };
}

function actorRouteFromRuntime(actorResult = {}, fallbackRoute = null) {
  const output = actorResult.response?.output || {};
  const textRoute = routeDecisionFromActorText(output.answer || output.text || output.message || "", fallbackRoute);
  const candidates = [
    textRoute,
    output.route_decision,
    output.route,
    output.routing,
    output.handoff,
    actorResult.response?.route_decision,
  ].filter(Boolean);
  const route = candidates.find((item) => item && typeof item === "object") || null;
  const decision = route?.decision || route?.route_decision || route?.intent_decision || fallbackRoute?.decision || "answer_direct";
  const target = route?.target_agent || route?.targetAgent || output.target_agent || fallbackRoute?.target_agent || targetAgentForRouteDecision(decision);
  const reconciled = reconcileActorRouteFromAnswer(output.answer || output.text || output.message || "", { ...(fallbackRoute || {}), ...(route || {}), decision, target_agent: target });
  return actorRoute({
    ...(fallbackRoute || {}),
    ...(route || {}),
    ...(reconciled || {}),
    decision: reconciled?.decision || decision,
    target_agent: reconciled?.target_agent || target,
    intent: reconciled?.intent || route?.intent || fallbackRoute?.intent || intentForRouteDecision(decision),
    visible_state: reconciled?.visible_state || route?.visible_state || fallbackRoute?.visible_state || visibleStateForRouteDecision(decision),
    approval_required: Boolean(reconciled?.approval_required ?? route?.approval_required ?? fallbackRoute?.approval_required ?? decision === "create_skill"),
    reason: reconciled?.reason || route?.reason || fallbackRoute?.reason || "Actor Twin runtime route decision.",
    handoff_required: Boolean(reconciled?.handoff_required ?? route?.handoff_required ?? !["answer_direct", "request_human_clarification"].includes(decision)),
    handoff_payload: route?.handoff_payload || output.handoff_payload || null,
    runtime: actorResult.runtime || fallbackRoute?.runtime || "actor_twin_runtime",
  });
}

function reconcileActorRouteFromAnswer(text = "", route = {}) {
  const normalized = String(text || "").toLowerCase();
  if (!normalized || route.decision === "answer_direct") return null;
  const explicitAnswerDirect = normalized.includes("route mismatch")
    && normalized.includes("answer_direct")
    && (
      normalized.includes("do not activate")
      || normalized.includes("no skill activation")
      || normalized.includes("no skill activation warranted")
      || normalized.includes("return control to actor twin")
    );
  if (!explicitAnswerDirect) return null;
  return {
    decision: "answer_direct",
    target_agent: "actor_twin",
    intent: "answer_question",
    visible_state: "answering",
    approval_required: false,
    handoff_required: false,
    reason: "Reconciled from Actor Twin/Butler route-mismatch output: direct answer is authoritative for this request.",
  };
}

function routeDecisionFromActorText(text = "", fallbackRoute = null) {
  const normalized = String(text || "").toLowerCase();
  if (!normalized) return null;
  if (fallbackRoute?.decision === "answer_direct") {
    const explicitRouteMarker = normalized.includes("route_decision")
      || normalized.includes("target_agent")
      || normalized.includes("target:")
      || normalized.includes("handoff_required")
      || normalized.includes("create_skill")
      || normalized.includes("activate_skill")
      || normalized.includes("ingest_or_stage_knowledge")
      || normalized.includes("retrieve_knowledge");
    if (!explicitRouteMarker) return null;
  }
  const mentionsKnowledgeRoute = normalized.includes("ingest_or_stage_knowledge")
    || normalized.includes("retrieve_knowledge")
    || (normalized.includes("knowledge fabric") && (normalized.includes("pending okf") || normalized.includes("staged as pending")));
  if (mentionsKnowledgeRoute) {
    const retrieve = normalized.includes("retrieve_knowledge");
    return {
      ...(fallbackRoute || {}),
      decision: retrieve ? "retrieve_knowledge" : "ingest_or_stage_knowledge",
      target_agent: "knowledge_fabric_agent",
      intent: retrieve ? "retrieve_context" : "ingest_concept",
      visible_state: "using_knowledge",
      approval_required: false,
      handoff_required: true,
      reason: "Actor Twin response text indicated Knowledge Fabric handoff; normalized for runtime routing.",
    };
  }
  const mentionsButlerRoute = normalized.includes("target: agentic butler")
    || normalized.includes("target_agent\":\"agentic_butler")
    || normalized.includes("target_agent: agentic_butler")
    || normalized.includes("create_skill")
    || normalized.includes("activate_skill");
  if (mentionsButlerRoute) {
    const createSkill = normalized.includes("create_skill") || normalized.includes("new skill") || normalized.includes("skill proposal");
    return {
      ...(fallbackRoute || {}),
      decision: createSkill ? "create_skill" : "activate_skill",
      target_agent: "agentic_butler",
      intent: createSkill ? "create_skill" : "activate_skill",
      visible_state: createSkill ? "drafting_new_skill" : "activating_skill",
      approval_required: createSkill || Boolean(fallbackRoute?.approval_required),
      handoff_required: true,
      reason: "Actor Twin response text indicated Agentic Butler handoff; normalized for runtime routing.",
    };
  }
  return null;
}

function targetAgentForRouteDecision(decision = "") {
  if (["retrieve_knowledge", "ingest_or_stage_knowledge"].includes(decision)) return "knowledge_fabric_agent";
  if (["activate_skill", "create_skill"].includes(decision)) return "agentic_butler";
  if (decision === "request_human_clarification") return "human";
  return "actor_twin";
}

function intentForRouteDecision(decision = "") {
  return {
    answer_direct: "answer_question",
    retrieve_knowledge: "retrieve_context",
    ingest_or_stage_knowledge: "ingest_concept",
    activate_skill: "activate_skill",
    create_skill: "create_skill",
    request_human_clarification: "clarify_request",
  }[decision] || "answer_question";
}

function visibleStateForRouteDecision(decision = "") {
  return {
    answer_direct: "answering",
    retrieve_knowledge: "using_knowledge",
    ingest_or_stage_knowledge: "using_knowledge",
    activate_skill: "activating_skill",
    create_skill: "drafting_new_skill",
    request_human_clarification: "approval_required",
  }[decision] || "answering";
}

function attachAgentRuntimeChain(result = {}, { actorResult = null, route = null, handoffStatus = "", chainContext = null } = {}) {
  const actorTrace = actorResult?.response?.trace?.trace_id || actorResult?.trace_id || "";
  const targetTrace = result.response?.trace?.trace_id || result.trace_id || "";
  const normalized = normalizeTraceChain(chainContext?.trace_chain || result.request?.context?.trace_chain);
  const traceChainId = chainContext?.trace_chain_id || result.request?.context?.trace_chain_id || normalized.trace_chain_id || "";
  const existingTargetStep = normalized.steps.some((step) => step.trace_id && step.trace_id === targetTrace);
  const steps = existingTargetStep || result.agent_id === "actor_twin"
    ? normalized.steps
    : [
        ...normalized.steps,
        {
          timestamp: new Date().toISOString(),
          agent_id: result.agent_id || result.response?.agent_id || "",
          request_id: result.response?.request_id || result.request?.request_id || "",
          trace_id: targetTrace,
          route_decision: route?.decision || "",
          target_agent: route?.target_agent || "",
          status: result.response?.status || "completed",
        },
      ].filter((item) => item.agent_id || item.trace_id || item.route_decision);
  const chain = {
    trace_chain_id: traceChainId,
    trace_chain: steps,
    actor_trace_id: actorTrace,
    handoff_trace_id: result.agent_id === "actor_twin" ? "" : targetTrace,
    target_agent: route?.target_agent || result.agent_id || "",
    route_decision: route?.decision || "",
    handoff_status: handoffStatus || result.response?.status || "",
  };
  result.runtime_chain = chain;
  if (result.response) {
    result.response.trace = {
      stored: false,
      used_agents: [],
      ...(result.response.trace || {}),
      ...chain,
    };
    result.response.output = {
      ...(result.response.output || {}),
      route_decision: result.response.output?.route_decision || route || null,
    };
  }
  return result;
}

async function postAgentContractEnvelope(agentId, envelope, fallbackFactory) {
  if (shouldUseAgentBackendProxy(agentId)) {
    const data = await postAgentBackendJson(agentBackendProxyPath(agentId), envelope);
    return normalizeAgentContractResponse(agentId, data, envelope, "backend proxy");
  }
  const webhookUrl = getAgentWebhook(agentId);
  if (!webhookUrl) return fallbackFactory(envelope, "fixture fallback");
  const body = isN8nChatWebhook(webhookUrl)
    ? {
        action: "sendMessage",
        sessionId: state.n8nSessionId,
        chatInput: envelope.input?.query || "",
        metadata: {
          source: "meids-contract-bridge",
          agent_id: agentId,
          contract_envelope: envelope,
        },
      }
    : envelope;
  const response = await fetch(webhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  const raw = await response.text();
  if (!response.ok) throw new Error(raw || `${agentId} returned ${response.status}`);
  const data = parseMaybeJson(raw);
  return normalizeAgentContractResponse(agentId, data, envelope, "n8n connected");
}

function shouldUseAgentBackendProxy(agentId = "") {
  return Boolean(agentBackendProxyEnabled && agentBackendProxyPath(agentId));
}

function agentBackendProxyPath(agentId = "") {
  if (agentId === "actor_twin") return "/api/agents/actor-twin/chat";
  if (agentId === "knowledge_fabric_agent") return "/api/agents/knowledge-fabric/ingest";
  if (agentId === "agentic_butler") return "/api/agents/agentic-butler/run";
  return "";
}

function agentBackendUrl(path = "") {
  if (!agentBackendBaseUrl || /^https?:\/\//i.test(path)) return path;
  return `${agentBackendBaseUrl}${path.startsWith("/") ? path : `/${path}`}`;
}

async function requestAgentBackendJson(path, options = {}) {
  const response = await fetch(agentBackendUrl(path), options);
  const raw = await response.text();
  if (!response.ok) throw new Error(raw || `Agent backend returned ${response.status}`);
  return parseMaybeJson(raw);
}

async function getAgentBackendJson(path) {
  return requestAgentBackendJson(path);
}

async function postAgentBackendJson(path, body) {
  return requestAgentBackendJson(path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}

function isN8nChatWebhook(url) {
  return /\/chat(?:$|[?#/])/i.test(String(url || ""));
}

function parseMaybeJson(raw) {
  try {
    return raw ? JSON.parse(raw) : {};
  } catch {
    return { output: { answer: raw } };
  }
}

function normalizeAgentContractResponse(agentId, data, envelope, runtime) {
  const response = data?.response || data?.data || data || {};
  const normalizedOutput = normalizeAgentOutput(response.output || data?.output || outputFromN8nData(data));
  const structuredOutput = normalizeAgentOutput(normalizedOutput.output || normalizedOutput);
  if (response.delegate_result && !normalizedOutput.delegate_result) normalizedOutput.delegate_result = response.delegate_result;
  if (data?.delegate_result && !normalizedOutput.delegate_result) normalizedOutput.delegate_result = data.delegate_result;
  if (normalizedOutput.delegate_result && !structuredOutput.delegate_result) structuredOutput.delegate_result = normalizedOutput.delegate_result;
  const normalizedApproval = response.approval || data?.approval || structuredOutput.approval || normalizedOutput.approval || null;
  const normalizedTrace = response.trace || data?.trace || structuredOutput.trace || normalizedOutput.trace || { trace_id: response.trace_id || data?.trace_id || envelope.request_id, stored: false };
  const status = shouldRequireHumanApprovalForAgentResult({
    agentId,
    response,
    output: structuredOutput,
    approval: normalizedApproval,
    envelope,
    trace: normalizedTrace,
  })
    ? "approval_required"
    : (response.status === "failed" || data?.status === "failed" ? "failed" : "completed");
  const approval = status === "approval_required" ? normalizedApproval : { required: false };
  return {
    agent_id: agentId,
    agent_name: agentDisplayName(agentId),
    runtime,
    trace_id: normalizedTrace.trace_id || response.trace_id || data?.trace_id || envelope.request_id,
    request: envelope,
    response: {
      envelope_version: response.envelope_version || envelope.envelope_version,
      request_id: response.request_id || envelope.request_id,
      agent_id: response.agent_id || agentId,
      status,
      output: structuredOutput,
      approval,
      trace: normalizedTrace,
      error: response.error || data?.error || null,
    },
    answer: extractAgentAnswer(structuredOutput || data, status),
  };
}

function shouldRequireHumanApprovalForAgentResult({ agentId = "", response = {}, output = {}, approval = {}, envelope = {}, trace = {} } = {}) {
  const route = output.route_decision || envelope.context?.route_decision || {};
  const decision = route.decision || trace.route_decision || envelope.intent || "";
  const gate = approval?.gate || output.approval_request?.gate || "";
  const query = originalAgentUserQuery({ envelope, output, response });
  if (response.status === "failed") return false;
  if (isWorkArtifactDraftIntent(query)) return false;
  return Boolean(isExplicitSkillOrAgentCreationIntent(query, { decision, gate, intent: envelope.intent }));
}

function originalAgentUserQuery({ envelope = {}, output = {}, response = {} } = {}) {
  const delegateInput = output.delegate_result?.input || output.delegate_result?.request?.input || {};
  const values = [
    envelope.input?.query,
    envelope.input?.message,
    envelope.message,
    envelope.chatInput,
    delegateInput.query,
    delegateInput.message,
    output.query,
    response.query,
  ];
  return String(values.find((value) => String(value || "").trim()) || "");
}

function isWorkArtifactDraftIntent(query = "") {
  const text = String(query || "").toLowerCase();
  if (!text) return false;
  return /\b(write|draft|prepare|compose|create)\b[\s\S]{0,80}\b(email|mail|message|meeting|agenda|brief|summary|plan|backlog|minutes|memo|status update|client update)\b/i.test(text)
    || /\b(plan my day|prioritized plan|daily plan|meeting prep|prepare for my next meeting)\b/i.test(text);
}

function isExplicitSkillOrAgentCreationIntent(query = "", context = {}) {
  const text = String(query || "").toLowerCase();
  if (context.gate === "new_agent_approval") return true;
  if (isWorkArtifactDraftIntent(text)) return false;
  const explicitCreation = /\b(create|shape|design|generate|build|define)\b[\s\S]{0,48}\b(new\s+)?(skill|agent|task-agent|task agent|subagent|sub-agent)\b/i.test(text)
    || /\b(new|additional)\s+(skill|agent|task-agent|task agent|subagent|sub-agent)\b/i.test(text)
    || /\b(skill|agent|task-agent|task agent|subagent|sub-agent)\b[\s\S]{0,48}\b(create|shape|design|generate|build|define)\b/i.test(text);
  if (!explicitCreation) return false;
  return context.decision === "create_skill" || context.intent === "create_skill" || context.gate === "skill_spec_approval" || context.gate === "new_agent_approval";
}

function normalizeAgentOutput(output = {}) {
  if (typeof output === "string") {
    const embeddedString = parseEmbeddedJsonObject(output);
    if (embeddedString && typeof embeddedString === "object") return normalizeAgentOutput(embeddedString.output || embeddedString);
    return { summary: output };
  }
  if (!output || typeof output !== "object") return output;
  if (typeof output.output === "string") {
    const embeddedOutputEnvelope = parseEmbeddedJsonObject(output.output);
    if (embeddedOutputEnvelope && typeof embeddedOutputEnvelope === "object") {
      return normalizeAgentOutput({ ...output, ...embeddedOutputEnvelope, output: embeddedOutputEnvelope.output || embeddedOutputEnvelope });
    }
  }
  if (output.answer && typeof output.answer === "object") {
    const answerObject = output.answer.output && typeof output.answer.output === "object" ? output.answer.output : output.answer;
    return {
      ...output,
      ...answerObject,
      answer: answerObject.answer || answerObject.summary || JSON.stringify(answerObject),
      approval: output.answer.approval || output.approval,
      trace: output.answer.trace || output.trace,
    };
  }
  if (output.delegate_result?.output) {
    output = {
      ...output,
      delegate_result: {
        ...output.delegate_result,
        output: normalizeAgentOutput(output.delegate_result.output),
      },
    };
  }
  const textCarrier = output.answer || output.summary || output.text || output.message || output.markdown || "";
  const embedded = parseEmbeddedJsonObject(textCarrier);
  if (!embedded || typeof embedded !== "object") return output;
  const embeddedOutput = embedded.output && typeof embedded.output === "object" ? embedded.output : embedded;
  return {
    ...output,
    ...embedded,
    ...embeddedOutput,
    answer: embeddedOutput.answer || embeddedOutput.summary || embedded.answer || output.answer || output.text || output.message,
    summary: embeddedOutput.summary || embedded.summary || output.summary,
    approval: embedded.approval || output.approval,
    trace: embedded.trace || output.trace,
  };
}

function parseEmbeddedJsonObject(value = "") {
  const text = String(value || "").trim();
  if (!text) return null;
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = (fenced ? fenced[1] : text).trim();
  const firstBrace = candidate.indexOf("{");
  const lastBrace = candidate.lastIndexOf("}");
  if (firstBrace < 0 || lastBrace <= firstBrace) return null;
  try {
    return JSON.parse(candidate.slice(firstBrace, lastBrace + 1));
  } catch {
    return null;
  }
}

function persistAgentTrace(result = {}) {
  const response = result.response || {};
  const trace = response.trace || {};
  const normalizedChain = normalizeTraceChain(trace.trace_chain || result.runtime_chain?.trace_chain || result.request?.context?.trace_chain);
  const approvalRequired = shouldRequireHumanApprovalForAgentResult({
    agentId: result.agent_id || response.agent_id || "",
    response,
    output: response.output || {},
    approval: response.approval || {},
    envelope: result.request || {},
    trace,
  });
  const entry = {
    timestamp: new Date().toISOString(),
    twin: state.activeTwin || "",
    agent_id: result.agent_id || response.agent_id || "",
    agent_name: result.agent_name || agentDisplayName(result.agent_id || response.agent_id || ""),
    status: response.status || result.status || "",
    runtime: result.runtime || "",
    request_id: response.request_id || result.request?.request_id || "",
    trace_id: trace.trace_id || result.trace_id || "",
    trace_chain_id: trace.trace_chain_id || result.runtime_chain?.trace_chain_id || result.request?.context?.trace_chain_id || normalizedChain.trace_chain_id || "",
    trace_chain: normalizedChain.steps,
    actor_trace_id: trace.actor_trace_id || result.runtime_chain?.actor_trace_id || "",
    handoff_trace_id: trace.handoff_trace_id || result.runtime_chain?.handoff_trace_id || "",
    target_agent: trace.target_agent || result.runtime_chain?.target_agent || "",
    route_decision: trace.route_decision || result.runtime_chain?.route_decision || "",
    handoff_status: trace.handoff_status || result.runtime_chain?.handoff_status || "",
    approval_required: approvalRequired,
  };
  persistAgentApprovalRequest(result, entry);
  try {
    const current = JSON.parse(window.localStorage.getItem(storageKeys.agentTraceLog) || "[]");
    const next = [entry, ...(Array.isArray(current) ? current : [])].slice(0, 50);
    window.localStorage.setItem(storageKeys.agentTraceLog, JSON.stringify(next));
    persistAgentTraceToBackend(entry, result);
    renderChatLatestAgentTraces();
    renderAgentTraceHistoryPanel();
    renderDashboardAgentTraceHistory();
  } catch (error) {
    console.warn("Agent trace persistence failed", error);
  }
}

function persistAgentTraceToBackend(entry = {}, result = {}) {
  if (!agentBackendProxyEnabled) return;
  postAgentBackendJson("/api/agents/traces", {
    trace: entry,
    response: result.response || null,
    request: result.request || null,
  }).catch((error) => {
    console.warn("Backend agent trace persistence failed", error);
  });
}

function persistAgentProbeTrace(agentId, envelope = {}, probe = {}, options = {}) {
  const status = probe.status || "unknown";
  const traceId = options.trace_id || `probe_${agentId}_${Date.now().toString(36)}`;
  const runtime = options.runtime || (
    status === "connected"
      ? "n8n connected · live probe"
      : status === "configured"
        ? "webhook configured · probe pending"
        : status === "fixture"
          ? "fixture fallback · probe"
          : "fixture replay · live URL missing"
  );
  const entry = {
    timestamp: new Date().toISOString(),
    twin: state.activeTwin || "",
    agent_id: agentId,
    agent_name: agentDisplayName(agentId),
    status: status === "connected" ? "completed" : status,
    runtime,
    request_id: envelope.request_id || "",
    trace_id: traceId,
    approval_required: false,
    artifact_path: envelope.intent || "live_probe",
    detail: probe.detail || agentRuntimeReadiness(agentId).detail || "",
    probe_trace: true,
  };
  try {
    const current = JSON.parse(window.localStorage.getItem(storageKeys.agentTraceLog) || "[]");
    const existing = Array.isArray(current) ? current : [];
    const deduped = existing.filter((trace) => trace.trace_id !== entry.trace_id && trace.request_id !== entry.request_id);
    window.localStorage.setItem(storageKeys.agentTraceLog, JSON.stringify([entry, ...deduped].slice(0, 50)));
    renderChatLatestAgentTraces();
    renderAgentTraceHistoryPanel();
    renderDashboardAgentTraceHistory();
  } catch (error) {
    console.warn("Agent probe trace persistence failed", error);
  }
}

function persistKnowledgeFabricIngest(result = {}) {
  const agentId = result.agent_id || result.response?.agent_id || "";
  if (agentId !== "knowledge_fabric_agent") return;
  const item = knowledgeFabricQueueItemFromResult(result);
  if (!item.concept_path && !item.evidence_path && !item.trace_id) return;
  const next = [item, ...state.knowledgeFabricIngestQueue.filter((existing) => existing.queue_id !== item.queue_id)].slice(0, 12);
  state.knowledgeFabricIngestQueue = next;
  try {
    window.localStorage.setItem(storageKeys.knowledgeFabricIngestQueue, JSON.stringify(next));
  } catch (error) {
    console.warn("Knowledge Fabric queue persistence failed", error);
  }
  renderKnowledgeFabricQueuePanels();
}

function knowledgeFabricQueueItemFromResult(result = {}) {
  const response = result.response || {};
  const output = response.output || {};
  const request = result.request || {};
  const input = request.input || {};
  const context = request.context || {};
  const trace = response.trace || {};
  const requestId = response.request_id || request.request_id || `req_kf_${Date.now().toString(36)}`;
  const title = input.title || input.query || output.title || "Source context handoff";
  const candidateEdges = Array.isArray(output.candidate_edges) ? output.candidate_edges : [];
  return {
    queue_id: `${requestId}:${output.concept_path || trace.trace_id || "pending"}`,
    request_id: requestId,
    trace_id: trace.trace_id || result.trace_id || "",
    created_at: request.timestamp || new Date().toISOString(),
    runtime: result.runtime || "fixture fallback",
    title,
    twin_id: request.principal?.twin_id || state.activeTwin || "florian",
    intent: request.intent || "ingest_concept",
    review_state: output.review_state || "pending_review",
    concept_path: output.concept_path || "",
    evidence_path: output.evidence_path || "",
    transcript_path: output.transcript_path || "",
    crud_log_path: output.crud_log_path || "",
    graph_curator_trigger: output.graph_curator_trigger || (candidateEdges.length ? "queued" : "not_requested"),
    vector_refresh: output.vector_refresh || output.vector_policy || "deferred_until_approved",
    candidate_edges: candidateEdges,
    source_type: input.source_type || context.source || "chat_source_context",
  };
}

function persistLocalKnowledgeFabricIngest(result = {}, options = {}) {
  const concepts = Array.isArray(result.concepts)
    ? result.concepts
    : result.concept
      ? [result.concept]
      : [];
  if (!concepts.length) return;
  const createdAt = new Date().toISOString();
  const sourceType = options.sourceType || result.source || "local-ingest";
  const sourceName = options.sourceName || result.source || "local source";
  const baseRequestId = `local_ingest_${createdAt.replace(/[-:.TZ]/g, "").slice(0, 14)}`;
  const items = concepts.map((concept, index) => {
    const conceptPath = concept.path || concept.concept_path || "";
    const title = concept.title || options.fallbackTitle || "Pending OKF concept";
    const sourceAnchor = concept.source_anchor || concept.anchor || "";
    const queueId = `${baseRequestId}_${index}:${conceptPath || slugify(title)}`;
    return {
      queue_id: queueId,
      request_id: `${baseRequestId}_${index}`,
      trace_id: result.trace_id || result.trace?.trace_id || `trace_${baseRequestId}_${index}`,
      created_at: createdAt,
      runtime: "local backend ingest",
      title,
      twin_id: result.twin || result.twin_id || state.activeTwin || "florian",
      intent: "ingest_concept",
      review_state: "pending-review",
      concept_path: conceptPath,
      evidence_path: concept.evidence_path || (sourceAnchor ? `${conceptPath}#${sourceAnchor}` : ""),
      transcript_path: concept.transcript_path || "",
      crud_log_path: concept.crud_log_path || `audit/${state.activeTwin || "florian"}/crud-log.jsonl`,
      graph_curator_trigger: "queued_for_candidate_generation",
      vector_refresh: "deferred_until_approved",
      candidate_edges: Array.isArray(concept.candidate_edges) ? concept.candidate_edges : [],
      source_type: sourceType,
      source_name: sourceName,
      guardrail_status: concept.guardrail_status || "not-evaluated",
    };
  });
  const nextById = new Map((state.knowledgeFabricIngestQueue || []).map((item) => [item.queue_id, item]));
  items.forEach((item) => nextById.set(item.queue_id, item));
  state.knowledgeFabricIngestQueue = Array.from(nextById.values())
    .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")))
    .slice(0, 12);
  try {
    window.localStorage.setItem(storageKeys.knowledgeFabricIngestQueue, JSON.stringify(state.knowledgeFabricIngestQueue));
  } catch (error) {
    console.warn("Local Knowledge Fabric ingest persistence failed", error);
  }
  renderKnowledgeFabricQueuePanels();
  showToast("Pending OKF handoff created", `${items.length} source concept${items.length === 1 ? "" : "s"} added to review queue.`, "success");
}

function readKnowledgeFabricIngestQueue() {
  try {
    const value = JSON.parse(window.localStorage.getItem(storageKeys.knowledgeFabricIngestQueue) || "[]");
    if (Array.isArray(value) && value.length) return value;
  } catch (error) {
    console.warn("Knowledge Fabric queue read failed", error);
  }
  return staticPagesMode ? buildStaticKnowledgeFabricQueue() : [];
}

