function bindKnowledgeFabricQueueActions() {
  document.addEventListener("click", async (event) => {
    const button = event.target.closest("[data-kf-queue-action]");
    if (!button) return;
    const action = button.dataset.kfQueueAction || "";
    const queueId = button.dataset.queueId || "";
    if (action === "filter") {
      state.knowledgeFabricQueueFilter = button.dataset.kfQueueFilter || "all";
      renderKnowledgeFabricQueuePanels();
      return;
    }
    if (action === "open-ingest") {
      showView("ingest");
      $("#ingest")?.scrollIntoView({ block: "start", behavior: "smooth" });
      return;
    }
    if (action === "review") {
      state.dashboardFilter = "concepts";
      showView("dashboard");
      renderDashboardFilter();
      $("#dashPendingConcepts")?.scrollIntoView({ block: "center", behavior: "smooth" });
      return;
    }
    if (action === "graph") {
      showView("graph");
      renderGraphCockpit();
      $("#graphStatus")?.scrollIntoView({ block: "center", behavior: "smooth" });
      return;
    }
    if (action === "copy") {
      const item = state.knowledgeFabricIngestQueue.find((entry) => entry.queue_id === queueId);
      if (!item) return;
      const copied = await copyTextToClipboard(JSON.stringify(item, null, 2));
      showToast("Knowledge Fabric manifest", copied ? "Copied to clipboard." : "Copy failed.", copied ? "success" : "warning");
      return;
    }
    if (action === "export") {
      exportKnowledgeFabricQueueArtifact(queueId, button);
      return;
    }
    if (action === "export-okf-graph") {
      exportKnowledgeFabricQueueOkfGraphPackage(queueId, button);
      return;
    }
    if (action === "export-reviewed-bundle") {
      exportReviewedKnowledgeFabricBundle(button);
      return;
    }
    if (action === "export-uat-checklist") {
      exportKnowledgeFabricLocalUatChecklist(button);
      return;
    }
    if (action === "copy-source-repo-sync") {
      copyKnowledgeFabricSourceRepoSyncPreview(button);
      return;
    }
    if (action === "copy-approved-pr-handoff") {
      copyApprovedKnowledgeFabricPrHandoff(button);
      return;
    }
    if (["approve", "needs-rework", "reject"].includes(action)) {
      updateKnowledgeFabricQueueReview(queueId, action);
      return;
    }
    if (action === "clear") {
      state.knowledgeFabricIngestQueue = [];
      try {
        window.localStorage.removeItem(storageKeys.knowledgeFabricIngestQueue);
      } catch (error) {
        console.warn("Knowledge Fabric queue clear failed", error);
      }
      renderKnowledgeFabricQueuePanels();
    }
  });
}

function reviewedKnowledgeFabricQueueItems() {
  return (state.knowledgeFabricIngestQueue || [])
    .filter((item) => item.reviewed_at && ["approved", "needs-rework", "rejected"].includes(String(item.review_state || "")));
}

