function buildKnowledgeFabricQueueOkfGraphPackage(item = {}) {
  const itemPath = item.concept_path || item.evidence_path || "";
  const queueSlug = slugify(item.queue_id || item.request_id || item.title || "");
  const itemEdgeKeys = new Set((Array.isArray(item.candidate_edges) ? item.candidate_edges : [])
    .map((edge, index) => edge.edge_key || `${queueSlug}-${slugify(edge.relation_type || edge.edge_type || "edge")}-${index}`)
    .filter(Boolean));
  const promotions = graphPromotionHistoryItems(120).filter((promotion) => {
    const promotionPath = promotion.source_path || promotion.path || "";
    return (
      (itemPath && promotionPath === itemPath) ||
      (promotion.edge_key && itemEdgeKeys.has(promotion.edge_key)) ||
      (queueSlug && String(promotion.edge_key || "").includes(queueSlug))
    );
  });
  const fallbackPromotions = !promotions.length && Array.isArray(item.candidate_edges)
    ? item.candidate_edges.map((edge, index) => ({
      edge_key: edge.edge_key || `${queueSlug}-${slugify(edge.relation_type || edge.edge_type || "edge")}-${index}`,
      decision: item.review_state || "pending-review",
      review_state: item.review_state || "pending-review",
      reviewed_at: item.reviewed_at || "",
      relation_type: edge.relation_type || edge.edge_type || "related",
      confidence: edge.confidence,
      note: item.review_note || "Candidate edge exported from Knowledge Fabric handoff before graph promotion history exists.",
      source_title: labelizeGraph(edge.source || item.title || "source"),
      target_title: labelizeGraph(edge.target || "target"),
      source_path: item.concept_path || item.evidence_path || "",
      target_path: edge.target_path || "",
      evidence_refs: [item.evidence_path, item.transcript_path].filter(Boolean),
      graph_curator_trigger: item.graph_curator_trigger || "candidate_export",
      edge_class: item.review_state === "approved" ? "candidate_pending_graph_acceptance" : "candidate",
      path: item.concept_path || item.evidence_path || "",
      source_handoff: knowledgeFabricGraphSourceHandoffContext(item, edge),
    }))
    : [];
  return buildOkfGraphPromotionPackageArtifact([item], promotions.length ? promotions : fallbackPromotions);
}

function buildKnowledgeFabricQueueArtifact(item = {}) {
  const exportedAt = new Date().toISOString();
  const graphPromotions = knowledgeFabricQueuePromotionHistoryItems()
    .filter((entry) => {
      const sourcePath = item.concept_path || item.evidence_path || "";
      return !sourcePath || entry.path === sourcePath || entry.source_path === sourcePath || String(entry.edge_key || "").includes(slugify(item.queue_id || item.request_id || ""));
    });
  return {
    schema: "meids.okf.reviewed_handoff.v1",
    exported_at: exportedAt,
    boundary: "Portable review artifact only. Does not mutate OKF storage, graph store, vector index, or n8n runtime.",
    twin_id: item.twin_id || state.activeTwin || "florian",
    status: item.review_state || "pending-review",
    queue: {
      queue_id: item.queue_id || "",
      request_id: item.request_id || "",
      trace_id: item.trace_id || "",
      created_at: item.created_at || "",
      reviewed_at: item.reviewed_at || "",
      reviewer: item.reviewer || "",
      review_note: item.review_note || "",
      runtime: item.runtime || "",
      source_type: item.source_type || "",
      intent: item.intent || "",
    },
    okf_targets: {
      concept_path: item.concept_path || "",
      evidence_path: item.evidence_path || "",
      transcript_path: item.transcript_path || "",
      crud_log_path: item.crud_log_path || "",
    },
    graph_promotion: {
      trigger: item.graph_curator_trigger || "not_queued",
      review_state: item.review_state || "pending-review",
      candidate_edges: Array.isArray(item.candidate_edges) ? item.candidate_edges : [],
      promotion_history: graphPromotions,
    },
    vector_boundary: {
      requested_state: item.vector_refresh || "deferred_until_approved",
      adapter_ready: Boolean(state.okfValidationStatus?.summary?.vector_request_fixture_count),
      rule: item.review_state === "approved"
        ? "Queue for approved-index adapter after OKF storage merge."
        : "Hold vector refresh until human review approves the concept.",
    },
    repo_split_target: {
      app_repo: "florianliepe/meids-app",
      knowledge_repo: "meids-knowledge-fabric",
      agent_config_repo: "meids-agent-configs",
    },
  };
}

function updateKnowledgeFabricQueueReview(queueId, action) {
  if (!queueId) return;
  const index = state.knowledgeFabricIngestQueue.findIndex((entry) => entry.queue_id === queueId);
  if (index < 0) {
    showToast("Knowledge Fabric queue", "Queue item not found.", "warning");
    return;
  }
  const reviewedAt = new Date().toISOString();
  const reviewState = action === "approve" ? "approved" : action === "reject" ? "rejected" : "needs-rework";
  const item = state.knowledgeFabricIngestQueue[index];
  const note = knowledgeFabricQueueReviewNote(reviewState, item);
  const updated = {
    ...item,
    review_state: reviewState,
    reviewed_at: reviewedAt,
    reviewer: "local-human-review",
    review_note: note,
    vector_refresh: reviewState === "approved" ? "queued_for_approved_index" : "hold_until_reworked",
    graph_curator_trigger: reviewState === "approved" ? "promotion_accepted" : reviewState === "needs-rework" ? "promotion_needs_rework" : "promotion_rejected",
  };
  state.knowledgeFabricIngestQueue = [
    updated,
    ...state.knowledgeFabricIngestQueue.filter((entry) => entry.queue_id !== queueId),
  ].slice(0, 12);
  try {
    window.localStorage.setItem(storageKeys.knowledgeFabricIngestQueue, JSON.stringify(state.knowledgeFabricIngestQueue));
  } catch (error) {
    console.warn("Knowledge Fabric queue review persistence failed", error);
  }
  appendKnowledgeFabricGraphReviews(updated, reviewState, note, reviewedAt);
  renderKnowledgeFabricQueuePanels();
  renderDashboardGraphPromotionHistory();
  renderGraphCockpit();
  showToast("Knowledge Fabric review saved", labelizeGraph(reviewState), reviewState === "approved" ? "success" : "warning");
}

function knowledgeFabricQueueReviewNote(reviewState, item = {}) {
  if (reviewState === "approved") {
    return "Source handoff approved for OKF promotion. Vector refresh may target the approved index.";
  }
  if (reviewState === "needs-rework") {
    return "Source handoff needs stronger evidence, clearer claim boundaries, or better graph relation wording.";
  }
  return "Source handoff rejected from trusted OKF use. Keep audit evidence but do not promote graph/vector artifacts.";
}

function appendKnowledgeFabricGraphReviews(item = {}, reviewState, note, reviewedAt) {
  const candidateEdges = Array.isArray(item.candidate_edges) && item.candidate_edges.length
    ? item.candidate_edges
    : [{
      source: item.concept_path || `concept:${slugify(item.title || "source-handoff")}`,
      target: "knowledge-fabric-review-gate",
      relation_type: "reviewed_for_promotion",
      confidence: reviewState === "approved" ? 0.8 : 0.5,
    }];
  const reviews = candidateEdges.map((edge, index) => ({
    edge_key: edge.edge_key || `${slugify(item.queue_id || item.request_id || item.title || "queue")}-${slugify(edge.relation_type || "edge")}-${index}`,
    decision: reviewState,
    review_state: reviewState,
    note,
    reviewer: "local-human-review",
    reviewed_at: reviewedAt,
    confidence: edge.confidence,
    source: edge.source || item.concept_path || "source",
    target: edge.target || "target",
    relation_type: edge.relation_type || edge.edge_type || "related",
    path: item.concept_path || item.evidence_path || "",
    source_path: item.concept_path || "",
  }));
  const nextByKey = new Map((state.graphEdgeReviews || []).map((review) => [review.edge_key, review]));
  reviews.forEach((review) => nextByKey.set(review.edge_key, review));
  state.graphEdgeReviews = Array.from(nextByKey.values())
    .sort((a, b) => String(b.reviewed_at || "").localeCompare(String(a.reviewed_at || "")))
    .slice(0, 24);
}

function renderKnowledgeFabricQueuePanels() {
  ["#chatKnowledgeFabricQueue", "#ingestKnowledgeFabricQueue"].forEach((selector) => {
    const target = $(selector);
    if (!target) return;
    const compact = selector.includes("chat");
    target.innerHTML = renderKnowledgeFabricQueue(state.knowledgeFabricIngestQueue || [], compact ? 3 : 8, { compact });
  });
  renderKnowledgeFabricLocalUatChecklist();
  renderKnowledgeFabricIngestPathStatus();
  renderAgentTraceHistoryPanel();
  renderDashboardAgentTraceHistory();
}

function renderKnowledgeFabricLocalUatChecklist() {
  const target = $("#knowledgeFabricLocalUatChecklist");
  if (!target) return;
  const items = knowledgeFabricLocalUatChecklistItems();
  const readyCount = items.filter((item) => item.ready).length;
  target.innerHTML = `
    <div class="knowledge-fabric-uat-head">
      <span class="badge">Local UAT path</span>
      <strong>${escapeHtml(`${readyCount}/${items.length} checks ready`)}</strong>
      <small>${escapeHtml(readyCount === items.length ? "Ready to repeat against live n8n once URLs exist." : "Use this to prove local OKF flow before live n8n rollout.")}</small>
    </div>
    <div class="knowledge-fabric-uat-grid">
      ${items.map((item) => `
        <span class="${item.ready ? "ready" : "open"}">
          <strong>${escapeHtml(item.label)}</strong>
          <small>${escapeHtml(item.detail)}</small>
        </span>
      `).join("")}
    </div>
  `;
}

function knowledgeFabricIngestPathStatus() {
  const queue = state.knowledgeFabricIngestQueue || [];
  const latest = queue[0] || {};
  const reviewed = reviewedKnowledgeFabricQueueItems();
  const approved = reviewed.filter((item) => item.review_state === "approved");
  const graphPromotions = graphPromotionHistoryItems(120);
  const liveKnowledgeUrl = productionAgentUrlReadiness().find((agent) => agent.agentId === "knowledge_fabric_agent")?.configured;
  const liveButlerUrl = productionAgentUrlReadiness().find((agent) => agent.agentId === "agentic_butler")?.configured;
  const hasSource = queue.length > 0;
  const hasOkfTarget = queue.some((item) => item.concept_path || item.evidence_path || item.transcript_path);
  const hasAudit = queue.some((item) => item.crud_log_path);
  const graphQueued = queue.some((item) => item.graph_curator_trigger && !String(item.graph_curator_trigger).includes("not"));
  const vectorHeld = hasSource && queue.every((item) => item.review_state === "approved"
    || String(item.vector_refresh || "").includes("deferred")
    || String(item.vector_refresh || "").includes("hold"));
  const stages = [
    {
      key: "source",
      label: "Source intake",
      status: hasSource ? "ready" : "open",
      detail: hasSource ? `${queue.length} handoff${queue.length === 1 ? "" : "s"} captured` : "Upload, paste, or transcribe a source.",
      action: "open-ingest",
    },
    {
      key: "okf",
      label: "Pending OKF",
      status: hasOkfTarget ? "ready" : hasSource ? "blocked" : "open",
      detail: hasOkfTarget ? "Concept and evidence targets prepared for review." : "Concept/evidence target pending.",
      action: "copy-source-repo-sync",
    },
    {
      key: "audit",
      label: "Evidence + CRUD",
      status: hasAudit ? "ready" : hasSource ? "blocked" : "open",
      detail: hasAudit ? "Audit trail target prepared." : "Append-only audit target pending.",
      action: "export-uat-checklist",
    },
    {
      key: "review",
      label: "Human review",
      status: approved.length ? "ready" : reviewed.length ? "warning" : hasSource ? "open" : "blocked",
      detail: reviewed.length ? `${reviewed.length} reviewed · ${approved.length} approved` : "Approve, rework, or reject before trusted use.",
      action: "review",
    },
    {
      key: "graph",
      label: "Graph curator",
      status: graphPromotions.length ? "ready" : graphQueued ? "warning" : hasSource ? "open" : "blocked",
      detail: graphPromotions.length ? `${graphPromotions.length} promotion decision${graphPromotions.length === 1 ? "" : "s"}` : graphQueued ? "Candidate edge generation queued." : "Graph candidate trigger pending.",
      action: "graph",
    },
    {
      key: "vector",
      label: "Vector boundary",
      status: vectorHeld ? "ready" : hasSource ? "warning" : "blocked",
      detail: approved.length ? "Approved-only refresh may be prepared after repo merge." : "Vector refresh held until approval and repo merge.",
      action: "export-reviewed-bundle",
    },
  ];
  return {
    queue,
    latest,
    reviewed,
    approved,
    liveKnowledgeUrl,
    liveButlerUrl,
    stages,
  };
}

function renderKnowledgeFabricIngestPathStatus() {
  const target = $("#knowledgeFabricIngestPathStatus");
  if (!target) return;
  const status = knowledgeFabricIngestPathStatus();
  const readyCount = status.stages.filter((stage) => stage.status === "ready").length;
  const liveClass = status.liveKnowledgeUrl ? "ready" : "blocked";
  target.innerHTML = `
    <section class="knowledge-fabric-path-panel">
      <div class="knowledge-fabric-path-head">
        <div>
          <span class="badge">Ingest path status</span>
          <h3>${escapeHtml(`${readyCount}/${status.stages.length} lifecycle gates ready`)}</h3>
          <p>${escapeHtml(status.queue.length
            ? "Captured sources are staged for review. Detailed evidence and queue decisions live in Knowledge and Review."
            : "No local source handoff yet. The first upload, paste, or transcript will create the pending OKF path.")}</p>
        </div>
        <span class="${liveClass}">${escapeHtml(status.liveKnowledgeUrl ? "Knowledge Fabric URL configured" : "Knowledge Fabric URL missing")}</span>
      </div>
      <div class="knowledge-fabric-path-flow">
        ${status.stages.map((stage, index) => `
          <button class="${safeGraphClass(stage.status)}" type="button" data-kf-queue-action="${escapeHtml(stage.action)}">
            <small>${escapeHtml(String(index + 1).padStart(2, "0"))}</small>
            <strong>${escapeHtml(stage.label)}</strong>
            <span>${escapeHtml(stage.detail)}</span>
          </button>
        `).join("")}
      </div>
      <div class="knowledge-fabric-path-boundary">
        <span><strong>Trusted retrieval</strong><small>${escapeHtml(status.approved.length ? "allowed only for approved handoffs after repo sync" : "blocked until review approval")}</small></span>
        <span><strong>Graph use</strong><small>${escapeHtml("candidate edges remain hypotheses until accepted")}</small></span>
        <span><strong>n8n bridge</strong><small>${escapeHtml(status.liveKnowledgeUrl && status.liveButlerUrl ? "ready for live UAT" : "fixture/local until remaining URLs exist")}</small></span>
      </div>
    </section>
  `;
}

function renderKnowledgeFabricQueue(items = [], limit = 6, options = {}) {
  if (!items.length) {
    return renderEmptyState("No pending OKF source handoffs yet. Upload, paste, or transcribe a source.");
  }
  const compact = Boolean(options.compact);
  const activeFilter = compact ? "all" : state.knowledgeFabricQueueFilter || "all";
  const filteredItems = filterKnowledgeFabricQueueItems(items, activeFilter);
  const visibleItems = filteredItems.slice(0, limit);
  return `
    ${renderKnowledgeFabricSourceRepoSyncPreview(items, { compact })}
    ${compact ? "" : renderKnowledgeFabricQueueFilterBar(items, activeFilter)}
    ${visibleItems.length
      ? visibleItems.map(renderKnowledgeFabricQueueCard).join("")
      : renderEmptyState(`No Knowledge Fabric handoffs match ${labelizeGraph(activeFilter)}.`)}
  `;
}

function filterKnowledgeFabricQueueItems(items = [], filter = "all") {
  if (filter === "all") return items;
  if (filter === "pending-review") return items.filter((item) => !item.reviewed_at || item.review_state === "pending-review");
  if (filter === "reviewed") return items.filter((item) => item.reviewed_at && ["approved", "needs-rework", "rejected"].includes(String(item.review_state || "")));
  if (filter === "graph-candidates") return items.filter((item) => Array.isArray(item.candidate_edges) && item.candidate_edges.length);
  if (filter === "repo-ready") return items.filter((item) => item.review_state === "approved");
  return items.filter((item) => String(item.review_state || "pending-review") === filter);
}

function knowledgeFabricQueueFilterCounts(items = []) {
  const reviewed = items.filter((item) => item.reviewed_at && ["approved", "needs-rework", "rejected"].includes(String(item.review_state || "")));
  return {
    all: items.length,
    "pending-review": items.filter((item) => !item.reviewed_at || item.review_state === "pending-review").length,
    reviewed: reviewed.length,
    approved: reviewed.filter((item) => item.review_state === "approved").length,
    "needs-rework": reviewed.filter((item) => item.review_state === "needs-rework").length,
    rejected: reviewed.filter((item) => item.review_state === "rejected").length,
    "graph-candidates": items.filter((item) => Array.isArray(item.candidate_edges) && item.candidate_edges.length).length,
    "repo-ready": reviewed.filter((item) => item.review_state === "approved").length,
  };
}

function renderKnowledgeFabricQueueFilterBar(items = [], activeFilter = "all") {
  const counts = knowledgeFabricQueueFilterCounts(items);
  const filters = [
    ["all", "All"],
    ["pending-review", "Pending"],
    ["reviewed", "Reviewed"],
    ["approved", "Approved"],
    ["needs-rework", "Rework"],
    ["rejected", "Rejected"],
    ["graph-candidates", "Graph"],
    ["repo-ready", "Repo ready"],
  ];
  return `
    <div class="knowledge-fabric-queue-filter" aria-label="Knowledge Fabric queue filter">
      <strong>${escapeHtml(`${filterKnowledgeFabricQueueItems(items, activeFilter).length}/${items.length} visible`)}</strong>
      <div class="filter-chip-row">
        ${filters.map(([value, label]) => `
          <button class="filter-chip ${activeFilter === value ? "active" : ""}" type="button" data-kf-queue-action="filter" data-kf-queue-filter="${escapeHtml(value)}" aria-pressed="${activeFilter === value ? "true" : "false"}">
            ${escapeHtml(label)} <span>${escapeHtml(String(counts[value] || 0))}</span>
          </button>
        `).join("")}
      </div>
    </div>
  `;
}

function renderKnowledgeFabricSourceRepoSyncPreview(items = [], options = {}) {
  const reviewed = reviewedKnowledgeFabricQueueItems();
  const approved = reviewed.filter((item) => item.review_state === "approved");
  const pending = items.filter((item) => !item.reviewed_at || item.review_state === "pending-review");
  const needsRework = reviewed.filter((item) => item.review_state === "needs-rework");
  const rejected = reviewed.filter((item) => item.review_state === "rejected");
  const withEvidence = items.filter((item) => item.concept_path || item.evidence_path || item.transcript_path);
  const graphCandidates = items.reduce((count, item) => count + (Array.isArray(item.candidate_edges) ? item.candidate_edges.length : 0), 0);
  const syncState = approved.length
    ? `${approved.length} approved handoff${approved.length === 1 ? "" : "s"} eligible for knowledge-repo PR.`
    : "No approved handoff is eligible for repo sync yet.";
  const vectorState = approved.length
    ? "Vector refresh can be queued only after knowledge repo merge."
    : "Vector refresh remains blocked until approval and repo merge.";
  const compact = Boolean(options.compact);
  return `
    <article class="knowledge-fabric-repo-sync-preview">
      <div>
        <span class="badge">OKF repo-sync preview</span>
        <h3>Source intake package is ready for review, not trusted retrieval.</h3>
        <p>${escapeHtml(`${items.length} handoff${items.length === 1 ? "" : "s"} · ${pending.length} pending · ${approved.length} approved · ${graphCandidates} candidate edge${graphCandidates === 1 ? "" : "s"}`)}</p>
      </div>
      <div class="knowledge-fabric-repo-sync-stats" aria-label="Knowledge repo-sync package readiness">
        <span><strong>${escapeHtml(withEvidence.length)}</strong><small>OKF targets</small></span>
        <span><strong>${escapeHtml(reviewed.length)}</strong><small>reviewed</small></span>
        <span><strong>${escapeHtml(approved.length)}</strong><small>eligible</small></span>
        <span><strong>hold</strong><small>vector rule</small></span>
      </div>
      <div class="knowledge-fabric-repo-sync-eligibility" aria-label="Reviewed handoff repo-sync eligibility">
        <span class="${approved.length ? "ready" : "blocked"}"><strong>${escapeHtml(String(approved.length))}</strong><small>${escapeHtml(syncState)}</small></span>
        <span class="${pending.length ? "warning" : "ready"}"><strong>${escapeHtml(String(pending.length))}</strong><small>pending review; audit-only until approved</small></span>
        <span class="${needsRework.length ? "warning" : "ready"}"><strong>${escapeHtml(String(needsRework.length))}</strong><small>needs rework; return to Knowledge Fabric Agent</small></span>
        <span class="${rejected.length ? "blocked" : "ready"}"><strong>${escapeHtml(String(rejected.length))}</strong><small>rejected; preserve as audit evidence only</small></span>
        <span class="${graphCandidates ? "warning" : "blocked"}"><strong>${escapeHtml(String(graphCandidates))}</strong><small>candidate graph edges require curator decision</small></span>
        <span class="${approved.length ? "warning" : "blocked"}"><strong>${escapeHtml(approved.length ? "queued later" : "blocked")}</strong><small>${escapeHtml(vectorState)}</small></span>
      </div>
      <div class="okf-graph-repo-sync-plan compact">
        <strong>Knowledge repo target</strong>
        <ol>
          <li>Materialize approved handoffs into OKF Markdown/YAML after human PR review.</li>
          <li>Store pending, rejected, and needs-rework handoffs as audit evidence only.</li>
          <li>Queue graph and vector updates only after the knowledge repo merge.</li>
        </ol>
      </div>
      ${compact || !approved.length ? "" : renderKnowledgeFabricApprovedPrHandoffPreview(approved)}
      <div class="button-row tight">
        <button class="secondary small" type="button" data-kf-queue-action="copy-source-repo-sync">Copy source repo-sync JSON</button>
        ${compact ? "" : `<button class="secondary small" type="button" data-kf-queue-action="copy-approved-pr-handoff" ${approved.length ? "" : "disabled"} title="${escapeHtml(approved.length ? "Copy approved handoffs as a knowledge-repo PR checklist." : "Approve at least one handoff before creating a PR handoff.")}">Copy approved PR handoff</button>`}
        <button class="secondary small" type="button" data-kf-queue-action="export-reviewed-bundle">Export reviewed bundle</button>
        <button class="secondary small" type="button" data-kf-queue-action="export-uat-checklist">Export UAT checklist</button>
      </div>
    </article>
  `;
}

function renderKnowledgeFabricApprovedPrHandoffPreview(approvedItems = []) {
  const graphCount = approvedItems.reduce((count, item) => count + (Array.isArray(item.candidate_edges) ? item.candidate_edges.length : 0), 0);
  const pathCount = approvedItems.reduce((count, item) => count + [
    item.concept_path,
    item.evidence_path,
    item.transcript_path,
    item.crud_log_path,
  ].filter(Boolean).length, 0);
  return `
    <div class="knowledge-fabric-approved-pr-preview" aria-label="Approved knowledge repo PR handoff">
      <div>
        <span class="badge">PR handoff candidate</span>
        <strong>${escapeHtml(`${approvedItems.length} approved OKF handoff${approvedItems.length === 1 ? "" : "s"}`)}</strong>
        <small>${escapeHtml(`${pathCount} target path${pathCount === 1 ? "" : "s"} · ${graphCount} graph candidate${graphCount === 1 ? "" : "s"} · vector refresh after merge`)}</small>
      </div>
      <ol>
        <li>Create a knowledge repo branch from the copied handoff.</li>
        <li>Materialize only approved concept/evidence/transcript files.</li>
        <li>Keep graph and vector updates gated until PR approval.</li>
      </ol>
    </div>
  `;
}

