function renderAgentTraceHistoryRows(traces = [], limit = 12) {
  return traces.slice(0, limit).map((trace) => {
    const agentId = String(trace.agent_id || "unknown").toLowerCase();
    const agentClass = safeGraphClass(agentId);
    const statusClass = trace.approval_required ? "approval" : safeGraphClass(trace.status || "completed");
    const traceKey = trace.trace_id || trace.request_id || "";
    const selected = traceKey && state.selectedAgentTraceId === traceKey;
    return `
    <article class="agent-trace-row ${statusClass} ${agentClass}${selected ? " selected" : ""}" data-agent-trace-key="${escapeHtml(traceKey)}">
      <div>
        <span class="badge">${escapeHtml(selected ? "selected trace" : trace.demo ? "staging trace" : trace.approval_required ? "approval gate" : trace.status || "trace")}</span>
        <span class="agent-trace-agent-chip ${agentClass}">${escapeHtml(agentDisplayName(agentId))}</span>
        <strong>${escapeHtml(trace.agent_name || agentDisplayName(trace.agent_id || ""))}</strong>
        <p>${escapeHtml(`${trace.runtime || "fixture/local"} · ${trace.twin || "active twin"} · ${formatShortDate(trace.timestamp)}`)}</p>
      </div>
      <div class="agent-trace-meta">
        <code>${escapeHtml(trace.trace_id || "trace pending")}</code>
        <small>${escapeHtml(trace.request_id || "")}</small>
      </div>
      ${renderAgentTraceChain(trace)}
      ${trace.artifact_path || trace.detail ? `
        <div class="agent-trace-artifact">
          ${trace.artifact_path ? `<code>${escapeHtml(trace.artifact_path)}</code>` : ""}
          ${trace.detail ? `<small>${escapeHtml(trace.detail)}</small>` : ""}
        </div>
      ` : ""}
    </article>
  `;
  }).join("");
}

function renderAgentTraceChain(trace = {}) {
  const actorTraceId = trace.actor_trace_id || (trace.agent_id === "actor_twin" ? trace.trace_id : "");
  const handoffTraceId = trace.handoff_trace_id || (trace.agent_id !== "actor_twin" ? trace.trace_id : "");
  const decision = trace.route_decision || "";
  const target = trace.target_agent || trace.agent_id || "";
  const status = trace.handoff_status || trace.status || "";
  if (!actorTraceId && !handoffTraceId && !decision && !target && !status) return "";
  return `
    <div class="agent-trace-chain" aria-label="Actor-to-target trace chain">
      ${decision ? `<span><strong>${escapeHtml(labelizeGraph(decision))}</strong><small>route decision</small></span>` : ""}
      ${target ? `<span><strong>${escapeHtml(agentDisplayName(target))}</strong><small>target</small></span>` : ""}
      ${status ? `<span><strong>${escapeHtml(labelizeGraph(status))}</strong><small>handoff status</small></span>` : ""}
      ${actorTraceId ? `<span><code>${escapeHtml(actorTraceId)}</code><small>actor trace</small></span>` : ""}
      ${handoffTraceId ? `<span><code>${escapeHtml(handoffTraceId)}</code><small>target trace</small></span>` : ""}
    </div>
  `;
}

function outputFromN8nData(data) {
  if (Array.isArray(data) && data[0]?.json) return outputFromN8nData(data[0].json);
  if (data?.json) return outputFromN8nData(data.json);
  if (data?.output) return data.output;
  if (typeof data === "string") return { answer: data };
  if (data?.answer || data?.text || data?.message) return { ...data, answer: data.answer || data.text || data.message };
  return data && typeof data === "object" ? data : {};
}

function extractAgentAnswer(output, status = "completed") {
  if (status === "approval_required") return "Human approval is required before this action can continue.";
  output = normalizeAgentOutput(output);
  if (typeof output === "string") return output;
  if (!output || typeof output !== "object") return "Agent completed.";
  if (output.email_draft?.subject) return `Drafted email: ${output.email_draft.subject}`;
  if (output.delegate_result?.output) return extractAgentAnswer(output.delegate_result.output, output.delegate_result.status || status);
  return output.answer || output.summary || output.concept_path || "Agent completed.";
}

function agentDisplayName(agentId) {
  return {
    actor_twin: "Actor Twin",
    knowledge_fabric_agent: "Knowledge Fabric Agent",
    agentic_butler: "Agentic Butler",
  }[agentId] || agentId || "Agent";
}

