function splitPromptList(value) {
  return String(value || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function splitTextList(value) {
  return String(value || "")
    .split(/\r?\n|,/)
    .map((item) => item.trim())
    .filter(Boolean);
}

async function reviewMcpCanaryPackage(path, decision) {
  if (!path || !decision) return;
  const labels = {
    approve_for_single_canary: "Approve this package for one canary?",
    revise: "Request revision for this package?",
    reject: "Reject this package?",
  };
  const confirmed = await requestDecision({
    eyebrow: "MCP canary governance",
    title: labels[decision] || "Review this package?",
    body: `${path}\n\nThis updates review state only. It will not enable the gateway or call GitHub.`,
    confirmLabel: decision === "reject" ? "Reject package" : decision === "revise" ? "Request revision" : "Approve single canary",
    danger: decision === "reject",
  });
  if (!confirmed) return;
  const rationale = window.prompt("Reviewer rationale / note", "") || "";
  try {
    const result = await postJson("/api/mcp/canary-approval-package/review", {
      path,
      decision,
      rationale,
      actor: "local-user",
    });
    state.mcpCanaryApprovalPackageDetail = {
      path: result.path,
      file_hash: result.file_hash,
      package: result.package,
    };
    await refreshMcpPackageLedger(false);
    renderMcpCockpit();
    showToast("Canary package reviewed", result.status || decision, "success");
  } catch (error) {
    showToast("Package review failed", error.message, "error");
  }
}

async function rollbackMcpCanaryPackage(path) {
  if (!path) return;
  const confirmed = await requestDecision({
    eyebrow: "MCP canary rollback",
    title: "Record rollback for this package?",
    body: `${path}\n\nThis records rollback evidence only. It does not call GitHub, rotate credentials, or change hosted gateway policy.`,
    confirmLabel: "Record rollback",
    danger: true,
  });
  if (!confirmed) return;
  const rationale = window.prompt("Rollback rationale / note", "") || "";
  try {
    const result = await postJson("/api/mcp/canary-approval-package/rollback", {
      path,
      rationale,
      actor: "local-user",
      actions: [
        "Gateway execution remains disabled or is set back to disabled.",
        "Canary GitHub/MCP credential is rotated or revoked if it was exposed to runtime.",
        "Canary pull request or branch is closed if it was created.",
        "Affected sync and skill paths remain pinned to mock MCP staging.",
      ],
    });
    state.mcpCanaryApprovalPackageDetail = {
      path: result.path,
      file_hash: result.file_hash,
      package: result.package,
    };
    await refreshMcpPackageLedger(false);
    renderMcpCockpit();
    showToast("Canary rollback recorded", result.path || "rollback ledger updated", "success");
  } catch (error) {
    showToast("Rollback failed", error.message, "error");
  }
}

