function productionProgressStages() {
  const readiness = state.productionReadiness || {};
  const githubBridge = state.productionGithubKnowledgeBridge || {};
  const finalPacket = state.productionFinalReviewPacket || {};
  const evidence = state.productionEvidenceCompleteness || {};
  const governance = state.productionGovernance || {};
  const mcpReadiness = state.mcpRealReadiness || {};
  const goNoGo = state.productionGoNoGo || {};
  const rollout = state.productionRolloutChecklist || {};
  const evidenceScore = evidence.score ?? finalPacket.summary?.evidence_score_percent ?? 0;
  return [
    {
      id: "hosted",
      label: "Hosted",
      ready: Boolean(readiness.hosted_ready),
      metric: `${readiness.ready_count ?? 0}/${readiness.check_count ?? 0}`,
      next: readiness.next_action || "Configure hosted production prerequisites.",
      detail: "Hosted foundation covers Postgres, object storage, auth, secrets, observability, and MCP credentials.",
      action: "Use Env setup guide and migration connection checklist.",
    },
    {
      id: "repository",
      label: "Repo",
      ready: githubBridge.status === "branch_ready",
      partial: githubBridge.status === "ready_to_apply_payload",
      metric: githubBridge.status || "pending",
      next: githubBridge.next_action || "Prepare knowledge repository PR evidence.",
      detail: githubBridge.expected_branch
        ? `Expected branch ${githubBridge.expected_branch}${githubBridge.local_repo?.branch ? ` · current ${githubBridge.local_repo.branch}` : ""}`
        : "Knowledge repository branch evidence is not available yet.",
      action: "Apply payload, push branch, then review GitHub compare page.",
    },
    {
      id: "mcp",
      label: "MCP",
      ready: Boolean(mcpReadiness.canary_ready || governance.safe_to_enable_real_mcp),
      metric: mcpReadiness.canary_ready ? "canary" : "blocked",
      next: mcpReadiness.next_action || "Complete MCP gateway and canary readiness.",
      detail: governance.safe_to_enable_real_mcp ? "Governance permits real MCP canary review." : "Real MCP remains gated by approval and hosted readiness evidence.",
      action: "Review MCP gateway package and hosted canary runbook.",
    },
    {
      id: "review",
      label: "Review",
      ready: finalPacket.status === "ready_for_final_review",
      metric: `${evidenceScore}%`,
      next: finalPacket.next_action || goNoGo.next_action || "Freeze final review packet.",
      detail: `${finalPacket.status || "blocked"} · rollout ${rollout.status || "blocked"} · verdict ${goNoGo.verdict || goNoGo.decision || "no_go"}`,
      action: "Export rollout checklist and final review packet after blockers clear.",
    },
  ];
}

function renderProductionProgressHeader() {
  const target = $("#productionProgressHeader");
  if (!target) return;
  if (document.body.dataset.activeView !== "quality") {
    target.hidden = true;
    target.innerHTML = "";
    return;
  }
  const readiness = state.productionReadiness || {};
  const finalPacket = state.productionFinalReviewPacket || {};
  const bridge = state.productionGithubKnowledgeBridge || {};
  const runtimeReadiness = state.n8nRuntimeReadinessStatus || {};
  const actorRouting = state.actorTwinRoutingReadinessStatus || {};
  const hasState = Boolean(
    readiness.type ||
    readiness.status ||
    readiness.check_count !== undefined ||
    finalPacket.status ||
    bridge.status ||
    runtimeReadiness.schema_version ||
    actorRouting.schema_version
  );
  if (!hasState) {
    target.hidden = true;
    target.innerHTML = "";
    return;
  }
  const stages = productionProgressStages();
  const readyCount = stages.filter((stage) => stage.ready).length;
  const partialCount = stages.filter((stage) => stage.partial).length;
  const next = stages.find((stage) => !stage.ready && !stage.partial) || stages.find((stage) => stage.partial) || stages.find((stage) => !stage.ready);
  target.hidden = false;
  target.innerHTML = `
    <section class="production-progress-strip ${readyCount === stages.length ? "ready" : "blocked"}">
      <div class="production-progress-main">
        <span class="badge">Production path</span>
        <strong>${escapeHtml(readyCount)}/${escapeHtml(stages.length)} lanes ready${partialCount ? ` · ${escapeHtml(partialCount)} in handoff` : ""}</strong>
        <p>${escapeHtml(next?.next || "Production evidence is ready for final review.")}</p>
      </div>
      <div class="production-progress-pills" aria-label="Production lane readiness">
        ${stages.map((stage) => `
          <span class="${stage.ready ? "ready" : stage.partial ? "partial" : "blocked"}">
            <strong>${escapeHtml(stage.label)}</strong>
            <small>${escapeHtml(stage.metric)}</small>
          </span>
        `).join("")}
      </div>
      <div class="production-progress-actions">
        <button class="secondary small" type="button" data-cockpit-action="openProductionCockpit">Open production</button>
        <button id="quickExportFinalReviewPacketBtn" class="secondary small" type="button">Export final packet</button>
      </div>
      ${renderN8nRuntimeReadinessMini()}
      <details class="production-progress-details">
        <summary>Lane details</summary>
        <div>
          ${stages.map((stage) => `
            <article class="${stage.ready ? "ready" : stage.partial ? "partial" : "blocked"}">
              <span>${escapeHtml(stage.label)} · ${escapeHtml(stage.ready ? "ready" : stage.partial ? "handoff" : "blocked")}</span>
              <strong>${escapeHtml(stage.next)}</strong>
              <p>${escapeHtml(stage.detail || "")}</p>
              <small>${escapeHtml(stage.action || "")}</small>
            </article>
          `).join("")}
        </div>
      </details>
    </section>
  `;
  $("#quickExportFinalReviewPacketBtn")?.addEventListener("click", exportProductionFinalReviewPacket);
}

function renderN8nRuntimeReadinessMini() {
  const readiness = state.n8nRuntimeReadinessStatus || {};
  const summary = readiness.summary || {};
  const agents = Array.isArray(readiness.agents) ? readiness.agents : [];
  if (!agents.length) return "";
  const configured = summary.configured_count ?? agents.filter((agent) => agent.url_configured).length;
  const runtimeReady = summary.runtime_ready_count ?? agents.filter((agent) => agent.runtime_ready || agent.url_configured).length;
  const total = summary.agent_count ?? agents.length;
  const awaiting = summary.awaiting_url_count ?? agents.filter((agent) => agent.status === "awaiting_url").length;
  const status = readiness.status || (runtimeReady === total ? "ready" : configured > 0 ? "partial" : "blocked");
  const nextAgent = agents.find((agent) => !(agent.runtime_ready || agent.url_configured)) || agents[0];
  return `
    <aside class="production-runtime-readiness-mini ${escapeHtml(status)}" aria-label="n8n runtime readiness">
      <div>
        <span class="badge">n8n contracts</span>
        <strong>${escapeHtml(runtimeReady)}/${escapeHtml(total)} runtime paths ready</strong>
        <p>${escapeHtml(awaiting ? `${awaiting} optional direct URL(s) still awaiting public UAT endpoint.` : "Actor Twin embedded chat is the frontend entrypoint; worker agents are internal n8n tools unless exposed for direct UAT.")}</p>
      </div>
      <div class="production-runtime-readiness-agents">
        ${agents.map((agent) => `
          <span class="${escapeHtml(agent.status || "unknown")}">
            <strong>${escapeHtml(agent.agent_name || agent.agent_id)}</strong>
            <small>${escapeHtml(agent.status_label || agent.status || "unknown")}</small>
          </span>
        `).join("")}
      </div>
      <div class="production-runtime-readiness-next">
        <small>${escapeHtml(nextAgent?.next_action || readiness.boundary || "Review runtime readiness artifact.")}</small>
        <a class="secondary small" href="${escapeHtml(githubBlobUrl("frontend/assets/n8n-runtime-readiness-status.json"))}" target="_blank" rel="noreferrer">Open status</a>
      </div>
    </aside>
  `;
}

