async function recordSqlExecutionEvidenceArtifact() {
  const confirmed = await requestDecision({
    eyebrow: "SQL execution evidence",
    title: "Record CI/staging SQL execution evidence?",
    body: "This records externally run validation results and log references. It does not install dependencies, connect to Postgres, run Alembic, or contact hosted systems.",
    confirmLabel: "Record evidence",
  });
  if (!confirmed) return;
  const outcome = window.prompt("Outcome: passed, passed_with_warnings, failed, not_run", "not_run") || "not_run";
  const environment = window.prompt("Environment: ci_ephemeral or staging", "ci_ephemeral") || "ci_ephemeral";
  const sharedLogRef = window.prompt("Main CI/staging log reference or artifact path", "") || "";
  const ciArtifactUrl = window.prompt("Optional CI artifact URL for this validation run", sharedLogRef) || "";
  const tableCountRaw = window.prompt("Observed public table count from catalog validation", "0") || "0";
  const expectedTableCountRaw = window.prompt("Expected public table count", "0") || "0";
  const rationale = window.prompt("Reviewer rationale / note", "Recorded from production cockpit") || "";
  const commandResults = (state.sqlValidationPlan?.commands || []).map((command) => ({
    id: command.id || "command",
    status: outcome === "failed" ? "failed" : outcome === "not_run" ? "skipped" : "passed",
    duration_seconds: 0,
    log_ref: sharedLogRef,
  }));
  try {
    const result = await postJson("/api/migration/sql-execution-evidence-artifact", {
      actor: "local-user",
      note: "recorded from production migration cockpit",
      environment,
      outcome,
      ci_artifact_url: ciArtifactUrl,
      database_url_ref: window.prompt("DATABASE_URL secret reference only", "CI secret: DATABASE_URL") || "",
      install_log_ref: sharedLogRef,
      offline_sql_log_ref: sharedLogRef,
      postgres_log_ref: sharedLogRef,
      upgrade_log_ref: sharedLogRef,
      catalog_validation_log_ref: sharedLogRef,
      table_count: Number.parseInt(tableCountRaw, 10) || 0,
      expected_table_count: Number.parseInt(expectedTableCountRaw, 10) || 0,
      warning_count: outcome === "passed_with_warnings" ? 1 : 0,
      error_count: outcome === "failed" ? 1 : 0,
      command_results: commandResults,
      reviewer: "local-user",
      rationale,
    });
    state.sqlExecutionEvidenceArtifact = result;
    await refreshProductionStatus();
    showToast("SQL execution evidence recorded", result.path || result.artifact_hash || "execution evidence saved", "success");
  } catch (error) {
    showToast("SQL execution evidence failed", error.message, "error");
  }
}

async function copySqlExecutionEvidenceGuide() {
  const guide = state.sqlExecutionEvidenceGuide || {};
  const text = guide.powershell || JSON.stringify(guide.payload_template || {}, null, 2);
  if (!text || text === "{}") {
    showToast("SQL evidence guide unavailable", "Refresh production readiness first.", "error");
    return;
  }
  const copied = await copyTextToClipboard(text);
  showToast(
    copied ? "SQL evidence payload copied" : "Copy unavailable",
    copied ? "Replace placeholders with CI/staging log refs before posting." : "Clipboard access was blocked.",
    copied ? "success" : "error",
  );
}

