function renderProductionConfigureNext(readiness = {}) {
  const target = $("#productionConfigureNext");
  if (!target) return;
  const action = readiness.next_configure_action || {};
  const bundle = state.productionNextActionCommandBundle || {};
  const env = Array.isArray(action.env) ? action.env : [];
  const docs = Array.isArray(action.docs) ? action.docs : [];
  const commands = Array.isArray(action.commands) ? action.commands : [];
  const validation = Array.isArray(action.validation) ? action.validation : [];
  const commandSections = Array.isArray(bundle.commands) ? bundle.commands : [];
  const priorityCommand = selectProductionPriorityCommand(commandSections);
  const operatorSteps = Array.isArray(bundle.operator_steps) ? bundle.operator_steps : [];
  const evidenceTargets = Array.isArray(bundle.evidence_to_export) ? bundle.evidence_to_export : [];
  const envRecords = Array.isArray(bundle.env) ? bundle.env : [];
  const ready = action.status === "ready" || readiness.hosted_ready;
  target.innerHTML = `
    <article class="production-configure-next ${ready ? "ready" : "blocked"}">
      <div class="production-configure-main">
        <span>${ready ? "Ready gate" : "Configure next"}</span>
        <strong>${escapeHtml(action.title || "Resolve hosted readiness blocker")}</strong>
        <p>${escapeHtml(action.action || readiness.next_action || "Review hosted readiness before production rollout.")}</p>
        ${action.ui_anchor ? `<small>${escapeHtml(action.ui_anchor)}</small>` : ""}
      </div>
      <div class="production-configure-meta">
        <span><strong>${escapeHtml(action.ready_count ?? readiness.ready_count ?? 0)}</strong>/${escapeHtml(action.check_count ?? readiness.check_count ?? 0)} checks ready</span>
        <span><strong>${escapeHtml(action.remaining_blockers ?? (Array.isArray(readiness.blockers) ? readiness.blockers.length : 0))}</strong> blockers</span>
      </div>
      <div class="production-configure-grid">
        <div>
          <span>Env vars</span>
          ${env.length ? `<code>${escapeHtml(env.join(" · "))}</code>` : "<small>No missing env vars.</small>"}
        </div>
        <div>
          <span>Docs</span>
          ${docs.length ? `<code>${escapeHtml(docs.join(" · "))}</code>` : "<small>Use deployment guide.</small>"}
        </div>
        <div>
          <span>Commands / APIs</span>
          ${commands.length ? `<code>${escapeHtml(commands.join(" · "))}</code>` : "<small>Refresh readiness.</small>"}
        </div>
        <div>
          <span>Validate</span>
          ${validation.length ? `<code>${escapeHtml(validation.join(" · "))}</code>` : "<small>Refresh readiness.</small>"}
        </div>
      </div>
      ${priorityCommand
        ? `<section class="production-priority-command">
            <div>
              <span class="badge">Copy next operator command</span>
              <strong>${escapeHtml(priorityCommand.label || "Next command")}</strong>
              <p>${escapeHtml(bundle.blocker?.action || action.action || readiness.next_action || "Run this first, then validate readiness again.")}</p>
            </div>
            ${renderProductionCommand(priorityCommand.label || "Next command", priorityCommand.command || "# command unavailable", { compact: true })}
          </section>`
        : ""}
      <details class="production-command-pack" open>
        <summary>Copy hosted setup command bundle</summary>
        <div class="production-command-grid">
          ${commandSections.length
            ? commandSections.map((item) => renderProductionCommand(item.label || "Command", item.command || "# command unavailable")).join("")
            : renderProductionCommand("Refresh bundle", "# GET /api/production/next-action-command-bundle")}
        </div>
      </details>
      <div class="production-configure-grid">
        <div>
          <span>Operator sequence</span>
          ${operatorSteps.length
            ? `<ol class="compact-list">${operatorSteps.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ol>`
            : "<small>Refresh command bundle.</small>"}
        </div>
        <div>
          <span>Evidence to export</span>
          ${evidenceTargets.length
            ? `<ul class="compact-list">${evidenceTargets.map((item) => `<li><strong>${escapeHtml(item.label || "Artifact")}</strong><small>${escapeHtml(item.endpoint || "")}</small></li>`).join("")}</ul>`
            : "<small>No evidence target returned.</small>"}
        </div>
        <div>
          <span>Env details</span>
          ${envRecords.length
            ? `<ul class="compact-list">${envRecords.map((item) => `<li><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.secret ? `secret · ${item.key_vault_secret || "key-vault"}` : item.placeholder || "value")}</small></li>`).join("")}</ul>`
            : "<small>No current env vars.</small>"}
        </div>
        <div>
          <span>Boundary</span>
          <small>${escapeHtml(bundle.boundary || "Secret-safe setup guidance only.")}</small>
        </div>
      </div>
    </article>
  `;
  bindConceptSourceActions(target);
}

function selectProductionPriorityCommand(commands = []) {
  const actionable = commands.find((item) => {
    const label = String(item.label || "").toLowerCase();
    const command = String(item.command || "").trim();
    if (!command || command.startsWith("#")) return false;
    if (label.includes("local readiness") || label.includes("validation")) return false;
    if (command.toLowerCase().includes("no non-secret app settings required")) return false;
    return true;
  });
  return actionable || commands.find((item) => String(item.command || "").trim() && !String(item.command || "").trim().startsWith("#")) || null;
}

function renderProductionEvidenceCompleteness() {
  const target = $("#productionEvidenceCompleteness");
  if (!target) return;
  const score = state.productionEvidenceCompleteness || {};
  const summary = score.summary || {};
  const missing = Array.isArray(score.missing) ? score.missing : [];
  const lanes = Array.isArray(score.lanes) ? score.lanes : [];
  if (!lanes.length) {
    target.innerHTML = "";
    return;
  }
  const nextExport = score.next_export || missing[0] || {};
  const readyCount = summary.ready_count ?? lanes.filter((item) => item.ready).length;
  const laneCount = summary.lane_count ?? lanes.length;
  target.innerHTML = `
    <section class="production-evidence-card ${score.status === "complete" ? "ready" : "blocked"}">
      <div class="production-evidence-head">
        <div>
          <span class="badge">Production evidence completeness</span>
          <strong>${escapeHtml(score.score ?? 0)}% evidence ready</strong>
          <p>${escapeHtml(score.next_action || "Review missing production evidence.")}</p>
        </div>
        <span class="production-evidence-score">${escapeHtml(readyCount)}/${escapeHtml(laneCount)}</span>
      </div>
      <div class="production-go-no-go-metrics">
        <span><strong>${escapeHtml(summary.missing_count ?? missing.length)}</strong>missing</span>
        <span><strong>${escapeHtml(summary.go_no_go_verdict || "no_go")}</strong>verdict</span>
        <span><strong>${escapeHtml(summary.hosted_ready ? "yes" : "no")}</strong>hosted ready</span>
        <span><strong>${escapeHtml(nextExport.label || "none")}</strong>next export</span>
      </div>
      ${missing.length
        ? `<div class="production-evidence-missing">
            ${missing.slice(0, 6).map((item) => `
              <article>
                <span>${escapeHtml(item.status || "missing")}</span>
                <strong>${escapeHtml(item.label || item.id || "Evidence lane")}</strong>
                <p>${escapeHtml(item.next_action || "Export evidence.")}</p>
              </article>
            `).join("")}
          </div>`
        : ""}
      <div class="production-evidence-checklist" role="table" aria-label="Production evidence checklist">
        <div class="production-evidence-checklist-head" role="row">
          <span>Lane</span>
          <span>Status</span>
          <span>Latest evidence</span>
          <span>Action</span>
        </div>
        ${lanes.map(renderProductionEvidenceChecklistRow).join("")}
      </div>
      <small>${escapeHtml(score.boundary || "Read-only evidence score.")}</small>
    </section>
  `;
  target.querySelectorAll(".production-evidence-action").forEach((button) => {
    button.addEventListener("click", () => handleProductionEvidenceAction(button.dataset.action, button.dataset.path || ""));
  });
}

function renderProductionEvidenceChecklistRow(item = {}) {
  const latestPath = item.latest_path || "";
  const action = productionEvidenceActionFor(item.id, latestPath);
  const count = Number(item.count || 0);
  return `
    <div class="production-evidence-checklist-row ${item.ready ? "ready" : "missing"}" role="row">
      <div role="cell">
        <strong>${escapeHtml(item.label || item.id || "Evidence lane")}</strong>
        <small>${escapeHtml(item.next_action || "Evidence available.")}</small>
      </div>
      <span role="cell">${escapeHtml(item.status || (item.ready ? "ready" : "missing"))}${count ? ` · ${escapeHtml(count)}` : ""}</span>
      <code role="cell">${escapeHtml(latestPath || "No local artifact yet")}</code>
      <div role="cell">
        ${action
          ? `<button class="secondary small production-evidence-action" type="button" data-action="${escapeHtml(action.name)}" data-path="${escapeHtml(latestPath)}">${escapeHtml(action.label)}</button>`
          : `<small>${escapeHtml(item.ready ? "No quick action" : "Use lane cockpit")}</small>`}
      </div>
    </div>
  `;
}

