function renderMigrationConnectionTarget(item) {
  const ready = Boolean(item.ready);
  const checks = Array.isArray(item.checks) ? item.checks : [];
  const env = Array.isArray(item.required_env) ? item.required_env : [];
  const docs = Array.isArray(item.docs) ? item.docs : [];
  return `
    <article class="migration-connection-card ${ready ? "ready" : "blocked"}">
      <div>
        <span>${escapeHtml(ready ? "ready" : "blocked")}</span>
        <strong>${escapeHtml(item.label || item.name || "Connection target")}</strong>
        <p>${escapeHtml(item.detail || item.next_action || "Review hosted connection readiness.")}</p>
      </div>
      <ul>
        ${checks.length
          ? checks.map((check) => `<li class="${check.ready ? "ready" : "blocked"}">${escapeHtml(check.label || check.name || "check")} · ${escapeHtml(check.status || (check.ready ? "ready" : "missing"))}</li>`).join("")
          : "<li>No sub-checks returned.</li>"}
      </ul>
      <div class="migration-connection-meta">
        ${env.length ? `<code>${escapeHtml(env.join(" · "))}</code>` : "<small>No missing env vars reported.</small>"}
        ${docs.length ? `<small>${escapeHtml(docs.join(" · "))}</small>` : ""}
      </div>
      <small>${escapeHtml(item.next_action || "No action returned.")}</small>
    </article>
  `;
}

