function renderProductionCheckCard(item, options = {}) {
  const missing = options.forceMissing || !item.ready;
  const status = item.status || (missing ? "missing" : "ready");
  const env = Array.isArray(item.env) ? item.env : [];
  return `
    <article class="production-check ${missing ? "missing" : "ready"}">
      <strong>${escapeHtml(item.label || item.name || "Production check")}</strong>
      <span>${escapeHtml(status)}</span>
      <small>${escapeHtml(item.name || "")}</small>
      ${item.detail ? `<p>${escapeHtml(item.detail)}</p>` : ""}
      ${item.action ? `<p class="production-check-action">${escapeHtml(item.action)}</p>` : ""}
      ${env.length ? `<code>${escapeHtml(env.join(" · "))}</code>` : ""}
    </article>
  `;
}

function renderProductionRestartHint() {
  const target = $("#productionRestartHint");
  if (!target) return;
  const status = state.backendStatus || {};
  const backendBuildTag = status.frontend_build_tag || "";
  const appVersion = status.app_version || "unknown";
  const startedAt = status.started_at || "";
  const isCurrent = backendBuildTag === FRONTEND_BUILD_TAG;
  if (isCurrent) {
    target.innerHTML = `
      <article class="production-restart-hint-card ready">
        <span>Runtime current</span>
        <strong>Frontend and backend build markers match.</strong>
        <small>${escapeHtml(appVersion)} · ${escapeHtml(backendBuildTag)}</small>
      </article>
    `;
    return;
  }
  target.innerHTML = `
    <article class="production-restart-hint-card warning">
      <span>Restart recommended</span>
      <strong>Running backend does not match this frontend build.</strong>
      <p>Restart the local MVP server before judging production readiness or testing newly added endpoints.</p>
      <code>expected ${escapeHtml(FRONTEND_BUILD_TAG)} · backend ${escapeHtml(backendBuildTag || "missing marker")}${startedAt ? ` · started ${escapeHtml(startedAt)}` : ""}</code>
    </article>
  `;
}

function renderProductionLaunchChecklist(readiness = {}, storage = {}, migration = {}, governance = {}) {
  const sync = state.syncStatus || {};
  const mcp = state.mcpStatus || {};
  const smoke = state.productionSmoke || {};
  const manifest = state.migrationManifest || {};
  const readinessChecks = Array.isArray(readiness.checks) ? readiness.checks : [];
  const githubMcpCredentials = readinessChecks.find((item) => item.name === "github_mcp_credentials");
  const mcpGatewayCredentials = readinessChecks.find((item) => item.name === "mcp_gateway");
  const connectors = Array.isArray(mcp.connectors) ? mcp.connectors : [];
  const realConnectors = connectors.filter((connector) => connector.state && connector.state !== "planned");
  const githubSync = productionGithubSyncGuidance(sync, manifest);
  const checks = [
    {
      key: "github",
      label: "GitHub knowledge sync",
      ready: githubSync.ready,
      detail: githubSync.detail,
      action: githubSync.action,
    },
    {
      key: "mcp",
      label: "MCP connector gateway",
      ready: Boolean(readiness.safe_to_enable_real_mcp) && realConnectors.length > 0,
      detail: `${mcp.mode || "planning"} mode · ${connectors.length} connector slots · ${realConnectors.length} non-planned`,
      action: "Configure MCP gateway URL/key and replace planned connectors with scoped real connectors.",
    },
    {
      key: "secrets",
      label: "Secrets and provider access",
      ready: Boolean(state.openAIConfigured) && Boolean(mcpGatewayCredentials?.ready) && Boolean(githubMcpCredentials?.ready),
      detail: `OpenAI ${state.openAIConfigured ? "configured" : "missing"} · MCP ${mcpGatewayCredentials?.ready ? "configured" : "missing"} · GitHub App ${githubMcpCredentials?.ready ? "configured" : "missing"}`,
      action: githubMcpCredentials?.ready
        ? "Store API keys in hosted secret manager; never commit keys to GitHub/GitLab."
        : "Add GitHub App connector credentials to the hosted secret manager before the first real canary.",
    },
    {
      key: "storage",
      label: "Hosted data and object storage",
      ready: storage.provider && storage.provider !== "local" && String(migration.target || "").includes("postgres"),
      detail: `${storage.provider || "local"} storage · target ${migration.target || "not configured"}`,
      action: "Provision Postgres plus object storage, then apply backfill manifest.",
    },
    {
      key: "governance",
      label: "Approval and governance gates",
      ready: Boolean(governance.governance_ready),
      detail: `${governance.skill_approval_pending ?? 0} skill gates · ${governance.mcp_pending ?? 0} MCP approvals`,
      action: "Resolve pending skill and MCP approvals before enabling external actions.",
    },
    {
      key: "deployment",
      label: "Hosted deployment smoke path",
      ready: Number(smoke.step_count || 0) > 0 && !smoke.real_mcp_enabled,
      detail: `${smoke.step_count || 0} smoke steps · environment ${smoke.environment || readiness.environment || "local"}`,
      action: "Run staging smoke path, then canary real MCP after human approval.",
    },
  ];
  const readyCount = checks.filter((item) => item.ready).length;
  $("#productionLaunchChecklist").innerHTML = `
    <section class="production-launch-summary">
      <div>
        <span class="badge">Hosted launch checklist</span>
        <strong>${escapeHtml(readyCount)}/${escapeHtml(checks.length)} production lanes ready</strong>
        <p>Use this as the handoff state for GitHub, MCP, secrets, migration, governance, and deployment.</p>
      </div>
      <span class="${readyCount === checks.length ? "ready" : "attention"}">${readyCount === checks.length ? "ready for staging" : "not production-ready"}</span>
    </section>
    <div class="production-launch-grid">
      ${checks.map((item) => `
        <article class="production-launch-item ${item.ready ? "ready" : "missing"}">
          <div>
            <span>${escapeHtml(item.key)}</span>
            <strong>${escapeHtml(item.label)}</strong>
          </div>
          <p>${escapeHtml(item.detail)}</p>
          <small>${escapeHtml(item.action)}</small>
        </article>
      `).join("")}
    </div>
  `;
}

function productionGithubSyncGuidance(sync = {}, manifest = {}) {
  const pending = Number(sync.pending_count || 0);
  const latestExport = sync.latest_export || {};
  const exported = Number(sync.exported_count || 0);
  const lastPayload = sync.latest_path || latestExport.path || sync.last_payload_path || sync.path || "";
  const manifestItems = Number(manifest.summary?.item_count || 0);
  if (lastPayload || exported > 0) {
    return {
      ready: true,
      state: "payload-exported",
      detail: `${exported || 1} exported payload${(exported || 1) === 1 ? "" : "s"}${lastPayload ? ` · latest ${lastPayload}` : ""}`,
      action: "Apply the latest exported payload to the knowledge repo branch, push, and open or update a PR.",
      latestPath: lastPayload,
      payloadHash: sync.latest_payload_hash || latestExport.payload_hash || "",
    };
  }
  if (pending > 0) {
    return {
      ready: true,
      state: "payload-ready",
      detail: `${pending} payload${pending === 1 ? "" : "s"} ready${lastPayload ? ` · latest ${lastPayload}` : ""}`,
      action: "Apply the latest payload to the knowledge repo branch, push, and open a PR for review.",
      latestPath: lastPayload,
      payloadHash: sync.latest_payload_hash || latestExport.payload_hash || "",
    };
  }
  if (manifestItems > 0) {
    return {
      ready: true,
      state: "manifest-ready",
      detail: `${manifestItems} manifest item${manifestItems === 1 ? "" : "s"} ready for backfill`,
      action: "Review the backfill manifest, then create the first knowledge repo branch from approved Markdown stores.",
      latestPath: "",
      payloadHash: "",
    };
  }
  return {
    ready: false,
    state: "export-needed",
    detail: "No GitHub sync payload or migration manifest is ready yet.",
    action: "Use Sync Export for a payload or create a backfill manifest before opening a knowledge-base PR.",
    latestPath: "",
    payloadHash: "",
  };
}

function renderProductionGithubSync() {
  const target = $("#productionGithubSync");
  if (!target) return;
  const sync = state.syncStatus || {};
  const manifest = state.migrationManifest || {};
  const bridge = state.productionGithubKnowledgeBridge || {};
  const bridgeRepo = bridge.repository || {};
  const bridgeLocal = bridge.local_repo || {};
  const bridgePayload = bridge.sync_payload || {};
  const bridgeCommands = Array.isArray(bridge.commands) ? bridge.commands : [];
  const applyPayloadCommand = bridgeCommands.find((item) => String(item.label || "").toLowerCase().includes("apply payload"));
  const pushBranchCommand = bridgeCommands.find((item) => String(item.label || "").toLowerCase().includes("push branch"));
  const bridgeBlockers = Array.isArray(bridge.blockers) ? bridge.blockers : [];
  const bridgeWarnings = Array.isArray(bridge.warnings) ? bridge.warnings : [];
  const guidance = productionGithubSyncGuidance(sync, manifest);
  const branchStatusArtifacts = Array.isArray(state.productionGithubBranchStatusArtifacts) ? state.productionGithubBranchStatusArtifacts : [];
  const branchStatusArtifact = state.productionGithubBranchStatusArtifact || null;
  const branchStatusDetail = state.productionGithubBranchStatusArtifactDetail || null;
  const branchReviewArtifacts = Array.isArray(state.productionGithubBranchReviewArtifacts) ? state.productionGithubBranchReviewArtifacts : [];
  const branchReviewArtifact = state.productionGithubBranchReviewArtifact || null;
  const branchReviewDetail = state.productionGithubBranchReviewArtifactDetail || null;
  const prStatusArtifacts = Array.isArray(state.productionGithubPrStatusArtifacts) ? state.productionGithubPrStatusArtifacts : [];
  const prStatusArtifact = state.productionGithubPrStatusArtifact || null;
  const prStatusDetail = state.productionGithubPrStatusArtifactDetail || null;
  const localReviewEvidence = githubBranchReviewEvidence(bridge, branchReviewArtifacts);
  const prChecklist = githubKnowledgePrChecklist(bridge, localReviewEvidence);
  const branchMismatch = Boolean(bridge.expected_branch && bridgeLocal.branch && bridge.expected_branch !== bridgeLocal.branch);
  const latest = sync.latest || {};
  const actions = sync.actions || {};
  const actionRows = Object.entries(actions).slice(0, 6);
  target.innerHTML = `
    <section class="production-github-sync-card ${guidance.ready ? "ready" : "blocked"}">
      <div class="production-github-sync-head">
        <div>
          <span class="badge">GitHub knowledge-base sync</span>
          <strong>${escapeHtml(guidance.ready ? "Knowledge sync evidence is available." : "Knowledge sync evidence is missing.")}</strong>
          <p>${escapeHtml(guidance.action)}</p>
        </div>
        <span>${escapeHtml(guidance.state)}</span>
      </div>
      <div class="production-go-no-go-metrics">
        <span><strong>${escapeHtml(sync.pending_count ?? 0)}</strong>pending ops</span>
        <span><strong>${escapeHtml(sync.exported_count ?? 0)}</strong>exports</span>
        <span><strong>${escapeHtml(manifest.summary?.item_count ?? 0)}</strong>manifest items</span>
        <span><strong>${escapeHtml((guidance.payloadHash || "").slice(0, 12) || "none")}</strong>payload hash</span>
      </div>
      ${guidance.latestPath ? `<code>${escapeHtml(guidance.latestPath)}</code>` : ""}
      ${latest?.timestamp || actionRows.length
        ? `<div class="production-github-sync-detail">
            ${latest?.timestamp ? `<span><strong>Latest operation</strong>${escapeHtml(latest.action || "operation")} · ${escapeHtml(latest.timestamp || "")}</span>` : ""}
            ${actionRows.length ? `<span><strong>Action mix</strong>${actionRows.map(([name, count]) => `${escapeHtml(name)} ${escapeHtml(count)}`).join(" · ")}</span>` : ""}
          </div>`
        : ""}
      <small>Boundary: this card only reads local sync evidence. GitHub branch creation, commit, push, and PR creation remain manual or MCP-governed actions with human approval.</small>
    </section>
    ${bridge.type
      ? `<section class="production-github-sync-card ${bridge.status === "branch_ready" || bridge.status === "ready_to_apply_payload" ? "ready" : "blocked"}">
          <div class="production-github-sync-head">
            <div>
              <span class="badge">GitHub operator bridge</span>
              <strong>${escapeHtml(bridge.next_action || "Review GitHub knowledge-base setup.")}</strong>
              <p>${escapeHtml(bridge.boundary || "Read-only command guidance.")}</p>
            </div>
            <div class="production-github-bridge-actions">
              <span>${escapeHtml(bridge.status || "unknown")}</span>
              <button id="exportGithubBranchStatusArtifactBtn" class="secondary small" type="button">Export branch status</button>
              <button id="recordGithubBranchLocalReviewBtn" class="secondary small" type="button">Mark reviewed locally</button>
            </div>
          </div>
          <div class="production-go-no-go-metrics">
            <span><strong>${escapeHtml(bridgeLocal.status || "unknown")}</strong>local repo</span>
            <span><strong>${escapeHtml(bridge.expected_branch || "pending")}</strong>branch</span>
            <span><strong>${escapeHtml((bridgePayload.payload_hash || "").slice(0, 12) || "none")}</strong>payload</span>
            <span><strong>${escapeHtml(bridge.git?.available_on_backend_path ? "yes" : "manual")}</strong>git on PATH</span>
          </div>
          <div class="production-github-sync-detail">
            <span><strong>Repo</strong>${escapeHtml(bridgeRepo.url || "not configured")}</span>
            <span><strong>Local path</strong>${escapeHtml(bridgeRepo.configured_path || bridgeLocal.path || "not configured")}</span>
            ${bridgePayload.latest_path ? `<span><strong>Payload</strong>${escapeHtml(bridgePayload.latest_path)}</span>` : ""}
            ${bridgeLocal.origin ? `<span><strong>Origin</strong>${escapeHtml(bridgeLocal.origin)}</span>` : ""}
          </div>
          ${branchMismatch
            ? `<section class="production-branch-mismatch">
                <div>
                  <span class="badge">Branch mismatch</span>
                  <strong>Apply latest payload branch before PR review.</strong>
                  <p>Current local branch is <code>${escapeHtml(bridgeLocal.branch)}</code>, but the latest payload expects <code>${escapeHtml(bridge.expected_branch)}</code>.</p>
                </div>
                ${applyPayloadCommand ? `<button class="secondary small source-copy-btn" type="button" data-copy-role="github-apply-payload" data-copy-value="${escapeHtml(applyPayloadCommand.command || "")}">Copy apply-payload command</button>` : ""}
              </section>`
            : applyPayloadCommand
              ? `<section class="production-branch-mismatch ready">
                  <div>
                    <span class="badge">Apply command</span>
                    <strong>Payload branch is aligned.</strong>
                    <p>Use this command only when a new payload is exported or the branch needs to be recreated.</p>
                  </div>
                  <button class="secondary small source-copy-btn" type="button" data-copy-role="github-apply-payload" data-copy-value="${escapeHtml(applyPayloadCommand.command || "")}">Copy apply-payload command</button>
                </section>`
              : ""}
          ${pushBranchCommand
            ? `<section id="productionGithubApplyGuidance" class="production-github-guided-next ${state.productionGithubApplyCopied ? "active" : ""}" ${state.productionGithubApplyCopied ? "" : "hidden"}>
                <div>
                  <span class="badge">Next after apply</span>
                  <strong>Apply command copied. After running it, review status and push.</strong>
                  <p>Run the apply command in PowerShell first. Then use this push command only after reviewing the local diff.</p>
                </div>
                <button class="secondary small source-copy-btn" type="button" data-copy-role="github-push-branch" data-copy-value="${escapeHtml(pushBranchCommand.command || "")}">Copy push command</button>
              </section>`
            : ""}
          ${bridge.compare_url
            ? `<div class="production-github-pr-actions">
                <a class="secondary small" href="${escapeHtml(bridge.compare_url)}" target="_blank" rel="noreferrer">Open compare page</a>
                <button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(bridge.compare_url)}">Copy compare URL</button>
              </div>`
            : ""}
          <section class="production-github-pr-checklist">
            <div>
              <span class="badge">PR-state checklist</span>
              <strong>${escapeHtml(prChecklist.ready_count)}/${escapeHtml(prChecklist.check_count)} handoff checks ready</strong>
              <p>${escapeHtml(prChecklist.next_action)}</p>
            </div>
            <div class="production-github-pr-grid">
              ${prChecklist.items.map((item) => `
                <article class="${escapeHtml(item.state)}">
                  <span>${escapeHtml(item.state)}</span>
                  <strong>${escapeHtml(item.label)}</strong>
                  <p>${escapeHtml(item.detail)}</p>
                  <small>${escapeHtml(item.action)}</small>
                </article>
              `).join("")}
            </div>
          </section>
          <section class="production-github-branch-artifacts">
            <div class="sync-payload-review-head compact">
              <div>
                <span class="badge">Local branch evidence</span>
                <strong>${escapeHtml(branchStatusArtifact?.path || "No branch status snapshot exported in this session.")}</strong>
                <p>Snapshots preserve the current local checkout, expected branch, payload hash, compare URL, and human-review boundary for PR handoff.</p>
              </div>
            </div>
            <div class="sync-ledger-list compact">
              ${branchStatusArtifacts.length ? branchStatusArtifacts.map(renderGithubBranchStatusArtifactRow).join("") : '<p class="empty">No GitHub branch status snapshots exported yet.</p>'}
            </div>
            ${branchStatusDetail?.artifact
              ? `<details class="sync-payload-json" open>
                  <summary>Selected GitHub branch status snapshot</summary>
                  <div class="sync-active-filters">
                    <span><strong>Decision</strong>${escapeHtml(branchStatusDetail.artifact.decision || "apply_payload_before_push")}</span>
                    <span><strong>Readiness</strong>${escapeHtml(branchStatusDetail.artifact.summary?.ready_count ?? 0)}/${escapeHtml(branchStatusDetail.artifact.summary?.check_count ?? 0)}</span>
                    <span><strong>Expected</strong>${escapeHtml(branchStatusDetail.artifact.summary?.expected_branch || "pending")}</span>
                    <span><strong>Current</strong>${escapeHtml(branchStatusDetail.artifact.summary?.current_branch || "pending")}</span>
                  </div>
                  <pre class="output compact-output">${escapeHtml(JSON.stringify(branchStatusDetail.artifact, null, 2))}</pre>
                </details>`
              : ""}
            <div class="sync-payload-review-head compact">
              <div>
                <span class="badge">Local review evidence</span>
                <strong>${escapeHtml(branchReviewArtifact?.path || localReviewEvidence.label)}</strong>
                <p>${escapeHtml(localReviewEvidence.detail)}</p>
              </div>
              <button class="secondary small" type="button" id="recordGithubBranchNeedsReworkBtn">Needs rework</button>
            </div>
            <div class="sync-ledger-list compact">
              ${branchReviewArtifacts.length ? branchReviewArtifacts.map(renderGithubBranchReviewArtifactRow).join("") : '<p class="empty">No local branch review artifacts recorded yet.</p>'}
            </div>
            ${branchReviewDetail?.artifact
              ? `<details class="sync-payload-json" open>
                  <summary>Selected GitHub local review</summary>
                  <div class="sync-active-filters">
                    <span><strong>Status</strong>${escapeHtml(branchReviewDetail.artifact.status || "reviewed_with_blockers")}</span>
                    <span><strong>Decision</strong>${escapeHtml(branchReviewDetail.artifact.decision || "needs_rework")}</span>
                    <span><strong>Accepted</strong>${escapeHtml(branchReviewDetail.artifact.review_accepted ? "yes" : "no")}</span>
                    <span><strong>Reviewer</strong>${escapeHtml(branchReviewDetail.artifact.reviewer || "local-user")}</span>
                  </div>
                  <pre class="output compact-output">${escapeHtml(JSON.stringify(branchReviewDetail.artifact, null, 2))}</pre>
                </details>`
              : ""}
            <div class="sync-payload-review-head compact">
              <div>
                <span class="badge">GitHub PR evidence</span>
                <strong>${escapeHtml(prStatusArtifact?.path || "No compare/PR status recorded in this session.")}</strong>
                <p>Record the GitHub page state after pushing or when GitHub says there is nothing to compare.</p>
              </div>
            </div>
            <div class="production-github-pr-actions compact">
              <button class="secondary small" type="button" data-github-pr-status="compare_ready">Compare ready</button>
              <button class="secondary small" type="button" data-github-pr-status="compare_no_diff">Nothing to compare</button>
              <button class="secondary small" type="button" data-github-pr-status="pr_opened">PR opened</button>
              <button class="secondary small" type="button" data-github-pr-status="pr_needs_rework">Needs rework</button>
              <button class="secondary small" type="button" data-github-pr-status="pr_merged">Merged</button>
            </div>
            <div class="sync-ledger-list compact">
              ${prStatusArtifacts.length ? prStatusArtifacts.map(renderGithubPrStatusArtifactRow).join("") : '<p class="empty">No GitHub PR status artifacts recorded yet.</p>'}
            </div>
            ${prStatusDetail?.artifact
              ? `<details class="sync-payload-json" open>
                  <summary>Selected GitHub PR status</summary>
                  <div class="sync-active-filters">
                    <span><strong>Status</strong>${escapeHtml(prStatusDetail.artifact.status || "manual_followup")}</span>
                    <span><strong>Expected</strong>${escapeHtml(prStatusDetail.artifact.expected_branch || "pending")}</span>
                    <span><strong>Payload</strong>${escapeHtml(String(prStatusDetail.artifact.payload_hash || "").slice(0, 12) || "none")}</span>
                    <span><strong>Actor</strong>${escapeHtml(prStatusDetail.artifact.created_by || "local-user")}</span>
                  </div>
                  <pre class="output compact-output">${escapeHtml(JSON.stringify(prStatusDetail.artifact, null, 2))}</pre>
                </details>`
              : ""}
          </section>
          ${bridgeBlockers.length || bridgeWarnings.length
            ? `<div class="migration-step-list">
                ${bridgeBlockers.map((item) => `<span class="missing"><strong>Blocker</strong><small>${escapeHtml(item)}</small></span>`).join("")}
                ${bridgeWarnings.map((item) => `<span class="ready"><strong>Warning</strong><small>${escapeHtml(item)}</small></span>`).join("")}
              </div>`
            : ""}
          <details class="production-command-pack" ${bridge.status === "setup_needed" ? "open" : ""}>
            <summary>Copy GitHub knowledge-base commands</summary>
            <div class="production-command-grid">
              ${bridgeCommands.map((item) => renderProductionCommand(item.label || "Command", item.command || "# command unavailable")).join("") || renderProductionCommand("Refresh bridge", "# GET /api/production/github-knowledge-bridge")}
            </div>
          </details>
        </section>`
      : ""}
  `;
  $("#exportGithubBranchStatusArtifactBtn")?.addEventListener("click", exportGithubBranchStatusArtifact);
  $("#recordGithubBranchLocalReviewBtn")?.addEventListener("click", () => recordGithubBranchLocalReview("reviewed_locally"));
  $("#recordGithubBranchNeedsReworkBtn")?.addEventListener("click", () => recordGithubBranchLocalReview("needs_rework"));
  target.querySelectorAll(".github-branch-status-open").forEach((button) => {
    button.addEventListener("click", () => openGithubBranchStatusArtifact(button.dataset.path));
  });
  target.querySelectorAll(".github-branch-review-open").forEach((button) => {
    button.addEventListener("click", () => openGithubBranchReviewArtifact(button.dataset.path));
  });
  target.querySelectorAll("[data-github-pr-status]").forEach((button) => {
    button.addEventListener("click", () => recordGithubPrStatus(button.dataset.githubPrStatus || "manual_followup"));
  });
  target.querySelectorAll(".github-pr-status-open").forEach((button) => {
    button.addEventListener("click", () => openGithubPrStatusArtifact(button.dataset.path));
  });
  bindConceptSourceActions(target);
}

function renderProductionKnowledgeRepoReadiness() {
  const target = $("#productionKnowledgeRepoReadiness");
  if (!target) return;
  const okf = state.okfValidationStatus || {};
  const okfSummary = okf.summary || {};
  const bridge = state.productionGithubKnowledgeBridge || {};
  const bridgeRepo = bridge.repository || {};
  const bridgeLocal = bridge.local_repo || {};
  const bridgePayload = bridge.sync_payload || {};
  const repoSplit = state.repoSplitGuidance || {};
  const repos = Array.isArray(repoSplit.repositories) ? repoSplit.repositories : [];
  const knowledgeRepo = repos.find((repo) => String(repo.name || "").includes("knowledge")) || {};
  const agentConfigRepo = repos.find((repo) => String(repo.name || "").includes("agent")) || {};
  const repoReady = Boolean(bridgeLocal.status === "git_repo" || bridgeLocal.branch || bridgeRepo.configured_path);
  const payloadReady = Boolean(bridgePayload.latest_path || bridgePayload.payload_hash);
  const okfReady = okf.status === "passed";
  const repoSyncFixtureReady = Number(okfSummary.repo_sync_package_fixture_count || 0) > 0;
  const postgresGraphReady = Number(okfSummary.postgres_graph_schema_count || 0) > 0;
  const splitReady = repos.length >= 3;
  const branchReady = Boolean(bridge.expected_branch && bridgeLocal.branch === bridge.expected_branch);
  const checks = [
    {
      key: "okf",
      label: "OKF contract",
      ready: okfReady,
      metric: `${okfSummary.passed_check_count ?? 0}/${okfSummary.check_count ?? 0}`,
      detail: okfReady ? "Schema, ingest, promotion, and vector fixture gates passed." : "Run OKF fixture validators before syncing knowledge.",
    },
    {
      key: "repo",
      label: "Knowledge repo",
      ready: repoReady,
      metric: bridgeLocal.branch || bridgeLocal.status || "not cloned",
      detail: repoReady ? bridgeRepo.configured_path || bridgeLocal.path || "Local knowledge repo configured." : "Clone/configure the private knowledge fabric repository.",
    },
    {
      key: "repo-sync-fixture",
      label: "Repo-sync package",
      ready: okfReady && repoSyncFixtureReady,
      metric: `${okfSummary.repo_sync_package_fixture_count || 0} fixture`,
      detail: repoSyncFixtureReady ? "OKF + graph promotion repo-sync package shape is regression-tested." : "Add repo-sync package fixture before relying on graph handoff exports.",
    },
    {
      key: "postgres-graph",
      label: "Graph projection",
      ready: okfReady && postgresGraphReady,
      metric: `${okfSummary.postgres_graph_schema_count || 0} schema`,
      detail: postgresGraphReady ? "Postgres graph projection contract is statically validated without credentials." : "Add or validate the Postgres graph projection schema before hosted graph retrieval.",
    },
    {
      key: "payload",
      label: "Sync payload",
      ready: payloadReady,
      metric: String(bridgePayload.payload_hash || "").slice(0, 12) || "missing",
      detail: payloadReady ? bridgePayload.latest_path || "Latest payload available." : "Export a GitHub sync payload from local reviewed knowledge.",
    },
    {
      key: "branch",
      label: "Sync branch",
      ready: branchReady,
      metric: bridge.expected_branch || "pending",
      detail: branchReady ? "Local branch matches expected payload branch." : "Apply payload to expected branch before PR review.",
    },
    {
      key: "split",
      label: "Repo split",
      ready: splitReady,
      metric: `${repos.length}/3`,
      detail: splitReady ? "App, knowledge, and agent-config boundaries are documented." : "Refresh repo split guidance or use the handoff checklist.",
    },
  ];
  const readyCount = checks.filter((check) => check.ready).length;
  const next = checks.find((check) => !check.ready);
  const statusClass = readyCount === checks.length ? "ready" : payloadReady || okfReady ? "pending" : "blocked";
  const operatorSteps = [
    {
      label: "Confirm repo boundaries",
      state: okfReady ? "ready" : "open",
      detail: okfReady ? "OKF schema, fixtures, graph promotions, Postgres projection, repo-sync package, and vector boundary are validated." : "Validate OKF fixtures before moving knowledge content.",
    },
    {
      label: "Clone private knowledge repo",
      state: repoReady ? "ready" : "open",
      detail: repoReady ? bridgeRepo.configured_path || bridgeLocal.path || "Private knowledge repo is available locally." : "Create or clone `meids-knowledge-fabric` as private.",
    },
    {
      label: "Export reviewed sync payload",
      state: payloadReady ? "ready" : "open",
      detail: payloadReady ? bridgePayload.latest_path || "Payload hash is available." : "Export only reviewed OKF concepts/evidence/transcripts from local MVP.",
    },
    {
      label: "Apply payload branch",
      state: branchReady ? "ready" : payloadReady ? "manual" : "blocked",
      detail: branchReady ? "Local branch matches the expected sync branch." : "Apply payload into `feature/knowledge-sync-*`, then inspect the diff.",
    },
    {
      label: "Open human-reviewed PR",
      state: branchReady && bridge.compare_url ? "manual" : "blocked",
      detail: bridge.compare_url ? "Use the compare page only after confirming changed OKF files." : "PR waits for branch alignment and compare URL.",
    },
    {
      label: "Prepare agent-config repo",
      state: splitReady ? "manual" : "open",
      detail: splitReady ? "Move live workflow specs/prompts to private agent-config repo when ready." : "Use handoff checklist to create `meids-agent-configs` boundary.",
    },
  ];
  const docsUrl = "https://github.com/florianliepe/meids-app/blob/main/docs/knowledge-fabric-okf-schema.md";
  const handoffUrl = "https://github.com/florianliepe/meids-app/blob/main/docs/production/repo-split-handoff-checklist.md";
  const agentConfigUrl = "https://github.com/florianliepe/meids-app/blob/main/docs/production/agent-config-handoff-package.md";
  const agentUrlReadiness = productionAgentUrlReadiness();
  target.innerHTML = `
    <section class="production-knowledge-repo-card ${statusClass}">
      <div class="production-knowledge-repo-head">
        <div>
          <span class="badge">Knowledge repo sync readiness</span>
          <strong>${escapeHtml(readyCount)}/${escapeHtml(checks.length)} gates ready</strong>
          <p>${escapeHtml(next?.detail || "Knowledge fabric handoff is ready for reviewed PR sync.")}</p>
        </div>
        <span>${escapeHtml(statusClass.replace("-", " "))}</span>
      </div>
      <div class="production-knowledge-repo-grid" aria-label="Knowledge repository sync gates">
        ${checks.map((check) => `
          <article class="${check.ready ? "ready" : "blocked"}">
            <span>${escapeHtml(check.ready ? "ready" : "open")}</span>
            <strong>${escapeHtml(check.label)}</strong>
            <p>${escapeHtml(check.metric)}</p>
            <small>${escapeHtml(check.detail)}</small>
          </article>
        `).join("")}
      </div>
      <div class="production-knowledge-repo-map">
        <span><strong>App repo</strong>Static UI, fixtures, public docs</span>
        <span><strong>Knowledge repo</strong>${escapeHtml(knowledgeRepo.name || "meids-knowledge-fabric")} · private OKF concepts, evidence, graph, audit</span>
        <span><strong>Agent config repo</strong>${escapeHtml(agentConfigRepo.name || "meids-agent-configs")} · n8n contracts, prompts, skill specs</span>
      </div>
      <div class="production-knowledge-repo-actions">
        <a class="secondary small" href="${docsUrl}" target="_blank" rel="noreferrer">Open OKF schema</a>
        <a class="secondary small" href="${handoffUrl}" target="_blank" rel="noreferrer">Open handoff checklist</a>
        <a class="secondary small" href="${agentConfigUrl}" target="_blank" rel="noreferrer">Open agent-config handoff</a>
        ${bridge.compare_url ? `<a class="secondary small" href="${escapeHtml(bridge.compare_url)}" target="_blank" rel="noreferrer">Open knowledge compare</a>` : ""}
      </div>
      ${renderProductionTrustedRetrievalReadiness()}
      <div class="production-graph-review-gates">
        <div class="production-graph-review-head">
          <span class="badge">Graph review gates</span>
          <strong>Relation promotion controls trusted retrieval.</strong>
          <p>Accepted relations can support Actor Twin reasoning. Candidate, inferred, rejected, and needs-rework edges remain attributed or blocked until reviewed.</p>
        </div>
        ${renderGraphPromotionSummary()}
        ${renderGraphActorContextHandoffStatus()}
      </div>
      ${renderProductionAgentUrlReadiness(agentUrlReadiness)}
      <details class="production-knowledge-operator" open>
        <summary>Repo split operator sequence</summary>
        <ol>
          ${operatorSteps.map((step) => `
            <li class="${escapeHtml(step.state)}">
              <span>${escapeHtml(step.state)}</span>
              <strong>${escapeHtml(step.label)}</strong>
              <small>${escapeHtml(step.detail)}</small>
            </li>
          `).join("")}
        </ol>
      </details>
      <small>Production rule: only approved or explicitly selected pending OKF material can move into trusted retrieval. Merge remains human-reviewed.</small>
    </section>
  `;
  bindConceptSourceActions(target);
  target.querySelector("[data-production-action='copyTrustedRetrievalPacket']")?.addEventListener("click", copyTrustedRetrievalReadinessPacket);
  target.querySelectorAll("[data-agent-webhook-action]").forEach((button) => {
    button.addEventListener("click", () => handleAgentWebhookOverrideAction(button));
  });
}

function productionTrustedRetrievalReadiness() {
  const concepts = Array.isArray(state.concepts) && state.concepts.length ? state.concepts : buildStaticPagesConcepts();
  const conceptSummary = knowledgeSourceReadinessSummary(concepts);
  const promotions = graphPromotionHistoryItems(120);
  const acceptedPromotions = promotions.filter((item) => ["approved", "accepted"].includes(String(item.review_state || item.decision || "").toLowerCase()));
  const acceptedWithEvidence = acceptedPromotions.filter((item) => graphPromotionEvidenceRefs(item).length > 0);
  const blockedPromotions = promotions.filter((item) => ["rejected", "needs-rework", "blocked"].includes(String(item.review_state || item.decision || "").toLowerCase()));
  const okf = state.okfValidationStatus || {};
  const summary = okf.summary || {};
  const azureVector = state.vectorIndex || {};
  const azureStatic = state.azureVectorReadinessStatus || {};
  const azureLive = state.azureVectorLiveActivationStatus || {};
  const azureStaticSummary = azureStatic.summary || {};
  const azureLiveReadiness = azureLive.readiness || {};
  const azureLivePortal = azureLive.portal_observation || {};
  const azureConfigured = Boolean(azureVector.available || azureVector.status === "configured");
  const azureEmbeddingConfigured = Boolean(azureVector.embedding?.status === "configured");
  const azureServiceObserved = Boolean(azureLiveReadiness.azure_search_service_ready || azureLivePortal.search_endpoint);
  const azureIndexesObserved = Boolean(azureLiveReadiness.azure_search_indexes_ready);
  const azureMissing = Array.isArray(azureVector.missing) ? azureVector.missing : [];
  const azureContractReady = azureStatic.status === "ready_for_secret_activation";
  const vectorFixtureReady = Number(summary.vector_request_fixture_count || 0) > 0 || azureContractReady;
  const repoSyncReady = Number(summary.repo_sync_package_fixture_count || 0) > 0;
  const postgresGraphReady = Number(summary.postgres_graph_schema_count || 0) > 0;
  const agentReadiness = productionAgentUrlReadiness();
  const knowledgeAgent = agentReadiness.find((agent) => agent.agentId === "knowledge_fabric_agent") || {};
  const butlerAgent = agentReadiness.find((agent) => agent.agentId === "agentic_butler") || {};
  const okfTrusted = conceptSummary.approved > 0 && conceptSummary.evidenceApproved > 0;
  const graphTrusted = acceptedPromotions.length > 0 && acceptedWithEvidence.length === acceptedPromotions.length;
  const vectorReadyForHandoff = vectorFixtureReady && repoSyncReady && okf.status === "passed";
  const liveReady = Boolean(knowledgeAgent.configured && butlerAgent.configured);
  const usable = okfTrusted && (graphTrusted || acceptedPromotions.length === 0) && vectorReadyForHandoff;
  const status = !conceptSummary.total || !okfTrusted
    ? "blocked"
    : usable && liveReady
      ? "ready"
      : usable
        ? "pending"
        : "warning";
  const cards = [
    {
      key: "okf",
      label: "OKF source trust",
      value: okfTrusted ? `${conceptSummary.approved} approved` : `${conceptSummary.pending} pending`,
      state: okfTrusted ? "ready" : conceptSummary.approved ? "warning" : "blocked",
      detail: okfTrusted
        ? `${conceptSummary.evidenceApproved} concepts have approved evidence signals.`
        : "Approve source-backed OKF concepts before trusted Actor Twin retrieval.",
    },
    {
      key: "graph",
      label: "Graph relation trust",
      value: acceptedPromotions.length ? `${acceptedPromotions.length} accepted` : `${promotions.length} review events`,
      state: graphTrusted ? "ready" : acceptedPromotions.length ? "warning" : promotions.length ? "pending" : "blocked",
      detail: graphTrusted
        ? "Accepted graph relations have evidence references."
        : blockedPromotions.length
          ? `${blockedPromotions.length} blocked/rework relation decisions remain excluded from trusted retrieval.`
          : "Accept candidate graph relations with evidence before graph-assisted retrieval.",
    },
    {
      key: "vector",
      label: "Azure vector boundary",
      value: azureConfigured
        ? "backend configured"
        : azureServiceObserved
          ? azureIndexesObserved ? "service + indexes observed" : "service observed"
          : azureContractReady ? "secret activation ready" : vectorFixtureReady ? "contract ready" : "deferred",
      state: azureConfigured && azureEmbeddingConfigured ? "ready" : azureServiceObserved || vectorFixtureReady ? "warning" : "pending",
      detail: azureConfigured
        ? `${escapeHtml(azureVector.approved_index || azureVector.indexes?.approved || "approved index")} · ${escapeHtml(azureVector.working_index || azureVector.indexes?.working || "working index")}`
        : azureServiceObserved
          ? `${azureLivePortal.search_service || "Azure Search"} running; indexes/backend/embedding activation still required.`
        : azureMissing.length
          ? `Backend secrets missing: ${azureMissing.join(", ")}.`
          : azureContractReady
            ? `${azureStaticSummary.ready_check_count || 0}/${azureStaticSummary.check_count || 0} local vector readiness checks pass; backend secrets still required.`
            : "Vector refresh remains staged until backend Azure secrets are available.",
    },
    {
      key: "projection",
      label: "Graph projection",
      value: postgresGraphReady ? "schema tested" : "missing",
      state: postgresGraphReady ? "ready" : "pending",
      detail: postgresGraphReady
        ? "Postgres graph tables are defined for hosted projection."
        : "Hosted graph projection waits for validated Postgres schema.",
    },
    {
      key: "handoff",
      label: "Live agent handoff",
      value: liveReady ? "configured" : "fixture gated",
      state: liveReady ? "ready" : "blocked",
      detail: liveReady
        ? "Actor Twin can reach Knowledge Fabric Agent and Agentic Butler through the configured runtime path."
        : "Actor Twin embedded chat must be verified with internal Knowledge Fabric and Butler tool calls.",
    },
  ];
  return {
    status,
    status_label: status === "ready" ? "trusted live" : status === "pending" ? "trusted local" : status === "warning" ? "partial trust" : "review gated",
    actor_policy: usable
      ? "Actor Twin may use approved OKF concepts and accepted evidence-backed graph relations; draft/pending material stays attributed."
      : "Actor Twin must treat OKF drafts, unaccepted graph edges, and vector candidates as untrusted context until review gates pass.",
    concept_summary: conceptSummary,
    graph_summary: {
      promotion_count: promotions.length,
      accepted_count: acceptedPromotions.length,
      accepted_with_evidence_count: acceptedWithEvidence.length,
      blocked_or_rework_count: blockedPromotions.length,
    },
    vector_summary: {
      fixture_ready: vectorFixtureReady,
      repo_sync_ready: repoSyncReady,
      postgres_graph_ready: postgresGraphReady,
      azure_search_configured: azureConfigured,
      azure_embedding_configured: azureEmbeddingConfigured,
      azure_contract_ready: azureContractReady,
      azure_search_service_observed: azureServiceObserved,
      azure_search_indexes_observed: azureIndexesObserved,
      azure_live_activation_status: azureLive.status || "",
      credentials_required_now: !azureConfigured,
      indexes: {
        approved: azureVector.approved_index || azureVector.indexes?.approved || "meids-okf-approved-v1",
        working: azureVector.working_index || azureVector.indexes?.working || "meids-okf-working-v1",
      },
    },
    live_agent_summary: {
      knowledge_fabric_agent: knowledgeAgent.configured ? "configured" : "awaiting_url",
      agentic_butler: butlerAgent.configured ? "configured" : "awaiting_url",
    },
    cards,
  };
}

function renderProductionTrustedRetrievalReadiness() {
  const readiness = productionTrustedRetrievalReadiness();
  return `
    <section class="trusted-retrieval-readiness ${escapeHtml(readiness.status)}" aria-label="Trusted retrieval readiness">
      <div class="trusted-retrieval-head">
        <div>
          <span class="badge">Trusted retrieval readiness</span>
          <strong>${escapeHtml(readiness.status_label)}</strong>
          <p>${escapeHtml(readiness.actor_policy)}</p>
        </div>
        <button class="secondary small" type="button" data-production-action="copyTrustedRetrievalPacket">Copy packet</button>
      </div>
      <div class="trusted-retrieval-grid">
        ${readiness.cards.map((card) => `
          <article class="${escapeHtml(card.state)}">
            <span>${escapeHtml(card.state)}</span>
            <strong>${escapeHtml(card.label)}</strong>
            <p>${escapeHtml(card.value)}</p>
            <small>${escapeHtml(card.detail)}</small>
          </article>
        `).join("")}
      </div>
      <div class="trusted-retrieval-actions">
        <a class="secondary small" href="${AZURE_VECTOR_GUIDE_URL}" target="_blank" rel="noreferrer">Open Azure vector guide</a>
        <span>${escapeHtml(readiness.vector_summary.azure_search_configured
          ? "Azure AI Search configured in backend"
          : readiness.vector_summary.azure_search_service_observed
            ? "Azure AI Search service observed; backend secrets and index setup pending"
            : "Azure AI Search waits for backend secrets")}</span>
      </div>
      <small>Use rule: approved OKF and accepted evidence-backed graph relations can inform trusted answers. Drafts and inferred edges require visible attribution or human review.</small>
    </section>
  `;
}

async function copyTrustedRetrievalReadinessPacket() {
  const readiness = productionTrustedRetrievalReadiness();
  const packet = {
    artifact_type: "trusted_retrieval_readiness",
    generated_at: new Date().toISOString(),
    boundary: "Public-safe cockpit evidence only. Does not mutate OKF storage, graph projection, vector indexes, GitHub, MCP, or n8n.",
    readiness,
  };
  const copied = await copyTextToClipboard(JSON.stringify(packet, null, 2));
  showToast(
    copied ? "Trusted retrieval packet copied" : "Trusted retrieval packet copy failed",
    copied ? readiness.status_label : "Clipboard access unavailable.",
    copied ? "success" : "error",
  );
}

function productionAgentUrlReadiness() {
  const contracts = Array.isArray(state.n8nAgentContracts?.contracts)
    ? state.n8nAgentContracts.contracts
    : buildStaticPagesN8nAgentContracts().contracts;
  const secretByAgent = {
    actor_twin: "GH_PAGES_N8N_ACTOR_TWIN_WEBHOOK_URL",
    knowledge_fabric_agent: "GH_PAGES_N8N_KNOWLEDGE_FABRIC_WEBHOOK_URL",
    agentic_butler: "GH_PAGES_N8N_AGENTIC_BUTLER_WEBHOOK_URL",
  };
  return contracts.map((contract) => {
    const agentId = contract.agent_id || "";
    const readiness = agentRuntimeReadiness(agentId);
    const probe = mergedN8nProbeEvidence(agentId);
    const status = probe?.status === "connected" && probe?.demo !== true && Boolean(probe?.trace_id)
      ? "n8n connected"
      : readiness.configured
        ? "configured"
        : readiness.status || "missing URL";
    return {
      agentId,
      name: contract.agent_name || agentDisplayName(agentId),
      status,
      className: status === "n8n connected" ? "ready" : readiness.configured ? "pending" : status === "awaiting URL" ? "pending" : "blocked",
      detail: probe?.detail || readiness.detail || contract.blocker || "",
      probe,
      envVar: contract.webhook_env_var || readiness.envVar || "N8N_WEBHOOK_URL",
      githubSecret: secretByAgent[agentId] || "GH_PAGES_N8N_WEBHOOK_URL",
      fixture: contract.source || "",
      fixtureUrl: contract.source_url || "",
      workflow: contract.workflow_source || "",
      workflowUrl: contract.workflow_url || "",
      approvalBoundary: contract.approval_boundary || "",
      configured: readiness.configured,
      urlSource: readiness.urlSource || "missing",
      urlSourceLabel: readiness.urlSourceLabel || "missing URL",
      runtimeSnippet: buildSingleAgentRuntimeConfigSnippet(agentId),
      liveProbePayload: contract.live_probe_payload || agentLiveProbePayload(agentId),
      liveProbeSource: contract.live_probe_source || "",
      liveProbeUrl: contract.live_probe_url || "",
    };
  });
}

function productionAgentRolloutGateSummary(agents = []) {
  const totalGates = agents.length * 6;
  const readyGates = agents
    .flatMap((agent) => productionAgentRolloutGates(agent))
    .filter((gate) => gate.ready).length;
  return { readyGates, totalGates };
}

function productionAgentRolloutGates(agent = {}) {
  const probe = mergedN8nProbeEvidence(agent.agentId);
  const traces = readComposedAgentTraces();
  const liveTrace = traces.find((trace) => {
    const sameAgent = String(trace.agent_id || "").toLowerCase() === String(agent.agentId || "").toLowerCase();
    const liveRuntime = /n8n connected|live n8n|webhook/i.test(String(trace.runtime || ""));
    return sameAgent && liveRuntime && !trace.demo;
  });
  const fixtureReady = Boolean(agent.fixture && agent.fixtureUrl);
  const blueprintReady = Boolean(agent.workflow && agent.workflowUrl);
  const urlReady = Boolean(agent.configured);
  const probeReady = probe?.status === "connected" && probe?.demo !== true && Boolean(probe?.trace_id);
  const traceReady = Boolean(liveTrace);
  const approvalReady = Boolean(agent.approvalBoundary);
  return [
    {
      key: "fixture",
      label: "Fixture",
      ready: fixtureReady,
      detail: fixtureReady ? "Contract fixture exists." : "Fixture missing.",
    },
    {
      key: "blueprint",
      label: "Blueprint",
      ready: blueprintReady,
      detail: blueprintReady ? "n8n workflow target exists." : "Workflow target missing.",
    },
    {
      key: "url",
      label: "URL",
      ready: urlReady,
      detail: urlReady ? `Runtime URL configured from ${agent.urlSourceLabel || "runtime config"}.` : "Live URL missing.",
    },
    {
      key: "probe",
      label: "Probe",
      ready: probeReady,
      detail: probeReady ? "Live probe reached n8n." : "Run live probe after URL setup.",
    },
    {
      key: "trace",
      label: "Trace",
      ready: traceReady,
      detail: traceReady ? `Trace ${liveTrace.trace_id || liveTrace.request_id || "recorded"}.` : "No non-demo live trace evidence.",
    },
    {
      key: "approval",
      label: "Approval",
      ready: approvalReady,
      detail: approvalReady ? "Approval boundary documented." : "Approval boundary missing.",
    },
  ];
}

function renderProductionAgentRolloutChecklist(agents = []) {
  const summary = productionAgentRolloutGateSummary(agents);
  return `
    <div class="production-agent-rollout-checklist">
      <div class="production-agent-rollout-head">
        <span class="badge">Agent rollout checklist</span>
        <strong>${escapeHtml(`${summary.readyGates}/${summary.totalGates} gates ready`)}</strong>
        <p>Fixture and blueprint prove build readiness. URL, probe, and non-demo trace evidence are required before live production approval.</p>
      </div>
      <div class="production-agent-rollout-grid">
        ${agents.map((agent) => {
          const gates = productionAgentRolloutGates(agent);
          const readyCount = gates.filter((gate) => gate.ready).length;
          return `
            <article class="${readyCount === gates.length ? "ready" : agent.configured ? "pending" : "blocked"}">
              <header>
                <strong>${escapeHtml(agent.name)}</strong>
                <span>${escapeHtml(`${readyCount}/${gates.length}`)}</span>
              </header>
              <ol>
                ${gates.map((gate) => `
                  <li class="${gate.ready ? "ready" : "pending"}">
                    <span>${gate.ready ? "ready" : "open"}</span>
                    <strong>${escapeHtml(gate.label)}</strong>
                    <small>${escapeHtml(gate.detail)}</small>
                  </li>
                `).join("")}
              </ol>
            </article>
          `;
        }).join("")}
      </div>
    </div>
  `;
}

function renderProductionAgentUrlReadiness(agents = []) {
  const configuredCount = agents.filter((agent) => agent.configured).length;
  const missing = agents.filter((agent) => !agent.configured);
  const missingConfig = buildN8nRuntimeConfigSnippet(missing.map((agent) => ({ id: agent.agentId })));
  const liveUrlGuide = githubBlobUrl("docs/n8n-live-url-configuration.md");
  const liveOperatorChecklist = githubBlobUrl("docs/production/n8n-live-readiness-operator-checklist.md");
  const runtimeAsset = githubBlobUrl("frontend/assets/agent-runtime-config.json");
  const runtimeStatusAsset = githubBlobUrl("frontend/assets/n8n-runtime-readiness-status.json");
  const runtimeStatus = state.n8nRuntimeReadinessStatus || {};
  const runtimeSummary = runtimeStatus.summary || {};
  return `
    <section class="production-agent-url-readiness">
      <div class="production-agent-url-head">
        <div>
          <span class="badge">Agent runtime readiness</span>
          <strong>${escapeHtml(`${runtimeSummary.runtime_ready_count ?? configuredCount}/${runtimeSummary.agent_count ?? agents.length} runtime paths ready`)}</strong>
          <p>${escapeHtml(missing.length
            ? "Actor Twin embedded chat is the frontend route. Direct public worker URLs are optional; verify internal workflow tools in n8n."
            : "All configured runtime paths are ready. Run live probes before production approval.")}</p>
        </div>
        ${missingConfig ? `<button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(missingConfig)}">Copy missing JSON</button>` : ""}
      </div>
      ${runtimeStatus.schema_version ? `
        <div class="production-agent-runtime-artifact">
          <span>${escapeHtml(runtimeStatus.status || "runtime status")}</span>
          <strong>${escapeHtml(`${runtimeSummary.runtime_ready_count ?? runtimeSummary.configured_count ?? configuredCount}/${runtimeSummary.agent_count ?? agents.length} runtime paths validated from runtime asset`)}</strong>
          <small>${escapeHtml(runtimeStatus.boundary || "Runtime readiness validates URL slots but does not prove live connectivity.")}</small>
          <a class="secondary small" href="${escapeHtml(runtimeStatusAsset)}" target="_blank" rel="noreferrer">Open readiness artifact</a>
          <a class="secondary small" href="${escapeHtml(liveOperatorChecklist)}" target="_blank" rel="noreferrer">Open live checklist</a>
        </div>
      ` : ""}
      ${renderProductionAgentUrlSourceComparison(agents, runtimeSummary)}
      ${renderProductionAgentUrlResolutionChecklist(agents)}
      ${missing.length ? renderN8nCurrentSupportedConfigPath(missingConfig) : ""}
      ${missing.length ? renderProductionAgentMissingUrlSetup(missing) : ""}
      ${missing.length ? renderProductionN8nHandoffPacket(missing) : ""}
      <div class="production-agent-url-grid">
        ${agents.map((agent) => `
          <article class="${escapeHtml(agent.className)}">
            <span>${escapeHtml(agent.status)}</span>
            <strong>${escapeHtml(agent.name)}</strong>
            <p>${escapeHtml(agent.detail)}</p>
            <dl>
              <div><dt>Runtime key</dt><dd><code>${escapeHtml(agent.envVar)}</code></dd></div>
              <div><dt>URL source</dt><dd>${escapeHtml(agent.urlSourceLabel || "missing URL")}</dd></div>
              <div><dt>GitHub secret</dt><dd><code>${escapeHtml(agent.githubSecret)}</code></dd></div>
              <div><dt>Fixture</dt><dd>${agent.fixtureUrl ? `<a href="${escapeHtml(agent.fixtureUrl)}" target="_blank" rel="noreferrer">${escapeHtml(agent.fixture)}</a>` : escapeHtml(agent.fixture)}</dd></div>
              <div><dt>Workflow target</dt><dd>${agent.workflowUrl ? `<a href="${escapeHtml(agent.workflowUrl)}" target="_blank" rel="noreferrer">${escapeHtml(agent.workflow)}</a>` : escapeHtml(agent.workflow || "missing")}</dd></div>
            </dl>
            <div class="button-row tight">
              <button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(agent.githubSecret)}">Copy secret</button>
              ${agent.runtimeSnippet ? `<button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(agent.runtimeSnippet)}">Copy JSON</button>` : ""}
              ${agent.liveProbePayload ? `<button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(JSON.stringify(agent.liveProbePayload, null, 2))}">Copy probe payload</button>` : ""}
              ${agent.liveProbeUrl ? `<a class="secondary small" href="${escapeHtml(agent.liveProbeUrl)}" target="_blank" rel="noreferrer">Open probe file</a>` : ""}
              <a class="secondary small" href="${escapeHtml(liveUrlGuide)}" target="_blank" rel="noreferrer">Live URL guide</a>
              <a class="secondary small" href="${escapeHtml(runtimeAsset)}" target="_blank" rel="noreferrer">Runtime asset</a>
            </div>
          </article>
        `).join("")}
      </div>
      ${renderProductionAgentLiveGateBoard(agents)}
      ${renderProductionAgentRolloutChecklist(agents)}
      <small>Public GitHub Pages can only use public UAT webhook URLs. Private production endpoints should move behind the hosted backend or a workflow-generated runtime config.</small>
    </section>
  `;
}

function renderProductionAgentUrlSourceComparison(agents = [], runtimeSummary = {}) {
  if (!agents.length) return "";
  const runtimeAssetCount = agents.filter((agent) => agent.urlSource === "runtime-asset").length;
  const browserLocalCount = agents.filter((agent) => agent.urlSource === "browser-local").length;
  const missingCount = agents.filter((agent) => agent.urlSource === "missing" || !agent.configured).length;
  const committedCount = Number.isFinite(runtimeSummary.configured_count)
    ? runtimeSummary.configured_count
    : runtimeAssetCount;
  const rows = [
    {
      label: "Committed runtime asset",
      value: `${committedCount}/${agents.length}`,
      detail: "`frontend/assets/agent-runtime-config.json`; used by every browser and GitHub Pages deploy.",
      state: committedCount === agents.length ? "ready" : committedCount ? "partial" : "blocked",
    },
    {
      label: "Browser-local UAT override",
      value: `${browserLocalCount}/${agents.length}`,
      detail: "Stored only in this browser profile for temporary public UAT webhook tests.",
      state: browserLocalCount ? "partial" : "neutral",
    },
    {
      label: "Still missing URL",
      value: `${missingCount}/${agents.length}`,
      detail: "Agents without runtime asset URL or local override remain fixture-only.",
      state: missingCount ? "blocked" : "ready",
    },
  ];
  return `
    <div class="production-agent-url-source-comparison" aria-label="n8n URL source comparison">
      ${rows.map((row) => `
        <article class="${escapeHtml(row.state)}">
          <span>${escapeHtml(row.label)}</span>
          <strong>${escapeHtml(row.value)}</strong>
          <p>${escapeHtml(row.detail)}</p>
        </article>
      `).join("")}
    </div>
  `;
}

function renderProductionAgentUrlResolutionChecklist(agents = []) {
  if (!agents.length) return "";
  const rows = agents.map(productionAgentFixtureLiveMappingRow);
  const readySteps = rows.reduce((sum, row) => sum + row.steps.filter((step) => step.ready).length, 0);
  const totalSteps = rows.reduce((sum, row) => sum + row.steps.length, 0);
  const blockedRows = rows.filter((row) => !row.urlReady);
  const setupPacket = {
    artifact_type: "agent_url_resolution_checklist",
    generated_at: new Date().toISOString(),
    status: blockedRows.length ? "blocked_until_missing_urls_are_configured" : "urls_configured_probe_required",
    public_safe: true,
    boundary: "Fixture and contract status are public-safe. Live n8n URLs must be public UAT URLs for GitHub Pages or proxied through a hosted backend.",
    rows,
  };
  return `
    <section class="production-agent-url-resolution-checklist">
      <div class="production-agent-url-resolution-head">
        <div>
          <span class="badge">URL resolution checklist</span>
          <strong>${escapeHtml(`${readySteps}/${totalSteps} setup steps ready`)}</strong>
          <p>${escapeHtml(blockedRows.length
            ? "Resolve missing Knowledge Fabric and Butler URLs before live agent routing or production trace review."
            : "All URL slots are configured. Continue with live probes and non-demo trace capture.")}</p>
        </div>
        <button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(JSON.stringify(setupPacket, null, 2))}">Copy checklist</button>
      </div>
      <div class="production-agent-fixture-live-map" role="table" aria-label="Fixture to live n8n mapping">
        <div class="production-agent-fixture-live-row header" role="row">
          <span role="columnheader">Agent</span>
          <span role="columnheader">Fixture contract</span>
          <span role="columnheader">Live URL slot</span>
          <span role="columnheader">Next action</span>
        </div>
        ${rows.map((row) => `
          <div class="production-agent-fixture-live-row ${escapeHtml(row.state)}" role="row">
            <span role="cell">
              <strong>${escapeHtml(row.agent_name)}</strong>
              <small>${escapeHtml(row.agent_id)}</small>
            </span>
            <span role="cell">
              <i class="${row.fixtureReady ? "ready" : "blocked"}">${escapeHtml(row.fixture_status)}</i>
              <small>${escapeHtml(row.fixture_ref)}</small>
            </span>
            <span role="cell">
              <i class="${row.urlReady ? "ready" : "blocked"}">${escapeHtml(row.url_status)}</i>
              <small>${escapeHtml(row.github_secret)}</small>
            </span>
            <span role="cell">
              <small>${escapeHtml(row.next_action)}</small>
              <div class="production-agent-step-strip">
                ${row.steps.map((step) => `
                  <em class="${step.ready ? "ready" : "open"}" title="${escapeHtml(step.detail)}">${escapeHtml(step.label)}</em>
                `).join("")}
              </div>
            </span>
          </div>
        `).join("")}
      </div>
    </section>
  `;
}

function productionAgentFixtureLiveMappingRow(agent = {}) {
  const gates = productionAgentRolloutGates(agent);
  const gateByKey = new Map(gates.map((gate) => [gate.key, gate]));
  const fixtureReady = Boolean(gateByKey.get("fixture")?.ready);
  const blueprintReady = Boolean(gateByKey.get("blueprint")?.ready);
  const urlReady = Boolean(gateByKey.get("url")?.ready);
  const probeReady = Boolean(gateByKey.get("probe")?.ready);
  const traceReady = Boolean(gateByKey.get("trace")?.ready);
  const approvalReady = Boolean(gateByKey.get("approval")?.ready);
  const nextAction = !fixtureReady
    ? "Fix the public fixture before exposing a live workflow."
    : !blueprintReady
      ? "Document the n8n workflow target in the agent contract."
      : !urlReady
        ? `Add ${agent.githubSecret || agent.envVar || "the webhook URL"} to runtime config or GitHub Pages secret.`
        : !probeReady
          ? "Run a no-write live probe and retain response evidence."
          : !traceReady
            ? "Run non-demo UAT and store trace evidence."
            : !approvalReady
              ? "Document approval boundary before production use."
              : "Ready for production review.";
  return {
    agent_id: agent.agentId || "",
    agent_name: agent.name || agentDisplayName(agent.agentId || ""),
    state: traceReady && approvalReady ? "ready" : urlReady ? "pending" : "blocked",
    fixture_status: fixtureReady ? "fixture ready" : "fixture missing",
    fixture_ref: agent.fixture || "No fixture reference",
    url_status: urlReady ? "URL configured" : "URL missing",
    url_ready: urlReady,
    urlReady,
    fixtureReady,
    github_secret: agent.githubSecret || "GH_PAGES_N8N_WEBHOOK_URL",
    runtime_key: agent.envVar || "N8N_WEBHOOK_URL",
    next_action: nextAction,
    steps: [
      {
        label: "Fixture",
        ready: fixtureReady,
        detail: gateByKey.get("fixture")?.detail || "Fixture contract must exist.",
      },
      {
        label: "Blueprint",
        ready: blueprintReady,
        detail: gateByKey.get("blueprint")?.detail || "Workflow target must be documented.",
      },
      {
        label: "URL",
        ready: urlReady,
        detail: gateByKey.get("url")?.detail || "Live URL must be configured.",
      },
      {
        label: "Probe",
        ready: probeReady,
        detail: gateByKey.get("probe")?.detail || "Live probe must pass.",
      },
      {
        label: "Trace",
        ready: traceReady,
        detail: gateByKey.get("trace")?.detail || "Non-demo trace evidence must exist.",
      },
      {
        label: "Approval",
        ready: approvalReady,
        detail: gateByKey.get("approval")?.detail || "Approval boundary must be documented.",
      },
    ],
  };
}

