function syncTraceReviewSignals(options = {}) {
  const checked = $$("#drawerContent .trace-signal-input:checked");
  const tagInput = $("#traceQualityTagsInput");
  const stateSelect = $("#traceReviewStateSelect");
  const noteInput = $("#traceReviewNoteInput");
  if (!tagInput || !stateSelect || !noteInput) return;

  const manualTags = tagInput.value
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
  const signalTags = checked.map((input) => input.value);
  tagInput.value = Array.from(new Set([...manualTags, ...signalTags])).join(", ");

  if (!options.preserveExistingState || stateSelect.value === "unreviewed") {
    const states = checked.map((input) => input.dataset.state).filter(Boolean);
    if (states.includes("unsafe")) stateSelect.value = "unsafe";
    else if (states.includes("needs-evidence")) stateSelect.value = "needs-evidence";
    else if (states.includes("needs-rewrite")) stateSelect.value = "needs-rewrite";
    else if (states.includes("not-useful")) stateSelect.value = "not-useful";
    else if (states.includes("approved")) stateSelect.value = "approved";
  }

  if (!noteInput.value.trim()) {
    noteInput.value = checked
      .map((input) => input.dataset.note)
      .filter(Boolean)
      .join(" ");
  }
}

async function saveTraceReview(path) {
  if (!path) return;
  const manualTags = ($("#traceQualityTagsInput")?.value || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
  const signalTags = $$("#drawerContent .trace-signal-input:checked").map((input) => input.value);
  const tags = Array.from(new Set([...manualTags, ...signalTags]));
  try {
    await postJson("/api/answer-traces/review", {
      path,
      review_state: $("#traceReviewStateSelect").value,
      note: $("#traceReviewNoteInput").value || "",
      quality_tags: tags,
      actor: "local-user",
    });
    await safeRefreshActivity();
    await safeRefreshReviewDashboard();
    await safeRefreshTraceExportStatus();
    const detail = await postJson("/api/answer-traces/detail", { path });
    renderAnswerTraceDetail(detail);
    showToast("Trace review saved", $("#traceReviewStateSelect").value, "success");
  } catch (error) {
    $("#drawerContent").insertAdjacentHTML(
      "afterbegin",
      `<p class="readiness missing">Trace review failed: ${escapeHtml(error.message)}</p>`,
    );
    showToast("Trace review failed", error.message, "error");
  }
}

function renderTraceSources(sources) {
  if (!sources.length) return '<p class="empty">No sources were retrieved.</p>';
  return sources
    .map(
      (source) => `
        <article class="linked-evidence">
          <div class="linked-evidence-head">
            <span>
              <strong>${escapeHtml(source.title || source.path)}</strong>
              <span>${escapeHtml(source.type || "Source")} - confidence ${escapeHtml(source.confidence || 0)} - ${escapeHtml(source.guardrail_status || "not-evaluated")}${source.source_anchor ? ` - ${escapeHtml(source.source_anchor)}` : ""}</span>
            </span>
            <button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(source.source_deep_link || source.path || "")}">Copy source</button>
          </div>
          <code>${escapeHtml(source.path || "")}</code>
          ${source.source_deep_link ? `<code>${escapeHtml(source.source_deep_link)}</code>` : ""}
          ${source.provenance_hash ? `<small>${escapeHtml(source.provenance_hash)}</small>` : ""}
        </article>
      `,
    )
    .join("");
}

async function deleteEvidence(path) {
  if (!path) return;
  const confirmed = await requestDecision({
    eyebrow: "Evidence cleanup",
    title: "Delete this evidence file?",
    body: `${path}\n\nConcepts created from this evidence will also be deleted and logged.`,
    confirmLabel: "Delete evidence",
    danger: true,
  });
  if (!confirmed) return;
  try {
    await deleteJson("/api/evidence", {
      path,
      actor: "local-user",
      delete_linked_concepts: true,
    });
    await refreshConcepts();
    await safeRefreshActivity();
    showToast("Evidence deleted", path, "success");
  } catch (error) {
    setOutputStatus("#qualityResult", "error", "Evidence delete failed", error.message);
    showToast("Evidence delete failed", error.message, "error");
  }
}

