function asLines(values) {
  if (Array.isArray(values) && values.length) return values.map((value) => `- ${value}`);
  if (values) return [`- ${values}`];
  return ["- none"];
}

function objectLines(value) {
  const entries = Object.entries(value || {});
  if (!entries.length) return ["- none"];
  return entries.map(([key, count]) => `- ${key}: ${count}`);
}

function formatInlineCounts(value) {
  const entries = Object.entries(value || {});
  if (!entries.length) return "none";
  return entries.map(([key, count]) => `${key}: ${count}`).join(", ");
}

function formatApprovalStateSummary(states) {
  if (!Array.isArray(states) || !states.length) return "approval queue: none";
  const counts = states.reduce((acc, item) => {
    const state = item?.state || "pending";
    acc[state] = (acc[state] || 0) + 1;
    return acc;
  }, {});
  return `approval queue: ${formatInlineCounts(counts)}`;
}

function formatShortDate(value) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value).slice(0, 10);
  return date.toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
}

function addMessage(role, text, metadata = null) {
  $("#messages .chat-empty-state")?.remove();
  const node = document.createElement("article");
  node.className = `message ${role}`;
  if (role === "assistant" && metadata?.run_id && metadata?.result) {
    node.classList.add("skill-run-message");
    node.innerHTML = renderSkillRunCard(metadata);
    $("#messages").appendChild(node);
    bindSkillRunReviewButtons(node, metadata.run_id);
    bindSkillRunArtifactActions(node, metadata);
    bindApprovalQueueActions(node);
    node.scrollIntoView({ block: "end" });
    return node;
  }
  if (role === "assistant" && metadata?.agent_contract_response) {
    node.classList.add("agent-contract-message");
    node.innerHTML = renderAgentContractChatCard(metadata.agent_contract_response);
    $("#messages").appendChild(node);
    node.querySelector(".speak-message-btn")?.addEventListener("click", () => speakMessage(node, agentContractResponseText(metadata.agent_contract_response)));
    node.scrollIntoView({ block: "end" });
    return node;
  }
  const sources = metadata?.sources?.length
    ? `<div class="sources">${metadata.sources
        .map((source) => renderSourceChip(source))
        .join("")}</div>`
    : "";
  const confidence = metadata?.confidence !== undefined ? `<strong>Confidence ${metadata.confidence}%</strong>` : "";
  const retrieval = metadata?.retrieval_mode ? `<small class="message-meta">retrieval: ${escapeHtml(metadata.retrieval_mode)}</small>` : "";
  const answerPath = renderAnswerPath(metadata?.answer_path || metadata?.graph_context?.answer_path || []);
  node.innerHTML = `
    <div class="message-header">
      <span>${escapeHtml(messageRoleLabel(role))}</span>
      <time>${escapeHtml(formatShortDate(new Date().toISOString()))}</time>
    </div>
    <p>${escapeHtml(text).replaceAll("\n", "<br>")}</p>
    ${role === "assistant" ? '<div class="message-actions"><button class="secondary small speak-message-btn" type="button">Play voice</button></div>' : ""}
    ${sources}${answerPath}${confidence}${retrieval}
  `;
  $("#messages").appendChild(node);
  if (role === "assistant") {
    node.querySelector(".speak-message-btn")?.addEventListener("click", () => speakMessage(node, text));
  }
  node.scrollIntoView({ block: "end" });
  return node;
}

function renderAnswerPath(answerPath) {
  if (!Array.isArray(answerPath) || !answerPath.length) return "";
  return `
    <details class="answer-path">
      <summary>Answer path (${answerPath.length})</summary>
      <ol>
        ${answerPath
          .slice(0, 6)
          .map((item) => `
            <li>
              <strong>${escapeHtml(item.title || item.node_key || "Graph node")}</strong>
              <span>${escapeHtml(item.reason || item.edge_type || item.node_type || "")}</span>
            </li>
          `)
          .join("")}
      </ol>
    </details>
  `;
}

async function speakMessage(node, text) {
  if (!node || !text) return;
  const actions = node.querySelector(".message-actions") || node;
  let status = node.querySelector(".voice-status");
  if (!status) {
    status = document.createElement("small");
    status.className = "voice-status message-meta";
    actions.appendChild(status);
  }
  if (isStaticFrontendSession()) {
    status.textContent = "Voice playback requires the hosted voice backend.";
    return;
  }
  status.textContent = "Creating voice answer...";
  try {
    const result = await postJson("/api/voice/speak", {
      text: String(text).slice(0, 4096),
      twin: state.activeTwin,
    });
    let audio = node.querySelector("audio.voice-answer");
    if (!audio) {
      audio = document.createElement("audio");
      audio.className = "voice-answer";
      audio.controls = true;
      actions.appendChild(audio);
    }
    audio.src = resolveAssetUrl(result.audio_url);
    status.textContent = `Voice: ${result.voice_id || "default"}`;
    await audio.play().catch(() => undefined);
  } catch (error) {
    status.textContent = `Voice failed: ${compactError(error.message)}`;
  }
}

function compactError(message) {
  const text = String(message || "unknown error");
  if (/<html|<!doctype|<body|<h1/i.test(text)) {
    if (/405 Not Allowed/i.test(text)) return "Hosted backend endpoint is not available from GitHub Pages.";
    if (/404/i.test(text)) return "Hosted backend resource is not available in this static session.";
    return "Hosted backend returned an HTML error page.";
  }
  try {
    const parsed = JSON.parse(text);
    return parsed.detail || text;
  } catch {
    return text.slice(0, 180);
  }
}

function isStaticFrontendSession() {
  if (staticPagesMode || githubPagesHost || window.location.protocol === "file:") return true;
  if (!apiBaseUrl) return false;
  try {
    return /github\.io$/i.test(new URL(apiBaseUrl, window.location.href).hostname);
  } catch {
    return false;
  }
}

function messageRoleLabel(role) {
  if (role === "user") return "You";
  if (role === "assistant") return "Twin";
  return role || "Message";
}

function renderSourceChip(source) {
  const type = source.type ? `${source.type}: ` : "";
  const anchor = source.source_anchor ? ` - ${source.source_anchor}` : "";
  const confidence = source.confidence !== undefined ? ` - ${source.confidence}%` : "";
  const guardrail = source.guardrail_status ? ` - ${source.guardrail_status}` : "";
  const title = type + (source.title || source.path) + anchor + confidence + guardrail;
  return `<span title="${escapeHtml(source.source_deep_link || source.path || "")}">${escapeHtml(title)}</span>`;
}

function removeLastAssistantPlaceholder() {
  const messages = $$("#messages .message.assistant");
  const last = messages[messages.length - 1];
  if (
    last &&
    (
      last.textContent.includes("Thinking with local OKF sources") ||
      last.textContent.includes("Running approved skill") ||
      last.textContent.includes("Asking Actor Twin") ||
      last.textContent.includes("Activating approved skill") ||
      last.textContent.includes("Preparing Knowledge Fabric handoff")
    )
  ) {
    last.remove();
  }
}

function renderAgentContractChatCard(result = {}) {
  const response = result.response || {};
  const output = normalizeAgentOutput(response.output || {});
  const approval = response.approval || {};
  const trace = response.trace || {};
  const status = response.status || result.status || "completed";
  const isApproval = shouldRequireHumanApprovalForAgentResult({
    agentId: result.agent_id || response.agent_id || "",
    response,
    output,
    approval,
    envelope: result.request || {},
    trace,
  });
  const effectiveStatus = isApproval ? "approval_required" : status === "failed" ? "failed" : "completed";
  const displayResponse = {
    ...response,
    status: effectiveStatus,
    output,
    approval: isApproval ? approval : { required: false },
  };
  const displayResult = { ...result, response: displayResponse };
  const agentId = response.agent_id || result.agent_id || "";
  const title = result.agent_name || agentDisplayName(agentId) || "Agent";
  const traceKey = trace.trace_id || result.trace_id || response.request_id || result.request?.request_id || "";
  const delegated = output.delegate_result?.agent_id ? agentDisplayName(output.delegate_result.agent_id) : "";
  const voiceButton = isStaticFrontendSession()
    ? ""
    : `<button class="secondary small speak-message-btn" type="button">Play voice</button>`;
  return `
    <div class="skill-run-card agent-response-card ${escapeHtml(effectiveStatus)} ${safeGraphClass(agentId)}">
      <div class="skill-run-head">
        <div>
          <span class="badge">${escapeHtml(isApproval ? "Approval required" : delegated ? `Delegated via ${delegated}` : title)}</span>
          <h3>${escapeHtml(title)}</h3>
          <p>${escapeHtml(agentContractResponseText(displayResult))}</p>
        </div>
      </div>
      ${!isApproval ? renderAgentContractOutput(output) : ""}
      ${isApproval ? `
        <div class="approval-card agent-approval-gate" data-approval-summary="${escapeHtml(approval.summary || "")}" data-approval-action="${escapeHtml(approval.proposed_action || "")}" data-trace-id="${escapeHtml(traceKey)}" data-request-id="${escapeHtml(response.request_id || result.request?.request_id || "")}">
          <div class="approval-gate-copy">
            <strong>${escapeHtml(approval.gate || "proposal_approval")}</strong>
            <p>${escapeHtml(approval.summary || "Human approval is required before a generated skill or agent design becomes active.")}</p>
            <small>${escapeHtml(approval.proposed_action || "Approve the proposal to stage generation, or revise it in the Skills cockpit.")}</small>
          </div>
          <div class="button-row tight">
            <button class="primary small" type="button" data-chat-action="ack-agent-approval">Approve proposal</button>
            <button class="secondary small" type="button" data-chat-action="copy-agent-approval">Copy approval note</button>
            <button class="secondary small" type="button" data-chat-action="copy-agent-resume" data-trace-id="${escapeHtml(traceKey)}">Copy resume payload</button>
            ${agentBackendProxyEnabled ? `<button class="primary small" type="button" data-chat-action="resume-agent-approval" data-trace-id="${escapeHtml(traceKey)}">Resume via backend</button>` : ""}
          </div>
        </div>
      ` : ""}
      <div class="message-actions">
        ${traceKey ? `<button class="secondary small" type="button" data-chat-action="open-agent-trace" data-trace-id="${escapeHtml(traceKey)}">Trace</button>` : ""}
        ${voiceButton}
      </div>
    </div>
  `;
}

function renderAgentResponseRouteCard(result = {}) {
  const response = result.response || {};
  const output = normalizeAgentOutput(response.output || {});
  const request = result.request || {};
  const approval = response.approval || {};
  const trace = response.trace || {};
  const agentId = response.agent_id || result.agent_id || "";
  const status = response.status || result.status || "completed";
  const isApproval = shouldRequireHumanApprovalForAgentResult({
    agentId,
    response,
    output,
    approval,
    envelope: request,
    trace,
  });
  const effectiveStatus = isApproval ? "approval_required" : status === "failed" ? "failed" : "completed";
  const sourceContext = request.context?.source_context || {};
  const sourceCount = ["email_input", "calendar_input", "teams_input", "knowledge_context"]
    .filter((key) => String(sourceContext[key] || request.input?.[key] || "").trim()).length;
  const route = agentResponseRouteMeta(agentId, output, isApproval, sourceCount);
  const stages = agentContractStatusesFor(agentId);
  const contract = chatAgentContractStatusFor(agentId);
  return `
    <section class="agent-response-route-card ${safeGraphClass(agentId)} ${safeGraphClass(effectiveStatus)}">
      <div class="agent-response-route-head">
        <span class="badge">${escapeHtml(route.badge)}</span>
        <strong>${escapeHtml(route.title)}</strong>
        <small>${escapeHtml(route.detail)}</small>
      </div>
      <div class="agent-response-route-grid">
        <span>
          <strong>${escapeHtml(route.mode)}</strong>
          <small>interaction mode</small>
        </span>
        <span>
          <strong>${escapeHtml(route.knowledgeUse)}</strong>
          <small>knowledge fabric use</small>
        </span>
        <span>
          <strong>${escapeHtml(route.boundary)}</strong>
          <small>governance boundary</small>
        </span>
        <span>
          <strong>${escapeHtml(route.nextAction)}</strong>
          <small>next action</small>
        </span>
      </div>
      <div class="agent-response-route-stages">
        ${stages.map((stage) => `<span>${escapeHtml(stage)}</span>`).join("")}
      </div>
      ${renderAgentResponseContractHealth(contract)}
    </section>
  `;
}

function chatAgentContractStatusFor(agentId = "") {
  return chatAgentContractStatuses().find((item) => item.agentId === agentId) || {
    agentId,
    label: agentDisplayName(agentId),
    state: "documented",
    detail: "Contract status is not loaded yet.",
    nextAction: "Load contract fixtures and runtime config.",
    configured: false,
    webhookLabel: "fixture only",
    readyGateCount: 0,
    totalGateCount: 4,
    stageItems: agentContractStatusesFor(agentId).map((label, index) => ({
      key: safeGraphClass(label),
      label: labelizeGraph(label),
      ready: index < 3,
      detail: label,
    })),
  };
}

function renderAgentResponseContractHealth(contract = {}) {
  const stateLabel = contract.state || "documented";
  const gateLabel = `${contract.readyGateCount ?? 0}/${contract.totalGateCount ?? 4} gates`;
  const runtimeLabel = contract.webhookLabel || (contract.configured ? "URL configured" : "fixture only");
  const nextAction = contract.nextAction || contract.detail || "";
  const probeEvidence = agentProbeEvidenceLine(contract);
  return `
    <div class="agent-response-contract-health ${contract.configured ? "configured" : "fixture"} ${safeGraphClass(stateLabel)}">
      <div>
        <span>Contract health</span>
        <strong>${escapeHtml(`${stateLabel} · ${runtimeLabel}`)}</strong>
        <small>${escapeHtml(`${gateLabel}${nextAction ? ` · ${nextAction}` : ""}`)}</small>
        ${probeEvidence ? `<small class="agent-response-probe-evidence">${escapeHtml(probeEvidence)}</small>` : ""}
      </div>
      ${renderChatContractStageRow(contract.stageItems || [], { compact: true })}
    </div>
  `;
}

function agentProbeEvidenceLine(contract = {}) {
  const probe = contract.probe || {};
  const status = probe.status || contract.probeStatus || "";
  const checkedAt = probe.checked_at || contract.probeCheckedAt || "";
  const lastError = probe.last_error || contract.probeLastError || "";
  const traceId = probe.trace_id || contract.probeTraceId || "";
  const aiAgent = probe.ai_agent || contract.aiAgent || {};
  const aiNode = aiAgent?.integrated ? aiAgent.node || "AI Agent" : "";
  if (!status && !checkedAt && !lastError && !traceId && !aiNode) return "";
  const parts = [];
  if (status) parts.push(`probe ${status}`);
  if (aiNode) parts.push(`AI ${aiNode}`);
  if (checkedAt) parts.push(`checked ${formatShortDate(checkedAt)}`);
  if (traceId) parts.push(`trace ${traceId}`);
  if (lastError) parts.push(`last error: ${lastError}`);
  return parts.join(" · ");
}

function agentResponseRouteMeta(agentId = "", output = {}, isApproval = false, sourceCount = 0) {
  if (agentId === "knowledge_fabric_agent") {
    return {
      badge: "Knowledge Fabric route",
      title: "Source context became pending OKF material",
      detail: "The Knowledge Fabric Agent owns ingest, evidence storage, CRUD audit, graph curator trigger, and vector refresh boundary.",
      mode: "Ingest",
      knowledgeUse: output.concept_path ? "pending OKF concept" : "source handoff",
      boundary: output.vector_refresh || "no vector refresh before approval",
      nextAction: output.graph_curator_trigger ? "review graph candidates" : "review pending concept",
    };
  }
  if (agentId === "agentic_butler") {
    return {
      badge: "Skill activation route",
      title: "Agentic Butler activated an approved work capability",
      detail: "Skill orchestration stays internal to Butler; Actor Twin steering is required before prioritization and risky actions.",
      mode: "Skill execution",
      knowledgeUse: sourceCount ? `${sourceCount} source lanes` : "approved skill context",
      boundary: isApproval ? "human approval required" : "approval gates monitored",
      nextAction: isApproval ? "resolve approval gate" : "review artifact and refine",
    };
  }
  return {
    badge: "Actor Twin route",
    title: "Actor Twin answered from governed context",
    detail: "The UI-facing actor interprets intent, applies persona and OKF context, and routes work only when execution is needed.",
    mode: "Answer",
    knowledgeUse: sourceCount ? `OKF + ${sourceCount} source lanes` : "approved-first OKF",
    boundary: "no external write action",
    nextAction: "ask follow-up or activate skill",
  };
}

function acknowledgeAgentApproval(button) {
  const card = button.closest(".agent-approval-gate");
  if (!card) return;
  const approval = {
    trace_id: card.dataset.traceId || "",
    request_id: card.dataset.requestId || "",
    gate: card.querySelector("strong")?.textContent || "skill_spec_approval",
    summary: card.dataset.approvalSummary || "",
    proposed_action: card.dataset.approvalAction || "",
  };
  card.classList.add("acknowledged");
  button.disabled = true;
  button.textContent = "Approved";
  if (approval.gate === "skill_spec_approval" || approval.gate === "new_agent_approval") {
    const sourceQuery = approval.proposed_action || approval.summary || "Approved generated skill or agent proposal";
    const draft = createStaticSkillDraft(sourceQuery, "Approved generated capability");
    addMessage("assistant", draft.message, {
      confidence: 82,
      retrieval_mode: "static approval",
      sources: [{ path: draft.skill.skill_id, title: "Staged skill proposal", type: "Skill draft", score: 1 }],
    });
    showToast("Proposal approved", "A local SkillSpec draft was staged. Hosted persistence will generate the active workflow later.", "success");
    return;
  }
  showToast("Approval acknowledged", "The gate was recorded locally; no external action was executed.", "success");
}

async function copyAgentApproval(button) {
  const card = button.closest(".agent-approval-gate");
  if (!card) return;
  const note = [
    "Approval required",
    `Summary: ${card.dataset.approvalSummary || "-"}`,
    `Proposed action: ${card.dataset.approvalAction || "-"}`,
    "Boundary: Human approval required before a generated skill, task-agent, subagent, or agent version becomes active.",
  ].join("\n");
  try {
    await navigator.clipboard.writeText(note);
    showToast("Approval note copied", "Paste it into the review or n8n UAT record.", "success");
  } catch {
    showToast("Approval note", note, "warning");
  }
}

function findStaticTraceDetail(path = "") {
  const traces = readComposedAgentTraces();
  const trace = traces.find((item) => item.path === path || item.trace_id === path || item.request_id === path || item.artifact_path === path);
  if (!trace) return null;
  return {
    path: trace.path || trace.artifact_path || trace.trace_id || "",
    title: trace.title || `${agentDisplayName(trace.agent_id)} trace`,
    timestamp: trace.timestamp || "",
    twin: trace.twin || state.activeTwin || "",
    confidence: trace.confidence || "",
    retrieval_mode: trace.retrieval_mode || trace.runtime || "",
    source_count: trace.source_count || 0,
    guardrail_statuses: trace.guardrail_statuses || [],
    review_state: trace.review_state || "unreviewed",
    reviewed_by: trace.reviewed_by || "",
    reviewed_at: trace.reviewed_at || "",
    quality_tags: trace.quality_tags || [],
    provenance_hash: trace.provenance_hash || "",
    query: trace.query || trace.request?.input?.query || "",
    answer: trace.answer || trace.detail || trace.status || "Static trace evidence is available in this browser session.",
    sources: trace.sources || [],
  };
}

async function copyAgentApprovalResumePayload(button) {
  const card = button.closest(".agent-approval-gate");
  const traceId = button.dataset.traceId || card?.dataset.traceId || "";
  const approval = agentApprovalByTrace(traceId) || {
    trace_id: traceId,
    request_id: card?.dataset.requestId || "",
    agent_id: "agentic_butler",
    target_agent: "agentic_butler",
    gate: "requires_human_action",
    summary: card?.dataset.approvalSummary || "Human approval is required before this action can continue.",
    proposed_action: card?.dataset.approvalAction || "",
  };
  const payload = buildAgentApprovalResumePayload(approval);
  const text = JSON.stringify(payload, null, 2);
  try {
    await navigator.clipboard.writeText(text);
    showToast("Resume payload copied", "Use it with the backend approval resume endpoint or n8n UAT resume branch.", "success");
  } catch {
    showToast("Resume payload", text, "warning");
  }
}

async function resumeAgentApproval(button) {
  const card = button.closest(".agent-approval-gate");
  const traceId = button.dataset.traceId || card?.dataset.traceId || "";
  const approval = agentApprovalByTrace(traceId);
  if (!approval) {
    showToast("Approval not found", "Refresh the trace cockpit and try again.", "warning");
    return;
  }
  if (!agentBackendProxyEnabled) {
    await copyAgentApprovalResumePayload(button);
    return;
  }
  button.disabled = true;
  const previousLabel = button.textContent;
  button.textContent = "Resuming...";
  try {
    const payload = buildAgentApprovalResumePayload(approval);
    const data = await postAgentBackendJson(`/api/agents/approvals/${encodeURIComponent(approval.approval_id)}/resume`, payload);
    const responsePayload = data.response ? data : { response: data };
    const result = normalizeAgentContractResponse("agentic_butler", responsePayload, payload, "backend proxy · resumed");
    persistAgentTrace(result);
    addMessage("assistant", agentContractResponseText(result), { agent_contract_response: result });
    await safeRefreshBackendAgentRuntimeState();
    showToast("Butler run resumed", "The approval gate was sent through the backend proxy.", "success");
  } catch (error) {
    showToast("Resume failed", error.message || "Backend approval resume failed.", "error");
    button.disabled = false;
    button.textContent = previousLabel;
  }
}

function renderAgentContractOutput(output = {}) {
  if (!output || typeof output !== "object" || !Object.keys(output).length) return "";
  const delegate = output.delegate_result && typeof output.delegate_result === "object" ? output.delegate_result : null;
  const delegateOutput = normalizeAgentOutput(delegate?.output && typeof delegate.output === "object" ? delegate.output : {});
  const delegateSummary = delegateOutput.summary || delegateOutput.answer || delegateOutput.markdown || delegate?.approval?.summary || "";
  const delegatePanel = delegate ? `
    <section class="agent-delegate-output">
      <div>
        <span class="badge">${escapeHtml(agentDisplayName(delegate.agent_id || "delegated_agent"))}</span>
        <strong>${escapeHtml(labelizeGraph(delegate.status || "delegated"))}</strong>
        <p>${escapeHtml(leanAgentSummary(delegateSummary || "Delegated agent returned a structured response."))}</p>
      </div>
    </section>
  ` : "";
  const directArtifactKeys = ["email_draft", "concept_path", "evidence_path", "crud_log_path", "graph_curator_trigger", "todos", "candidate_edges"]
    .some((key) => output[key]);
  if (delegate && !directArtifactKeys && Object.keys(delegateOutput).length) {
    return `${renderAgentContractOutput({ ...delegateOutput, delegate_result: null })}${delegatePanel}`;
  }
  if (output.email_draft && typeof output.email_draft === "object") {
    const draft = output.email_draft;
    return `
      <section class="agent-work-artifact email-draft-artifact">
        <div class="agent-work-artifact-head">
          <span class="badge">Email draft</span>
          <strong>${escapeHtml(draft.subject || "Draft email")}</strong>
        </div>
        <div class="email-draft-meta">
          ${draft.to ? `<span><strong>To</strong>${escapeHtml(draft.to)}</span>` : ""}
          ${draft.cc ? `<span><strong>Cc</strong>${escapeHtml(draft.cc)}</span>` : ""}
        </div>
        <pre class="email-draft-body">${escapeHtml(draft.body || "")}</pre>
      </section>
    `;
  }
  if (output.concept_path || output.evidence_path || output.crud_log_path || output.graph_curator_trigger) {
    return `
      <section class="knowledge-fabric-output">
        <div class="ingest-contract-grid compact">
          <span><strong>${escapeHtml(labelizeGraph(output.review_state || "pending review"))}</strong><small>review state</small></span>
          <span><strong>${escapeHtml(output.graph_curator_trigger || "not queued")}</strong><small>graph curator</small></span>
          <span><strong>${escapeHtml(output.vector_refresh || "deferred")}</strong><small>vector boundary</small></span>
        </div>
        ${Array.isArray(output.candidate_edges) && output.candidate_edges.length ? `
          <div class="agent-consumer-list">
            ${output.candidate_edges.slice(0, 6).map((edge) => `<span>${escapeHtml(`${edge.relation_type || "edge"} · ${edge.confidence ?? "-"} confidence`)}</span>`).join("")}
          </div>
        ` : ""}
      </section>
      ${delegatePanel}
    `;
  }
  if (Array.isArray(output.todos)) {
    return `
      <div class="todo-table compact">
        ${output.todos.slice(0, 5).map((todo) => `
          <article>
            <strong>${escapeHtml(todo.what || "Todo")}</strong>
            <p>${escapeHtml(todo.how || todo.why || "")}</p>
            <small>${escapeHtml(`${todo.priority || "priority n/a"} · ${todo.whom || "owner n/a"}`)}</small>
          </article>
        `).join("")}
      </div>
      ${delegatePanel}
    `;
  }
  if (Array.isArray(output.candidate_edges)) {
    return `
      <div class="agent-consumer-list">
        ${output.candidate_edges.slice(0, 6).map((edge) => `<span>${escapeHtml(`${edge.relation_type || "edge"} · ${edge.confidence ?? "-"} confidence`)}</span>`).join("")}
      </div>
      ${delegatePanel}
    `;
  }
  const displayOutput = delegate ? Object.fromEntries(Object.entries(output).filter(([key]) => key !== "delegate_result")) : output;
  const publicKeys = ["summary", "answer", "next_suggested_action"].filter((key) => displayOutput[key]);
  if (publicKeys.length) {
    return `
      <section class="agent-work-artifact">
        ${publicKeys.map((key) => `
          <div>
            <span>${escapeHtml(labelizeGraph(key))}</span>
            <p>${escapeHtml(leanAgentSummary(displayOutput[key]))}</p>
          </div>
        `).join("")}
      </section>
      ${delegatePanel}
    `;
  }
  return `${delegatePanel}`;
}

function leanAgentSummary(value = "") {
  const text = String(value || "").trim();
  const embedded = parseEmbeddedJsonObject(text);
  if (embedded && typeof embedded === "object") {
    const output = normalizeAgentOutput(embedded.output || embedded);
    return output.email_draft?.subject
      ? `Drafted email: ${output.email_draft.subject}`
      : output.summary || output.answer || "Agent completed.";
  }
  return text.slice(0, 520);
}

function renderAgentTraceSummaryOutput(traceSummary = null) {
  if (!traceSummary || typeof traceSummary !== "object") return "";
  const steps = Array.isArray(traceSummary.steps) ? traceSummary.steps.slice(0, 4) : [];
  return `
    <details class="agent-artifact-trace-summary">
      <summary>Work trace</summary>
      <div>
        ${traceSummary.skill_activated ? `<span><strong>Skill</strong>${escapeHtml(traceSummary.skill_activated)}</span>` : ""}
        ${traceSummary.orchestration_model ? `<span><strong>Model</strong>${escapeHtml(traceSummary.orchestration_model)}</span>` : ""}
      </div>
      ${steps.length ? `<ol>${steps.map((step) => `<li>${escapeHtml(step)}</li>`).join("")}</ol>` : ""}
      ${traceSummary.next_suggested_action ? `<p>${escapeHtml(traceSummary.next_suggested_action)}</p>` : ""}
    </details>
  `;
}

function renderSkillRunCard(metadata) {
  const result = metadata.result || {};
  const steering = result.actor_steering || {};
  const todos = Array.isArray(result.todos) ? result.todos : [];
  const approvalQueue = Array.isArray(result.approval_queue) ? result.approval_queue : [];
  const approvalStates = Array.isArray(metadata.approval_states) ? metadata.approval_states : [];
  const preflight = metadata.preflight || result.preflight || {};
  const readiness = metadata.inputs ? sourceReadiness(metadata.inputs || {}) : sourceReadinessFromPreflight(preflight);
  return `
    <div class="skill-run-card">
      <div class="skill-run-head">
        <div class="skill-run-brand">
          <img src="${escapeHtml(frontendAssetUrl("assets/intellectual-twin-mark.svg"))}" alt="" />
          <div>
            <span class="badge">Skill artifact</span>
            <h3>${escapeHtml(metadata.skill_name || metadata.skill_id || "Skill run")}</h3>
            <p>${escapeHtml(result.summary || "Skill run completed.")}</p>
          </div>
        </div>
        <div class="run-id-block">
          <span>Run trace</span>
          <code>${escapeHtml(metadata.run_id || "")}</code>
        </div>
      </div>
      <div class="artifact-summary">
        <span><strong>${escapeHtml(todos.length)}</strong> todos</span>
        <span><strong>${escapeHtml(approvalQueue.length)}</strong> approvals</span>
        <span><strong>${escapeHtml((result.timeline || []).length)}</strong> timeline items</span>
        <span><strong>${escapeHtml(steering.confidence_floor || "-")}</strong> confidence floor</span>
      </div>
      ${renderSkillRunNextAction(todos, approvalQueue, readiness)}
      ${renderSkillRunContinuation(metadata, todos, approvalQueue, readiness)}
      ${renderSourceQuality(readiness)}
      ${renderSkillRunTraceReason(metadata, steering)}
      ${renderSkillRuntime(metadata)}
      ${renderSkillRunActions(metadata.run_id || "")}
      ${renderSkillRunFocus(steering, result.assumptions || [])}
      ${renderSkillRunTodos(todos, result.workstreams || {})}
      <div class="artifact-grid">
        ${renderSkillRunTimeline(result.timeline || [])}
        ${renderSkillRunApprovalQueue(approvalQueue, metadata.run_id || "", approvalStates)}
      </div>
      ${renderSkillRunMeetingBrief(result.meeting_brief || {})}
      ${renderSkillRunReview(metadata)}
      <details class="skill-run-secondary">
        <summary>Cockpit details</summary>
        ${renderSkillRunSteering(steering)}
        ${renderSkillRunKpis(result.kpi_signals || {})}
        ${renderSkillRunAssumptions(result.assumptions || [])}
        ${renderSkillRunMarkdownExport(result.markdown || "")}
      </details>
      <small class="message-meta">Trace: ${escapeHtml(metadata.trace_path || "-")}</small>
    </div>
  `;
}

function renderSkillRunContinuation(metadata, todos, approvalQueue, readiness) {
  const runId = metadata.run_id || "";
  const sourceHelp = readiness.level === "low"
    ? "Add missing sources and rerun before external use."
    : approvalQueue.length
      ? "Resolve approvals, then continue the artifact."
      : "Review outcome, reuse the run, or propose a refinement.";
  const firstTodo = todos[0] || {};
  return `
    <section class="skill-run-continuation">
      <div>
        <span>Continue this run</span>
        <strong>${escapeHtml(firstTodo.what || "Decide how to use the artifact")}</strong>
        <p>${escapeHtml(sourceHelp)}</p>
      </div>
      <div class="skill-run-continuation-actions">
        <button class="small secondary" type="button" data-chat-action="focus-run-review" data-run-id="${escapeHtml(runId)}">Review outcome</button>
        <button class="small secondary" type="button" data-chat-action="open-run-detail" data-run-id="${escapeHtml(runId)}">Open trace</button>
        <button class="small secondary" type="button" data-chat-action="continue-run" data-run-id="${escapeHtml(runId)}">Rerun with sources</button>
        <button class="small secondary" type="button" data-chat-action="open-skill-context">Add sources</button>
        <button class="small danger" type="button" data-chat-action="propose-run-refinement" data-run-id="${escapeHtml(runId)}">Propose refinement</button>
      </div>
      <div class="skill-run-continuation-status" aria-live="polite"></div>
    </section>
  `;
}

function renderSkillRunNextAction(todos, approvalQueue, readiness) {
  const firstTodo = Array.isArray(todos) && todos.length ? todos[0] : null;
  let label = "Start with the first priority";
  let detail = firstTodo
    ? `${firstTodo.what || "Review the prioritized plan."}${firstTodo.whom ? ` · ${firstTodo.whom}` : ""}`
    : "Review the generated artifact and decide whether it is useful enough to reuse.";
  let badge = "Plan";
  if (approvalQueue.length) {
    badge = "Approval";
    label = "Resolve human-gated actions first";
    detail = `${approvalQueue.length} action${approvalQueue.length === 1 ? "" : "s"} need approval before sending, scheduling, or committing externally.`;
  } else if (readiness.level === "low") {
    badge = "Source";
    label = "Improve source context before acting";
    detail = "The run has low source coverage. Add email, calendar, Teams, or knowledge context before relying on the output.";
  }
  return `
    <section class="next-action-strip">
      <span>${escapeHtml(badge)}</span>
      <div>
        <strong>${escapeHtml(label)}</strong>
        <p>${escapeHtml(detail)}</p>
      </div>
    </section>
  `;
}

function sourceReadinessFromPreflight(preflight) {
  if (!preflight || !Object.keys(preflight).length) {
    return sourceReadiness({});
  }
  const present = Array.isArray(preflight.present_sources) ? preflight.present_sources : [];
  const missing = Array.isArray(preflight.missing_sources) ? preflight.missing_sources : [];
  const readyCount = present.filter((item) => item !== "manual_request").length;
  const level = preflight.source_quality || (readyCount >= 3 ? "high" : readyCount >= 2 ? "medium" : "low");
  const label = level === "high" ? "High source coverage" : level === "medium" ? "Medium source coverage" : "Low source coverage";
  return {
    level,
    label,
    detail: `${readyCount}/4 source blocks ready from backend preflight.`,
    readyCount,
    present: present.filter((item) => item !== "manual_request").map((item) => item.replace("_input", "")),
    missing: missing.filter((item) => item !== "manual_request").map((item) => item.replace("_input", "")),
  };
}

function renderSkillRunActions(runId) {
  return `
    <div class="artifact-actions">
      <div>
        <span>Export</span>
        <button class="small secondary artifact-copy-md" type="button" data-run-id="${escapeHtml(runId)}">Copy markdown</button>
        <button class="small secondary artifact-copy-plan" type="button" data-run-id="${escapeHtml(runId)}">Copy plan table</button>
      </div>
      <div>
        <span>Evidence</span>
        <button class="small secondary artifact-toggle-sources" type="button">Show sources</button>
      </div>
    </div>
  `;
}

function renderSkillRunTraceReason(metadata, steering) {
  const skillName = metadata.skill_name || metadata.skill_id || steering.skill || "selected skill";
  const active = state.twins.find((twin) => twin.twin_id === state.activeTwin);
  const twinName = steering.twin || active?.display_name || metadata.twin || state.activeTwin;
  const firstSteer = Array.isArray(steering.steering) && steering.steering.length ? steering.steering[0] : "";
  const boundary = Array.isArray(steering.hard_boundaries) && steering.hard_boundaries.length ? steering.hard_boundaries[0] : "";
  return `
    <section class="skill-run-trace">
      <div>
        <span>Why this skill</span>
        <p>${escapeHtml(skillName)} was selected in chat mode to turn the supplied source exports into an actionable artifact.</p>
      </div>
      <div>
        <span>Why this twin</span>
        <p>${escapeHtml(twinName)} supplied priorities, tone, decision boundaries, and approval posture.</p>
      </div>
      <div>
        <span>Steering evidence</span>
        <p>${escapeHtml(firstSteer || steering.directive || "No explicit actor steer recorded.")}</p>
      </div>
      <div>
        <span>Approval boundary</span>
        <p>${escapeHtml(boundary || "External actions remain human-gated.")}</p>
      </div>
    </section>
  `;
}

function renderSkillRuntime(metadata) {
  const result = metadata.result || {};
  const orchestration = metadata.orchestration || result.orchestration || {};
  const preflight = metadata.preflight || result.preflight || {};
  const evidence = metadata.evidence_package || result.evidence_package || {};
  const boundary = metadata.boundary_decisions || result.boundary_decisions || orchestration.boundary_decisions || {};
  const runtimeContext = metadata.runtime_context || result.runtime_context || {};
  const graphContext = metadata.graph_context || result.graph_context || runtimeContext.graph_context || {};
  const graphPacket = metadata.graph_context_packet || result.graph_context_packet || runtimeContext.graph_context_packet || {};
  const stages = Array.isArray(orchestration.state_machine) ? orchestration.state_machine : [];
  const agents = Array.isArray(metadata.task_agent_trace)
    ? metadata.task_agent_trace
    : Array.isArray(result.task_agent_trace)
      ? result.task_agent_trace
      : Array.isArray(orchestration.task_agents)
        ? orchestration.task_agents
        : [];
  const checkpoints = Array.isArray(orchestration.actor_checkpoints) ? orchestration.actor_checkpoints : [];
  const anchors = Array.isArray(evidence.source_anchors) ? evidence.source_anchors : [];
  return `
    <section class="skill-runtime">
      <div class="runtime-head">
        <div>
          <span>Runtime orchestration</span>
          <h4>${escapeHtml(orchestration.orchestrator?.mode || "manager_agents_as_tools")}</h4>
        </div>
        <span class="runtime-quality ${escapeHtml(preflight.source_quality || evidence.quality || "low")}">
          ${escapeHtml(preflight.status || "recorded")}
        </span>
      </div>
      ${stages.length ? `<div class="runtime-stage-list">${stages.map(renderRuntimeStage).join("")}</div>` : ""}
      <div class="runtime-grid">
        <div>
          <span>Preflight</span>
          <p>${escapeHtml(renderPreflightText(preflight))}</p>
          ${Array.isArray(preflight.warnings) && preflight.warnings.length ? `<ul>${preflight.warnings.slice(0, 3).map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>` : ""}
        </div>
        <div>
          <span>Evidence package</span>
          <p>${escapeHtml(evidence.grounding_rule || "Evidence-first grounding recorded.")}</p>
          ${anchors.length ? `<div class="evidence-anchor-list">${anchors.slice(0, 4).map(renderEvidenceAnchor).join("")}</div>` : ""}
        </div>
        <div>
          <span>Boundary enforcement</span>
          <p>${escapeHtml(boundary.enforcement || "Human gates are enforced before external action.")}</p>
          <strong>${escapeHtml(String(boundary.requires_human_detected ?? 0))} approval item${Number(boundary.requires_human_detected || 0) === 1 ? "" : "s"}</strong>
        </div>
        <div>
          <span>Graph context</span>
          <p>${escapeHtml(graphContext.usage || "skill_context_graph")}</p>
          <strong>${escapeHtml(String((graphContext.nodes || []).length || 0))} nodes · ${escapeHtml(String((graphContext.edges || []).length || 0))} relations</strong>
        </div>
        ${renderSkillRunGraphPacketRuntime(graphPacket, metadata.run_id || "")}
      </div>
      <details class="runtime-details">
        <summary>Actor checkpoints and task agents</summary>
        ${checkpoints.length ? `<div class="checkpoint-list">${checkpoints.map(renderActorCheckpoint).join("")}</div>` : ""}
        ${agents.length ? `<div class="runtime-agent-grid">${agents.map(renderTaskAgentTrace).join("")}</div>` : ""}
      </details>
    </section>
  `;
}

function renderSkillRunGraphPacketRuntime(packet, runId = "") {
  if (!packet || !Object.keys(packet).length) return "";
  const projection = packet.projection || {};
  const nodes = Array.isArray(packet.nodes) ? packet.nodes : [];
  const edges = Array.isArray(packet.edges) ? packet.edges : [];
  const prepared = projection.prepared_at ? `Prepared ${formatShortDate(projection.prepared_at)}` : "Prepared in graph cockpit";
  return `
    <div class="runtime-graph-packet">
      <span>Attached graph packet</span>
      <p>${escapeHtml(projection.preset ? `${labelizeGraph(projection.preset)} preset` : packet.query || "Prepared OKF graph context")}</p>
      <strong>${escapeHtml(String(nodes.length))} nodes · ${escapeHtml(String(edges.length))} relations</strong>
      <small>${escapeHtml(prepared)}</small>
      <button class="secondary small runtime-open-graph-packet" type="button" data-chat-action="open-run-graph" data-run-id="${escapeHtml(runId)}">Open in graph</button>
    </div>
  `;
}

function renderRuntimeStage(stage) {
  const status = stage.status || "completed";
  return `
    <span class="runtime-stage ${escapeHtml(String(status).replaceAll("_", "-"))}">
      <strong>${escapeHtml(stage.label || stage.key || "Stage")}</strong>
      <small>${escapeHtml(stage.detail || status)}</small>
    </span>
  `;
}

function renderPreflightText(preflight) {
  if (!preflight || !Object.keys(preflight).length) return "No preflight data recorded.";
  const present = Array.isArray(preflight.present_sources) ? preflight.present_sources.length : 0;
  const missing = Array.isArray(preflight.required_missing) ? preflight.required_missing.length : 0;
  return `${preflight.source_quality || "unknown"} source quality, ${present} source blocks present, ${missing} required gaps.`;
}

function renderEvidenceAnchor(anchor) {
  return `
    <span>
      <strong>${escapeHtml(anchor.label || anchor.source_id || "Source")}</strong>
      <small>${escapeHtml(anchor.item_count ?? 0)} items · ${escapeHtml(anchor.char_count ?? 0)} chars</small>
    </span>
  `;
}

function renderActorCheckpoint(checkpoint) {
  return `
    <div class="checkpoint-item">
      <span>${escapeHtml(checkpoint.name || "checkpoint")}</span>
      <strong>${escapeHtml(checkpoint.status || "completed")}</strong>
      <p>${escapeHtml(checkpoint.steer || "")}</p>
    </div>
  `;
}

function renderTaskAgentTrace(agent) {
  const tools = Array.isArray(agent.tools) ? agent.tools : [];
  const inputs = Array.isArray(agent.input_contract) ? agent.input_contract : [];
  const checks = Array.isArray(agent.contract_checks) ? agent.contract_checks : [];
  const passRate = agent.quality_signals?.contract_pass_rate;
  return `
    <div class="runtime-agent">
      <span>${escapeHtml(agent.status || "completed")}</span>
      <strong>${escapeHtml(agent.name || "task-agent")}</strong>
      <p>${escapeHtml(agent.summary || "Task agent completed.")}</p>
      <small>${escapeHtml(agent.output_contract || "structured_output")}${tools.length ? ` · ${escapeHtml(tools.join(", "))}` : ""}</small>
      ${inputs.length ? `<small>Inputs: ${escapeHtml(inputs.slice(0, 4).join(", "))}</small>` : ""}
      ${passRate !== undefined ? `<small>Contract pass rate: ${escapeHtml(passRate)}</small>` : ""}
      ${checks.length ? `<ul class="contract-checks">${checks.map(renderContractCheck).join("")}</ul>` : ""}
    </div>
  `;
}

function renderContractCheck(check) {
  return `<li class="${check.passed ? "passed" : "failed"}">${escapeHtml(check.name || "check")}</li>`;
}

function renderSourceQuality(readiness) {
  return `
    <section class="source-quality ${escapeHtml(readiness.level)}">
      <div>
        <span>Source quality</span>
        <strong>${escapeHtml(readiness.label)}</strong>
        <p>${escapeHtml(readiness.detail)}</p>
      </div>
      <div class="preflight-grid">
        <span>${escapeHtml(readiness.readyCount)}/4 ready</span>
        <span>${escapeHtml(readiness.present.join(", ") || "manual request only")}</span>
        ${readiness.missing.length ? `<span>missing ${escapeHtml(readiness.missing.join(", "))}</span>` : "<span>all source blocks present</span>"}
      </div>
    </section>
  `;
}

function renderSkillRunFocus(steering, assumptions) {
  const firstSteer = Array.isArray(steering.steering) && steering.steering.length ? steering.steering[0] : "";
  const assumption = Array.isArray(assumptions) && assumptions.length ? assumptions[0] : "";
  return `
    <section class="artifact-focus">
      <div>
        <span>Actor steer</span>
        <p>${escapeHtml(firstSteer || steering.directive || "Prioritize high-signal work and keep external actions gated.")}</p>
      </div>
      <div>
        <span>Working assumption</span>
        <p>${escapeHtml(assumption || "Generated from the provided source context.")}</p>
      </div>
    </section>
  `;
}

function renderSkillRunReview(metadataOrRunId) {
  const metadata = typeof metadataOrRunId === "string" ? { run_id: metadataOrRunId } : metadataOrRunId || {};
  const runId = metadata.run_id || "";
  return `
    <div class="skill-run-review" data-run-id="${escapeHtml(runId)}">
      <div>
        <strong>Review artifact</strong>
        <span>Feedback improves the skill and can create a refinement proposal.</span>
      </div>
      ${renderSkillRunInferenceReview(metadata)}
      <label class="review-note-field">
        <span>Review note</span>
        <textarea class="skill-run-review-note" rows="2" placeholder="What was useful, missing, or incorrectly prioritized?"></textarea>
      </label>
      <div class="review-button-group">
        <button class="small secondary skill-run-review-btn" data-state="useful">Useful</button>
        <button class="small secondary skill-run-review-btn" data-state="needs_rework">Needs rework</button>
        <button class="small secondary skill-run-review-btn" data-state="wrong_priority">Wrong priority</button>
        <button class="small secondary skill-run-review-btn" data-state="missing_context">Missing context</button>
        <button class="small danger skill-run-review-btn" data-state="rejected">Reject</button>
      </div>
      <label class="inline-check review-refinement-toggle"><input type="checkbox" class="chat-propose-refinement" checked /> propose refinement for corrective feedback</label>
      <div class="review-status" aria-live="polite"></div>
    </div>
  `;
}

function renderSkillRunInferenceReview(metadata) {
  const graphContext = skillRunGraphContext(metadata);
  const path = skillRunInferencePath(graphContext, metadata);
  if (!path.length) {
    return `
      <section class="skill-inference-review empty">
        <span>Graph inference path</span>
        <p>No graph relation path was recorded for this run. Review mainly covers source quality and actor steering.</p>
      </section>
    `;
  }
  const counts = countBy(path, (item) => item.edgeClass);
  const topRisk = path.find((item) => item.edgeClass.includes("candidate") || item.reviewState === "needs-rework");
  const guidance = topRisk
    ? "Candidate or rework relation present. Use corrective feedback if the artifact relied on this path without enough evidence."
    : counts.inferred
      ? "Inferred relation present. Confirm the reasoning is acceptable before marking the run useful."
      : "Explicit graph evidence only. Focus review on output quality and actionability.";
  return `
    <section class="skill-inference-review">
      <div class="skill-inference-head">
        <div>
          <span>Graph inference path</span>
          <strong>${escapeHtml(path.length)} relation${path.length === 1 ? "" : "s"} used for review context</strong>
          <p>${escapeHtml(guidance)}</p>
        </div>
        <div class="skill-inference-counts">
          <span class="explicit">${escapeHtml(counts.explicit || 0)} explicit</span>
          <span class="inferred">${escapeHtml(counts.inferred || 0)} inferred</span>
          <span class="candidate">${escapeHtml((counts.candidate || 0) + (counts["duplicate-candidate"] || 0) + (counts["contradiction-candidate"] || 0))} candidate</span>
        </div>
      </div>
      <ol class="skill-inference-path">
        ${path.slice(0, 4).map(renderSkillInferencePathItem).join("")}
      </ol>
    </section>
  `;
}

function skillRunGraphContext(metadata) {
  const result = metadata.result || {};
  const runtimeContext = metadata.runtime_context || result.runtime_context || {};
  return metadata.graph_context || result.graph_context || runtimeContext.graph_context || {};
}

function skillRunInferencePath(graphContext, metadata) {
  const edges = Array.isArray(graphContext.edges) ? graphContext.edges : [];
  if (!edges.length) return [];
  const nodes = new Map((graphContext.nodes || []).map((node) => [node.node_key, node]));
  const packetEdgeKeys = graphPacketEdgeKeys(metadata.graph_context_packet || metadata.result?.graph_context_packet || metadata.runtime_context?.graph_context_packet || {});
  return [...edges]
    .sort((a, b) => {
      const packetA = packetEdgeKeys.has(a.edge_key) ? 1 : 0;
      const packetB = packetEdgeKeys.has(b.edge_key) ? 1 : 0;
      return packetB - packetA || Number(b.confidence || 0) - Number(a.confidence || 0);
    })
    .slice(0, 6)
    .map((edge) => {
      const source = nodes.get(edge.source) || {};
      const target = nodes.get(edge.target) || {};
      return {
        edge,
        edgeClass: graphEdgeClass(edge),
        relation: edge.relation_type || edge.edge_type || "related",
        reviewState: edge.review_state || "unreviewed",
        confidence: graphEdgeConfidencePercent(edge),
        sourceTitle: source.title || edge.source || "Source node",
        targetTitle: target.title || edge.target || "Target node",
      };
    });
}

function renderSkillInferencePathItem(item) {
  return `
    <li class="${escapeHtml(safeGraphClass(item.edgeClass))}">
      <span>${escapeHtml(labelizeGraph(item.edgeClass))}</span>
      <strong>${escapeHtml(item.sourceTitle)} → ${escapeHtml(item.targetTitle)}</strong>
      <small>${escapeHtml(labelizeGraph(item.relation))} · ${escapeHtml(item.reviewState)} · confidence ${escapeHtml(item.confidence || "-")}%</small>
    </li>
  `;
}

function renderSkillRunSteering(steering) {
  if (!steering.twin) return "";
  return `
    <section class="skill-run-section">
      <h4>Twin Steering</h4>
      <p><strong>${escapeHtml(steering.twin)}</strong> steers this skill with tone: ${escapeHtml(steering.tone || "-")}</p>
      <p>${escapeHtml(steering.directive || "")}</p>
      ${(steering.steering || []).length ? `<ul>${steering.steering.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>` : ""}
    </section>
  `;
}

function renderSkillRunKpis(kpis) {
  return `
    <section class="skill-run-section">
      <h4>KPI Signals</h4>
      <div class="metric-row compact-metrics">
        ${Object.entries(kpis).map(([key, value]) => `<span><strong>${escapeHtml(value)}</strong>${escapeHtml(key.replaceAll("_", " "))}</span>`).join("") || "<span>No KPI signals detected</span>"}
      </div>
    </section>
  `;
}

function renderSkillRunTimeline(timeline) {
  if (!timeline.length) return "";
  return `
    <section class="skill-run-section">
      <h4>Timeline</h4>
      <table class="data-table">
        <thead><tr><th>Slot</th><th>Work stream</th><th>Item</th></tr></thead>
        <tbody>${timeline.map((item) => `<tr><td>${escapeHtml(item.slot)}</td><td>${escapeHtml(item.workstream)}</td><td>${escapeHtml(item.item)}</td></tr>`).join("")}</tbody>
      </table>
    </section>
  `;
}

function renderSkillRunTodos(todos, workstreams) {
  const rows = Array.isArray(todos) && todos.length
    ? todos
    : Object.entries(workstreams || {}).flatMap(([stream, items]) => (items || []).map((item) => ({ workstream: stream, ...item })));
  if (!rows.length) return "";
  const groupedRows = groupTodosByWorkstream(rows);
  return `
    <section class="skill-run-section">
      <h4>Prioritized Daily Plan</h4>
      <div class="table-scroll">
      <table class="data-table daily-plan-table">
        <thead>
          <tr>
            <th>What</th>
            <th>How</th>
            <th>Why important</th>
            <th>Whom</th>
            <th>Deadline</th>
            <th>KPI / Signals</th>
            <th>Comments</th>
            <th>Approval needed</th>
          </tr>
        </thead>
        <tbody>${groupedRows
          .map(({ workstream, items }) => `
            <tr class="workstream-row"><td colspan="8">${escapeHtml(titleCase(workstream || "other"))}</td></tr>
            ${items.map((item, index) => renderTodoRow(item, index)).join("")}
          `)
          .join("")}</tbody>
      </table>
      </div>
    </section>
  `;
}

function groupTodosByWorkstream(rows) {
  const order = ["client delivery", "sales", "internal", "admin", "other"];
  const buckets = new Map();
  rows.forEach((item) => {
    const key = String(item.workstream || item.stream || "other").toLowerCase();
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key).push(item);
  });
  return [...buckets.entries()]
    .sort(([a], [b]) => {
      const ai = order.includes(a) ? order.indexOf(a) : order.length;
      const bi = order.includes(b) ? order.indexOf(b) : order.length;
      return ai - bi || a.localeCompare(b);
    })
    .map(([workstream, items]) => ({ workstream, items }));
}

function renderTodoRow(item, index) {
  const needsApproval = item.approval_needed || (item.signals || []).includes("requires_human");
  return `<tr class="${needsApproval ? "approval-row" : ""}">
    <td><span class="priority-token">P${index + 1}</span>${escapeHtml(item.what)}${renderTodoEvidence(item)}</td>
    <td>${escapeHtml(item.how)}</td>
    <td>${escapeHtml(item.why)}</td>
    <td>${escapeHtml(item.whom)}</td>
    <td>${escapeHtml(item.deadline || "not specified")}</td>
    <td>${escapeHtml(item.kpi || "")}${renderSignalBadges(item.signals || [])}</td>
    <td>${escapeHtml(item.comments || item.source || "-")}</td>
    <td>${needsApproval ? '<span class="signal-pill approval">Yes</span>' : "No"}</td>
  </tr>`;
}

function renderTodoEvidence(item) {
  const signals = Array.isArray(item.signals) ? item.signals.join(", ") : "";
  const parts = [
    item.source ? `source: ${item.source}` : "",
    item.score !== undefined ? `score: ${item.score}` : "",
    signals ? `signals: ${signals}` : "",
  ].filter(Boolean);
  if (!parts.length) return "";
  return `<details class="todo-evidence"><summary>Why prioritized</summary><p>${escapeHtml(parts.join(" · "))}</p></details>`;
}

function titleCase(value) {
  return String(value || "")
    .split(" ")
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

function renderSignalBadges(signals) {
  if (!Array.isArray(signals) || !signals.length) return '<span class="empty">-</span>';
  return signals.map((signal) => `<span class="signal-pill">${escapeHtml(signal)}</span>`).join("");
}

function renderSkillRunMeetingBrief(brief) {
  if (!brief || !Object.keys(brief).length) return "";
  return `
    <section class="skill-run-section">
      <h4>Meeting Brief</h4>
      <p><strong>Executive summary:</strong> ${escapeHtml(brief.executive_summary || "-")}</p>
      <p><strong>Desired outcome:</strong> ${escapeHtml(brief.desired_outcome || "-")}</p>
      <p><strong>Necessary decisions:</strong></p>
      <ul>${(brief.necessary_decisions || []).map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>
      <p><strong>Decision ideas:</strong></p>
      <ul>${(brief.decision_ideas || []).map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>
    </section>
  `;
}

function renderSkillRunApprovalQueue(queue, runId = "", approvalStates = []) {
  return `
    <section class="skill-run-section">
      <h4>Approval Queue</h4>
      ${
        queue.length
          ? `<div class="approval-cards">${queue.map((item, index) => renderApprovalCard(item, runId, index, approvalStates[index])).join("")}</div>`
          : '<p class="empty">No send, schedule, or external commitment action detected.</p>'
      }
    </section>
  `;
}

function renderApprovalCard(item, runId, index, persistedState = null) {
  const state = persistedState?.state || getApprovalItemState(runId, index);
  return `
    <article class="approval-card" data-run-id="${escapeHtml(runId)}" data-index="${index}">
      <div>
        <span class="approval-state ${escapeHtml(state)}">${escapeHtml(state)}</span>
        <p>${escapeHtml(item.action)}</p>
        <small>${escapeHtml(item.reason || "Human approval required before external action.")}</small>
      </div>
      <div class="approval-actions">
        <button class="small secondary approval-state-btn" type="button" data-state="approved">Approve</button>
        <button class="small secondary approval-mcp-btn" type="button">Create MCP item</button>
        <button class="small secondary approval-state-btn" type="button" data-state="done">Done</button>
        <button class="small danger approval-state-btn" type="button" data-state="rejected">Reject</button>
      </div>
    </article>
  `;
}

function getApprovalItemState(runId, index) {
  const key = approvalStateKey(runId, index);
  return storedValue(key) || "pending";
}

function setApprovalItemState(runId, index, value) {
  localStorage.setItem(approvalStateKey(runId, index), value);
}

function approvalStateKey(runId, index) {
  return `${storageKeys.approvalPrefix}.${runId}.${index}`;
}

function renderSkillRunAssumptions(assumptions) {
  if (!assumptions.length) return "";
  return `<section class="skill-run-section"><h4>Assumptions</h4><ul>${assumptions.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul></section>`;
}

function renderSkillRunMarkdownExport(markdown) {
  if (!markdown) return "";
  return `
    <section class="skill-run-section">
      <details class="markdown-export">
        <summary>Markdown export</summary>
        <pre>${escapeHtml(markdown)}</pre>
      </details>
    </section>
  `;
}

function bindSkillRunReviewButtons(node, runId) {
  node.querySelectorAll(".skill-run-review-btn").forEach((button) => {
    button.addEventListener("click", async () => {
      const reviewBox = button.closest(".skill-run-review");
      const note = reviewBox?.querySelector(".skill-run-review-note")?.value.trim() || "";
      const status = reviewBox?.querySelector(".review-status");
      if (status) {
        status.className = "review-status";
        status.textContent = "Saving review...";
      }
      button.disabled = true;
      try {
        const result = await postJson("/api/skills/runs/review", {
          run_id: runId,
          review_state: button.dataset.state,
          note,
          actor: "local-user",
        });
        if (status) {
          status.className = "review-status review-saved";
          status.textContent = `Saved: ${result.review.state}`;
        }
        if (["needs_rework", "wrong_priority", "missing_context", "rejected"].includes(button.dataset.state)) {
          const shouldPropose = reviewBox.querySelector(".chat-propose-refinement")?.checked;
          if (shouldPropose) await proposeRefinementFromChat(runId, reviewBox);
        }
        await safeRefreshReviewDashboard();
        await safeRefreshSkillRuns();
        await safeRefreshSkillRefinements();
      } catch (error) {
        if (status) {
          status.className = "review-status review-error";
          status.textContent = `Review failed: ${error.message}`;
        }
        button.disabled = false;
      }
    });
  });
}

function bindSkillRunArtifactActions(node, metadata) {
  const markdown = metadata.result?.markdown || formatPlanAsMarkdown(metadata.result || {});
  const tableText = formatPlanAsTableText(metadata.result?.todos || [], metadata.result?.workstreams || {});
  node.querySelector(".artifact-copy-md")?.addEventListener("click", async (event) => {
    const copied = await copyTextToClipboard(markdown);
    if (!copied) showArtifactExportText(node, markdown, "Markdown export");
    markButtonDone(event.currentTarget, copied ? "Copied" : "Select text");
  });
  node.querySelector(".artifact-copy-plan")?.addEventListener("click", async (event) => {
    const copied = await copyTextToClipboard(tableText);
    if (!copied) showArtifactExportText(node, tableText, "Plan table export");
    markButtonDone(event.currentTarget, copied ? "Copied" : "Select text");
  });
  node.querySelector(".artifact-toggle-sources")?.addEventListener("click", (event) => {
    const context = $("#chatSkillContext");
    context.open = !context.open;
    event.currentTarget.textContent = context.open ? "Hide sources" : "Show sources";
  });
  node.querySelector(".runtime-open-graph-packet")?.addEventListener("click", (event) => {
    event.stopPropagation();
    replaySkillRunGraphContext(metadata.run_id || "", metadata);
  });
}

function bindApprovalQueueActions(node) {
  node.querySelectorAll(".approval-state-btn").forEach((button) => {
    button.addEventListener("click", async () => {
      const card = button.closest(".approval-card");
      if (!card) return;
      const runId = card.dataset.runId || "";
      const index = Number(card.dataset.index || 0);
      const nextState = button.dataset.state || "pending";
      button.disabled = true;
      try {
        await postJson("/api/skills/runs/approval-item", {
          run_id: runId,
          item_index: index,
          state: nextState,
          note: "Updated from Chat approval queue.",
          actor: "local-user",
        });
        setApprovalItemState(runId, index, nextState);
        const badge = card.querySelector(".approval-state");
        badge.textContent = nextState;
        badge.className = `approval-state ${nextState}`;
        await safeRefreshSkillRuns();
        await safeRefreshReviewDashboard();
        showToast("Approval item updated", nextState, "success");
      } catch (error) {
        addMessage("assistant", `Approval update failed: ${error.message}`);
        showToast("Approval update failed", error.message, "error");
      } finally {
        button.disabled = false;
      }
    });
  });
  node.querySelectorAll(".approval-mcp-btn").forEach((button) => {
    button.addEventListener("click", async () => {
      const card = button.closest(".approval-card");
      if (!card) return;
      button.disabled = true;
      try {
        const result = await postJson("/api/mcp/tool-calls/from-skill-approval", {
          run_id: card.dataset.runId || "",
          item_index: Number(card.dataset.index || 0),
          connector: "email",
          tool_name: "draft_create",
          actor: "local-user",
        });
        markButtonDone(button, "MCP item created");
        await safeRefreshMcpStatus();
        await safeRefreshReviewDashboard();
        setOutputStatus("#qualityResult", "success", "MCP approval item created", result.call?.call_id || "-");
        showToast("MCP approval item created", result.call?.call_id || "-", "success");
      } catch (error) {
        setOutputStatus("#qualityResult", "error", "MCP item creation failed", error.message);
        showToast("MCP item creation failed", error.message, "error");
        button.disabled = false;
      }
    });
  });
}

function formatPlanAsTableText(todos, workstreams) {
  const rows = Array.isArray(todos) && todos.length
    ? todos
    : Object.entries(workstreams || {}).flatMap(([stream, items]) => (items || []).map((item) => ({ workstream: stream, ...item })));
  const header = ["Workstream", "What", "How", "Why important", "Whom", "Deadline", "KPI / Signals", "Comments", "Approval needed"];
  const lines = [header.join("\t")];
  rows.forEach((item) => {
    const signals = Array.isArray(item.signals) ? item.signals.join(", ") : "";
    const needsApproval = item.approval_needed || (item.signals || []).includes("requires_human");
    lines.push([
      item.workstream || item.stream || "other",
      item.what || "",
      item.how || "",
      item.why || "",
      item.whom || "",
      item.deadline || "",
      [item.kpi || "", signals].filter(Boolean).join(" | "),
      item.comments || item.source || "",
      needsApproval ? "yes" : "no",
    ].map(cleanClipboardCell).join("\t"));
  });
  return lines.join("\n");
}

function formatPlanAsMarkdown(result) {
  const todos = result.todos || [];
  const lines = ["# Skill Artifact", "", result.summary || "Skill run completed.", ""];
  groupTodosByWorkstream(todos).forEach(({ workstream, items }) => {
    lines.push(`## ${titleCase(workstream)}`);
    items.forEach((item, index) => {
      lines.push(`- P${index + 1}: ${item.what || ""}`);
      if (item.how) lines.push(`  - How: ${item.how}`);
      if (item.why) lines.push(`  - Why: ${item.why}`);
      if (item.deadline) lines.push(`  - Deadline: ${item.deadline}`);
    });
    lines.push("");
  });
  return lines.join("\n");
}

function cleanClipboardCell(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

async function copyTextToClipboard(text) {
  if (navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch (error) {
      console.warn("Clipboard API unavailable, using fallback copy.", error);
    }
  }
  const textarea = document.createElement("textarea");
  textarea.value = text;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.opacity = "0";
  document.body.appendChild(textarea);
  textarea.select();
  const copied = document.execCommand("copy");
  textarea.remove();
  return copied;
}

function markButtonDone(button, label) {
  if (!button) return;
  const original = button.textContent;
  button.textContent = label;
  window.setTimeout(() => {
    button.textContent = original;
  }, 1400);
}

function showArtifactExportText(node, text, label) {
  let box = node.querySelector(".artifact-export-fallback");
  if (!box) {
    box = document.createElement("div");
    box.className = "artifact-export-fallback";
    node.querySelector(".artifact-actions")?.insertAdjacentElement("afterend", box);
  }
  box.innerHTML = `
    <label>${escapeHtml(label)}</label>
    <textarea readonly rows="6">${escapeHtml(text)}</textarea>
  `;
  const textarea = box.querySelector("textarea");
  textarea.focus();
  textarea.select();
}

async function proposeRefinementFromChat(runId, reviewBox) {
  try {
    const result = await postJson("/api/skills/refinements/propose", {
      run_id: runId,
      use_ai: true,
      actor: "local-user",
    });
    const proposal = result.proposal || {};
    reviewBox.insertAdjacentHTML(
      "beforeend",
      `<span class="review-saved">Proposal: ${escapeHtml(proposal.proposal_id || result.status || "created")}</span>`,
    );
  } catch (error) {
    reviewBox.insertAdjacentHTML(
      "beforeend",
      `<span class="review-error">Proposal failed: ${escapeHtml(error.message)}</span>`,
    );
  }
}

async function proposeRunRefinementFromCard(runId, button) {
  if (!runId || !button) return;
  const card = button.closest(".skill-run-continuation");
  const status = card?.querySelector(".skill-run-continuation-status");
  button.disabled = true;
  if (status) {
    status.className = "skill-run-continuation-status";
    status.textContent = "Creating refinement proposal...";
  }
  try {
    const result = await postJson("/api/skills/refinements/propose", {
      run_id: runId,
      use_ai: true,
      actor: "local-user",
    });
    const proposal = result.proposal || {};
    if (status) {
      status.className = "skill-run-continuation-status review-saved";
      status.textContent = `Proposal created: ${proposal.proposal_id || result.status || "pending review"}`;
    }
    markButtonDone(button, "Proposal created");
    await safeRefreshSkillRefinements();
    await safeRefreshReviewDashboard();
  } catch (error) {
    if (status) {
      status.className = "skill-run-continuation-status review-error";
      status.textContent = `Proposal failed: ${compactError(error.message)}`;
    }
    button.disabled = false;
    showToast("Refinement proposal failed", error.message, "error");
  }
}

function showIngest(text) {
  $("#ingestResult").textContent = text;
}

function formatIngestResult(result) {
  if (Array.isArray(result.concepts)) {
    const lines = [
      `Created ${result.count || result.concepts.length} concept(s) from ${result.source || "upload"}.`,
      "",
      ...result.concepts.map(
        (concept) =>
          `- ${concept.title} (${concept.type})\n  ${concept.path}${concept.source_anchor ? `\n  anchor: ${concept.source_anchor}` : ""}\n  guardrails: ${concept.guardrail_status || "not-evaluated"}${concept.guardrail_findings?.length ? ` (${concept.guardrail_findings.length} finding(s))` : ""}`,
      ),
    ];
    return lines.join("\n");
  }
  return JSON.stringify(result, null, 2);
}

function formatAnchorDetail(detail) {
  if (!detail || typeof detail !== "object" || Array.isArray(detail)) return "";
  return Object.entries(detail)
    .map(([key, value]) => `${key}: ${Array.isArray(value) || typeof value === "object" ? JSON.stringify(value) : value}`)
    .join(", ");
}

async function apiRequestJson(url, options = {}) {
  if (window.IntellectualTwinApi) return window.IntellectualTwinApi.requestJson(url, options);
  const response = await fetch(apiUrl(url), options);
  if (!response.ok) throw new Error(await response.text());
  return response.json();
}

async function getJson(url) {
  return apiRequestJson(url);
}

async function postJson(url, body) {
  return apiRequestJson(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}

async function postForm(url, form) {
  return apiRequestJson(url, { method: "POST", body: form });
}

async function deleteJson(url, body) {
  return apiRequestJson(url, {
    method: "DELETE",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}

function normalizeBaseUrl(value) {
  return String(value || "").trim().replace(/\/+$/, "");
}

function apiUrl(path) {
  if (window.IntellectualTwinApi) return window.IntellectualTwinApi.apiUrl(path);
  if (!apiBaseUrl || /^https?:\/\//i.test(path)) return path;
  return `${apiBaseUrl}${path.startsWith("/") ? path : `/${path}`}`;
}

function resolveAssetUrl(path) {
  if (window.IntellectualTwinApi) return window.IntellectualTwinApi.resolveAssetUrl(path);
  if (!path || /^https?:\/\//i.test(path) || path.startsWith("data:") || path.startsWith("blob:")) return path;
  if (path.startsWith("/static/") && apiBaseUrl) return `${apiBaseUrl}${path}`;
  return path;
}

function frontendAssetUrl(path) {
  if (window.IntellectualTwinApi) return window.IntellectualTwinApi.frontendAssetUrl(path);
  const cleanPath = String(path || "").replace(/^\/+/, "");
  if (!assetBaseUrl || assetBaseUrl === ".") return `./${cleanPath}`;
  return `${assetBaseUrl}/${cleanPath}`;
}

async function fetchFrontendAssetJson(path, options = {}) {
  const cleanPath = String(path || "").replace(/^\/+/, "");
  const candidates = Array.from(new Set([
    frontendAssetUrl(cleanPath),
    `./${cleanPath}`,
    cleanPath,
  ]));
  let lastError = null;
  for (const url of candidates) {
    try {
      const response = await fetch(url, { cache: "no-store" });
      if (!response.ok) {
        lastError = new Error(`${url} returned ${response.status}`);
        continue;
      }
      return response.json();
    } catch (error) {
      lastError = error;
    }
  }
  if (options.optional) return null;
  throw lastError || new Error(`Asset unavailable: ${cleanPath}`);
}

function storedValue(primaryKey, legacyKey = "") {
  const primary = window.localStorage.getItem(primaryKey);
  if (primary !== null || !legacyKey) return primary;
  const legacy = window.localStorage.getItem(legacyKey);
  if (legacy !== null) window.localStorage.setItem(primaryKey, legacy);
  return legacy;
}

function escapeHtml(text) {
  return String(text)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
